// Calefaccion (Heating) -- 692 Preguntas -- Maestro HVACR | maestrohvacr.com
// Categorias: CALEF_ELECTRICIDAD (162), CALEF_HORNOS (186), CALEF_COMBUSTION (57), CALEF_HIDRONICA (112), CALEF_TERMODINAMICA (175)
// ~38 preguntas por quiz (150/4)

var CALEF_QUESTIONS = [

  // -- Electricidad y Motores (1-162) --
  { id:"calef_1", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor de soplador (blower) de inducción PSC presenta una lectura de 0 ohmios entre el terminal común y el de marcha (run). ¿Cuál es el diagnóstico técnico más preciso?", opciones:["El motor está en perfectas condiciones ya que la resistencia en bobinados de alta eficiencia tiende a cero.", "Existe un cortocircuito interno en el bobinado de marcha que anula la reactancia inductiva.", "El protector térmico interno está abierto por sobrecalentamiento excesivo del estator.", "La lectura es errónea porque no se ha descargado el capacitor de marcha previamente."], respuesta_correcta:1, explicacion:"0 ohmios indica continuidad total sin resistencia, lo cual en un bobinado significa un cortocircuito. Una lectura de 'infinito' u 'OL' indicaría un bobinado abierto." , question: "A PSC induction blower motor shows a reading of 0 ohms between the common terminal and the run terminal. What is the most accurate technical diagnosis?", options: ["The motor is in perfect condition since winding resistance in high-efficiency motors tends toward zero.", "There is an internal short circuit in the run winding that nullifies the inductive reactance.", "The internal thermal overload protector is open due to excessive stator overheating.", "The reading is erroneous because the run capacitor was not discharged beforehand."], explanation: "0 ohms indicates total continuity with no resistance, which in a winding means a short circuit. A reading of 'infinity' or 'OL' would indicate an open winding." },
  { id:"calef_2", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Por qué un motor de condensador de 208-230V consume más amperaje si el voltaje cae a 190V mientras mueve la misma carga de aire?", opciones:["Porque la resistencia del cobre aumenta al calentarse por el bajo voltaje.", "Debido a que el motor debe mantener el torque; al caer el voltaje, la corriente sube para igualar la demanda de trabajo (Ley de Watt en cargas inductivas).", "Por el efecto de histéresis magnética en las chapas del estator.", "Es un error de medición común; el amperaje en realidad baja según la Ley de Ohm pura (I=V/R)."], respuesta_correcta:1, explicacion:"En motores de inducción, la potencia es constante para una carga dada. Si el voltaje (V) baja, el amperaje (A) debe subir para mantener los Watts (P=V*A*FP)." , question: "Why does a 208-230V condenser motor draw more amperage if the voltage drops to 190V while moving the same air load?", options: ["Because the copper resistance increases as it heats up due to low voltage.", "Because the motor must maintain torque; when voltage drops, current rises to match the work demand (Watt's Law in inductive loads).", "Due to the magnetic hysteresis effect in the stator laminations.", "It is a common measurement error; the amperage actually drops according to pure Ohm's Law (I=V/R)."], explanation: "In induction motors, power is constant for a given load. If voltage (V) drops, amperage (A) must rise to maintain the watts (P=V*A*PF)." },
  { id:"calef_3", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V entre el terminal 'R' y 'W' de un termostato mientras el horno está encendido y calentando. ¿Qué indica esto?", opciones:["Que el termostato está funcionando correctamente y cerró el contacto.", "Que el contacto del termostato está abierto (falla de continuidad).", "Que hay un cortocircuito en la placa de control principal.", "Es una lectura normal de retorno a través de la bobina del contactor."], respuesta_correcta:1, explicacion:"Si el contacto estuviera cerrado (encendido), la diferencia de potencial sería 0V. Medir 24V significa que el circuito está abierto y estamos midiendo la caída de tensión a través del interruptor." , question: "You measure 24V between the 'R' terminal and the 'W' terminal of a thermostat while the furnace is on and heating. What does this indicate?", options: ["The thermostat is functioning correctly and closed the contact.", "The thermostat contact is open (continuity failure).", "There is a short circuit in the main control board.", "It is a normal return reading through the contactor coil."], explanation: "If the contact were closed (on), the potential difference would be 0V. Measuring 24V means the circuit is open and you are reading the voltage drop across the switch." },
  { id:"calef_4", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor soplador ECM (Electronically Commutated Motor) está programado para 'Flujo Constante'. Si los filtros de aire se ensucian severamente, ¿qué acción tomará el motor automáticamente?", opciones:["Reducirá las RPM para proteger los rodamientos del exceso de torque.", "Aumentará el torque y las RPM para intentar mantener los CFM programados, incrementando el consumo de Watts.", "Se apagará por una señal de error de 'Static Pressure High' enviada por el termostato comunicante.", "Entrará en modo 'Bypass' permitiendo que el aire recircule internamente en la carcasa."], respuesta_correcta:1, explicacion:"Los motores ECM de flujo constante monitorean su propio consumo y velocidad. Si detectan restricción (presión estática alta), aceleran para vencer la resistencia, lo que a menudo los quema si el filtro nunca se cambia." , question: "An ECM (Electronically Commutated Motor) blower motor is programmed for 'Constant Airflow'. If the air filters become severely dirty, what action will the motor take automatically?", options: ["It will reduce RPM to protect the bearings from excess torque.", "It will increase torque and RPM to try to maintain the programmed CFM, increasing watt consumption.", "It will shut down via a 'Static Pressure High' error signal sent by the communicating thermostat.", "It will enter 'Bypass' mode, allowing air to recirculate internally within the housing."], explanation: "Constant airflow ECM motors monitor their own consumption and speed. If they detect restriction (high static pressure), they speed up to overcome the resistance, which often burns them out if the filter is never changed." },
  { id:"calef_5", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un horno eléctrico tiene 3 etapas de calefacción controladas por un secuenciador de calor de '2-4' segundos. Si al apagar el termostato el ventilador sigue encendido por 2 minutos, ¿cuál es el diagnóstico?", opciones:["El secuenciador está defectuoso y tiene los contactos soldados.", "Es una operación normal; el secuenciador tiene un retardo térmico (cool down) para extraer el calor residual de las resistencias.", "El relé del ventilador está pegado en la posición de 'Always On'.", "Existe un retorno de 24V desde el terminal 'G' debido a un error de cableado."], respuesta_correcta:1, explicacion:"Los secuenciadores son dispositivos térmicos. Tardan en cerrar contactos (calentarse) y tardan en abrirlos (enfriarse). Ese retraso es intencional para no enviar aire frío al inicio y enfriar las resistencias al final." , question: "An electric furnace has 3 heating stages controlled by a '2-4' second heat sequencer. If, after turning off the thermostat, the blower continues running for 2 minutes, what is the diagnosis?", options: ["The sequencer is defective and has welded contacts.", "This is normal operation; the sequencer has a thermal cool-down delay to extract residual heat from the heating elements.", "The fan relay is stuck in the 'Always On' position.", "There is a 24V backfeed from the 'G' terminal due to a wiring error."], explanation: "Sequencers are thermal devices. They take time to close contacts (heat up) and time to open them (cool down). This delay is intentional to avoid blowing cold air at startup and to cool the heating elements at shutdown." },
  { id:"calef_6", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 12V AC entre el terminal 'W' y el común 'C' en la placa de un horno de gas mientras el termostato pide calor. ¿Cuál es el diagnóstico?", opciones:["Es un voltaje de 'fantasma' normal en sistemas de estado sólido.", "Existe una caída de tensión excesiva en el cableado o el termostato tiene una alta resistencia de contacto.", "La placa de control está enviando una señal de media onda para ahorrar energía.", "El transformador de 24V está fallando y solo entrega el 50% de su capacidad nominal."], respuesta_correcta:1, explicacion:"En un sistema de 24V, una lectura de 12V indica una caída de tensión masiva. El circuito está 'cerrado' pero la resistencia es tan alta que el voltaje se divide, impidiendo que los relés actúen." , question: "You measure 12V AC between the 'W' terminal and the common 'C' on a gas furnace control board while the thermostat is calling for heat. What is the diagnosis?", options: ["It is a normal 'phantom' voltage in solid-state systems.", "There is excessive voltage drop in the wiring, or the thermostat has high contact resistance.", "The control board is sending a half-wave signal to save energy.", "The 24V transformer is failing and only delivering 50% of its rated capacity."], explanation: "In a 24V system, a 12V reading indicates a massive voltage drop. The circuit is 'closed' but the resistance is so high that the voltage divides, preventing relays from actuating." },
  { id:"calef_7", categoria:"CALEF_ELECTRICIDAD", pregunta:"En un sistema de control digital (DDC), un sensor de temperatura de 10k Ohmios tipo Tipo II muestra 'Open Circuit' en el controlador. Al medir con el multímetro en el sensor, lee 10,500 Ohmios. ¿Dónde está el problema?", opciones:["El sensor está descalibrado por 500 Ohmios.", "El cableado entre el sensor y el controlador está roto o desconectado.", "El controlador necesita un puente (jumper) de terminación de 120 Ohmios.", "El sensor es de coeficiente positivo y debería ser negativo."], respuesta_correcta:1, explicacion:"Si el sensor lee bien en sus terminales pero el controlador ve 'circuito abierto', el fallo está en la infraestructura de cables que lleva la señal." , question: "In a digital direct control (DDC) system, a 10k-ohm Type II temperature sensor shows 'Open Circuit' on the controller. When measuring the sensor with a multimeter, it reads 10,500 ohms. Where is the problem?", options: ["The sensor is out of calibration by 500 ohms.", "The wiring between the sensor and the controller is broken or disconnected.", "The controller needs a 120-ohm termination jumper.", "The sensor has a positive temperature coefficient and should be negative."], explanation: "If the sensor reads correctly at its terminals but the controller sees 'open circuit,' the fault lies in the cable infrastructure carrying the signal." },
  { id:"calef_8", categoria:"CALEF_ELECTRICIDAD", pregunta:"En un motor de inducción trifásico utilizado en grandes manejadoras de aire, ¿qué ocurre si se pierde una de las tres fases (single-phasing) mientras el motor está en marcha?", opciones:["El motor se detiene instantáneamente por falta de campo magnético rotativo.", "El motor continúa girando pero el amperaje en las dos fases restantes aumenta drásticamente, lo que quemará los devanados si no hay protección térmica adecuada.", "La velocidad del motor se reduce exactamente a un tercio de las RPM nominales.", "El motor invierte su sentido de giro automáticamente por la ley de Lenz."], respuesta_correcta:1, explicacion:"Un motor trifásico puede seguir girando con dos fases si ya tiene inercia, pero no podrá arrancar de nuevo. La carga se distribuye en solo dos cables, elevando el calor por efecto Joule hasta destruir el aislante." , question: "In a three-phase induction motor used in large air handlers, what happens if one of the three phases is lost (single-phasing) while the motor is running?", options: ["The motor stops instantly due to the loss of the rotating magnetic field.", "The motor continues running but the amperage in the two remaining phases increases drastically, which will burn the windings if there is no adequate thermal protection.", "The motor speed is reduced to exactly one-third of the rated RPM.", "The motor automatically reverses its direction of rotation due to Lenz's law."], explanation: "A three-phase motor can continue spinning on two phases if it already has inertia, but it cannot restart. The load is distributed across only two conductors, raising heat through the Joule effect until it destroys the insulation." },
  { id:"calef_9", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor de soplador PSC tiene un capacitor de 5 mFD. Si el técnico instala por error uno de 15 mFD, ¿qué efecto tendrá a corto plazo?", opciones:["El motor girará más rápido y consumirá menos energía.", "El motor se sobrecalentará debido a un exceso de corriente en el devanado auxiliar y fallará prematuramente.", "El torque de arranque será nulo y el motor no podrá vencer la inercia.", "El voltaje de línea se estabilizará gracias al factor de potencia corregido."], respuesta_correcta:1, explicacion:"Un capacitor demasiado grande permite el paso de demasiada corriente por el devanado de arranque/marcha, lo que genera calor excesivo en el cobre y quema el aislante." , question: "A PSC blower motor has a 5 MFD capacitor. If the technician mistakenly installs a 15 MFD capacitor, what effect will this have in the short term?", options: ["The motor will spin faster and consume less energy.", "The motor will overheat due to excessive current in the auxiliary winding and will fail prematurely.", "The starting torque will be zero and the motor will not be able to overcome inertia.", "The line voltage will stabilize thanks to the corrected power factor."], explanation: "An oversized capacitor allows too much current through the start/run winding, generating excessive heat in the copper and burning the insulation." },
  { id:"calef_10", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Por qué no se debe usar un multímetro de baja impedancia (LoZ) para medir señales de microamperios en un circuito de sensor de llama?", opciones:["Porque la baja impedancia del medidor 'carga' el circuito y drena la pequeña corriente, dando una lectura de cero o errónea.", "Debido a que el multímetro podría quemar el electrodo de porcelana.", "La función LoZ solo sirve para medir voltajes fantasma en líneas de alta tensión.", "No hay problema, de hecho es el método recomendado por los fabricantes de Carrier y York."], respuesta_correcta:0, explicacion:"La señal de ionización es de apenas millonésimas de amperio. Un medidor LoZ actúa como una resistencia baja que desvía esa corriente, impidiendo ver la señal real que recibe la placa." , question: "Why should you not use a low-impedance (LoZ) multimeter to measure microamp signals in a flame sensor circuit?", options: ["Because the meter's low impedance 'loads' the circuit and drains the small current, giving a zero or erroneous reading.", "Because the multimeter could burn the porcelain electrode.", "The LoZ function is only for measuring phantom voltages on high-voltage lines.", "There is no problem; in fact, it is the recommended method by Carrier and York manufacturers."], explanation: "The ionization signal is only millionths of an ampere. A LoZ meter acts as a low resistance that diverts that current, preventing you from seeing the real signal that the board receives." },
  { id:"calef_11", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor ECM de torque constante (X13) recibe señales de 24V en sus terminales de velocidad. Si se activan accidentalmente 'Heat' y 'Cool' al mismo tiempo, ¿qué hace el motor?", opciones:["Se detiene para evitar un cortocircuito en el microprocesador.", "Prioriza la velocidad más alta programada para proteger el intercambiador de calor o evitar congelamiento.", "Gira a la mitad de la velocidad de cada señal sumada.", "Explota el módulo de control debido a un conflicto de fases lógicas."], respuesta_correcta:1, explicacion:"La mayoría de los motores ECM están programados con una lógica de 'prioridad de seguridad'. La velocidad de enfriamiento (Cool) suele ser la más alta, o bien el firmware prioriza evitar el sobrecalentamiento." , question: "A constant-torque ECM motor (X13) receives 24V signals at its speed terminals. If 'Heat' and 'Cool' are accidentally activated at the same time, what does the motor do?", options: ["It stops to prevent a short circuit in the microprocessor.", "It prioritizes the highest programmed speed to protect the heat exchanger or prevent freezing.", "It spins at half the speed of each combined signal.", "The control module blows up due to a logic phase conflict."], explanation: "Most ECM motors are programmed with a 'safety priority' logic. The cooling speed (Cool) is usually the highest, or the firmware prioritizes preventing overheating." },
  { id:"calef_12", categoria:"CALEF_ELECTRICIDAD", pregunta:"En un sistema comunicante (ClimateTalk o similar), usted mide 0V DC entre los terminales de datos (A y B) mientras el equipo está encendido. ¿Qué diagnóstico es el más probable?", opciones:["La comunicación está funcionando perfectamente en modo binario puro.", "Hay un cortocircuito en el bus de datos o la resistencia de terminación está dañada.", "El termostato está en modo 'Legacy' y no requiere voltaje en esos pines.", "Los cables están invertidos con el común de 24V."], respuesta_correcta:1, explicacion:"Los sistemas comunicantes HVAC operan con una pequeña tensión DC (usualmente entre 2V y 5V) para transmitir paquetes de datos. 0V indica que la señal se está yendo a tierra o hay un corto físico." , question: "In a communicating system (ClimateTalk or similar), you measure 0V DC between the data terminals (A and B) while the equipment is powered on. What is the most likely diagnosis?", options: ["Communication is working perfectly in pure binary mode.", "There is a short circuit on the data bus or the termination resistor is damaged.", "The thermostat is in 'Legacy' mode and does not require voltage on those pins.", "The cables are reversed with the 24V common."], explanation: "Communicating HVAC systems operate with a small DC voltage (usually between 2V and 5V) to transmit data packets. 0V indicates the signal is going to ground or there is a physical short." },
  { id:"calef_13", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted instala un termostato inteligente y un relé de zona adicional. El transformador original de 40VA comienza a vibrar y se siente muy caliente. ¿Qué debe calcular?", opciones:["La resistencia de los cables hacia el condensador exterior.", "La carga total en VA (Volt-Amperios) de todos los componentes de control para no exceder la capacidad del transformador.", "La impedancia del devanado primario en relación con la frecuencia de 60Hz.", "El factor de potencia del motor del soplador únicamente."], respuesta_correcta:1, explicacion:"Cada solenoide, relé y termostato consume VA. Si la suma supera los 40VA del transformador, este se sobrecalentará, el voltaje caerá y eventualmente se quemará el fusible térmico interno." , question: "You install a smart thermostat and an additional zone relay. The original 40VA transformer begins to vibrate and feels very hot. What should you calculate?", options: ["The resistance of the cables to the outdoor condenser.", "The total VA (Volt-Ampere) load of all control components to ensure the transformer capacity is not exceeded.", "The impedance of the primary winding relative to the 60Hz frequency.", "The power factor of the blower motor only."], explanation: "Each solenoid, relay, and thermostat consumes VA. If the sum exceeds the transformer's 40VA rating, it will overheat, the voltage will drop, and eventually the internal thermal fuse will blow." },
  { id:"calef_14", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 0 ohmios de resistencia en la bobina de un contactor de 24V. ¿Qué sucederá cuando el termostato pida calor?", opciones:["El contactor cerrará con mucha fuerza magnética.", "Se quemará el fusible de 3 o 5 amperios de la placa de control debido a un cortocircuito.", "El sistema funcionará pero consumirá más vatios de lo normal.", "La bobina actuará como un capacitor de marcha secundario."], respuesta_correcta:1, explicacion:"0 ohmios significa que no hay resistencia (cortocircuito). Al aplicar 24V, la corriente será infinita (teóricamente), lo que funde el fusible de protección inmediatamente." , question: "You measure 0 ohms resistance across the coil of a 24V contactor. What will happen when the thermostat calls for heat?", options: ["The contactor will close with very strong magnetic force.", "The 3A or 5A fuse on the control board will blow due to a short circuit.", "The system will work but will consume more watts than normal.", "The coil will act as a secondary run capacitor."], explanation: "0 ohms means there is no resistance (short circuit). When 24V is applied, the current will be infinite (theoretically), which blows the protective fuse immediately." },
  { id:"calef_15", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor ECM reporta una falla de 'Overvoltage' interna pero el voltaje de línea es correcto (120V). ¿Cuál es la causa técnica capciosa?", opciones:["Un capacitor de marcha externo defectuoso.", "El motor está siendo 'arrastrado' por un flujo de aire externo (viento en los ductos), actuando como generador y enviando voltaje de retorno al módulo.", "La placa de control del horno está enviando 24V DC en lugar de AC.", "El sensor de efecto Hall está detectando demasiada humedad en el estator."], respuesta_correcta:1, explicacion:"Si el ventilador gira por aire externo mientras el motor está apagado, los imanes permanentes generan electricidad (Back-EMF) que el módulo interpreta como un pico de voltaje." , question: "An ECM motor reports an internal 'Overvoltage' fault, but the line voltage is correct (120V). What is the tricky technical cause?", options: ["A defective external run capacitor.", "The motor is being 'dragged' by external airflow (wind through the ductwork), acting as a generator and sending back-EMF voltage to the module.", "The furnace control board is sending 24V DC instead of AC.", "The Hall effect sensor is detecting too much moisture in the stator."], explanation: "If the blower wheel spins due to external air while the motor is off, the permanent magnets generate electricity (back-EMF) that the module interprets as a voltage spike." },
  { id:"calef_16", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Por qué se recomienda el uso de cables blindados y anillos de conexión a tierra en el eje (shaft grounding rings) al alimentar un motor de soplador con un Variador de Frecuencia (VFD)?", opciones:["Para aumentar la capacitancia del devanado y mejorar el torque de arranque.", "Para prevenir que las corrientes parásitas de alta frecuencia (EDM) destruyan los rodamientos del motor por erosión eléctrica.", "Debido a que el VFD genera un voltaje de corriente directa constante que atrae partículas de polvo metálico.", "Es una medida estética para cumplir con las normas de cableado estructurado en cuartos de máquinas."], respuesta_correcta:1, explicacion:"Los VFD generan picos de voltaje rápidos (PWM) que pueden inducir voltajes en el eje del motor. Sin un camino a tierra, esta electricidad salta a través de los rodamientos, creando micro-cráteres que causan fallas prematuras." , question: "Why is the use of shielded cables and shaft grounding rings recommended when powering a blower motor with a Variable Frequency Drive (VFD)?", options: ["To increase the winding capacitance and improve starting torque.", "To prevent high-frequency parasitic currents (EDM) from destroying the motor bearings through electrical erosion.", "Because the VFD generates a constant DC voltage that attracts metallic dust particles.", "It is a cosmetic measure to comply with structured cabling standards in mechanical rooms."], explanation: "VFDs generate rapid voltage spikes (PWM) that can induce voltages on the motor shaft. Without a path to ground, this electricity arcs through the bearings, creating micro-craters that cause premature failure." },
  { id:"calef_17", categoria:"CALEF_ELECTRICIDAD", pregunta:"En un sistema con protocolo BACnet, ¿qué define técnicamente a un 'Objeto' (Object)?", opciones:["Es el hardware físico del controlador.", "Una estructura de datos que representa una entrada, salida o valor de software, con propiedades como 'Present_Value' y 'Status_Flags'.", "El cable de par trenzado que conecta los dispositivos.", "La dirección IP asignada al enrutador maestro."], respuesta_correcta:1, explicacion:"BACnet organiza la información en objetos. Por ejemplo, un sensor de temperatura es un 'Analog Input Object' que contiene no solo el valor, sino también sus unidades y estado de alarma." , question: "In a BACnet protocol system, what technically defines an 'Object'?", options: ["It is the physical hardware of the controller.", "A data structure that represents an input, output, or software value, with properties such as 'Present_Value' and 'Status_Flags'.", "The twisted-pair cable that connects the devices.", "The IP address assigned to the master router."], explanation: "BACnet organizes information into objects. For example, a temperature sensor is an 'Analog Input Object' that contains not only the value but also its units and alarm status." },
  { id:"calef_18", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted detecta que un motor ECM emite un pitido agudo (high-pitched whine) mientras está apagado pero con energía aplicada. ¿Qué componente del módulo está fallando?", opciones:["El termistor de protección de entrada (Inrush Current Limiter).", "Los capacitores de filtrado del bus DC que están perdiendo su ESR (Resistencia Serie Equivalente).", "El devanado de cobre del estator por falta de barniz dieléctrico.", "El puente rectificador de onda completa."], respuesta_correcta:1, explicacion:"Los ruidos de alta frecuencia en módulos ECM en reposo suelen ser causados por capacitores secos o fallas en la fuente conmutada interna que intenta mantener el microcontrolador encendido." , question: "You detect that an ECM motor emits a high-pitched whine while it is off but with power applied. What component in the module is failing?", options: ["The input protection thermistor (Inrush Current Limiter).", "The DC bus filter capacitors that are losing their ESR (Equivalent Series Resistance).", "The stator copper winding due to lack of dielectric varnish.", "The full-wave bridge rectifier."], explanation: "High-frequency noises in idle ECM modules are usually caused by dry capacitors or failures in the internal switching power supply that is trying to keep the microcontroller powered." },
  { id:"calef_19", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si un transformador de control de 24V se quema repetidamente al activar el modo de calefacción, y el solenoide de gas mide 15 ohmios, ¿qué otra carga podría ser la culpable?", opciones:["Un cable de termostato pelado que hace contacto intermitente con el chasis (tierra) solo cuando el relé de calor se activa.", "El sensor de llama que está enviando demasiados microamperios.", "El interruptor de límite que tiene una resistencia de 0.2 ohmios.", "La batería del termostato digital que está descargada."], respuesta_correcta:0, explicacion:"Un corto a tierra en el cableado de control es la causa número uno de transformadores quemados. Ocurre a menudo donde el cable entra al gabinete del condensador o del horno sin protección (grommet)." , question: "If a 24V control transformer repeatedly burns out when heating mode is activated, and the gas valve solenoid measures 15 ohms, what other load could be the culprit?", options: ["A stripped thermostat wire making intermittent contact with the chassis (ground) only when the heating relay engages.", "The flame sensor sending too many microamps.", "The limit switch that has a resistance of 0.2 ohms.", "The dead battery in the digital thermostat."], explanation: "A short to ground in the control wiring is the number one cause of burned transformers. It often occurs where the wire enters the condenser or furnace cabinet without a protective grommet." },
  { id:"calef_20", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué indica un aumento súbito en el consumo de amperaje de un motor de soplador si la presión estática y el voltaje se mantienen constantes?", opciones:["Que el filtro de aire se ha caído y no hay restricción.", "Falla inminente de los rodamientos o un cortocircuito entre espiras en el devanado del estator.", "Que el termostato está pidiendo 'Fan On' en lugar de 'Auto'.", "Un aumento en la humedad específica del aire de retorno."], respuesta_correcta:1, explicacion:"Si la carga (aire) no ha cambiado, el aumento de corriente es interno al motor. La fricción mecánica o la pérdida de aislamiento eléctrico obligan al motor a consumir más energía antes de fallar." , question: "What does a sudden increase in blower motor amperage indicate if the static pressure and voltage remain constant?", options: ["The air filter has fallen out and there is no restriction.", "Imminent bearing failure or a turn-to-turn short circuit in the stator winding.", "The thermostat is calling for 'Fan On' instead of 'Auto'.", "An increase in the specific humidity of the return air."], explanation: "If the load (air) has not changed, the current increase is internal to the motor. Mechanical friction or loss of electrical insulation forces the motor to consume more energy before failing." },
  { id:"calef_21", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor de soplador de 1/2 HP se reemplaza por uno de 1 HP del mismo tipo y voltaje. Si la carga (el ventilador) sigue siendo la misma, ¿qué sucederá con el amperaje?", opciones:["El amperaje se duplicará porque el motor es el doble de potente.", "El amperaje será casi el mismo que el motor original, ya que el amperaje depende de la carga de aire movida, no de la capacidad nominal del motor.", "El motor girará al doble de RPM y el amperaje subirá al cubo.", "El factor de potencia bajará tanto que el medidor de luz se detendrá."], respuesta_correcta:1, explicacion:"Un motor consume corriente en función del trabajo que realiza. Si el ventilador no cambia, el trabajo es el mismo. El motor de 1 HP simplemente estará 'sobrado' y trabajará más frío." , question: "A 1/2 HP blower motor is replaced with a 1 HP motor of the same type and voltage. If the load (the fan wheel) remains the same, what will happen with the amperage?", options: ["The amperage will double because the motor is twice as powerful.", "The amperage will be nearly the same as the original motor, since amperage depends on the air load being moved, not the motor's rated capacity.", "The motor will spin at double the RPM and the amperage will rise by a factor of three.", "The power factor will drop so much that the electric meter will stop."], explanation: "A motor draws current based on the work it performs. If the fan wheel does not change, the work is the same. The 1 HP motor will simply be oversized and will run cooler." },
  { id:"calef_22", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Cuál es el efecto de una 'Baja Resistencia de Aislamiento' (Low Megohm reading) en un compresor de bomba de calor que aún funciona?", opciones:["El compresor consume menos amperaje por menor fricción electrónica.", "Indica una degradación del barniz de los devanados, lo que eventualmente causará un corto a tierra catastrófico.", "Mejora el factor de potencia del sistema de calefacción.", "Es una lectura normal en sistemas que usan aceite POE debido a su higroscopicidad."], respuesta_correcta:1, explicacion:"Una lectura baja en el megóhmetro avisa que el aislamiento está fallando. Es un diagnóstico preventivo: el motor 'morirá' pronto aunque hoy parezca funcionar bien." , question: "What is the effect of 'Low Insulation Resistance' (low megohm reading) in a heat pump compressor that still operates?", options: ["The compressor draws less amperage due to lower electronic friction.", "It indicates degradation of the winding varnish, which will eventually cause a catastrophic ground fault.", "It improves the power factor of the heating system.", "It is a normal reading in systems using POE oil due to its hygroscopic nature."], explanation: "A low megohmmeter reading warns that the insulation is failing. It is a preventive diagnosis: the motor will 'die' soon even though it appears to work fine today." },
  { id:"calef_23", categoria:"CALEF_ELECTRICIDAD", pregunta:"En una red MS/TP (BACnet), ¿por qué es crítico respetar la polaridad de los cables (+) y (-)?", opciones:["Para evitar que el transformador de 24V se queme.", "Porque las señales RS-485 son diferenciales; una inversión de cables impedirá que los dispositivos se entiendan (ruido vs señal).", "Si se invierten, el motor del ventilador girará al revés.", "La polaridad determina la dirección del flujo de aire en los ductos."], respuesta_correcta:1, explicacion:"RS-485 compara el voltaje entre dos cables. Si los cruzas, el '1' lógico se lee como '0', y la comunicación se rompe totalmente en ese segmento de la red." , question: "In an MS/TP (BACnet) network, why is it critical to maintain the polarity of the (+) and (-) wires?", options: ["To prevent the 24V transformer from burning out.", "Because RS-485 signals are differential; reversing the wires will prevent devices from communicating (noise vs. signal).", "If reversed, the fan motor will spin in reverse.", "The polarity determines the direction of airflow in the ductwork."], explanation: "RS-485 compares the voltage between two wires. If you swap them, a logical '1' is read as '0,' and communication breaks down completely on that network segment." },
  { id:"calef_24", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un horno está 'polarizado inversamente' (Línea y Neutro cambiados). ¿Qué síntoma técnico presentará el equipo?", opciones:["El motor del soplador girará al revés.", "El horno encenderá la llama pero se apagará a los pocos segundos porque el circuito de detección de llama no puede rectificar la señal a tierra.", "El transformador de 24V explotará instantáneamente.", "No hay síntoma, los sistemas AC no dependen de la polaridad."], respuesta_correcta:1, explicacion:"Capciosa: Aunque es corriente alterna, la detección de llama usa el neutro como referencia de tierra. Si los cables están invertidos, la placa no puede leer los microamperios y corta el gas por seguridad." , question: "A furnace has 'reverse polarity' (Line and Neutral swapped). What technical symptom will the equipment present?", options: ["The blower motor will spin in reverse.", "The furnace will ignite the flame but shut down within seconds because the flame detection circuit cannot rectify the signal to ground.", "The 24V transformer will explode instantly.", "There is no symptom; AC systems do not depend on polarity."], explanation: "Tricky: Although it is alternating current, flame detection uses the neutral as a ground reference. If the wires are swapped, the board cannot read the microamps and shuts off the gas as a safety measure." },
  { id:"calef_25", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un sensor de CO2 en un sistema de ventilación por demanda (DCV) marca 1200 ppm. ¿Qué acción debe tomar el controlador?", opciones:["Cerrar todas las entradas de aire exterior.", "Abrir los dampers de aire exterior para diluir la concentración y mejorar la calidad del aire interior.", "Apagar el horno inmediatamente por riesgo de asfixia.", "Actuar sobre la válvula de gas para reducir la llama."], respuesta_correcta:1, explicacion:"1200 ppm indica que hay mucha gente o poca ventilación. El sistema 'mete' aire fresco de la calle para bajar ese nivel según los estándares de salud ocupacional." , question: "A CO2 sensor in a Demand Controlled Ventilation (DCV) system reads 1200 ppm. What action should the controller take?", options: ["Close all outdoor air intakes.", "Open the outdoor air dampers to dilute the concentration and improve indoor air quality.", "Shut down the furnace immediately due to asphyxiation risk.", "Act on the gas valve to reduce the flame."], explanation: "1200 ppm indicates high occupancy or insufficient ventilation. The system brings in fresh outdoor air to lower that level according to occupational health standards." },
  { id:"calef_26", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si un elemento calefactor de 240V tiene una resistencia de 12 ohmios, ¿cuántos amperios consumirá?", opciones:["10 amperios.", "20 amperios.", "2880 amperios.", "12 amperios."], respuesta_correcta:1, explicacion:"Ley de Ohm: $I = V / R$. $240 / 12 = 20$. Saber esto es básico para diagnosticar si una resistencia está funcionando bien con una pinza amperimétrica." , question: "If a 240V heating element has a resistance of 12 ohms, how many amps will it draw?", options: ["10 amps.", "20 amps.", "2880 amps.", "12 amps."], explanation: "Ohm's Law: I = V / R. 240 / 12 = 20. Knowing this is fundamental for diagnosing whether a heating element is functioning properly with a clamp meter." },
  { id:"calef_27", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué sucede si usted desconecta el arnés de control de 5 o 16 pines de un motor ECM mientras tiene energía de 120/240V aplicada?", opciones:["Nada, el motor se detiene suavemente.", "Puede dañar permanentemente el microprocesador del módulo de control debido a arcos eléctricos o picos de voltaje.", "El motor acelerará hasta explotar por falta de límite de velocidad.", "Se borrará la programación de la placa madre del horno."], respuesta_correcta:1, explicacion:"Regla de oro: Primero corta la energía total, luego desconecta el control. Los ECM son computadoras sensibles; un chispazo en los pines de datos puede freír el módulo." , question: "What happens if you disconnect the 5-pin or 16-pin control harness from an ECM motor while 120/240V power is applied?", options: ["Nothing; the motor stops smoothly.", "You can permanently damage the control module's microprocessor due to electrical arcing or voltage spikes.", "The motor will accelerate until it explodes due to the lack of a speed limit.", "The furnace motherboard's programming will be erased."], explanation: "Golden rule: First cut all power, then disconnect the control. ECMs are sensitive computers; a spark on the data pins can fry the module." },
  { id:"calef_28", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un relé SPDT tiene tres terminales de carga. ¿Qué significan?", opciones:["Start, Power, Drive, Torque.", "Common, Normally Open (NO), Normally Closed (NC).", "Suelo, Pared, Ducto, Techo.", "24V, 120V, 240V."], respuesta_correcta:1, explicacion:"Single Pole Double Throw. Es un interruptor que puede desviar la corriente hacia un camino u otro (ej: o prendo el calor o prendo el ventilador)." , question: "An SPDT relay has three load terminals. What do they stand for?", options: ["Start, Power, Drive, Torque.", "Common, Normally Open (NO), Normally Closed (NC).", "Floor, Wall, Duct, Ceiling.", "24V, 120V, 240V."], explanation: "Single Pole Double Throw. It is a switch that can divert current to one path or another (e.g., either turn on heating or turn on the fan)." },
  { id:"calef_29", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si un motor tiene un capacitor de arranque (Start Capacitor) y un relé de potencial, ¿qué sucede si el relé se queda pegado 'cerrado'?", opciones:["El motor funcionará con más fuerza.", "El capacitor de arranque explotará en pocos segundos porque no está diseñado para estar bajo tensión continua.", "El motor consumirá la mitad de los amperios.", "El termostato se reiniciará por interferencia magnética."], respuesta_correcta:1, explicacion:"El capacitor de arranque solo debe estar en el circuito por un segundo. Si no se desconecta, se sobrecalienta y 'explota' (abre su válvula de seguridad)." , question: "If a motor has a start capacitor and a potential relay, what happens if the relay gets stuck 'closed'?", options: ["The motor will run with more power.", "The start capacitor will explode within seconds because it is not designed to be under continuous voltage.", "The motor will draw half the amps.", "The thermostat will reset due to magnetic interference."], explanation: "The start capacitor should only be in the circuit for about one second. If it is not disconnected, it overheats and 'explodes' (its safety valve opens)." },
  { id:"calef_30", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V entre el terminal 'C' y el chasis del horno. ¿Es esto correcto?", opciones:["Sí, el común siempre tiene voltaje.", "No, el terminal común 'C' debe estar conectado a tierra; la lectura debería ser 0V o muy cercana.", "Depende de si el horno es de 120V o 240V.", "Solo si el motor del soplador está encendido."], respuesta_correcta:1, explicacion:"Si hay 24V hacia tierra, hay un problema de cableado o el transformador no está referenciado a tierra. Esto causa que los sensores de llama fallen constantemente." , question: "You measure 24V between the 'C' terminal and the furnace chassis. Is this correct?", options: ["Yes, the common always has voltage.", "No, the common 'C' terminal should be connected to ground; the reading should be 0V or very close to it.", "It depends on whether the furnace is 120V or 240V.", "Only if the blower motor is running."], explanation: "If there is 24V to ground, there is a wiring problem or the transformer is not referenced to ground. This causes flame sensors to fail constantly." },
  { id:"calef_31", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 120V en el terminal de un motor soplador, pero el motor no gira y está frío al tacto. ¿Cuál es el diagnóstico más probable?", opciones:["El motor está quemado internamente.", "El devanado del motor está abierto (cable roto por dentro o protector térmico quemado).", "El capacitor de marcha está en cortocircuito.", "El voltaje de 120V es en realidad un voltaje fantasma."], respuesta_correcta:1, explicacion:"Si tiene voltaje y no está caliente, no hay flujo de corriente. El camino eléctrico está roto. Si estuviera trabado mecánicamente, el motor estaría ardiendo al tacto." , question: "You measure 120V at a blower motor terminal, but the motor is not spinning and is cold to the touch. What is the most likely diagnosis?", options: ["The motor is internally burned out.", "The motor winding is open (internal broken wire or burned thermal protector).", "The run capacitor is short-circuited.", "The 120V is actually a phantom voltage."], explanation: "If it has voltage and is not hot, no current is flowing. The electrical path is broken. If it were mechanically seized, the motor would be hot to the touch." },
  { id:"calef_32", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si un transformador de 40VA alimenta un circuito de 24V, ¿cuál es el amperaje máximo que puede entregar antes de quemarse?", opciones:["40 amperios.", "1.66 amperios.", "0.6 amperios.", "24 amperios."], respuesta_correcta:1, explicacion:"Fórmula: $Amperios = VA / Voltaje$. $40 / 24 = 1.66$. Si conectas demasiados relés o accesorios, superarás este límite y el transformador morirá." , question: "If a 40VA transformer powers a 24V circuit, what is the maximum amperage it can deliver before burning out?", options: ["40 amps.", "1.66 amps.", "0.6 amps.", "24 amps."], explanation: "Formula: Amps = VA / Voltage. 40 / 24 = 1.66. If you connect too many relays or accessories, you will exceed this limit and the transformer will fail." },
  { id:"calef_33", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un ignitor de superficie caliente (HSI) de nitruro de silicio mide 75 ohmios en frío. Si al aplicar 120V no brilla y la resistencia ahora es 'OL', ¿qué sucedió?", opciones:["El ignitor entró en un estado de superconductividad térmica.", "El elemento cerámico tiene una micro-fractura que se expandió con el calor, abriendo el circuito (falla por fatiga).", "La placa de control invirtió la polaridad del neutro.", "Es una lectura normal ya que el nitruro de silicio no conduce electricidad."], respuesta_correcta:1, explicacion:"Los ignitores HSI son frágiles. Una grieta invisible puede dar continuidad en frío, pero al dilatarse por el calor, el circuito se rompe y el horno no enciende." , question: "A silicon nitride Hot Surface Igniter (HSI) measures 75 ohms when cold. If 120V is applied and it does not glow, and the resistance now reads 'OL', what happened?", options: ["The igniter entered a state of thermal superconductivity.", "The ceramic element has a micro-fracture that expanded with heat, opening the circuit (fatigue failure).", "The control board reversed the neutral polarity.", "This is a normal reading since silicon nitride does not conduct electricity."], explanation: "HSI igniters are fragile. An invisible crack can give continuity when cold, but as it expands with heat, the circuit breaks and the furnace will not ignite." },
  { id:"calef_34", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor soplador controlado por VFD emite un silbido agudo constante. El técnico cambia la 'Frecuencia de Portadora' (Carrier Frequency) de 2kHz a 8kHz. ¿Qué efecto tiene esto?", opciones:["El motor girará 4 veces más rápido.", "El ruido audible disminuye (se vuelve ultrasónico), pero el VFD generará más calor interno y más interferencia electromagnética.", "El consumo de amperaje bajará a la mitad debido a la resonancia magnética.", "El motor perderá el 50% de su torque de arranque."], respuesta_correcta:1, explicacion:"Subir la frecuencia de portadora hace que el motor sea más silencioso para el oído humano, pero fuerza más a los transistores (IGBT) del variador, calentándolo más." , question: "A VFD-controlled blower motor emits a constant high-pitched whine. The technician changes the 'Carrier Frequency' from 2kHz to 8kHz. What effect does this have?", options: ["The motor will spin 4 times faster.", "The audible noise decreases (becomes ultrasonic), but the VFD will generate more internal heat and more electromagnetic interference.", "The amperage draw will drop by half due to magnetic resonance.", "The motor will lose 50% of its starting torque."], explanation: "Raising the carrier frequency makes the motor quieter to the human ear but puts more stress on the VFD's transistors (IGBTs), causing them to run hotter." },
  { id:"calef_35", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V entre 'W' y 'C' en la placa de control, el motor inductor corre, pero el ignitor nunca enciende. ¿Qué componente revisaría primero después del interruptor de presión?", opciones:["El sensor de llama (flame rod).", "El interruptor de límite de alta temperatura (High Limit) y los fusibles térmicos de roll-out.", "El capacitor de marcha del motor soplador.", "La resistencia de los cables del termostato."], respuesta_correcta:1, explicacion:"Si el límite de seguridad está abierto, la placa permitirá que el inductor corra (para enfriar), pero nunca enviará energía al ignitor ni a la válvula de gas por seguridad." , question: "You measure 24V between 'W' and 'C' on the control board, the inducer motor runs, but the igniter never fires. What component would you check first after the pressure switch?", options: ["The flame sensor (flame rod).", "The high-temperature limit switch (High Limit) and the roll-out thermal fuses.", "The blower motor run capacitor.", "The thermostat wire resistance."], explanation: "If the high-temperature limit safety is open, the board will allow the inducer to run (to cool down), but it will never send power to the igniter or the gas valve for safety reasons." },
  { id:"calef_36", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un técnico encuentra un capacitor de 45+5 mFD. El lado de 45 mFD mide 32 mFD. ¿Qué efecto tiene esto en el sistema de calefacción (Bomba de Calor)?", opciones:["El compresor consumirá menos energía y vibrará menos.", "El compresor tendrá dificultad para arrancar, se calentará en exceso y el amperaje de marcha subirá, reduciendo su vida útil.", "El ventilador exterior girará en sentido contrario.", "No hay efecto hasta que la capacitancia llegue a cero."], respuesta_correcta:1, explicacion:"Un capacitor débil reduce el torque y desfasa el campo magnético. El motor 'sufre' eléctricamente, genera más calor y puede quemarse o disparar el protector interno." , question: "A technician finds a 45+5 MFD dual capacitor. The 45 MFD side reads 32 MFD. What effect does this have on the heating system (heat pump)?", options: ["The compressor will use less energy and vibrate less.", "The compressor will have difficulty starting, will overheat excessively, and run amperage will increase, drastically reducing its lifespan.", "The outdoor fan will spin in the opposite direction.", "There is no effect until the capacitance reaches zero."], explanation: "A weak capacitor reduces torque and shifts the magnetic field out of phase. The motor 'suffers' electrically, generates more heat, and can burn out or trip the internal protector." },
  { id:"calef_37", categoria:"CALEF_ELECTRICIDAD", pregunta:"En un sistema comunicante, ¿qué sucede si se utiliza cable de termostato estándar (no trenzado) en una tirada de 150 pies cerca de cables de alta tensión?", opciones:["El sistema funcionará con un ligero retraso de 2 segundos.", "La interferencia electromagnética (EMI) corromperá los paquetes de datos, causando errores intermitentes de comunicación o bloqueo del sistema.", "El voltaje de 24V subirá a 120V por inducción.", "Las señales de datos se convertirán en señales de audio audibles en el horno."], respuesta_correcta:1, explicacion:"Los datos digitales son pulsos rápidos. Los cables de fuerza inducen ruido que 'ensucia' la señal. Para tiradas largas o ruidosas, se requiere cable blindado o trenzado (twisted pair)." , question: "In a communicating system, what happens if standard (non-twisted) thermostat wire is used in a 150-foot run near high-voltage cables?", options: ["The system will operate with a slight 2-second delay.", "Electromagnetic interference (EMI) will corrupt data packets, causing intermittent communication errors or system lockup.", "The 24V voltage will spike to 120V due to induction.", "The data signals will convert into audible audio signals in the furnace."], explanation: "Digital data consists of rapid pulses. Power cables induce noise that 'dirties' the signal. For long or noisy runs, shielded or twisted-pair cable is required." },
  { id:"calef_38", categoria:"CALEF_ELECTRICIDAD", pregunta:"En un motor trifásico, si intercambiamos dos de los tres cables de alimentación, ¿qué sucede?", opciones:["El motor consume el doble de amperaje.", "El sentido de giro del motor se invierte.", "El motor se bloquea magnéticamente y zumba sin girar.", "El voltaje se duplica por el efecto de fase invertida."], respuesta_correcta:1, explicacion:"Básico de electricidad industrial. Al cambiar dos cables, cambias la secuencia de fases del campo magnético rotatorio, haciendo que el ventilador o compresor gire al revés." , question: "In a three-phase motor, if you swap two of the three supply wires, what happens?", options: ["The motor draws double the amperage.", "The direction of rotation reverses.", "The motor locks up magnetically and hums without spinning.", "The voltage doubles due to the inverted phase effect."], explanation: "Basic industrial electrical principle. By swapping two wires, you change the phase sequence of the rotating magnetic field, causing the fan or compressor to spin in reverse." },
  { id:"calef_39", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 120V en el terminal de un relé, pero al conectar la carga, el voltaje cae a 10V. ¿Qué indica esto?", opciones:["Que la carga está en cortocircuito.", "Una conexión suelta o de alta resistencia en el circuito (ej. un cable quemado o contacto de relé picado) que no soporta el flujo de corriente.", "Que el multímetro está en modo de corriente directa por error.", "Es un fenómeno normal de inductancia mutua."], respuesta_correcta:1, explicacion:"Es el clásico 'voltaje fantasma'. Hay continuidad pero no hay 'fuerza'. Una conexión pobre deja pasar el voltaje pero al pedir amperaje, toda la energía se pierde en el punto de mala conexión (calor)." , question: "You measure 120V at a relay terminal, but when you connect the load, the voltage drops to 10V. What does this indicate?", options: ["The load is short-circuited.", "A loose or high-resistance connection in the circuit (e.g., a burned wire or pitted relay contact) that cannot sustain current flow.", "The multimeter is accidentally set to DC mode.", "This is a normal mutual inductance phenomenon."], explanation: "This is the classic 'phantom voltage.' There is continuity but no 'force.' As soon as the wire is asked to work, all the energy is lost at the point of poor connection (as heat)." },
  { id:"calef_40", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Por qué un motor soplador centrífugo consume **menos** amperaje si cerramos todas las rejillas de aire de la casa?", opciones:["Porque el motor se esfuerza más.", "Capciosa: Consume menos porque no está moviendo aire. Sin flujo de aire, el ventilador gira en un vacío parcial y no realiza trabajo mecánico.", "Porque el aire atrapado ayuda a empujar las aspas.", "El motor se apaga automáticamente por ahorro de energía."], respuesta_correcta:1, explicacion:"Contrario a la intuición, un ventilador tapado trabaja menos. No hay masa de aire que empujar. Si mides el amperaje con el ducto tapado, verás que la lectura baja significativamente." , question: "Why does a centrifugal blower motor draw LESS amperage if all the air registers in the house are closed?", options: ["Because the motor works harder.", "Tricky: It draws less because it is not moving air. Without airflow, the fan wheel spins in a partial vacuum and performs no mechanical work.", "Because the trapped air helps push the blades.", "The motor shuts off automatically to save energy."], explanation: "Counterintuitively, a blocked fan does less work. There is no mass of air to push. If you measure the amperage with the duct blocked, you will see the reading drop significantly." },
  { id:"calef_41", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor de soplador PSC tiene tres velocidades. ¿Cómo se logra esto técnicamente?", opciones:["Cambiando la frecuencia de la red eléctrica.", "Variando la cantidad de espiras activas en el devanado del estator (cambiando la impedancia interna).", "Usando tres capacitores diferentes.", "Mediante un engranaje mecánico dentro del motor."], respuesta_correcta:1, explicacion:"El motor tiene 'taps' o salidas en su bobinado. Al conectar la energía a un punto diferente, cambias la fuerza del campo magnético y, por ende, la velocidad a la que gira el ventilador." , question: "A PSC blower motor has three speeds. How is this achieved technically?", options: ["By changing the frequency of the electrical supply.", "By varying the number of active turns in the stator winding (changing the internal impedance).", "By using three different capacitors.", "Through a mechanical gear system inside the motor."], explanation: "The motor has 'taps' or terminals on its winding. By connecting power to a different tap point, you change the strength of the magnetic field and, consequently, the speed at which the fan spins." },
  { id:"calef_42", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Por qué es peligroso usar un fusible de 20A en un circuito diseñado para 15A en un horno eléctrico?", opciones:["El motor soplador girará demasiado rápido.", "El cableado podría sobrecalentarse e incendiarse antes de que el fusible se funda ante una sobrecarga.", "El transformador de 24V se quemará.", "La válvula de gas no abrirá por falta de amperaje."], respuesta_correcta:1, explicacion:"El fusible protege el cable. Si el cable soporta 15A y le pones un fusible de 20A, el cable se convierte en el fusible (se derrite/quema) antes de que la protección actúe." , question: "Why is it dangerous to use a 20A fuse in a circuit designed for 15A in an electric furnace?", options: ["The blower motor will spin too fast.", "The wiring could overheat and catch fire before the fuse blows during an overload.", "The 24V transformer will burn out.", "The gas valve will not open due to insufficient amperage."], explanation: "The fuse protects the wire. If the wire can handle 15A and you install a 20A fuse, the wire becomes the fuse (it melts/burns) before the protection activates." },
  { id:"calef_43", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide una resistencia de 'Infinito' entre los dos cables de una resistencia eléctrica de calefacción. ¿Qué significa?", opciones:["Que la resistencia es tan potente que no se puede medir.", "Que el filamento interno está roto (circuito abierto); la resistencia no calentará.", "Que la resistencia está en perfecto estado.", "Que el multímetro debe estar en modo de voltaje DC."], respuesta_correcta:1, explicacion:"Si no hay continuidad, no hay calor. El cable interno de nicromo se quemó y se cortó, como una bombilla de luz fundida." , question: "You measure 'Infinity' resistance between the two wires of an electric heating element. What does this mean?", options: ["The element is so powerful it cannot be measured.", "The internal filament is broken (open circuit); the element will not produce heat.", "The element is in perfect condition.", "The multimeter should be set to DC voltage mode."], explanation: "If there is no continuity, there is no heat. The internal nichrome wire burned out and broke, like a blown light bulb." },
  { id:"calef_44", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un disyuntor (breaker) se dispara inmediatamente cada vez que el horno intenta encender el soplador. ¿Cuál es el problema?", opciones:["El filtro está sucio.", "Un cortocircuito directo a tierra en el motor del soplador o en el cableado de potencia.", "El termostato tiene las baterías bajas.", "La válvula de gas está consumiendo mucho amperaje."], respuesta_correcta:1, explicacion:"Un breaker que salta 'al instante' indica un corto. Hay un cable tocando el metal o el motor tiene sus cables internos fundidos." , question: "A circuit breaker trips immediately every time the furnace tries to start the blower. What is the problem?", options: ["The filter is dirty.", "A direct short circuit to ground in the blower motor or in the power wiring.", "The thermostat has low batteries.", "The gas valve is drawing too much amperage."], explanation: "A breaker that trips 'instantly' indicates a short circuit. There is a wire touching metal or the motor has internally fused wires." },
  { id:"calef_45", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V AC en la bobina de un contactor, pero el contactor no 'cliquea' ni cierra. Al medir la resistencia de la bobina, obtiene '12.5 MΩ'. ¿Cuál es el problema?", opciones:["La bobina está en perfecto estado.", "La bobina está abierta (quemada) internamente; la lectura de Mega-Ohmios indica una ruptura en el hilo de cobre.", "El contactor está mecánicamente trabado por suciedad.", "El voltaje de 24V es de corriente directa y no alterna."], respuesta_correcta:1, explicacion:"Una bobina de 24V saludable debería medir entre 10 y 100 ohmios. Millones de ohmios (MΩ) significan que el circuito está roto. Hay voltaje, pero no hay flujo de corriente para crear el campo magnético." , question: "You measure 24V AC across a contactor coil, but the contactor does not 'click' or close. When measuring the coil resistance, you get '12.5 megohms.' What is the problem?", options: ["The coil is in perfect condition.", "The coil is internally open (burned); the megohm reading indicates a break in the copper wire.", "The contactor is mechanically stuck due to dirt.", "The 24V voltage is DC and not AC."], explanation: "A healthy 24V coil should measure between 10 and 100 ohms. Millions of ohms (megohms) means the circuit is broken. There is voltage, but no current flow to create the magnetic field." },
  { id:"calef_46", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor ECM de 120V recibe 24V en su terminal de control 'G'. El motor no arranca, pero el módulo se calienta. ¿Qué indica esto?", opciones:["Que la señal de 24V es demasiado fuerte.", "Falla interna del puente rectificador o del microprocesador del módulo ECM (el motor está 'vivo' pero el cerebro está frito).", "El motor necesita un capacitor de arranque de 200 mFD.", "Es una operación normal de pre-calentamiento del estator."], respuesta_correcta:1, explicacion:"Los ECM tienen electrónica constante. Si el módulo calienta sin moverse y tiene las señales correctas, los componentes internos (como los MOSFETs) están en corto o fallando." , question: "A 120V ECM motor receives 24V on its 'G' control terminal. The motor does not start, but the module gets hot. What does this indicate?", options: ["The 24V signal is too strong.", "Internal failure of the bridge rectifier or the microprocessor in the ECM module (the motor is 'alive' but the brain is fried).", "The motor needs a 200 MFD start capacitor.", "This is normal pre-heating operation of the stator."], explanation: "ECMs have constant electronics. If the module heats up without moving and has the correct signals, the internal components (such as MOSFETs) are shorted or failing." },
  { id:"calef_47", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué indica un voltaje de 1.5V AC entre el Neutro y la Tierra en un horno de gas de alta eficiencia?", opciones:["Una conexión a tierra perfecta.", "Una falla de conexión a tierra o un neutro compartido que está 'sucio' con carga, lo que puede causar fallas intermitentes en el sensor de llama.", "Es el voltaje necesario para que el microprocesador funcione.", "Indica que el transformador de 24V está invertido."], respuesta_correcta:1, explicacion:"Idealmente debería ser 0V. Un voltaje mayor a 0.5V indica que la tierra no es sólida. Como la detección de llama usa la tierra como retorno, esto 'confunde' a la placa y apaga el horno." , question: "What does a voltage of 1.5V AC between Neutral and Ground indicate in a high-efficiency gas furnace?", options: ["A perfect ground connection.", "A ground connection fault or a 'dirty' shared neutral carrying load, which can cause intermittent flame sensor failures.", "It is the voltage needed for the microprocessor to operate.", "It indicates that the 24V transformer is reversed."], explanation: "Ideally it should be 0V. A voltage greater than 0.5V indicates that the ground is not solid. Since flame detection uses ground as the return path, this 'confuses' the board and shuts down the furnace." },
  { id:"calef_48", categoria:"CALEF_ELECTRICIDAD", pregunta:"En un sistema BAS (Building Automation System), ¿qué es el 'Deadband'?", opciones:["Un área del edificio donde no llega el Wi-Fi.", "Un rango de temperatura en el que ni la calefacción ni el enfriamiento están activos, evitando que los sistemas compitan entre sí.", "Cuando el controlador se queda sin batería.", "La presión máxima que aguanta un damper motorizado."], respuesta_correcta:1, explicacion:"Si el setpoint es 22°C, el deadband podría ser entre 21.5°C y 22.5°C. Esto evita que el equipo prenda y apague por variaciones mínimas de temperatura." , question: "In a Building Automation System (BAS), what is 'Deadband'?", options: ["An area of the building where Wi-Fi does not reach.", "A temperature range in which neither heating nor cooling is active, preventing the systems from competing against each other.", "When the controller runs out of battery.", "The maximum pressure a motorized damper can withstand."], explanation: "If the setpoint is 72 degrees F, the deadband might be between 71.5 and 72.5. This prevents the equipment from cycling on and off due to minimal temperature variations." },
  { id:"calef_49", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor de condensador tiene un capacitor de marcha defectuoso (abierto). ¿Qué lectura de amperaje esperaría ver en el cable común del motor?", opciones:["0 Amperios.", "Un amperaje muy alto (LRA - Locked Rotor Amps) mientras el motor intenta arrancar y zumba, hasta que el protector térmico abra.", "El amperaje nominal de placa (FLA).", "La mitad del amperaje normal."], respuesta_correcta:1, explicacion:"Sin el capacitor, no hay desfase para crear el campo rotatorio. El motor está 'trabado' eléctricamente. Consume toda la corriente posible tratando de moverse, generando calor masivo." , question: "If a 240V heating element has a resistance of 12 ohms, how many amps will it draw?", options: ["10 amps.", "20 amps.", "2880 amps.", "12 amps."], explanation: "Ohm's Law: I = V / R. 240 / 12 = 20. Knowing this is essential for diagnosing whether a heating element is functioning properly using a clamp meter." },
  { id:"calef_50", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un termostato inteligente requiere 24V constantes. Si el horno solo tiene cables R y W, ¿qué componente se puede instalar para evitar tirar un cable nuevo?", opciones:["Un capacitor de 5 mFD en serie con la válvula de gas.", "Un kit de 'Añadir un cable' (Add-a-Wire) o un transformador de pared independiente con un relé de aislamiento.", "Un puente de metal entre W y C.", "No se puede; es físicamente imposible según la Ley de Kirchhoff."], respuesta_correcta:1, explicacion:"Estos kits usan diodos o electrónica para enviar dos señales por un solo cable, o bien se provee energía externa. Sin el común (C), el termostato no tiene circuito de retorno para su propia batería." , question: "What happens if you disconnect the 5-pin or 16-pin control harness from an ECM motor while 120/240V power is applied?", options: ["Nothing; the motor stops smoothly.", "You can permanently damage the control module's microprocessor due to electrical arcing or voltage spikes.", "The motor will accelerate until it explodes due to the lack of a speed limit.", "The furnace motherboard's programming will be erased."], explanation: "Golden rule: First cut all power, then disconnect the control. ECMs are sensitive computers; a spark on the data pins can fry the module." },
  { id:"calef_51", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si duplicamos el voltaje aplicado a una resistencia eléctrica fija, ¿qué sucede con la potencia (Watts) entregada?", opciones:["La potencia se duplica.", "La potencia aumenta cuatro veces ($P = V^2 / R$).", "La potencia se mantiene igual pero el amperaje baja.", "La resistencia se quema instantáneamente por inducción térmica."], respuesta_correcta:1, explicacion:"Relación cuadrática. Si pasas un horno eléctrico de 120V a 240V por error, entregarás 4 veces más calor del diseñado y causarás un incendio o derretirás el equipo en segundos." , question: "If we double the voltage applied to a fixed electrical resistance, what happens to the power (watts) delivered?", options: ["The power doubles.", "The power increases fourfold (P = V squared / R).", "The power stays the same but the amperage drops.", "The resistance burns instantly due to thermal induction."], explanation: "Quadratic relationship. If you mistakenly connect a 120V electric furnace to 240V, you will deliver 4 times the designed heat and cause a fire or melt the equipment in seconds." },
  { id:"calef_52", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un horno se apaga por 'Límite de Alta Temperatura'. El técnico mide el amperaje del motor soplador y es 0.5A menor al nominal. ¿Cuál es la conclusión?", opciones:["El motor está fallando eléctricamente.", "El motor no está moviendo suficiente aire (posible restricción o aspas sucias), por lo que realiza menos trabajo y consume menos corriente.", "El motor es demasiado potente para el horno.", "El voltaje de línea es demasiado alto."], respuesta_correcta:1, explicacion:"Capciosa: Si el motor consume menos es porque no tiene aire que empujar. Si no hay aire, el horno se calienta y se apaga por seguridad. La falla es de flujo de aire, no del motor." , question: "A furnace shuts down on 'High Temperature Limit.' The technician measures blower motor amperage at 0.5A below the rated value. What is the conclusion?", options: ["The motor is failing electrically.", "The motor is not moving enough air (possible restriction or dirty blower wheel), so it performs less work and draws less current.", "The motor is too powerful for the furnace.", "The line voltage is too high."], explanation: "Tricky: If the motor draws less, it is because it has no air to push. If there is no air, the furnace overheats and shuts down on safety. The fault is airflow, not the motor." },
  { id:"calef_53", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted encuentra una polea de ventilador 'desalineada' por 5 grados. ¿Qué efecto tiene esto?", opciones:["Aumenta la velocidad del aire por efecto de torsión.", "Causa desgaste prematuro de la correa (belt), vibración excesiva y posible daño a los rodamientos del motor.", "Reduce el consumo de amperaje del motor.", "Mejora la eficiencia del ventilador centrífugo."], respuesta_correcta:1, explicacion:"La correa sufrirá fricción lateral constante. Se calentará, soltará polvo negro y se romperá en semanas. Además, el ruido será una queja constante del cliente." , question: "You find a fan pulley misaligned by 5 degrees. What effect does this have?", options: ["It increases air velocity due to the torsion effect.", "It causes premature belt wear, excessive vibration, and possible damage to the motor bearings.", "It reduces the motor amperage draw.", "It improves the efficiency of the centrifugal fan."], explanation: "The belt will suffer constant lateral friction. It will heat up, shed black dust, and break within weeks. Additionally, the noise will be a constant customer complaint." },
  { id:"calef_54", categoria:"CALEF_ELECTRICIDAD", pregunta:"En un circuito de calefacción, ¿qué es una 'Carga Inductiva'?", opciones:["Una resistencia eléctrica pura que genera calor.", "Componentes con bobinas (motores, transformadores, solenoides) que crean campos magnéticos y desfasar la corriente respecto al voltaje.", "El cableado de tierra de la casa.", "La batería del termostato digital."], respuesta_correcta:1, explicacion:"Los motores son cargas inductivas. Generan picos de voltaje al apagarse (inductancia) y requieren contactores diseñados para aguantar esos 'chispazos' eléctricos." , question: "In a heating circuit, what is an 'Inductive Load'?", options: ["A pure electrical resistance that generates heat.", "Components with coils (motors, transformers, solenoids) that create magnetic fields and cause the current to lag behind the voltage.", "The house's ground wiring.", "The digital thermostat battery."], explanation: "Motors are inductive loads. They generate voltage spikes when turned off (inductance) and require contactors designed to handle those electrical 'arcs.'" },
  { id:"calef_55", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide un capacitor de 5 mFD y el multímetro marca 4.2 mFD. ¿Cuál es la regla técnica para su reemplazo?", opciones:["Se debe reemplazar si la lectura cae más del 6% o 10% del valor nominal (según fabricante). En este caso, ya perdió el 16%, está fuera de rango.", "Se puede dejar hasta que marque 0 mFD.", "Se debe añadir otro capacitor pequeño en paralelo para compensar.", "El motor funcionará mejor con menos capacitancia."], respuesta_correcta:0, explicacion:"Un capacitor débil hace que el motor consuma más amperaje y se caliente. No esperes a que falle del todo; cámbialo ahora para salvar la vida del motor soplador." , question: "You measure a 5 MFD capacitor and the multimeter reads 4.2 MFD. What is the technical rule for replacement?", options: ["It must be replaced if the reading drops more than 6% or 10% of the rated value (per manufacturer). In this case, it has already lost 16%, which is out of range.", "It can be left in service until it reads 0 MFD.", "Another small capacitor should be added in parallel to compensate.", "The motor will actually perform better with less capacitance."], explanation: "A weak capacitor causes the motor to draw more amperage and overheat. Do not wait for complete failure; replace it now to save the life of the blower motor." },
  { id:"calef_56", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V en el transformador de control, pero solo 18V en el termostato al final de un pasillo largo. ¿A qué se debe?", opciones:["Caída de tensión (Voltage Drop) debido a cables de calibre muy delgado (ej. 22 AWG) para una distancia excesiva.", "Interferencia del Wi-Fi de la casa.", "El transformador es de corriente directa por error.", "Es una lectura normal por el efecto de la gravedad en los electrones."], respuesta_correcta:0, explicacion:"Los cables tienen resistencia. Si el cable es muy largo o muy fino, se 'traga' parte del voltaje. Esto causa que los relés del horno vibren (chattering) o no activen bien." , question: "You measure 24V at the control transformer, but only 18V at the thermostat at the end of a long hallway. What causes this?", options: ["Voltage drop due to wire gauge that is too thin (e.g., 22 AWG) for the excessive distance.", "Interference from the house Wi-Fi.", "The transformer is accidentally DC instead of AC.", "This is a normal reading due to the effect of gravity on electrons."], explanation: "Wires have resistance. If the wire is too long or too thin, it 'absorbs' part of the voltage. This causes furnace relays to chatter or fail to properly engage." },
  { id:"calef_57", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un horno tiene un interruptor de 'Roll-out' térmico. ¿Cuál es la diferencia fundamental en su circuito comparado con el 'High Limit' principal?", opciones:["El roll-out es de restablecimiento automático.", "El roll-out es de restablecimiento manual (manual reset) porque indica que las llamas salieron de la cámara de combustión, una condición de peligro de incendio extremo.", "El roll-out solo funciona con voltajes de 120V.", "El roll-out detecta la temperatura del aire de retorno."], respuesta_correcta:1, explicacion:"Si el fuego se sale de su lugar, algo anda muy mal (intercambiador tapado o chimenea bloqueada). La ley exige que un técnico verifique el equipo antes de que pueda volver a encenderse." , question: "A furnace has a thermal 'Roll-out' switch. What is the fundamental difference in its circuit compared to the main 'High Limit'?", options: ["The roll-out is an auto-reset device.", "The roll-out is a manual-reset device because it indicates that flames exited the combustion chamber, an extreme fire hazard condition.", "The roll-out only works with 120V voltages.", "The roll-out senses the return air temperature."], explanation: "If fire escapes from its designated area, something is seriously wrong (plugged heat exchanger or blocked flue). Code requires a technician to inspect the equipment before it can be restarted." },
  { id:"calef_58", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué sucede si conecta accidentalmente el primario de un transformador de 120V/24V a una línea de 240V?", opciones:["El transformador entregará 48V de forma segura.", "El transformador se saturará magnéticamente, se sobrecalentará instantáneamente y quemará su devanado primario o el fusible térmico interno.", "El horno funcionará al doble de velocidad.", "La placa de control convertirá el exceso de voltaje en calor útil."], respuesta_correcta:1, explicacion:"Los transformadores están diseñados para una relación de vueltas específica. Duplicar el voltaje de entrada satura el núcleo de hierro y causa un cortocircuito térmico interno." , question: "What happens if you accidentally connect the primary of a 120V/24V transformer to a 240V line?", options: ["The transformer will safely deliver 48V.", "The transformer will magnetically saturate, overheat instantly, and burn its primary winding or the internal thermal fuse.", "The furnace will run at double speed.", "The control board will convert the excess voltage into useful heat."], explanation: "Transformers are designed for a specific turns ratio. Doubling the input voltage saturates the iron core and causes an internal thermal short circuit." },
  { id:"calef_59", categoria:"CALEF_ELECTRICIDAD", pregunta:"En un motor ECM, ¿cuál es la función del 'VDR' (Varistor de Óxido Metálico) en la etapa de entrada?", opciones:["Aumentar el torque del motor en el arranque.", "Proteger la electrónica sensible del módulo contra picos de voltaje (surges) transitorios de la red eléctrica.", "Medir la velocidad de rotación mediante magnetismo.", "Actuar como un puente rectificador de onda completa."], respuesta_correcta:1, explicacion:"El VDR es el 'fusible de rayos'. Si hay un pico de voltaje, se sacrifica poniéndose en corto para salvar el resto de la computadora del motor." , question: "In an ECM motor, what is the function of the 'MOV' (Metal Oxide Varistor) at the input stage?", options: ["To increase the motor's starting torque.", "To protect the module's sensitive electronics against transient voltage spikes (surges) from the electrical supply.", "To measure the rotation speed using magnetism.", "To act as a full-wave bridge rectifier."], explanation: "The MOV is the 'lightning fuse.' If there is a voltage spike, it sacrifices itself by shorting to save the rest of the motor's computer." },
  { id:"calef_60", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide corriente (Amperios) colocando las puntas del multímetro en paralelo con la carga de un motor soplador. ¿Qué ocurre?", opciones:["Mide el amperaje perfectamente.", "Causa un cortocircuito masivo que fundirá el fusible interno del multímetro o destruirá el medidor, ya que el modo amperímetro tiene resistencia casi nula.", "El motor girará más rápido debido al bypass eléctrico.", "El multímetro mostrará una lectura de voltaje por seguridad."], respuesta_correcta:1, explicacion:"Regla básica de supervivencia. Los amperios se miden en serie o con pinza inductiva. En paralelo, creas un 'puente' de metal puro que causa un chispazo peligroso." , question: "You measure current (amps) by placing the multimeter leads in parallel with a blower motor load. What happens?", options: ["You measure the amperage perfectly.", "It causes a massive short circuit that will blow the multimeter's internal fuse or destroy the meter, since the ammeter mode has nearly zero resistance.", "The motor will spin faster due to the electrical bypass.", "The multimeter will display a voltage reading for safety."], explanation: "Basic survival rule. Amps are measured in series or with an inductive clamp meter. In parallel, you create a 'bridge' of pure metal that causes a dangerous arc." },
  { id:"calef_61", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V en el terminal 'R' y 0V en el terminal 'W' del horno mientras el termostato está en 'OFF'. ¿Qué lectura esperaría ver si el termostato se activa?", opciones:["24V en el terminal 'W' (medido respecto al común 'C').", "0V en el terminal 'R' porque la energía se consumió.", "120V en el terminal 'W' por inducción.", "La lectura no cambia porque el termostato es inalámbrico."], respuesta_correcta:0, explicacion:"Cuando el termostato pide calor, une R con W. Por lo tanto, W recibe la energía de R. Si mides de W a C, ahora deberías ver los 24 voltios que activan la placa." , question: "You measure 24V at the 'R' terminal and 0V at the 'W' terminal of the furnace while the thermostat is 'OFF.' What reading would you expect if the thermostat activates?", options: ["24V at the 'W' terminal (measured with respect to common 'C').", "0V at the 'R' terminal because the energy was consumed.", "120V at the 'W' terminal due to induction.", "The reading does not change because the thermostat is wireless."], explanation: "When the thermostat calls for heat, it connects R to W. Therefore, W receives the energy from R. If you measure from W to C, you should now see the 24 volts that activate the board." },
  { id:"calef_62", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Por qué nunca se debe puentear (jumper) el interruptor de límite alto de un horno para que el cliente tenga calefacción el fin de semana?", opciones:["Porque el puente consume mucha batería.", "Es una negligencia grave que puede causar que el intercambiador de calor se derrita, se incendie la casa o se libere CO masivo si el ventilador falla.", "El horno funcionará demasiado bien y el cliente no querrá repararlo.", "La placa de control detectará el puente y borrará su memoria."], respuesta_correcta:1, explicacion:"El límite es el 'cinturón de seguridad'. Si lo quitas y el ventilador se detiene, el horno se convierte en un lanzallamas incontrolable dentro de un gabinete de metal. Jamás se hace." , question: "Why should you NEVER jumper the high-limit switch on a furnace to give the customer heat over the weekend?", options: ["Because the jumper consumes too much battery.", "It is serious negligence that can cause the heat exchanger to melt, the house to catch fire, or massive CO release if the blower fails.", "The furnace will work too well and the customer will not want to have it repaired.", "The control board will detect the jumper and erase its memory."], explanation: "The limit switch is the 'seatbelt.' If you remove it and the blower stops, the furnace becomes an uncontrollable blowtorch inside a metal cabinet. This must never be done." },
  { id:"calef_63", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted gira la rueda del soplador con la mano y se detiene casi de inmediato. ¿Qué indica esto?", opciones:["Que el motor tiene mucho torque magnético.", "Rodamientos secos o dañados que generan fricción excesiva; la rueda debería girar libremente por varios segundos (coast down).", "Es normal en motores de alta eficiencia (ECM).", "El filtro de aire está creando un vacío que frena la rueda."], respuesta_correcta:1, explicacion:"Fricción mecánica. El motor está gastando la mitad de su fuerza solo en vencer el roce de sus propios rodamientos. Se calentará y morirá pronto." , question: "You spin the blower wheel by hand and it stops almost immediately. What does this indicate?", options: ["The motor has a lot of magnetic torque.", "Dry or damaged bearings generating excessive friction; the wheel should spin freely for several seconds (coast down).", "This is normal in high-efficiency (ECM) motors.", "The air filter is creating a vacuum that brakes the wheel."], explanation: "Mechanical friction. The motor is spending half its energy just overcoming the drag of its own bearings. It will overheat and fail soon." },
  { id:"calef_64", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué es un 'Relé de Retardo de Tiempo' (Time Delay Relay) y para qué se usa en calefacción eléctrica?", opciones:["Para que el horno encienda solo por la noche.", "Para escalonar el encendido de los bancos de resistencias, evitando que la carga eléctrica total entre de golpe a la red de la casa.", "Para medir cuánto tiempo tarda el técnico en reparar el equipo.", "Es un cronómetro para el cambio de filtro."], respuesta_correcta:1, explicacion:"Imagina encender 4 hornos eléctricos al mismo tiempo. Las luces de la cuadra parpadearían. El retardo hace que entren uno por uno, suavemente." , question: "What is a 'Time Delay Relay' and what is it used for in electric heating?", options: ["To make the furnace turn on only at night.", "To stagger the activation of heating element banks, preventing the total electrical load from hitting the house's power supply all at once.", "To measure how long the technician takes to repair the equipment.", "It is a timer for filter changes."], explanation: "Imagine turning on 4 electric furnaces at the same time. The lights on the block would flicker. The time delay brings them online one at a time, smoothly." },
  { id:"calef_65", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si un circuito de 120V tiene una resistencia total de 20 ohmios, ¿cuál es el consumo de potencia en Watts?", opciones:["2400 Watts.", "720 Watts ($P = V^2 / R$).", "6 Watts.", "120 Watts."], respuesta_correcta:1, explicacion:"Matemática de taller: $120 	imes 120 = 14400$. Luego $14400 / 20 = 720$. Útil para saber si un breaker aguantará una carga eléctrica de calefacción." , question: "If a 120V circuit has a total resistance of 20 ohms, what is the power consumption in watts?", options: ["2400 watts.", "720 watts (P = V squared / R).", "6 watts.", "120 watts."], explanation: "Shop math: 120 x 120 = 14,400. Then 14,400 / 20 = 720. Useful for knowing if a breaker can handle an electric heating load." },
  { id:"calef_66", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué significa que un motor tenga un 'Protector Térmico de Restablecimiento Automático'?", opciones:["Que el motor se apaga y nunca vuelve a encender.", "Que el motor se apaga si se calienta demasiado y vuelve a encender solo una vez que se enfría; puede ser peligroso para un técnico desprevenido.", "Que el motor cambia de velocidad automáticamente.", "Que el motor se limpia solo."], respuesta_correcta:1, explicacion:"Ojo con esto. Estás revisando un motor parado, crees que no tiene energía, y de repente arranca y te atrapa los dedos. Siempre corta la luz antes de tocar." , question: "What does it mean for a motor to have an 'Automatic Reset Thermal Protector'?", options: ["The motor shuts off and never turns on again.", "The motor shuts off if it gets too hot and restarts on its own once it cools down; this can be dangerous for an unsuspecting technician.", "The motor changes speed automatically.", "The motor cleans itself."], explanation: "Watch out for this. You are inspecting a stopped motor, you think it has no power, and suddenly it starts and catches your fingers. Always disconnect power before touching." },
  { id:"calef_67", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted instala un capacitor de 440V en lugar de uno de 370V del mismo valor de mFD. ¿Qué ocurre?", opciones:["El motor se quemará inmediatamente.", "Nada malo; el voltaje del capacitor es el 'máximo' que aguanta. Usar uno de mayor voltaje es seguro y a menudo dura más tiempo.", "El motor consumirá el doble de amperios.", "La velocidad del ventilador aumentará un 20%."], respuesta_correcta:1, explicacion:"Hacia arriba es seguro, hacia abajo es peligroso. Si pones uno de 370V donde hay 440V, explotará. Al revés, simplemente tienes una pieza más robusta." , question: "You install a 440V capacitor instead of a 370V capacitor of the same MFD value. What happens?", options: ["The motor will burn immediately.", "Nothing bad; the capacitor voltage is the 'maximum' it can handle. Using one with a higher voltage rating is safe and often lasts longer.", "The motor will draw double the amps.", "The fan speed will increase by 20%."], explanation: "Going higher in voltage rating is safe; going lower is dangerous. If you install a 370V capacitor where there is 440V, it will explode. The reverse simply gives you a more robust component." },
  { id:"calef_68", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 0V entre 'R' y 'C' en el horno. ¿Cuál es el primer componente a revisar?", opciones:["El motor del soplador.", "El fusible de la placa de control (usualmente de 3A o 5A) y el transformador de 24V.", "El sensor de llama.", "Las baterías del termostato."], respuesta_correcta:1, explicacion:"Si no hay 24V, el cerebro no tiene energía. Un cable pelado o un corto en el termostato suelen fundir ese fusible. Si el fusible está bien, el transformador se quemó." , question: "You measure 0V between 'R' and 'C' at the furnace. What is the first component to check?", options: ["The blower motor.", "The control board fuse (usually 3A or 5A) and the 24V transformer.", "The flame sensor.", "The thermostat batteries."], explanation: "If there is no 24V, the brain has no power. A stripped wire or a short in the thermostat circuit usually blows that fuse. If the fuse is good, the transformer is burned out." },
  { id:"calef_69", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué es la 'Fuerza Contraelectromotriz' (Back EMF) en un motor de soplador y qué sucede si la carga de aire es nula?", opciones:["Es un voltaje generado por el motor que se opone al de la línea; si no hay aire, las RPM suben, el Back EMF aumenta y el amperaje cae drásticamente.", "Es una fuga de corriente hacia el chasis del horno.", "Un voltaje extra que ayuda al motor a arrancar en climas fríos.", "La energía que consume el capacitor de marcha durante el ciclo."], respuesta_correcta:0, explicacion:"El motor actúa como generador mientras gira. A más velocidad (menos carga), genera más voltaje interno que frena la entrada de corriente de la red, por eso baja el amperaje." , question: "What is 'Back-EMF' (Counter-Electromotive Force) in a blower motor, and what happens if the air load is zero?", options: ["It is a voltage generated by the motor that opposes the line voltage; if there is no air, RPM rises, back-EMF increases, and amperage drops drastically.", "It is a current leak to the furnace chassis.", "An extra voltage that helps the motor start in cold climates.", "The energy consumed by the run capacitor during the cycle."], explanation: "The motor acts as a generator while it spins. At higher speed (less load), it generates more internal voltage that opposes incoming current from the supply, which is why amperage drops." },
  { id:"calef_70", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide un capacitor de marcha y obtiene la capacitancia correcta, pero nota que el motor se calienta en exceso. ¿Qué prueba de 'factor de disipación' (ESR) debería considerar?", opciones:["Medir la caída de voltaje en DC a través de las placas del condensador.", "Comprobar si hay fugas de corriente internas o una alta resistencia serie equivalente que genera calor inútil dentro del motor.", "Cambiar el multímetro a modo de microfaradios dinámicos.", "No existe tal prueba para capacitores de HVAC."], respuesta_correcta:1, explicacion:"A veces un capacitor tiene los mFD correctos pero sufre 'fugas' internas de energía. Esto desequilibra el campo magnético del motor y causa sobrecalentamiento." , question: "You measure a run capacitor and get the correct capacitance, but notice the motor overheats excessively. What 'dissipation factor' (ESR) test should you consider?", options: ["Measuring the DC voltage drop across the capacitor plates.", "Checking for internal current leakage or high equivalent series resistance that generates useless heat inside the motor.", "Switching the multimeter to dynamic microfarad mode.", "No such test exists for HVAC capacitors."], explanation: "Sometimes a capacitor has the correct MFD but suffers from internal energy 'leakage.' This unbalances the motor's magnetic field and causes overheating." },
  { id:"calef_71", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Cuál es el riesgo de tener una 'Resistencia de Tierra' mayor a 25 ohmios en un equipo de calefacción industrial?", opciones:["Aumento del consumo de combustible fósil.", "Falla en la activación de las protecciones de sobrecorriente ante un fallo a tierra y riesgo de voltajes peligrosos en el chasis del equipo.", "El motor del ventilador perderá el 10% de su torque nominal.", "La ionización de la llama se volverá excesivamente potente."], respuesta_correcta:1, explicacion:"La tierra debe ser un camino fácil. Si tiene mucha resistencia, la electricidad preferirá pasar por una persona antes que por el cable de tierra en caso de falla." , question: "What is the risk of having a 'Ground Resistance' greater than 25 ohms on industrial heating equipment?", options: ["Increased fossil fuel consumption.", "Failure of overcurrent protections to trip during a ground fault, and risk of dangerous voltages on the equipment chassis.", "The fan motor will lose 10% of its rated torque.", "The flame ionization will become excessively powerful."], explanation: "The ground path must be easy. If it has too much resistance, electricity will prefer to flow through a person rather than through the ground wire in case of a fault." },
  { id:"calef_72", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué indica un valor de 'Vibración en Cascada' en un análisis predictivo de un ventilador de calefacción de gran tamaño?", opciones:["Que el ventilador está perfectamente balanceado mecánicamente.", "Presencia de desalineación, soltura mecánica o falla inminente en los rodamientos del motor o del eje del ventilador.", "Un aumento en la densidad del aire debido a la baja temperatura.", "Es el sonido normal del aire pasando por las aspas curvas."], respuesta_correcta:1, explicacion:"Las máquinas 'hablan' mediante vibración. Si la vibración se repite en patrones específicos, te dice exactamente qué pieza se va a romper antes de que suceda." , question: "What does a 'Cascade Vibration' value indicate in a predictive analysis of a large heating fan?", options: ["The fan is perfectly mechanically balanced.", "The presence of misalignment, mechanical looseness, or imminent failure of the motor or fan shaft bearings.", "An increase in air density due to low temperature.", "It is the normal sound of air passing through curved blades."], explanation: "Machines 'talk' through vibration. If the vibration repeats in specific patterns, it tells you exactly which part is going to break before it happens." },
  { id:"calef_73", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si un contactor de calefacción eléctrica tiene los contactos 'picados' o carbonizados, ¿qué efecto tiene sobre el voltaje que llega a las resistencias?", opciones:["El voltaje aumenta por el efecto de arco eléctrico.", "Se produce una caída de voltaje a través del contactor, lo que reduce la potencia calorífica y genera calor peligroso en el propio contactor.", "El amperaje bajará a cero instantáneamente por seguridad.", "No hay efecto, la electricidad salta sobre el carbón."], respuesta_correcta:1, explicacion:"El carbón es resistencia. Si el voltaje 'se queda' en el contactor, no llega a la resistencia. Además, ese contactor se pondrá tan caliente que puede causar un incendio." , question: "If an electric heating contactor has 'pitted' or carbonized contacts, what effect does this have on the voltage reaching the heating elements?", options: ["The voltage increases due to the arcing effect.", "A voltage drop occurs across the contactor, reducing heating output and generating dangerous heat within the contactor itself.", "The amperage drops to zero instantly for safety.", "No effect; electricity jumps over carbon."], explanation: "Carbon is resistance. If the voltage 'stays' at the contactor, it does not reach the heating element. Additionally, that contactor will get so hot it can cause a fire." },
  { id:"calef_74", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué sucede con el ángulo de fase entre el voltaje y la corriente en un motor PSC si el capacitor de marcha tiene una capacitancia mayor a la especificada?", opciones:["El ángulo de fase se vuelve perfecto de 90 grados.", "El ángulo de fase se desvía del valor óptimo, aumentando el consumo de amperaje y el calor generado en el devanado auxiliar.", "La corriente y el voltaje se sincronizan totalmente eliminando la reactancia.", "El motor se convierte técnicamente en un generador trifásico."], respuesta_correcta:1, explicacion:"Más no siempre es mejor. El capacitor está calculado para que el 'empuje' magnético sea preciso. Si te pasas, el motor pierde eficiencia y se calienta de más." , question: "What happens to the phase angle between voltage and current in a PSC motor if the run capacitor has a higher capacitance than specified?", options: ["The phase angle becomes a perfect 90 degrees.", "The phase angle deviates from the optimal value, increasing amperage draw and heat generated in the auxiliary winding.", "The current and voltage synchronize completely, eliminating reactance.", "The motor technically becomes a three-phase generator."], explanation: "More is not always better. The capacitor is calculated so the magnetic 'push' is precise. If you overshoot, the motor loses efficiency and overheats." },
  { id:"calef_75", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 28V AC en la salida de un transformador de 24V sin carga conectada. ¿Cuál es el diagnóstico?", opciones:["El transformador está defectuoso y debe reemplazarse.", "Es una lectura normal 'Open Circuit Voltage'; el voltaje caerá a ~24V una vez que se conecte la carga nominal (termostato, relés).", "Existe un cortocircuito parcial en el devanado primario.", "La frecuencia de la red subió de 60Hz a 70Hz."], respuesta_correcta:1, explicacion:"Los transformadores pequeños están diseñados para 'bajar' un poco su voltaje bajo carga. Si ves 24V exactos sin nada conectado, probablemente baje a 20V cuando el horno arranque." , question: "You measure 28V AC at the output of a 24V transformer with no load connected. What is the diagnosis?", options: ["The transformer is defective and must be replaced.", "This is a normal 'Open Circuit Voltage' reading; the voltage will drop to approximately 24V once the rated load is connected (thermostat, relays).", "There is a partial short circuit in the primary winding.", "The supply frequency increased from 60Hz to 70Hz."], explanation: "Small transformers are designed to 'drop' their voltage slightly under load. If you see exactly 24V with nothing connected, it will probably drop to 20V when the furnace starts." },
  { id:"calef_76", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si un motor de soplador PSC tiene un devanado de marcha (Run) abierto, ¿qué lectura de ohmios obtendrá entre los terminales de marcha y común?", opciones:["0 Ohmios.", "Infinito u 'OL' (Open Loop).", "Aproximadamente 2.5 Ohmios.", "Depende de la temperatura ambiente."], respuesta_correcta:1, explicacion:"Abierto significa roto. No hay camino para la electricidad. El multímetro mostrará que no hay continuidad, confirmando que el motor es chatarra." , question: "If a PSC blower motor has an open run winding, what ohm reading will you get between the run and common terminals?", options: ["0 ohms.", "Infinity or 'OL' (Open Loop).", "Approximately 2.5 ohms.", "It depends on the ambient temperature."], explanation: "Open means broken. There is no path for electricity. The multimeter will show no continuity, confirming the motor is scrap." },
  { id:"calef_77", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un sistema comunicante muestra un error de 'Impedancia de Bus Alta'. ¿Qué debería revisar el técnico?", opciones:["El voltaje de la batería del termostato.", "Conexiones flojas, corrosión en los terminales o el uso de un cable demasiado largo/delgado que degrada la señal digital.", "La presión del gas en la válvula principal.", "El estado del filtro de aire de alta eficiencia."], respuesta_correcta:1, explicacion:"Los datos digitales necesitan un camino limpio. Una conexión mal apretada actúa como un 'muro' para los bits de información, causando que las máquinas dejen de hablarse." , question: "A communicating system displays a 'High Bus Impedance' error. What should the technician check?", options: ["The thermostat battery voltage.", "Loose connections, corrosion on terminals, or the use of cable that is too long or thin, degrading the digital signal.", "The gas pressure at the main valve.", "The condition of the high-efficiency air filter."], explanation: "Digital data needs a clean path. A poorly tightened connection acts as a 'wall' for data bits, causing the equipment to stop communicating." },
  { id:"calef_78", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted encuentra que el fusible de 3A de la placa de control se funde cada vez que el termostato pide 'Cool' pero no cuando pide 'Heat'. ¿Dónde está la falla?", opciones:["En la válvula de gas del horno.", "En el cableado que va hacia la unidad condensadora exterior (terminal Y), probablemente pelado y tocando el chasis o el tubo de cobre.", "El motor del soplador interior está trabado.", "El transformador de 24V es demasiado pequeño."], respuesta_correcta:1, explicacion:"Diagnóstico por eliminación. Si el calor funciona, la placa y el transformador están bien. El problema está en el cable que solo se usa para el frío: el que sale hacia afuera de la casa." , question: "You find that the 3A fuse on the control board blows every time the thermostat calls for 'Cool' but not when it calls for 'Heat.' Where is the fault?", options: ["In the furnace gas valve.", "In the wiring going to the outdoor condensing unit (Y terminal), likely stripped and touching the chassis or copper tubing.", "The indoor blower motor is seized.", "The 24V transformer is undersized."], explanation: "Diagnosis by elimination. If heating works, the board and transformer are fine. The problem is in the wire used only for cooling: the one that runs to the outside of the house." },
  { id:"calef_79", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si un banco de resistencias de 10kW se alimenta con 208V en lugar de 240V, ¿cuánta potencia entregará?", opciones:["Exactamente 10kW.", "Aproximadamente 7.5kW ($P = V^2 / R$).", "12kW debido al aumento del amperaje.", "0kW, el sistema se bloqueará por bajo voltaje."], respuesta_correcta:1, explicacion:"Al bajar el voltaje, la potencia cae al cuadrado. El cliente se quejará de que el horno 'no calienta igual' aunque todo parezca funcionar bien eléctricamente." , question: "If a 10kW heating element bank is fed with 208V instead of 240V, how much power will it deliver?", options: ["Exactly 10kW.", "Approximately 7.5kW (P = V squared / R).", "12kW due to increased amperage.", "0kW; the system will lock out on low voltage."], explanation: "When voltage drops, power falls by the square. The customer will complain that the furnace 'doesn't heat the same' even though everything seems to work electrically." },
  { id:"calef_80", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide un capacitor de 45 mFD y marca 44.8 mFD, pero el motor hace un ruido de 'zumbido' y no arranca. ¿Qué es lo siguiente a revisar?", opciones:["Reemplazar el capacitor de todos modos.", "Verificar la continuidad de los devanados del motor y asegurarse de que el eje no esté mecánicamente trabado (rodamientos fundidos).", "Bajar el voltaje de la línea a 110V.", "Cambiar el termostato de pared."], respuesta_correcta:1, explicacion:"Si el capacitor está perfecto, el problema es el motor. O se quemó un cable interno o los baleros se pegaron y no dejan que el rotor gire." , question: "You measure a 45 MFD capacitor and it reads 44.8 MFD, but the motor hums and does not start. What should you check next?", options: ["Replace the capacitor anyway.", "Verify the continuity of the motor windings and make sure the shaft is not mechanically seized (fused bearings).", "Lower the line voltage to 110V.", "Replace the wall thermostat."], explanation: "If the capacitor is perfect, the problem is the motor. Either an internal wire burned out or the bearings are seized and will not let the rotor turn." },
  { id:"calef_81", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V entre 'W' y 'C' en la placa, pero la válvula de gas nunca recibe energía. El cableado está bien. ¿Qué es lo más probable?", opciones:["La válvula de gas está en cortocircuito.", "El microprocesador de la placa detectó un fallo en otro sensor (como el de presión) y decidió no abrir el relé de la válvula por seguridad.", "El transformador está entregando demasiada potencia.", "El termostato está configurado en modo 'Fan Only'."], respuesta_correcta:1, explicacion:"La placa es el juez. Aunque el termostato pida calor (24V en W), si la placa ve que el extractor no está girando o que el límite está abierto, no dejará pasar gas jamás." , question: "You measure 24V between 'W' and 'C' on the control board, but the gas valve never receives power. The wiring checks out fine. What is most likely?", options: ["The gas valve is short-circuited.", "The control board microprocessor detected a fault on another sensor (such as the pressure switch) and decided not to close the gas valve relay for safety.", "The transformer is delivering too much power.", "The thermostat is set to 'Fan Only' mode."], explanation: "The board is the judge. Even though the thermostat calls for heat (24V at W), if the board sees that the inducer is not running or the limit is open, it will never allow gas to flow." },
  { id:"calef_82", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un horno de gas de 2 etapas utiliza un algoritmo de 'Adaptive Learning'. Si el termostato es de una sola etapa (W1), ¿cómo decide el horno pasar a la segunda etapa (W2)?", opciones:["Nunca pasa a la segunda etapa sin la señal física del termostato.", "La placa de control monitorea la duración de los ciclos previos; si el ciclo dura más de 10-15 minutos, activa la etapa alta asumiendo que la baja no es suficiente.", "Mide la temperatura del aire de retorno mediante un sensor infrarrojo.", "Aumenta el voltaje del ignitor para forzar más fuego."], respuesta_correcta:1, explicacion:"Es una función de confort. La placa 'aprende' que la casa está muy fría si el horno no logra apagar el termostato en un tiempo razonable, subiendo la potencia automáticamente." , question: "A two-stage gas furnace uses an 'Adaptive Learning' algorithm. If the thermostat is single-stage (W1 only), how does the furnace decide to switch to the second stage (W2)?", options: ["It never goes to the second stage without the physical signal from the thermostat.", "The control board monitors the duration of previous cycles; if a cycle runs longer than 10-15 minutes, it activates the high stage, assuming the low stage is insufficient.", "It measures the return air temperature using an infrared sensor.", "It increases the igniter voltage to force more flame."], explanation: "It is a comfort feature. The board 'learns' that the house is very cold if the furnace cannot satisfy the thermostat within a reasonable time and automatically ramps up the output." },
  { id:"calef_83", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide la señal PWM de un motor ECM con un osciloscopio y nota que el 'Duty Cycle' es del 10%. ¿Qué velocidad debería tener el motor?", opciones:["Velocidad máxima (100% RPM).", "Velocidad mínima o cercana al reposo, ya que el Duty Cycle representa el porcentaje de potencia demandada.", "Exactamente 100 RPM por cada voltio detectado.", "El motor debería estar girando al revés para autolimpieza."], respuesta_correcta:1, explicacion:"PWM (Pulse Width Modulation) es el lenguaje de los motores modernos. 10% significa 've despacio', 90% significa 've a todo lo que des'." , question: "You measure the PWM signal of an ECM motor with an oscilloscope and note that the duty cycle is 10%. What speed should the motor be running?", options: ["Maximum speed (100% RPM).", "Minimum speed or near standstill, since the duty cycle represents the percentage of power demanded.", "Exactly 100 RPM per volt detected.", "The motor should be spinning in reverse for self-cleaning."], explanation: "PWM (Pulse Width Modulation) is the language of modern motors. 10% means 'go slow,' 90% means 'go full speed.'" },
  { id:"calef_84", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un disyuntor de 15A se dispara tras 20 minutos de funcionamiento del horno. El motor consume 12A. ¿Cuál es la causa capciosa?", opciones:["El motor tiene un cortocircuito intermitente.", "Conexión floja en el disyuntor que genera calor local, engañando al bimetal del breaker y haciendo que salte por temperatura, no por amperaje real.", "El voltaje de la casa subió a 130V.", "El filtro de aire está tan limpio que el motor se acelera."], respuesta_correcta:1, explicacion:"El calor es amperaje para un breaker. Si el tornillo está flojo, el cable se calienta. El breaker 'siente' ese calor y cree que hay una sobrecarga, aunque el motor esté bien." , question: "A 15A circuit breaker trips after 20 minutes of furnace operation. The motor draws 12A. What is the tricky cause?", options: ["The motor has an intermittent short circuit.", "A loose connection at the breaker generating local heat, fooling the bimetallic strip into tripping on temperature rather than actual amperage.", "The house voltage rose to 130V.", "The air filter is so clean the motor is speeding up."], explanation: "Heat equals amperage for a breaker. If the terminal screw is loose, the wire heats up. The breaker 'senses' that heat and thinks there is an overload, even though the motor is fine." },
  { id:"calef_85", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V en el transformador, pero al conectar la bobina del contactor, el voltaje cae a 12V. El contactor es nuevo. ¿Qué indica esto?", opciones:["El contactor tiene la bobina equivocada.", "El transformador está subdimensionado (pocos VA) o hay una resistencia alta (conexión floja) en el circuito de control.", "Es normal en sistemas de calefacción eléctrica de 10kW.", "El termostato está en modo de protección de batería."], respuesta_correcta:1, explicacion:"El transformador no tiene la 'fuerza' (VA) para mantener el voltaje cuando se le pide trabajo. O es muy pequeño para tantos relés, o hay un cable casi roto que no deja pasar la corriente." , question: "You measure 24V at the transformer, but when you connect the contactor coil, the voltage drops to 12V. The contactor is new. What does this indicate?", options: ["The contactor has the wrong coil.", "The transformer is undersized (too few VA) or there is a high-resistance (loose connection) in the control circuit.", "This is normal in 10kW electric heating systems.", "The thermostat is in battery protection mode."], explanation: "The transformer does not have the 'strength' (VA) to maintain voltage when asked to work. Either it is too small for that many relays, or there is a nearly broken wire that will not pass the current." },
  { id:"calef_86", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor soplador de 120V consume 10A. Si el voltaje cae a 100V debido a una extensión muy larga, ¿qué sucede con el motor?", opciones:["El motor consume menos amperaje y corre más frío.", "El motor consume más amperaje (para mantener el torque), se sobrecalienta y probablemente dispare el protector térmico interno.", "La velocidad del motor se duplica por el efecto inductivo.", "El capacitor de marcha compensa la pérdida de voltaje automáticamente."], respuesta_correcta:1, explicacion:"Motores de inducción: si el voltaje baja, el amperaje sube para compensar. Es la receta perfecta para quemar un motor soplador en un día de baja tensión." , question: "A 120V blower motor draws 10A. If the voltage drops to 100V due to a very long extension cord, what happens to the motor?", options: ["The motor draws less amperage and runs cooler.", "The motor draws more amperage (to maintain torque), overheats, and will likely trip the internal thermal protector.", "The motor speed doubles due to the inductive effect.", "The run capacitor automatically compensates for the voltage loss."], explanation: "Induction motors: if voltage drops, amperage rises to compensate. It is the perfect recipe for burning out a blower motor on a low-voltage day." },
  { id:"calef_87", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide un capacitor de 5 mFD y lee 4.9 mFD. Sin embargo, el motor no arranca. ¿Cuál es la prueba definitiva?", opciones:["Medir el voltaje en el capacitor mientras el motor intenta arrancar; si es igual al voltaje de línea, el capacitor no está desfasando la corriente.", "Reemplazar el motor inmediatamente.", "Cortar el cable del común para ver si hay chispa.", "Girar el eje del motor; si está trabado, no importa el estado del capacitor."], respuesta_correcta:3, explicacion:"Capciosa: Antes de culpar a la electricidad, revisa la mecánica. Si el balero está fundido, el mejor capacitor del mundo no hará que ese motor gire." , question: "You measure a 5 MFD capacitor and read 4.9 MFD. However, the motor does not start. What is the definitive test?", options: ["Measure the voltage across the capacitor while the motor tries to start; if it equals line voltage, the capacitor is not phase-shifting the current.", "Replace the motor immediately.", "Cut the common wire to see if there is a spark.", "Spin the motor shaft; if it is seized, the capacitor's condition is irrelevant."], explanation: "Tricky: Before blaming the electrical side, check the mechanical side. If the bearing is fused, the best capacitor in the world will not make that motor spin." },
  { id:"calef_88", categoria:"CALEF_ELECTRICIDAD", pregunta:"En una placa de control moderna, ¿qué indica un LED parpadeando de forma rápida y constante (Heartbeat)?", opciones:["Falla crítica en el microprocesador.", "Operación normal; la placa está recibiendo energía y el software está corriendo correctamente (Status OK).", "Que el filtro de aire debe ser cambiado en menos de 24 horas.", "Llamada de servicio pendiente desde el termostato."], respuesta_correcta:1, explicacion:"Es el 'pulso' de la máquina. Si el LED parpadea rítmicamente, el cerebro electrónico está vivo. Si se queda fijo o da códigos de destellos, entonces hay un problema." , question: "On a modern control board, what does a rapidly and steadily blinking LED (Heartbeat) indicate?", options: ["A critical microprocessor failure.", "Normal operation; the board is receiving power and the software is running correctly (Status OK).", "The air filter must be changed within 24 hours.", "A pending service call from the thermostat."], explanation: "It is the machine's 'pulse.' If the LED blinks rhythmically, the electronic brain is alive. If it stays solid or gives flash codes, then there is a problem." },
  { id:"calef_89", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué sucede si el terminal 'C' (Común) de un termostato inteligente se conecta por error al terminal 'Y'?", opciones:["El termostato funcionará pero solo en modo frío.", "Se producirá un cortocircuito directo que fundirá el fusible de la placa de control en cuanto el termostato intente encender el aire acondicionado.", "La pantalla del termostato brillará el doble de lo normal.", "El soplador girará a la mitad de su velocidad nominal."], respuesta_correcta:1, explicacion:"C es un polo y Y es el retorno del otro polo (vía relé). Si los unes, es como tocar el positivo y negativo de una batería. ¡Adiós fusible!" , question: "What happens if the 'C' (Common) terminal of a smart thermostat is accidentally connected to the 'Y' terminal?", options: ["The thermostat will work but only in cooling mode.", "It will cause a direct short circuit that blows the control board fuse as soon as the thermostat tries to turn on the air conditioner.", "The thermostat screen will glow twice as bright as normal.", "The blower will spin at half its rated speed."], explanation: "C is one pole and Y is the return of the other pole (via a relay). If you connect them together, it is like touching the positive and negative of a battery. Goodbye fuse!" },
  { id:"calef_90", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Cuál es la diferencia técnica entre un motor 'Abierto' (Open Drip Proof) y uno 'Totalmente Cerrado' (TEFC) en HVAC?", opciones:["El cerrado es solo para uso en exteriores.", "El abierto permite que el aire pase por los devanados para enfriarse; el cerrado usa un ventilador externo para enfriar la carcasa sin que entre aire sucio al motor.", "El abierto consume la mitad de la energía eléctrica.", "Los motores cerrados no tienen rodamientos de bolas."], respuesta_correcta:1, explicacion:"Usa un motor abierto en un ambiente con grasa de cocina y morirá en un mes. El motor TEFC es más caro pero sobrevive en ambientes hostiles y sucios." , question: "What is the technical difference between an 'Open Drip Proof' (ODP) motor and a 'Totally Enclosed Fan Cooled' (TEFC) motor in HVAC?", options: ["The enclosed motor is for outdoor use only.", "The open motor allows air to pass through the windings for cooling; the enclosed motor uses an external fan to cool the housing without letting dirty air into the motor.", "The open motor uses half the electrical energy.", "Enclosed motors do not have ball bearings."], explanation: "Use an open motor in an environment with kitchen grease and it will die in a month. A TEFC motor is more expensive but survives in hostile, dirty environments." },
  { id:"calef_91", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V entre 'G' y 'C' en la placa, pero el motor soplador no arranca. ¿Qué es lo siguiente a revisar si el motor es PSC?", opciones:["El sensor de llama.", "El capacitor de marcha y la continuidad de los devanados del motor, además de verificar si el relé de la placa está cerrando los 120V.", "La presión del gas en la válvula.", "Cambiar el filtro de aire."], respuesta_correcta:1, explicacion:"Si la señal de control (24V) está ahí, la placa dio la orden. Ahora hay que ver si el motor tiene 'fuerza' (capacitor) y si le llega la energía de potencia (120V)." , question: "You measure 24V between 'G' and 'C' on the control board, but the blower motor does not start. What should you check next if the motor is PSC?", options: ["The flame sensor.", "The run capacitor and the continuity of the motor windings, plus verify that the board relay is closing and providing 120V.", "The gas pressure at the valve.", "Change the air filter."], explanation: "If the control signal (24V) is present, the board gave the order. Now you need to check if the motor has 'muscle' (capacitor) and if it is receiving the power supply (120V)." },
  { id:"calef_92", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Cuál es la función del 'Cable de Tierra de Seguridad' (Verde) en un horno?", opciones:["Transportar la señal de datos hacia el termostato.", "Proveer un camino de baja resistencia de regreso al panel eléctrico en caso de un cortocircuito, disparando el breaker y evitando electrocuciones.", "Mejorar el factor de potencia del motor soplador.", "Actuar como antena para el Wi-Fi del equipo."], respuesta_correcta:1, explicacion:"Es el salvavidas. Si un cable pelado toca el metal del horno, la electricidad viaja por el cable verde hacia el panel. Sin él, el chasis del horno tendría 120V esperando a que alguien lo toque." , question: "What is the purpose of the 'Safety Ground Wire' (green) in a furnace?", options: ["To carry the data signal to the thermostat.", "To provide a low-resistance path back to the electrical panel in the event of a short circuit, tripping the breaker and preventing electrocution.", "To improve the blower motor's power factor.", "To act as an antenna for the equipment's Wi-Fi."], explanation: "It is the lifeline. If a stripped wire touches the furnace metal, the electricity travels through the green wire to the panel. Without it, the furnace chassis would have 120V waiting for someone to touch it." },
  { id:"calef_93", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un horno de gas muestra un código de 'Límite de Alta Temperatura' abierto. El técnico nota que el filtro está limpio pero el aire sale a 70°C. ¿Cuál es el diagnóstico?", opciones:["El motor del soplador está girando demasiado rápido.", "Sobre-fuego (Overfiring): la presión del gas en el manifold es excesiva o los orificios son demasiado grandes para el diseño del intercambiador.", "El sensor de llama está en cortocircuito con el chasis.", "La altitud de la casa es inferior al nivel del mar."], respuesta_correcta:1, explicacion:"Si el aire se mueve bien pero sale muy caliente, es porque hay demasiado fuego adentro. La válvula de gas está mandando más BTUs de los que el metal puede procesar de forma segura." , question: "A gas furnace shows a 'High Temperature Limit' open code. The technician notes the filter is clean, but the supply air is coming out at 158 degrees F. What is the diagnosis?", options: ["The blower motor is spinning too fast.", "Over-firing: the gas manifold pressure is excessive or the orifices are too large for the heat exchanger design.", "The flame sensor is short-circuited to the chassis.", "The house altitude is below sea level."], explanation: "If the air moves well but comes out excessively hot, it is because there is too much fire inside. The gas valve is delivering more BTUs than the metal can safely process." },
  { id:"calef_94", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide un motor soplador PSC y obtiene 5 ohmios entre Start y Run, y 3 ohmios entre Run y Common. ¿Cuál debería ser la lectura entre Start y Common?", opciones:["2 ohmios.", "8 ohmios (la suma de ambos devanados).", "15 ohmios debido a la reactancia inductiva.", "0 ohmios si el motor está en cortocircuito."], respuesta_correcta:1, explicacion:"En un motor PSC, el devanado total (S a C) es la suma del devanado de arranque (S a R) y el de marcha (R a C). Si la suma no cuadra, el motor tiene un corto interno." , question: "You measure a PSC blower motor and get 5 ohms between Start and Run, and 3 ohms between Run and Common. What should the reading be between Start and Common?", options: ["2 ohms.", "8 ohms (the sum of both windings).", "15 ohms due to inductive reactance.", "0 ohms if the motor is short-circuited."], explanation: "In a PSC motor, the total winding (S to C) is the sum of the start winding (S to R) and the run winding (R to C). If the sum does not add up, the motor has an internal short." },
  { id:"calef_95", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor ECM gira muy lentamente y vibra. Usted mide 24V en todas las señales. ¿Qué es lo más probable que esté fallando?", opciones:["El termostato de pared.", "Falla de un transistor (IGBT) interno en el módulo de control del motor, lo que causa una pérdida de fase hacia el estator.", "El filtro de aire está demasiado limpio.", "El voltaje de la casa es de 120V en lugar de 240V."], respuesta_correcta:1, explicacion:"Si el cerebro del motor pierde una de las 'piernas' con las que empuja el rotor, el motor no puede girar bien, vibra y hace ruido, aunque tenga corriente." , question: "An ECM motor spins very slowly and vibrates. You measure 24V on all signals. What is most likely failing?", options: ["The wall thermostat.", "An internal transistor (IGBT) failure in the motor's control module, causing a loss of phase to the stator.", "The air filter is too clean.", "The house voltage is 120V instead of 240V."], explanation: "If the motor's brain loses one of the 'legs' it uses to push the rotor, the motor cannot spin properly, vibrates, and makes noise, even though it has power." },
  { id:"calef_96", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V en el terminal 'W' de la placa de control, pero el LED indica 'Open High Limit'. Usted puentea el límite y el horno arranca. ¿Cuál es la conclusión?", opciones:["La placa de control está defectuosa.", "El interruptor de límite está abierto (quemado) o realmente el horno se está sobrecalentando y el sensor está haciendo su trabajo.", "El transformador es demasiado potente.", "El termostato está en modo de ahorro de energía."], respuesta_correcta:1, explicacion:"El sensor está roto o el horno tiene fiebre. Jamás dejes el puente puesto. Hay que buscar por qué se abrió: ¿Filtro sucio? ¿Motor lento? ¿Ductos tapados?" , question: "You measure 24V at the 'W' terminal of the control board, but the LED indicates 'Open High Limit.' You jumper the limit and the furnace starts. What is the conclusion?", options: ["The control board is defective.", "The limit switch is open (burned out) or the furnace is actually overheating and the sensor is doing its job.", "The transformer is too powerful.", "The thermostat is in energy-saving mode."], explanation: "The sensor is either broken or the furnace is running too hot. Never leave the jumper in place. You must find out why it opened: Dirty filter? Slow motor? Blocked ductwork?" },
  { id:"calef_97", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide la resistencia de un elemento calefactor de 5kW y obtiene 11.5 ohmios. ¿Es este un valor correcto para un sistema de 240V?", opciones:["No, debería medir 0 ohmios.", "Sí, según la Ley de Ohm ($P = V^2 / R$), 5000W a 240V requiere aproximadamente 11.5 ohmios de resistencia.", "Es demasiado alto, el elemento está a punto de romperse.", "No se puede medir la resistencia de un elemento caliente."], respuesta_correcta:1, explicacion:"Hacer el cálculo es la única forma de saber si la resistencia está bien sin prenderla. Si midiera 50 ohmios, sabrías que no va a calentar casi nada." , question: "You measure the resistance of a 5kW heating element and get 11.5 ohms. Is this a correct value for a 240V system?", options: ["No, it should read 0 ohms.", "Yes, according to Ohm's Law (P = V squared / R), 5000W at 240V requires approximately 11.5 ohms of resistance.", "It is too high; the element is about to break.", "You cannot measure the resistance of a hot element."], explanation: "Doing the calculation is the only way to know if the element is good without powering it on. If it read 50 ohms, you would know it is not going to produce much heat." },
  { id:"calef_98", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué sucede si se instala un capacitor de 10 mFD en un motor que requiere uno de 5 mFD?", opciones:["El motor tendrá el doble de fuerza y durará más.", "El motor consumirá un exceso de amperaje, vibrará más y se sobrecalentará, lo que acortará drásticamente su vida útil.", "El motor girará a la mitad de su velocidad normal.", "El voltaje de la casa subirá a 130V por inducción."], respuesta_correcta:1, explicacion:"El capacitor debe ser exacto. Si le pones uno más grande, es como darle demasiada cafeína al motor; trabajará con mucha furia pero se quemará rápido." , question: "What happens if a 10 MFD capacitor is installed on a motor that requires a 5 MFD capacitor?", options: ["The motor will have double the power and last longer.", "The motor will draw excessive amperage, vibrate more, and overheat, drastically shortening its lifespan.", "The motor will spin at half its normal speed.", "The house voltage will rise to 130V due to induction."], explanation: "The capacitor must be the exact value. If you install one that is too large, it is like giving the motor too much caffeine; it will work with too much fury but burn out quickly." },
  { id:"calef_99", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V entre 'W' y 'C' en el termostato, pero 0V entre 'W' y 'C' en el horno. ¿Cuál es el diagnóstico?", opciones:["El transformador del horno está fallando.", "El cable que lleva la señal de calefacción (W) está roto o desconectado en algún punto entre el termostato y el equipo.", "La placa de control del horno está en modo de bloqueo.", "El soplador está consumiendo toda la energía del sistema."], respuesta_correcta:1, explicacion:"Si el termostato manda la señal pero no llega al horno, la 'carretera' (el cable) tiene un bache o está cortada. Toca buscar dónde se rompió el hilo." , question: "You measure 24V between 'W' and 'C' at the thermostat, but 0V between 'W' and 'C' at the furnace. What is the diagnosis?", options: ["The furnace transformer is failing.", "The wire carrying the heating signal (W) is broken or disconnected somewhere between the thermostat and the equipment.", "The furnace control board is in lockout mode.", "The blower is consuming all the system's energy."], explanation: "If the thermostat sends the signal but it does not reach the furnace, the 'highway' (the wire) has a break or is cut somewhere. You need to find where the conductor is severed." },
  { id:"calef_100", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 120V en la entrada del transformador y 0V en la salida de 24V. No hay cortocircuitos. ¿Cuál es el diagnóstico?", opciones:["El transformador es demasiado pequeño.", "El devanado primario o secundario del transformador está abierto (quemado); el componente debe reemplazarse.", "El transformador necesita una batería de respaldo.", "La polaridad de los 120V está invertida."], respuesta_correcta:1, explicacion:"Si entra luz pero no sale, el transformador se convirtió en una piedra. Algún esfuerzo excesivo o un pico de voltaje rompió el cable interno de cobre." , question: "You measure 120V at the transformer input and 0V at the 24V output. There are no short circuits. What is the diagnosis?", options: ["The transformer is too small.", "The primary or secondary winding of the transformer is open (burned out); the component must be replaced.", "The transformer needs a backup battery.", "The 120V polarity is reversed."], explanation: "If power goes in but does not come out, the transformer has become a paperweight. Some excessive load or a voltage spike broke the internal copper wire." },
  { id:"calef_101", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor de soplador PSC zumba pero no arranca. Usted lo ayuda con la mano y arranca con fuerza. ¿Cuál es el problema?", opciones:["El motor tiene un devanado abierto.", "El capacitor de marcha está defectuoso y no puede proveer el torque de arranque necesario para vencer la inercia inicial.", "El eje del motor está torcido.", "El voltaje de la línea es demasiado alto."], respuesta_correcta:1, explicacion:"El motor perdió su 'empujón' inicial. El capacitor crea el campo magnético que dice 'gira hacia allá'. Sin él, el motor se queda vibrando sin saber para dónde ir." , question: "A PSC blower motor hums but does not start. You help it by hand and it starts with force. What is the problem?", options: ["The motor has an open winding.", "The run capacitor is defective and cannot provide the starting torque needed to overcome initial inertia.", "The motor shaft is bent.", "The line voltage is too high."], explanation: "The motor lost its initial 'push.' The capacitor creates the magnetic field that says 'spin this way.' Without it, the motor just sits there vibrating, not knowing which direction to go." },
  { id:"calef_102", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 0V entre 'R' y 'C' en el termostato, pero el horno está encendido y tiene luz. ¿Cuál es el diagnóstico?", opciones:["El termostato no necesita energía.", "El cable común (C) no está conectado o está roto; el termostato podría estar funcionando solo con baterías y no recibir carga del horno.", "La placa de control quemó su transformador.", "El interruptor de límite está abierto."], respuesta_correcta:1, explicacion:"Si el horno tiene luz pero el termostato no recibe los 24V, el cable se soltó. Es la razón número uno por la cual los termostatos inteligentes 'se mueren' de repente." , question: "You measure 0V between 'R' and 'C' at the thermostat, but the furnace is on and has power. What is the diagnosis?", options: ["The thermostat does not need power.", "The common (C) wire is not connected or is broken; the thermostat may be running solely on batteries and not receiving a charge from the furnace.", "The control board burned out its transformer.", "The limit switch is open."], explanation: "If the furnace has power but the thermostat is not receiving 24V, the wire came loose. This is the number one reason smart thermostats 'die' suddenly." },
  { id:"calef_103", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 120V en el terminal de un motor soplador, pero el motor está ardiendo al tacto y no se mueve. ¿Cuál es el diagnóstico?", opciones:["El motor no tiene suficiente voltaje.", "El motor está trabado mecánicamente o tiene un cortocircuito interno (devanado quemado) que genera calor excesivo sin producir movimiento.", "El capacitor de marcha es demasiado grande.", "El filtro de aire está creando demasiada succión."], respuesta_correcta:1, explicacion:"Si tiene luz y está caliente pero no gira, es un problema interno grave. El motor está tratando de luchar contra un bloqueo o su cableado interno se fundió." , question: "You measure 120V at a blower motor terminal, but the motor is burning hot to the touch and not spinning. What is the diagnosis?", options: ["The motor does not have enough voltage.", "The motor is mechanically seized or has an internal short circuit (burned winding) generating excessive heat without producing movement.", "The run capacitor is too large.", "The air filter is creating too much suction."], explanation: "If it has power and is hot but not spinning, it is a serious internal problem. The motor is trying to fight a blockage or its internal wiring has fused." },
  { id:"calef_104", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor arranca solo si usted gira el eje con un palo, pero el capacitor de marcha mide bien. ¿Qué otra cosa falla?", opciones:["El motor tiene un devanado de arranque (Start) abierto internamente; aunque el capacitor esté bien, el circuito no se completa.", "El voltaje de la casa es de corriente directa.", "El eje del motor está perfectamente lubricado.", "El sensor de llama está bloqueando el arranque del soplador."], respuesta_correcta:0, explicacion:"Si el cable interno de arranque se rompió, el motor nunca tendrá fuerza por sí solo. El capacitor manda la señal, pero el motor no tiene cómo recibirla." , question: "A motor starts only if you spin the shaft with a stick, but the run capacitor tests good. What else is failing?", options: ["The motor has an internally open start winding; even though the capacitor is good, the circuit is not complete.", "The house voltage is DC.", "The motor shaft is perfectly lubricated.", "The flame sensor is blocking the blower from starting."], explanation: "If the internal start winding wire is broken, the motor will never have enough force on its own. The capacitor sends the signal, but the motor has no way to receive it." },
  { id:"calef_105", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V entre 'W' y 'C' en el horno, pero el motor inductor no arranca. El motor tiene 120V de entrada. ¿Cuál es el diagnóstico?", opciones:["La placa de control no está cerrando el relé del inductor.", "El motor inductor está quemado (devanado abierto) o el relé de la placa de control está fallando internamente.", "El transformador de 24V es demasiado pequeño.", "El sensor de llama está bloqueando el inductor."], respuesta_correcta:1, explicacion:"Si hay orden (24V) y hay potencia (120V), pero no hay movimiento, el motor está muerto. Si no hubiera 120V, la falla sería de la placa de control." , question: "You measure 24V between 'W' and 'C' at the furnace, but the inducer motor does not start. The motor has 120V at its input. What is the diagnosis?", options: ["The control board is not closing the inducer relay.", "The inducer motor is burned out (open winding) or the control board relay is failing internally.", "The 24V transformer is too small.", "The flame sensor is blocking the inducer."], explanation: "If there is a command (24V) and there is power (120V) but no movement, the motor is dead. If there were no 120V, the fault would be in the control board." },
  { id:"calef_106", categoria:"CALEF_ELECTRICIDAD", pregunta:"En un sistema comunicante de 4 hilos (R, C, D+, D-), ¿qué sucede si se cruzan accidentalmente los cables de datos con los de energía?", opciones:["El termostato simplemente no encenderá.", "Daño catastrófico inmediato a los transceptores de comunicación de la placa de control y del termostato por sobretensión en el bus de datos.", "El sistema entrará en un modo de diagnóstico automático de seguridad.", "La velocidad de transmisión de datos bajará a 1200 baudios."], respuesta_correcta:1, explicacion:"Los terminales de datos operan a voltajes bajos (5V DC). Meterle 24V AC de la línea de energía 'fríe' los chips de comunicación al instante." , question: "In a 4-wire communicating system (R, C, D+, D-), what happens if the data wires are accidentally crossed with the power wires?", options: ["The thermostat simply will not turn on.", "Immediate catastrophic damage to the communication transceivers of the control board and thermostat due to overvoltage on the data bus.", "The system will enter an automatic safety diagnostic mode.", "The data transmission speed will drop to 1200 baud."], explanation: "Data terminals operate at low voltages (5V DC). Feeding 24V AC from the power line into them 'fries' the communication chips instantly." },
  { id:"calef_107", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un horno moderno tiene un 'Relé de Aislamiento' para el motor del soplador. ¿Cuál es su propósito técnico principal?", opciones:["Permitir que el motor use baterías en caso de emergencia.", "Separar el circuito de control de 24V de la placa electrónica del circuito de potencia de 120V/240V del motor, protegiendo al microprocesador.", "Aumentar el amperaje del motor en un 15%.", "Reducir la velocidad del ventilador durante el modo de espera."], respuesta_correcta:1, explicacion:"Es una barrera de seguridad. Si el motor entra en corto, el relé se quema pero protege el 'cerebro' (la placa de control) que es mucho más cara de reemplazar." , question: "A modern furnace has an 'Isolation Relay' for the blower motor. What is its primary technical purpose?", options: ["To allow the motor to run on batteries in an emergency.", "To separate the 24V control circuit of the electronic board from the 120V/240V power circuit of the motor, protecting the microprocessor.", "To increase the motor amperage by 15%.", "To reduce the fan speed during standby mode."], explanation: "It is a safety barrier. If the motor shorts out, the relay burns but protects the 'brain' (the control board), which is much more expensive to replace." },
  { id:"calef_108", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué es la 'Corriente de Rotor Bloqueado' (LRA) y por qué es importante para el dimensionamiento de los cables de un horno eléctrico?", opciones:["Es la corriente que consume el motor cuando gira a máxima velocidad.", "Es el amperaje inicial masivo que consume el motor al arrancar desde cero; los cables y el disyuntor deben soportar este pico momentáneo.", "La corriente mínima para que el termostato no se apague.", "El amperaje que genera el motor cuando se apaga por inercia."], respuesta_correcta:1, explicacion:"Al arrancar, un motor es casi un cortocircuito. Consume hasta 5 o 6 veces su amperaje normal. Si el cable es muy delgado, el voltaje caerá y el motor nunca arrancará." , question: "What is 'Locked Rotor Amperage' (LRA) and why is it important for sizing the wiring of an electric furnace?", options: ["It is the current the motor draws when spinning at maximum speed.", "It is the massive initial amperage the motor draws when starting from a standstill; the wires and breaker must be able to handle this momentary spike.", "The minimum current for the thermostat not to shut off.", "The amperage generated by the motor when it coasts to a stop."], explanation: "At startup, a motor is nearly a short circuit. It draws up to 5 or 6 times its normal amperage. If the wire is too thin, the voltage will drop and the motor will never start." },
  { id:"calef_109", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V entre 'R' y 'W' en la placa del horno, pero el termostato está pidiendo calor. ¿Cuál es el diagnóstico?", opciones:["El termostato está funcionando correctamente.", "El contacto del termostato está abierto (falla del equipo o del cableado); si estuviera cerrado, la diferencia de potencial sería 0V.", "Existe un cortocircuito directo en la válvula de gas.", "El transformador de 24V está invertido respecto al neutro."], respuesta_correcta:1, explicacion:"Si mides 'voltaje' a través de un interruptor, es porque el interruptor está ABIERTO. Si estuviera cerrado, los dos puntos serían el mismo cable y el multímetro marcaría cero." , question: "You measure 24V between 'R' and 'W' at the furnace control board, but the thermostat is calling for heat. What is the diagnosis?", options: ["The thermostat is functioning correctly.", "The thermostat contact is open (equipment or wiring failure); if it were closed, the potential difference would be 0V.", "There is a direct short circuit in the gas valve.", "The 24V transformer is reversed relative to the neutral."], explanation: "If you measure 'voltage' across a switch, it means the switch is OPEN. If it were closed, the two points would be the same wire and the multimeter would read zero." },
  { id:"calef_110", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor soplador PSC consume 5.0A con un filtro MERV 8. Al poner un filtro MERV 16 (muy restrictivo), el amperaje baja a 4.2A. ¿Por qué?", opciones:["Porque el filtro MERV 16 es más eficiente eléctricamente.", "Porque el motor realiza menos trabajo mecánico al mover menos masa de aire debido a la alta restricción del filtro (Fan Law).", "Debido a que el aire limpio tiene menos resistencia al avance.", "El motor entra en modo de ahorro de energía 'Eco-Mode'."], respuesta_correcta:1, explicacion:"Capciosa: Un ventilador tapado no 'sufre' más, simplemente no puede agarrar aire. Como no mueve peso, el motor descansa y el amperaje baja. ¡Pero el horno se va a quemar!" , question: "A PSC blower motor draws 5.0A with a MERV 8 filter. After installing a MERV 16 (highly restrictive) filter, the amperage drops to 4.2A. Why?", options: ["Because the MERV 16 filter is more electrically efficient.", "Because the motor performs less mechanical work by moving less air mass due to the high filter restriction (Fan Law).", "Because clean air has less resistance to movement.", "The motor enters an 'Eco-Mode' energy-saving mode."], explanation: "Tricky: A blocked fan does not 'struggle' more; it simply cannot grab air. Since it moves no weight, the motor rests and amperage drops. But the furnace will overheat!" },
  { id:"calef_111", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 0V entre los terminales de una bobina de contactor de 24V, pero el horno está pidiendo calor y el inductor está corriendo. ¿Qué es lo más probable?", opciones:["La placa de control está esperando a que pase el tiempo de retardo (delay) antes de activar el soplador principal.", "El transformador de 24V está quemado.", "El motor del soplador está en cortocircuito.", "El termostato no tiene baterías suficientes."], respuesta_correcta:0, explicacion:"Los hornos no prenden el ventilador de inmediato. Esperan a que el intercambiador de calor esté caliente (unos 30-45 segundos) para no soplar aire frío a los ocupantes." , question: "You measure 0V across the terminals of a 24V contactor coil, but the furnace is calling for heat and the inducer is running. What is most likely happening?", options: ["The control board is waiting for the time delay to elapse before activating the main blower.", "The 24V transformer is burned out.", "The blower motor is short-circuited.", "The thermostat does not have enough battery power."], explanation: "Furnaces do not turn on the blower immediately. They wait for the heat exchanger to warm up (about 30-45 seconds) so they do not blow cold air to the occupants." },
  { id:"calef_112", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted encuentra que el Neutro y la Tierra están puenteados DENTRO del gabinete del horno. ¿Por qué es esto una violación de código y seguridad?", opciones:["Porque el cable verde es más caro que el blanco.", "Crea caminos de corriente paralelos por el chasis metálico del equipo, pudiendo causar choques eléctricos y fallas en la detección electrónica de llama.", "Aumenta el consumo de vatios del motor del ventilador.", "El código exige que el puente se haga solo con soldadura de plata."], respuesta_correcta:1, explicacion:"El Neutro y la Tierra solo se unen en el panel principal. Si los unes en el horno, el metal del horno ahora lleva corriente. ¡Si lo tocas, podrías recibir una descarga!" , question: "You find that Neutral and Ground are jumpered INSIDE the furnace cabinet. Why is this a code and safety violation?", options: ["Because the green wire is more expensive than the white one.", "It creates parallel current paths through the metal chassis of the equipment, potentially causing electric shocks and failures in electronic flame detection.", "It increases the watt consumption of the fan motor.", "Code requires the jumper to be made only with silver solder."], explanation: "Neutral and Ground are only bonded at the main panel. If you bond them at the furnace, the furnace metal now carries current. If you touch it, you could get a shock!" },
  { id:"calef_113", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor soplador PSC zumba y no arranca. El capacitor mide bien. El eje gira libremente con la mano. ¿Cuál es el diagnóstico?", opciones:["El motor tiene un devanado de arranque abierto internamente.", "El voltaje de la línea de 120V está invertido con el neutro.", "El termostato está enviando una señal de corriente directa por error.", "El filtro de aire es de un tamaño incorrecto."], respuesta_correcta:0, explicacion:"Si el motor tiene 'comida' (luz) y no está trabado, pero no sabe para dónde ir (zumba), es que el circuito de arranque interno está roto. Toca cambiar el motor." , question: "A PSC blower motor hums and does not start. The capacitor tests good. The shaft spins freely by hand. What is the diagnosis?", options: ["The motor has an internally open start winding.", "The 120V line voltage is reversed with the neutral.", "The thermostat is sending a DC signal by mistake.", "The air filter is the wrong size."], explanation: "If the motor has 'food' (power) and is not seized, but does not know which way to go (hums), the internal start circuit is broken. The motor must be replaced." },
  { id:"calef_114", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide un capacitor de 5 mFD y obtiene una lectura de 5.1 mFD. Sin embargo, el motor se apaga por térmico a los 10 minutos. ¿Qué revisaría?", opciones:["Reemplazar el capacitor por uno de 10 mFD.", "Verificar el amperaje de marcha del motor; es probable que la rueda del soplador esté sucia o los rodamientos estén fallando bajo carga térmica.", "Bajar el voltaje de la casa a 110V.", "Cambiar el sensor de llama del horno."], respuesta_correcta:1, explicacion:"El capacitor está bien. El motor se calienta por un problema mecánico (mugre en las aspas o falta de grasa). El calor acumulado hace que el motor 'se proteja' y se apague." , question: "You measure a 5 MFD capacitor and get a reading of 5.1 MFD. However, the motor shuts off on thermal protector after 10 minutes. What would you check?", options: ["Replace the capacitor with a 10 MFD.", "Verify the motor's running amperage; the blower wheel is likely dirty or the bearings are failing under thermal load.", "Lower the house voltage to 110V.", "Replace the furnace flame sensor."], explanation: "The capacitor is fine. The motor overheats due to a mechanical problem (dirty blades or lack of lubrication). The accumulated heat causes the motor to 'protect itself' and shut down." },
  { id:"calef_115", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si un circuito de 24V tiene una resistencia total de 2 ohmios, ¿cuántos Watts de potencia consume?", opciones:["12 Watts.", "288 Watts ($P = V^2 / R$).", "48 Watts.", "0 Watts por falta de inductancia."], respuesta_correcta:1, explicacion:"$24 	imes 24 = 576$. $576 / 2 = 288$. Es mucha potencia para un circuito de control; probablemente fundiría el transformador de 40VA de inmediato." , question: "If a 24V circuit has a total resistance of 2 ohms, how many watts of power does it consume?", options: ["12 watts.", "288 watts (P = V squared / R).", "48 watts.", "0 watts due to lack of inductance."], explanation: "24 x 24 = 576. 576 / 2 = 288. That is a lot of power for a control circuit; it would probably blow the 40VA transformer immediately." },
  { id:"calef_116", categoria:"CALEF_ELECTRICIDAD", pregunta:"En un sistema comunicante de 4 hilos, usted mide 2.5V DC constantes entre los terminales de datos (D+ y D-) mientras el equipo intenta hablar. ¿Qué diagnóstico es el más probable?", opciones:["La comunicación es perfecta y estable.", "Bus de datos bloqueado o en 'colisión'; debería haber un voltaje pulsante (oscilante) que indique el tráfico de bits.", "El termostato está en modo de ahorro de energía analógico.", "Falta la resistencia de terminación de 120 ohmios en la unidad exterior."], respuesta_correcta:1, explicacion:"Los datos son pulsos. Si el voltaje está 'congelado' en un valor fijo, significa que los chips no están enviando información o hay un corto que mantiene la línea en estado lógico alto permanente." , question: "In a 4-wire communicating system, you measure a constant 2.5V DC between the data terminals (D+ and D-) while the equipment is trying to communicate. What is the most likely diagnosis?", options: ["Communication is perfect and stable.", "The data bus is blocked or in 'collision'; there should be a pulsating (oscillating) voltage indicating bit traffic.", "The thermostat is in analog energy-saving mode.", "The 120-ohm termination resistor is missing on the outdoor unit."], explanation: "Data consists of pulses. If the voltage is 'frozen' at a fixed value, it means the chips are not sending information or there is a short holding the line in a permanent logic-high state." },
  { id:"calef_117", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide un motor soplador PSC y nota que el amperaje de marcha es un 20% superior al nominal (FLA). El capacitor es nuevo y correcto. ¿Qué revisaría después?", opciones:["La polaridad de los 120V de entrada.", "La presión estática total externa (TESP); una restricción masiva en los ductos o un serpentín de evaporador tapado obligan al motor a trabajar en una zona ineficiente de calor.", "El color de los cables del termostato.", "Si el motor tiene lubricación permanente o requiere aceite."], respuesta_correcta:1, explicacion:"Si el motor no puede mover el aire que debe, se calienta. Ese calor aumenta la resistencia de los devanados y dispara el amperaje. Es un motor 'ahogándose' mecánicamente." , question: "You measure a PSC blower motor and note the running amperage is 20% above the rated FLA. The capacitor is new and correct. What would you check next?", options: ["The polarity of the 120V input.", "The Total External Static Pressure (TESP); a massive restriction in the ductwork or a clogged evaporator coil is forcing the motor to operate in an inefficient, high-heat zone.", "The color of the thermostat wires.", "Whether the motor has permanent lubrication or requires oil."], explanation: "If the motor cannot move the air it should, it heats up. That heat increases the winding resistance and drives up the amperage. It is a motor 'suffocating' mechanically." },
  { id:"calef_118", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Cuál es la función del 'Varistor' (MOV) en la entrada de alimentación de una placa de control electrónica?", opciones:["Aumentar el brillo de los LEDs de diagnóstico.", "Actuar como un protector contra transitorios; se pone en corto para derivar picos de voltaje (rayos o sobretensiones) a tierra y proteger el microprocesador.", "Medir la temperatura del transformador de 24V.", "Cambiar la frecuencia de 60Hz a 50Hz automáticamente."], respuesta_correcta:1, explicacion:"Es el guardaespaldas de la placa. Si hay un rayo cerca, el MOV 'recibe la bala' y se quema para que el resto de la placa sobreviva. Si ves un componente quemado y negro cerca de la entrada, es este." , question: "What is the function of the 'Varistor' (MOV) at the power input of an electronic control board?", options: ["To increase the brightness of the diagnostic LEDs.", "To act as a transient voltage protector; it shorts to divert voltage spikes (lightning or surges) to ground and protect the microprocessor.", "To measure the 24V transformer temperature.", "To automatically switch the frequency from 60Hz to 50Hz."], explanation: "It is the board's bodyguard. If there is a nearby lightning strike, the MOV 'takes the bullet' and burns so the rest of the board survives. If you see a burned, blackened component near the input, this is it." },
  { id:"calef_119", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 120V AC en los terminales de un motor soplador, pero el motor está frío y no zumba. Al medir continuidad entre los cables, obtiene 'OL'. ¿Qué falló?", opciones:["El capacitor de marcha está abierto.", "El protector térmico interno del motor o un devanado se quemó y abrió el circuito; el motor es chatarra eléctrica.", "El motor es de 240V y solo recibe 120V.", "Falta la señal de 24V del termostato."], respuesta_correcta:1, explicacion:"Si tiene energía y no hace nada (ni calienta ni zumba) y no hay continuidad, el camino de la electricidad dentro del motor se rompió. Es un 'fallecimiento' total del motor." , question: "You measure 120V AC at the terminals of a blower motor, but the motor is cold and does not hum. When measuring continuity between the wires, you get 'OL.' What failed?", options: ["The run capacitor is open.", "The motor's internal thermal protector or a winding burned out and opened the circuit; the motor is electrical scrap.", "The motor is a 240V unit receiving only 120V.", "The 24V thermostat signal is missing."], explanation: "If it has power and does nothing (does not heat up or hum) and there is no continuity, the electrical path inside the motor is broken. It is a total motor 'death.'" },
  { id:"calef_120", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V entre 'C' y el chasis de metal del horno. ¿Qué indica esta lectura técnica?", opciones:["Operación normal del transformador de control.", "El transformador no está correctamente referenciado a tierra o hay una falla de aislamiento en el devanado secundario; esto impedirá la detección de llama por ionización.", "El motor del soplador está en cortocircuito con el termostato.", "El voltaje de la casa es de 240V sin neutro."], respuesta_correcta:1, explicacion:"El terminal Común (C) debe estar unido al chasis (tierra). Si mides 24V ahí, la 'tierra' no es tierra. Sin una tierra sólida, el sensor de llama no funciona porque no tiene retorno." , question: "You measure 24V between 'C' and the metal chassis of the furnace. What does this technical reading indicate?", options: ["Normal operation of the control transformer.", "The transformer is not properly referenced to ground, or there is an insulation failure in the secondary winding; this will prevent ionization flame detection from working.", "The blower motor is short-circuited to the thermostat.", "The house voltage is 240V without a neutral."], explanation: "The Common (C) terminal must be bonded to the chassis (ground). If you measure 24V there, the 'ground' is not ground. Without a solid ground, the flame sensor will not work because it has no return path." },
  { id:"calef_121", categoria:"CALEF_ELECTRICIDAD", pregunta:"En un motor ECM, ¿qué significa que el motor esté en modo 'Go To Zero'?", opciones:["Que el motor ha alcanzado la velocidad máxima de 5000 RPM.", "Es una orden de la placa de control para que el motor se detenga de forma controlada y verifique su posición de reposo.", "El motor ha perdido la comunicación con el termostato digital.", "Indica que el capacitor de marcha tiene 0 microfaradios."], respuesta_correcta:1, explicacion:"Los ECM son inteligentes. A veces la placa les pide detenerse para recalibrar los sensores de torque y flujo antes de empezar un nuevo ciclo de calefacción." , question: "In an ECM motor, what does 'Go To Zero' mode mean?", options: ["The motor has reached its maximum speed of 5000 RPM.", "It is a command from the control board for the motor to stop in a controlled manner and verify its resting position.", "The motor has lost communication with the digital thermostat.", "It indicates the run capacitor has 0 microfarads."], explanation: "ECMs are intelligent. Sometimes the board tells them to stop so they can recalibrate their torque and airflow sensors before starting a new heating cycle." },
  { id:"calef_122", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted encuentra que el cable de 'Neutro' de un horno de 120V tiene 15V AC respecto a la tierra. ¿Cómo afecta esto a la electrónica?", opciones:["Mejora la velocidad de procesamiento de la placa.", "Causa errores erráticos en el circuito de detección de llama, ya que la placa usa el neutro como referencia de cero para medir los microamperios de la llama.", "Aumenta la fuerza del arco eléctrico en el ignitor.", "No afecta, los 120V se mantienen constantes entre línea y neutro."], respuesta_correcta:1, explicacion:"El neutro debería tener 0V. Si tiene 15V, hay un problema de cableado en la casa. Esto 'ensucia' la señal de los sensores y el horno se apagará solo sin razón aparente." , question: "You find that the Neutral wire of a 120V furnace has 15V AC with respect to ground. How does this affect the electronics?", options: ["It improves the board's processing speed.", "It causes erratic errors in the flame detection circuit, since the board uses Neutral as a zero reference to measure the microamps from the flame.", "It increases the arc strength of the igniter.", "No effect; 120V is maintained constant between Line and Neutral."], explanation: "Neutral should have 0V. If it has 15V, there is a wiring problem in the house. This 'dirties' the sensor signals and the furnace will shut down on its own for no apparent reason." },
  { id:"calef_123", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si un banco de resistencias de 20kW se conecta a una línea que tiene una caída de voltaje del 10%, ¿cuánta potencia calorífica se pierde?", opciones:["Se pierde el 10% de la potencia.", "Se pierde aproximadamente el 19-20% de la potencia ($P = V^2 / R$), reduciendo significativamente la capacidad de calefacción del equipo.", "La potencia se mantiene igual porque la resistencia es fija.", "El amperaje aumenta para compensar la caída de voltaje."], respuesta_correcta:1, explicacion:"Matemática cruel: si el voltaje baja un poco, el calor baja mucho. Por eso es vital que los cables sean gruesos y las conexiones estén bien apretadas." , question: "If a 20kW heating element bank is connected to a line with a 10% voltage drop, how much heating power is lost?", options: ["10% of the power is lost.", "Approximately 19-20% of the power is lost (P = V squared / R), significantly reducing the equipment's heating capacity.", "Power stays the same because resistance is fixed.", "Amperage increases to compensate for the voltage drop."], explanation: "Harsh math: if the voltage drops a little, the heat drops a lot. That is why it is vital that cables are thick and connections are tight." },
  { id:"calef_124", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 12 ohmios en la bobina de un relé de 24V. Al aplicar 24V, el relé vibra violentamente (chattering). ¿Qué está ocurriendo?", opciones:["El relé está perfectamente sano.", "El voltaje de 24V está 'cayendo' bajo carga debido a una conexión suelta o un transformador débil, haciendo que el relé abra y cierre rápidamente.", "La bobina del relé tiene un cortocircuito con el núcleo de hierro.", "El relé es de corriente directa y se conectó a corriente alterna."], respuesta_correcta:1, explicacion:"Es como si el relé no tuviera fuerza para quedarse pegado. Se pega, el voltaje cae, se despega, el voltaje sube, y así mil veces. Esto quema los contactos en minutos." , question: "You measure 12 ohms across the coil of a 24V relay. When 24V is applied, the relay chatters violently. What is happening?", options: ["The relay is perfectly healthy.", "The 24V is 'sagging' under load due to a loose connection or a weak transformer, causing the relay to rapidly open and close.", "The relay coil has a short circuit to the iron core.", "The relay is a DC type and was connected to AC."], explanation: "It is as if the relay does not have enough force to stay pulled in. It engages, the voltage drops, it releases, the voltage rises, and so on thousands of times. This burns the contacts in minutes." },
  { id:"calef_125", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor de soplador PSC tiene tres cables de velocidad (Negro, Azul, Rojo). ¿Qué cable ofrece técnicamente la mayor resistencia eléctrica interna?", opciones:["El cable Negro (Alta velocidad).", "El cable Rojo (Baja velocidad); a mayor resistencia, menor flujo de corriente y menor velocidad de rotación del campo magnético.", "El cable Azul (Velocidad media).", "Todos tienen la misma resistencia si el motor es de 1/2 HP."], respuesta_correcta:1, explicacion:"Capciosa: Para ir lento, necesitas 'frenar' la electricidad con más vueltas de cable (más resistencia). Por eso el cable de baja velocidad siempre mide más ohmios." , question: "A PSC blower motor has three speed wires (Black, Blue, Red). Which wire technically has the highest internal electrical resistance?", options: ["The Black wire (High speed).", "The Red wire (Low speed); higher resistance means less current flow and a lower rotational speed of the magnetic field.", "The Blue wire (Medium speed).", "They all have the same resistance if the motor is 1/2 HP."], explanation: "Tricky: To go slow, you need to 'brake' the electricity with more wire turns (more resistance). That is why the low-speed wire always reads higher ohms." },
  { id:"calef_126", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V en el terminal 'W' del horno, pero el motor inductor no arranca. Al medir la resistencia del motor inductor, obtiene 15 ohmios. ¿Cuál es el diagnóstico?", opciones:["El motor inductor está quemado.", "La placa de control tiene un relé defectuoso que no está enviando los 120V de potencia al motor, a pesar de recibir la orden del termostato.", "El transformador de 24V es demasiado potente para el motor.", "El sensor de llama está bloqueando el arranque del inductor."], respuesta_correcta:1, explicacion:"Si el motor mide 15 ohmios, su cableado interno está bien. Si no se mueve teniendo orden, es que la placa no le está dando la 'comida' (120V) que necesita para girar." , question: "You measure 24V at the 'W' terminal of the furnace, but the inducer motor does not start. When you measure the inducer motor resistance, you get 15 ohms. What is the diagnosis?", options: ["The inducer motor is burned out.", "The control board has a defective relay that is not sending 120V power to the motor, despite receiving the thermostat command.", "The 24V transformer is too powerful for the motor.", "The flame sensor is blocking the inducer from starting."], explanation: "If the motor reads 15 ohms, its internal wiring is fine. If it is not moving while having a command, the board is not giving it the 'food' (120V) it needs to spin." },
  { id:"calef_127", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor soplador PSC tiene un capacitor de marcha de 5 mFD. El técnico lo mide y marca 4.5 mFD. ¿Debería reemplazarse según el estándar de la industria?", opciones:["No, está dentro del 10% de tolerancia normal.", "Sí, la mayoría de los fabricantes exigen el reemplazo si la capacitancia cae más del 6% o 10% del valor nominal para proteger los devanados del motor.", "No, los motores funcionan mejor con menos capacitancia en invierno.", "Solo si el motor hace un ruido fuerte de zumbido."], respuesta_correcta:1, explicacion:"No esperes a que falle. Un capacitor débil hace que el motor consuma más corriente y se caliente. Cambiarlo ahora por $20 salva un motor de $300." , question: "A PSC blower motor has a 5 MFD run capacitor. The technician measures it at 4.5 MFD. Should it be replaced according to industry standards?", options: ["No, it is within the normal 10% tolerance.", "Yes, most manufacturers require replacement if the capacitance drops more than 6% or 10% of the rated value to protect the motor windings.", "No, motors actually perform better with less capacitance in winter.", "Only if the motor makes a loud humming noise."], explanation: "Do not wait for it to fail. A weak capacitor makes the motor draw more current and overheat. Replacing it now for $20 saves a $300 motor." },
  { id:"calef_128", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Por qué es peligroso usar un disyuntor de 20A en un circuito de control de un horno donde el cableado es de calibre 18 AWG?", opciones:["Porque el motor del soplador girará demasiado rápido.", "El cable de calibre 18 se derretirá e incendiará antes de que el disyuntor de 20A detecte la sobrecarga (el cable se convierte en el fusible).", "El transformador de 24V entregará el doble de voltaje.", "No hay riesgo si el horno es de gas natural."], respuesta_correcta:1, explicacion:"Seguridad básica. El disyuntor protege al cable. Si el cable es 'flaquito', no aguanta 20 amperios. Se quemará la casa antes de que el interruptor se entere." , question: "Why is it dangerous to use a 20A circuit breaker on a furnace control circuit where the wiring is 18 AWG?", options: ["Because the blower motor will spin too fast.", "The 18 AWG wire will melt and catch fire before the 20A breaker detects the overload (the wire becomes the fuse).", "The 24V transformer will deliver double the voltage.", "There is no risk if the furnace runs on natural gas."], explanation: "Basic safety. The breaker protects the wire. If the wire is 'skinny,' it cannot handle 20 amps. The house will catch fire before the breaker knows there is a problem." },
  { id:"calef_129", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor ECM reporta una falla de 'Comunicación Perdida' (Lost Comm). El técnico mide 24V en los pines de datos. ¿Qué indica esto sobre el módulo?", opciones:["Que el termostato digital tiene la batería baja.", "Falla interna del microprocesador del módulo del motor o del optoacoplador que traduce la señal de la placa hacia el motor.", "El cable de tierra del horno está desconectado.", "El motor está girando demasiado rápido y generó interferencia."], respuesta_correcta:1, explicacion:"Si el voltaje de control está presente pero el motor no 'entiende' la orden, el problema es el 'traductor' interno del motor. El módulo electrónico está frito." , question: "An ECM motor reports a 'Lost Communication' (Lost Comm) fault. The technician measures 24V on the data pins. What does this indicate about the module?", options: ["The digital thermostat has a low battery.", "Internal failure of the motor module's microprocessor or the optocoupler that translates the signal from the control board to the motor.", "The furnace ground wire is disconnected.", "The motor is spinning too fast and created interference."], explanation: "If the control voltage is present but the motor does not 'understand' the command, the problem is the internal 'translator' of the motor. The electronic module is fried." },
  { id:"calef_130", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide una caída de tensión de 5V AC a través de un contacto de relé cerrado mientras el motor soplador está funcionando. ¿Es aceptable?", opciones:["Sí, cualquier voltaje menor a 10V es normal.", "No; un contacto cerrado debería tener 0V (o milivoltios). 5V indican una alta resistencia de contacto que generará calor y acabará quemando el relé.", "Depende de si el motor es de 1/2 HP o 1 HP.", "Es una lectura normal en sistemas con ahorro de energía."], respuesta_correcta:1, explicacion:"Si hay voltaje a través de un switch 'cerrado', es que el switch no es un cable perfecto. Esos 5V multiplicados por el amperaje del motor son vatios desperdiciados en forma de calor." , question: "You measure a 5V AC voltage drop across a closed relay contact while the blower motor is running. Is this acceptable?", options: ["Yes, any voltage below 10V is normal.", "No; a closed contact should have 0V (or millivolts). 5V indicates high contact resistance that will generate heat and eventually burn the relay.", "It depends on whether the motor is 1/2 HP or 1 HP.", "It is a normal reading in energy-saving systems."], explanation: "If there is voltage across a 'closed' switch, the switch is not a perfect conductor. Those 5V multiplied by the motor amperage are watts wasted as heat." },
  { id:"calef_131", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Cuál es la función del 'Transformador de Aislamiento' en un controlador DDC de alta gama?", opciones:["Aumentar el voltaje de 24V a 120V.", "Separar eléctricamente la electrónica sensible del ruido y transitorios de la red eléctrica, evitando 'lazos de tierra' (ground loops) que corrompan los datos.", "Ahorrar energía apagando los relés innecesarios.", "Convertir la corriente alterna en corriente directa de forma pasiva."], respuesta_correcta:1, explicacion:"Protege el 'cerebro' digital. Si hay un corto en otra parte del edificio, este transformador asegura que el ruido eléctrico no llegue a la computadora del HVAC." , question: "What is the function of an 'Isolation Transformer' in a high-end DDC controller?", options: ["To step up the voltage from 24V to 120V.", "To electrically separate the sensitive electronics from the noise and transients of the electrical supply, preventing 'ground loops' that corrupt data.", "To save energy by turning off unnecessary relays.", "To passively convert AC to DC."], explanation: "It protects the digital 'brain.' If there is a short elsewhere in the building, this transformer ensures that electrical noise does not reach the HVAC computer." },
  { id:"calef_132", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor soplador PSC consume 10A nominales. El técnico mide 12A con un filtro MERV 16 nuevo. ¿Cuál es el diagnóstico?", opciones:["El motor es de excelente calidad y está rindiendo más.", "El motor se está sobrecalentando y superando su FLA (Full Load Amps) debido a la altísima restricción del filtro, lo que causará una falla prematura.", "El capacitor de marcha está en cortocircuito.", "Es una lectura normal en sistemas de 2 etapas."], respuesta_correcta:1, explicacion:"Contrario a lo que algunos creen, un motor PSC suele subir amperaje si se 'ahoga' demasiado en ciertas configuraciones de torque o se calienta por falta de flujo de aire." , question: "A PSC blower motor draws 10A nominal. The technician measures 12A with a new MERV 16 filter installed. What is the diagnosis?", options: ["The motor is excellent quality and performing above spec.", "The motor is overheating and exceeding its FLA (Full Load Amps) due to the extremely high filter restriction, which will cause premature failure.", "The run capacitor is short-circuited.", "This is a normal reading in two-stage systems."], explanation: "Contrary to what some believe, a PSC motor can draw higher amperage if it 'chokes' excessively in certain torque configurations or overheats due to lack of airflow." },
  { id:"calef_133", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un termostato inteligente muestra error de 'Falta de Energía' intermitente. El técnico mide 24V estables entre R y C. ¿Qué está fallando?", opciones:["El transformador es de mala calidad.", "Caída de tensión momentánea cuando la válvula de gas o el relé se activan, debido a un transformador de pocos VA que no aguanta la carga total del sistema.", "El Wi-Fi de la casa interfiere con la corriente alterna.", "El motor del soplador consume energía del termostato."], respuesta_correcta:1, explicacion:"Es el clásico 'apagón' por falta de fuerza. El voltaje está bien hasta que el horno intenta prender algo. Ahí el voltaje cae, el termostato se queda sin luz y se reinicia." , question: "A smart thermostat intermittently shows a 'Power Loss' error. The technician measures a stable 24V between R and C. What is failing?", options: ["The transformer is low quality.", "Momentary voltage drop when the gas valve or relay activates, due to a low-VA transformer that cannot handle the system's total load.", "The house Wi-Fi is interfering with the alternating current.", "The blower motor is drawing power from the thermostat."], explanation: "It is the classic 'brownout' from lack of power. The voltage is fine until the furnace tries to energize something. Then the voltage drops, the thermostat loses power, and it reboots." },
  { id:"calef_134", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 0 Ohmios entre un cable de resistencia eléctrica de 240V y el chasis de metal. ¿Qué indica esto?", opciones:["Que la resistencia tiene una excelente conexión a tierra.", "Un cortocircuito directo a tierra (Ground Fault); si se enciende, disparará el breaker instantáneamente o electrificará el gabinete del horno.", "Es la lectura normal para resistencias de nicromo de alta potencia.", "El multímetro está mal configurado para medir calefacción."], respuesta_correcta:1, explicacion:"¡Peligro! Nada eléctrico debe tocar el chasis con 0 ohmios. Significa que el metal del horno ahora es un cable vivo. Es un riesgo de muerte por electrocución." , question: "You measure 0 ohms between a 240V electric heating element wire and the metal chassis. What does this indicate?", options: ["The element has an excellent ground connection.", "A direct short circuit to ground (ground fault); if energized, it will trip the breaker instantly or electrify the furnace cabinet.", "This is the normal reading for high-power nichrome elements.", "The multimeter is set wrong for measuring heating equipment."], explanation: "Danger! Nothing electrical should touch the chassis at 0 ohms. It means the furnace metal is now a live wire. This is a risk of death by electrocution." },
  { id:"calef_135", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si un elemento calefactor de 10,000 Watts está diseñado para 240V, ¿cuántos amperios consumirá en funcionamiento normal?", opciones:["100 Amperios.", "41.6 Amperios ($I = P / V$).", "24 Amperios según la ley de Lenz.", "10 Amperios constantes."], respuesta_correcta:1, explicacion:"Saber el amperaje es vital para elegir el breaker. 42 amperios es mucho calor; si el cable es delgado, se va a derretir." , question: "If a 10,000-watt heating element is designed for 240V, how many amps will it draw during normal operation?", options: ["100 amps.", "41.6 amps (I = P / V).", "24 amps per Lenz's law.", "10 constant amps."], explanation: "Knowing the amperage is vital for choosing the breaker. 42 amps is a lot of heat; if the wire is thin, it will melt." },
  { id:"calef_136", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor soplador PSC intenta arrancar, zumba por 5 segundos y se detiene. El eje gira libre con la mano. ¿Qué pieza cambiaría primero?", opciones:["El motor completo.", "El capacitor de marcha; su falla impide que el motor genere el torque de arranque necesario.", "La placa de control del horno.", "El termostato de pared."], respuesta_correcta:1, explicacion:"El motor quiere pero no puede. El capacitor es el 'empujón' inicial. Sin él, el motor solo vibra hasta que se calienta y se apaga por seguridad." , question: "A PSC blower motor tries to start, hums for 5 seconds, and stops. The shaft spins freely by hand. What part would you replace first?", options: ["The complete motor.", "The run capacitor; its failure prevents the motor from generating the starting torque needed.", "The furnace control board.", "The wall thermostat."], explanation: "The motor wants to but cannot. The capacitor is the initial 'push.' Without it, the motor only vibrates until it heats up and shuts off on the thermal protector." },
  { id:"calef_137", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si una resistencia de calefacción de 240V tiene un cortocircuito interno y su resistencia baja a la mitad, ¿qué sucede con el calor producido?", opciones:["El calor se reduce a la mitad.", "El calor se duplica ($P = V^2 / R$), lo que probablemente derretirá el componente o disparará el breaker por sobrecorriente.", "El amperaje baja para proteger el circuito.", "La potencia se mantiene igual pero el voltaje sube."], respuesta_correcta:1, explicacion:"Menos resistencia = más corriente = MUCHO más calor. Es una situación de peligro de incendio. Por eso los breakers son tan importantes." , question: "If a 240V heating element develops an internal short circuit and its resistance drops to half, what happens to the heat produced?", options: ["The heat is reduced by half.", "The heat doubles (P = V squared / R), which will likely melt the component or trip the breaker on overcurrent.", "The amperage drops to protect the circuit.", "The power stays the same but the voltage rises."], explanation: "Less resistance = more current = MUCH more heat. This is a fire hazard situation. That is why breakers are so important." },
  { id:"calef_138", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Cuál es la ventaja de un motor ECM sobre un motor PSC en un sistema de calefacción?", opciones:["Es mucho más barato de reemplazar.", "Mayor eficiencia eléctrica, capacidad de mantener CFM constantes ante cambios de presión y operación mucho más silenciosa.", "Funciona sin necesidad de cables de control.", "No requiere conexión a tierra de seguridad."], respuesta_correcta:1, explicacion:"El ECM es el motor inteligente. Gasta menos luz y, si el filtro se ensucia, él solito acelera para que te siga llegando aire. Es el futuro del HVAC." , question: "What is the advantage of an ECM motor over a PSC motor in a heating system?", options: ["It is much cheaper to replace.", "Greater electrical efficiency, the ability to maintain constant CFM despite pressure changes, and much quieter operation.", "It works without the need for control wires.", "It does not require a safety ground connection."], explanation: "The ECM is the smart motor. It uses less electricity and, if the filter gets dirty, it speeds up on its own to maintain airflow. It is the future of HVAC." },
  { id:"calef_139", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 0 ohmios de resistencia en la bobina de un contactor de 24V. ¿Qué sucederá cuando el termostato pida calor?", opciones:["El contactor cerrará con mucha fuerza magnética.", "Se quemará el fusible de 3 o 5 amperios de la placa de control debido a un cortocircuito.", "El sistema funcionará pero consumirá más vatios de lo normal.", "La bobina actuará como un capacitor de marcha secundario."], respuesta_correcta:1, explicacion:"0 ohmios significa que no hay resistencia (cortocircuito). Al aplicar 24V, la corriente será infinita (teóricamente), lo que funde el fusible de protección inmediatamente." , question: "You measure 0 ohms resistance across the coil of a 24V contactor. What will happen when the thermostat calls for heat?", options: ["The contactor will close with very strong magnetic force.", "The 3A or 5A fuse on the control board will blow due to a short circuit.", "The system will work but will consume more watts than normal.", "The coil will act as a secondary run capacitor."], explanation: "0 ohms means there is no resistance (short circuit). When 24V is applied, the current will be infinite (theoretically), which blows the protective fuse immediately." },
  { id:"calef_140", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué indica un voltaje de 12V AC entre el Neutro y la Tierra en un equipo de calefacción?", opciones:["Es un voltaje de respaldo para la placa de control.", "Una falla de conexión a tierra o un 'Neutro flotante', lo que puede causar que los sensores de llama fallen y choques eléctricos leves al tocar el chasis.", "Operación normal en sistemas de alta eficiencia comunicantes.", "Indica que el transformador de 24V está trabajando a máxima carga."], respuesta_correcta:1, explicacion:"El Neutro y la Tierra deben estar al mismo potencial (0V). Si hay 12V, la electricidad está buscando camino por donde no debe, lo cual es peligroso y confunde a los microprocesadores." , question: "What does a voltage of 12V AC between Neutral and Ground indicate in a heating equipment installation?", options: ["It is a backup voltage for the control board.", "A ground connection fault or a 'floating neutral,' which can cause flame sensor failures and mild electric shocks when touching the chassis.", "Normal operation in high-efficiency communicating systems.", "It indicates the 24V transformer is working at maximum load."], explanation: "Neutral and Ground should be at the same potential (0V). If there is 12V, electricity is seeking a path where it should not, which is dangerous and confuses microprocessors." },
  { id:"calef_141", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un motor de soplador PSC tiene un capacitor de 5 mFD. El técnico mide 3.2 mFD. ¿Qué síntoma presentará el horno?", opciones:["El ventilador girará más rápido para compensar.", "El motor tendrá bajo torque, tardará en arrancar, consumirá más amperaje y se apagará por protector térmico (Limit trip).", "El consumo de gas aumentará un 20%.", "No hay síntomas hasta que el capacitor llegue a 0 mFD."], respuesta_correcta:1, explicacion:"Un capacitor débil hace que el motor 'sufra'. Al no poder girar bien, el motor se calienta. Al no mover aire, el horno se calienta. Es una falla doble." , question: "A PSC blower motor has a 5 MFD capacitor. The technician measures 3.2 MFD. What symptom will the furnace exhibit?", options: ["The fan will spin faster to compensate.", "The motor will have low torque, will be slow to start, will draw more amperage, and will trip the thermal protector (limit trip).", "Gas consumption will increase by 20%.", "No symptoms until the capacitor reaches 0 MFD."], explanation: "A weak capacitor makes the motor 'suffer.' Unable to spin properly, the motor heats up. Unable to move air, the furnace overheats. It is a double failure." },
  { id:"calef_142", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V entre 'W' y 'C' en la placa de control, pero el motor inductor no arranca. El inductor tiene 120V de entrada. ¿Cuál es el diagnóstico?", opciones:["La placa de control no está enviando la señal.", "El motor inductor está quemado o tiene el devanado abierto.", "El sensor de llama está bloqueando el arranque.", "El termostato de pared está dañado."], respuesta_correcta:1, explicacion:"Si hay orden (24V) y hay potencia (120V), el motor debería girar. Si no lo hace, el motor pasó a mejor vida." , question: "You measure 24V between 'W' and 'C' on the control board, but the inducer motor does not start. The inducer has 120V at its input. What is the diagnosis?", options: ["The control board is not sending the signal.", "The inducer motor is burned out or has an open winding.", "The flame sensor is blocking startup.", "The wall thermostat is damaged."], explanation: "If there is a command (24V) and there is power (120V), the motor should spin. If it does not, the motor has passed on." },
  { id:"calef_143", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si un elemento calefactor de 10kW se conecta a 208V en lugar de 240V, ¿qué sucede con el calor?", opciones:["El calor se mantiene en 10kW.", "El calor disminuye a aproximadamente 7.5kW porque la potencia cae al cuadrado del voltaje.", "El calor sube a 12kW debido al amperaje.", "El elemento se quema instantáneamente."], respuesta_correcta:1, explicacion:"Matemática de resistencias: menos voltaje = mucho menos calor. El cliente se quejará de que el horno 'no calienta igual' aunque el breaker no se dispare." , question: "If a 10kW heating element is connected to 208V instead of 240V, what happens to the heat output?", options: ["The heat stays at 10kW.", "The heat decreases to approximately 7.5kW because power drops with the square of the voltage.", "The heat rises to 12kW due to higher amperage.", "The element burns out instantly."], explanation: "Resistance math: less voltage = much less heat. The customer will complain that the furnace 'doesn't heat the same' even though the breaker does not trip." },
  { id:"calef_144", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide continuidad en un motor soplador entre el cable de velocidad y el chasis (tierra). Obtiene 50 ohmios. ¿Cuál es el diagnóstico?", opciones:["El motor está perfectamente sano.", "El motor tiene un corto a tierra parcial; el aislamiento de los devanados falló y es peligroso.", "Es una lectura normal de magnetismo residual.", "El multímetro está en el modo equivocado."], respuesta_correcta:1, explicacion:"Entre el cable y el metal nunca debe haber continuidad. Si hay 50 ohmios, la electricidad se está 'fugando' al chasis. El motor debe cambiarse." , question: "You measure continuity on a blower motor between the speed wire and the chassis (ground). You get 50 ohms. What is the diagnosis?", options: ["The motor is perfectly healthy.", "The motor has a partial ground fault; the winding insulation has failed and it is dangerous.", "This is a normal reading of residual magnetism.", "The multimeter is in the wrong mode."], explanation: "There should never be continuity between the wire and the metal. If there are 50 ohms, electricity is 'leaking' to the chassis. The motor must be replaced." },
  { id:"calef_145", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Cuál es la función del 'Transformador de Control' en un horno?", opciones:["Ahorrar energía eléctrica.", "Reducir los 120V de la casa a 24V seguros para operar el termostato y las válvulas de gas.", "Convertir la corriente alterna en directa.", "Aumentar el voltaje para el ignitor."], respuesta_correcta:1, explicacion:"Sin este pequeño componente no habría control. Los 24V son el estándar de seguridad para que el termostato no te dé un choque eléctrico si tocas los cables." , question: "What is the function of the 'Control Transformer' in a furnace?", options: ["To save electrical energy.", "To step down the house 120V to a safe 24V to operate the thermostat and gas valves.", "To convert AC to DC.", "To increase the voltage for the igniter."], explanation: "Without this small component, there would be no control. The 24V is the safety standard so the thermostat does not give you an electric shock if you touch the wires." },
  { id:"calef_146", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 120V en un cable negro y 0V en el cable blanco (respecto a tierra). ¿Es correcto?", opciones:["No, ambos deberían tener 120V.", "Sí, el Negro es la Línea (fase) y el Blanco es el Neutro (referencia de retorno).", "No, el blanco debería tener 24V para el termostato.", "Solo si el motor del ventilador está apagado."], respuesta_correcta:1, explicacion:"Es la base del cableado en USA. El blanco lleva la corriente de regreso al panel. Si el blanco tuviera 120V, tendrías un cortocircuito o una fase invertida." , question: "You measure 120V on a black wire and 0V on a white wire (with respect to ground). Is this correct?", options: ["No, both should have 120V.", "Yes, the Black wire is the Line (hot) and the White wire is the Neutral (return reference).", "No, the white wire should have 24V for the thermostat.", "Only if the fan motor is off."], explanation: "This is the basis of wiring in the USA. The white wire carries the current back to the panel. If the white had 120V, you would have a short circuit or reversed polarity." },
  { id:"calef_147", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Para qué sirve el 'Módulo de Control' (el cerebro) en un motor ECM?", opciones:["Para filtrar el polvo del motor.", "Para convertir la corriente AC en DC y controlar la velocidad y el torque de forma eficiente mediante microprocesadores.", "Es solo una caja de conexiones para facilitar el cableado.", "Sirve para que el motor pueda conectarse al Wi-Fi de la casa."], respuesta_correcta:1, explicacion:"El módulo es lo que hace al motor 'inteligente'. Si el motor falla pero tiene energía, usualmente es este módulo el que se quemó." , question: "What is the purpose of the 'Control Module' (the brain) in an ECM motor?", options: ["To filter dust from the motor.", "To convert AC to DC and efficiently control speed and torque via microprocessors.", "It is just a junction box to simplify wiring.", "It allows the motor to connect to the house Wi-Fi."], explanation: "The module is what makes the motor 'smart.' If the motor fails but has power, it is usually this module that burned out." },
  { id:"calef_148", categoria:"CALEF_ELECTRICIDAD", pregunta:"Si usted tiene un cortocircuito entre el cable 'R' (24V) y el chasis (tierra), ¿qué componente se dañará primero?", opciones:["El termostato de pared.", "El fusible de 3A o 5A de la placa de control.", "El motor del soplador principal.", "La válvula de gas."], respuesta_correcta:1, explicacion:"Ese fusible está ahí para salvar la placa y el transformador. Si lo encuentras quemado, busca un cable pelado tocando el metal." , question: "If you have a short circuit between the 'R' wire (24V) and the chassis (ground), what component will be damaged first?", options: ["The wall thermostat.", "The 3A or 5A fuse on the control board.", "The main blower motor.", "The gas valve."], explanation: "That fuse is there to save the board and the transformer. If you find it blown, look for a stripped wire touching metal." },
  { id:"calef_149", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 0.2 ohmios en los cables de un motor soplador. ¿Cuál es el diagnóstico?", opciones:["El motor está en perfecto estado.", "El motor tiene un cortocircuito interno (devanado fundido); la resistencia debería ser mayor (típicamente entre 1 y 10 ohmios).", "El multímetro necesita una batería nueva.", "Es una lectura normal para motores de 1 HP."], respuesta_correcta:1, explicacion:"Resistencia de 0.2 es básicamente un cable directo. Si le metes 120V a eso, va a haber un chispazo y el breaker saltará al instante." , question: "You measure 0.2 ohms across a blower motor's wires. What is the diagnosis?", options: ["The motor is in perfect condition.", "The motor has an internal short circuit (fused winding); the resistance should be higher (typically between 1 and 10 ohms).", "The multimeter needs a new battery.", "This is a normal reading for 1 HP motors."], explanation: "A resistance of 0.2 is basically a direct wire. If you put 120V across that, there will be a spark and the breaker will trip instantly." },
  { id:"calef_150", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué sucede si desconecta el motor del soplador mientras el horno está en pleno ciclo de calefacción?", opciones:["El horno calentará la casa más rápido.", "El intercambiador de calor se sobrecalentará rápidamente, disparando el Límite Alto y posiblemente dañando el metal del horno.", "El motor inductor de tiro se detendrá por seguridad.", "El consumo de gas bajará a la mitad."], respuesta_correcta:1, explicacion:"El ventilador es el que 'se lleva' el calor. Si lo quitas, el fuego sigue pero no hay quien saque el calor. Es como poner una olla vacía al fuego máximo." , question: "What happens if you disconnect the blower motor while the furnace is in the middle of a heating cycle?", options: ["The furnace will heat the house faster.", "The heat exchanger will overheat rapidly, tripping the High Limit and possibly damaging the metal of the furnace.", "The inducer motor will stop for safety.", "Gas consumption will drop by half."], explanation: "The blower is what 'carries away' the heat. If you remove it, the fire continues but there is nothing to extract the heat. It is like putting an empty pot on maximum heat." },
  { id:"calef_151", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V entre 'R' y 'C', pero al puentear 'R' y 'W', el voltaje cae a 5V y nada sucede. ¿Cuál es el diagnóstico?", opciones:["El termostato está dañado.", "Transformador de control 'débil' (VA insuficientes) o una conexión de alta resistencia que no soporta la carga de la bobina del relé.", "La válvula de gas está en cortocircuito total.", "El motor inductor consume toda la energía del sistema."], respuesta_correcta:1, explicacion:"Es el clásico transformador que 'muere' bajo carga. Tiene voltaje en reposo, pero en cuanto le pides trabajo, no tiene la fuerza (amperaje) para mantener la tensión." , question: "You measure 24V between 'R' and 'C,' but when you jumper 'R' and 'W,' the voltage drops to 5V and nothing happens. What is the diagnosis?", options: ["The thermostat is damaged.", "A 'weak' control transformer (insufficient VA) or a high-resistance connection that cannot sustain the relay coil load.", "The gas valve is in total short circuit.", "The inducer motor is consuming all the system's energy."], explanation: "It is the classic transformer that 'dies' under load. It has voltage at rest, but as soon as you ask it to work, it does not have the strength (amperage) to maintain the voltage." },
  { id:"calef_152", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted encuentra que un técnico anterior cambió un fusible de 3A quemado por un trozo de papel de aluminio. ¿Qué riesgo técnico es el más inmediato?", opciones:["Que el horno consuma más gas de lo normal.", "Destrucción total de la placa de control o incendio del transformador ante cualquier falla menor en el cableado del termostato.", "El motor del soplador girará más despacio por falta de resistencia.", "No hay riesgo si el papel de aluminio es de grado industrial."], respuesta_correcta:1, explicacion:"El fusible es el 'fusible'. Si lo puenteas con metal, la siguiente falla quemará el componente más caro (la placa) o causará un incendio en el cuarto de máquinas." , question: "You discover that a previous technician replaced a blown 3A fuse with a piece of aluminum foil. What is the most immediate technical risk?", options: ["The furnace will consume more gas than normal.", "Total destruction of the control board or transformer fire upon any minor wiring fault in the thermostat circuit.", "The blower motor will spin slower due to the lack of resistance.", "There is no risk if the aluminum foil is industrial grade."], explanation: "The fuse is the 'fuse.' If you bypass it with metal, the next fault will burn the most expensive component (the board) or cause a fire in the mechanical room." },
  { id:"calef_153", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Qué es el 'Efecto de Histéresis' en un motor de soplador y cómo afecta a la eficiencia?", opciones:["Es la pérdida de energía por calor en el núcleo de hierro del motor debido a la magnetización y desmagnetización constante.", "La diferencia de velocidad entre el campo magnético y el rotor.", "El retraso en el encendido del motor tras recibir la señal de 24V.", "La resistencia que ofrece el aire al paso de las aspas."], respuesta_correcta:0, explicacion:"Es una pérdida de energía interna del metal del motor. Los motores de alta eficiencia (ECM) minimizan este efecto para gastar menos luz y generar menos calor." , question: "What is the 'Hysteresis Effect' in a blower motor and how does it affect efficiency?", options: ["It is the energy lost as heat in the motor's iron core due to the constant magnetization and demagnetization.", "The speed difference between the magnetic field and the rotor.", "The delay in starting the motor after receiving the 24V signal.", "The resistance that air offers to the passing blades."], explanation: "It is an internal energy loss within the motor's metal. High-efficiency motors (ECM) minimize this effect to use less electricity and generate less heat." },
  { id:"calef_154", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 24V en el transformador, pero solo 19V en la bobina de la válvula de gas al intentar encender. ¿Qué indica esto?", opciones:["Que el gas natural tiene mucha resistencia.", "Caída de tensión (Voltage Drop) causada por cables de calibre muy fino o conexiones sulfatadas/sueltas en el circuito de control.", "Es una lectura normal en modo de ahorro de energía.", "La válvula de gas está generando su propio voltaje."], respuesta_correcta:1, explicacion:"Si pierdes 5 voltios en el camino, tienes un problema de cables. Con 19V la válvula puede que no tenga fuerza para abrirse o que vibre y falle." , question: "You measure 24V at the transformer, but only 19V at the gas valve solenoid when attempting to ignite. What does this indicate?", options: ["The natural gas has a lot of resistance.", "Voltage drop caused by wire gauge that is too thin or corroded/loose connections in the control circuit.", "This is a normal reading in energy-saving mode.", "The gas valve is generating its own voltage."], explanation: "If you lose 5 volts along the way, you have a cable problem. At 19V, the valve may not have enough force to open, or it may chatter and fail." },
  { id:"calef_155", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Cuál es la función del 'Capacitor de Marcha' (Run Capacitor) en un motor PSC durante el funcionamiento continuo?", opciones:["Almacenar energía para cortes de luz breves.", "Proveer un desfase eléctrico constante para crear un campo magnético rotatorio eficiente y mejorar el factor de potencia del motor.", "Aumentar el voltaje de la línea de 120V a 240V.", "Actuar como un filtro de ruido para el termostato."], respuesta_correcta:1, explicacion:"Sin el capacitor de marcha, el motor no gira de forma suave. El capacitor mantiene el 'empuje' magnético en la dirección correcta todo el tiempo." , question: "What is the function of the 'Run Capacitor' in a PSC motor during continuous operation?", options: ["To store energy for brief power outages.", "To provide a constant electrical phase shift that creates an efficient rotating magnetic field and improves the motor's power factor.", "To step up the line voltage from 120V to 240V.", "To act as a noise filter for the thermostat."], explanation: "Without the run capacitor, the motor does not spin smoothly. The capacitor maintains the magnetic 'push' in the correct direction at all times." },
  { id:"calef_156", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un horno de gas entra en Lockout tras fallar la ignición. El técnico apaga el interruptor de pared y lo enciende. El horno arranca. ¿Qué ocurrió?", opciones:["El horno se reparó solo con el descanso.", "Se realizó un 'Hard Reset' de la placa de control, borrando la memoria de falla momentánea (Soft Lockout).", "El gas natural aumentó su presión durante el apagado.", "El ignitor se enfrió y recuperó su resistencia original."], respuesta_correcta:1, explicacion:"Apagar y prender borra el error de la computadora. Pero ojo: si no arreglaste la causa, el horno se volverá a bloquear en un rato. El reset no es una reparación." , question: "A gas furnace enters lockout after failing to ignite. The technician turns off the wall switch and turns it back on. The furnace starts. What happened?", options: ["The furnace repaired itself during the rest.", "A 'Hard Reset' of the control board was performed, clearing the momentary fault memory (Soft Lockout).", "The natural gas pressure increased during the shutdown.", "The igniter cooled down and recovered its original resistance."], explanation: "Turning it off and on clears the computer error. But beware: if you did not fix the cause, the furnace will lock out again shortly. A reset is not a repair." },
  { id:"calef_157", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 120V entre el cable Negro y el chasis. Mide 120V entre el cable Blanco y el chasis. ¿Cuál es el diagnóstico?", opciones:["El horno tiene una potencia de 240V.", "Neutro abierto o 'fase invertida' peligrosa; el cable blanco no está regresando al panel y tiene voltaje de retorno.", "Es una lectura normal en motores de alta eficiencia.", "El transformador de 24V está en cortocircuito."], respuesta_correcta:1, explicacion:"¡Peligro! El blanco (neutro) nunca debe tener 120V respecto a tierra. Esto indica un cable roto en el panel o una mala conexión que puede electrificar todo el horno." , question: "You measure 120V between the Black wire and the chassis. You measure 120V between the White wire and the chassis. What is the diagnosis?", options: ["The furnace has 240V power.", "An open or 'reverse polarity' Neutral; the white wire is not returning to the panel and has backfeed voltage -- a dangerous condition.", "This is a normal reading in high-efficiency motors.", "The 24V transformer is short-circuited."], explanation: "Danger! The white (Neutral) should never have 120V with respect to ground. This indicates a broken wire at the panel or a bad connection that can electrify the entire furnace." },
  { id:"calef_158", categoria:"CALEF_ELECTRICIDAD", pregunta:"Un horno de gas se apaga por 'Límite Alto'. El técnico nota que el soplador corre pero el motor está muy caliente. ¿Qué revisaría primero?", opciones:["El sensor de llama.", "El capacitor de marcha; si está débil, el motor gira lento, no mueve aire y se sobrecalienta, apagando el horno.", "La presión del gas natural en la calle.", "Cambiar el termostato por uno digital."], respuesta_correcta:1, explicacion:"Si el motor gira pero está 'flojo' y caliente, es el capacitor. Al no mover suficiente aire, el metal del horno se calienta de más y el seguro corta el fuego." , question: "A gas furnace shuts down on 'High Limit.' The technician notes the blower runs but the motor is very hot. What should be checked first?", options: ["The flame sensor.", "The run capacitor; if it is weak, the motor spins slowly, does not move air, and overheats, causing the furnace to shut down.", "The natural gas pressure at the street.", "Replace the thermostat with a digital one."], explanation: "If the motor spins but is 'sluggish' and hot, it is the capacitor. By not moving enough air, the furnace metal overheats and the safety limit cuts the flame." },
  { id:"calef_159", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Por qué un horno nunca debe ser alimentado con un cable de extensión (extension cord) permanente?", opciones:["Porque el cable se ve feo por el suelo.", "Riesgo de caída de voltaje, sobrecalentamiento del cable e incendios; además de la falta de una conexión a tierra sólida y permanente requerida por código.", "El motor del soplador girará al revés.", "El gas natural se vuelve inestable con cables de extensión."], respuesta_correcta:1, explicacion:"Un horno consume mucha energía. Un cable de extensión no está hecho para estar prendido meses enteros. Se puede derretir y causar un incendio en cualquier momento." , question: "Why should a furnace NEVER be permanently powered by an extension cord?", options: ["Because the cord looks ugly on the floor.", "Risk of voltage drop, cable overheating, and fire; plus the lack of a solid, permanent ground connection required by code.", "The blower motor will spin in reverse.", "Natural gas becomes unstable with extension cords."], explanation: "A furnace draws a lot of power. An extension cord is not designed to be powered on for months at a time. It can melt and cause a fire at any moment." },
  { id:"calef_160", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 0 Ohmios entre los dos cables de un transformador de 24V (bobina primaria). ¿Qué indica esto?", opciones:["El transformador está en perfecto estado.", "Cortocircuito interno masivo en el devanado; el transformador fundirá el breaker o explotará si se conecta a 120V.", "La lectura es correcta para transformadores de 40VA.", "El multímetro debe estar en modo de Voltios, no Ohmios."], respuesta_correcta:1, explicacion:"Una bobina debe tener algo de resistencia (ohmios). Si marca 0, es solo un trozo de metal unido. Es un corto total y es peligroso energizarlo." , question: "You measure 0 ohms between the two wires of a 24V transformer (primary coil). What does this indicate?", options: ["The transformer is in perfect condition.", "A massive internal short circuit in the winding; the transformer will blow the breaker or explode if connected to 120V.", "This is the correct reading for 40VA transformers.", "The multimeter should be in voltage mode, not ohms."], explanation: "A coil must have some resistance (ohms). If it reads 0, it is just a piece of metal joined together. It is a total short and it is dangerous to energize." },
  { id:"calef_161", categoria:"CALEF_ELECTRICIDAD", pregunta:"Usted mide 120V en un cable. Al conectar un foco de prueba, el voltaje cae a 0V. ¿Cuál es el diagnóstico?", opciones:["El foco de prueba está fundido.", "Conexión 'fantasma' o de alta resistencia (un cable casi roto o un contacto sucio) que no permite el paso de corriente bajo carga.", "El voltaje es de corriente directa y el foco es de alterna.", "Es un síntoma normal de magnetismo residual en los ductos."], respuesta_correcta:1, explicacion:"Es el error más común. Tienes voltaje pero no tienes 'amperaje'. En cuanto le pides al cable que trabaje, se rinde porque la conexión está floja en algún lado." , question: "You measure 120V on a wire. When you connect a test light, the voltage drops to 0V. What is the diagnosis?", options: ["The test light is blown.", "A 'phantom' or high-resistance connection (a nearly broken wire or dirty contact) that cannot sustain current under load.", "The voltage is DC and the light is AC.", "This is a normal symptom of residual magnetism in the ductwork."], explanation: "It is the most common error. You have voltage but no 'amperage.' As soon as the wire is asked to work, it gives up because the connection is loose somewhere." },
  { id:"calef_162", categoria:"CALEF_ELECTRICIDAD", pregunta:"¿Cuál es la función del 'Interruptor de Límite de Temperatura de Retorno'?", opciones:["Asegurar que el aire de la casa esté a 22°C.", "Seguridad: apaga el horno si el aire que entra al equipo está demasiado caliente (ej. > 35°C), evitando que el intercambiador se sobrecalientre de inmediato.", "Cambiar la velocidad del soplador automáticamente.", "Medir la humedad del aire que viene de las habitaciones."], respuesta_correcta:1, explicacion:"Es un guardaespaldas extra. Si por alguna razón el aire de la casa ya viene muy caliente, el horno no puede añadirle más calor sin riesgo de derretirse." , question: "What is the function of the 'Return Air Temperature Limit Switch'?", options: ["To ensure the house air is at 72 degrees F.", "Safety: it shuts down the furnace if the incoming air is too hot (e.g., above 95 degrees F), preventing the heat exchanger from overheating immediately.", "To automatically change the blower speed.", "To measure the humidity of the air coming from the rooms."], explanation: "It is an extra bodyguard. If for some reason the return air is already very hot, the furnace cannot add more heat without the risk of melting." },

  // -- Hornos de Gas (163-348) --
  { id:"calef_163", categoria:"CALEF_HORNOS", pregunta:"Un sensor de temperatura NTC (Negative Temperature Coefficient) marca una resistencia de 100k ohmios a 0°C. Si la temperatura sube a 25°C, ¿qué cambio esperarías ver en el multímetro?", opciones:["La resistencia subirá a aproximadamente 150k ohmios debido a la agitación molecular del semiconductor.", "La resistencia bajará significativamente.", "La resistencia se mantendrá igual pero el voltaje de retorno aumentará linealmente.", "El sensor emitirá una señal de milivoltios proporcional al logaritmo de la temperatura seca."], respuesta_correcta:1, explicacion:"En los termistores NTC, a mayor temperatura, menor resistencia. Es la base del control de la mayoría de los sistemas HVAC modernos." , question: "An NTC (Negative Temperature Coefficient) temperature sensor reads a resistance of 100k ohms at 32 degrees F. If the temperature rises to 77 degrees F, what change would you expect to see on the multimeter?", options: ["The resistance will increase to approximately 150k ohms due to the molecular agitation of the semiconductor.", "The resistance will drop significantly.", "The resistance will stay the same but the return voltage will increase linearly.", "The sensor will emit a millivolt signal proportional to the logarithm of the dry-bulb temperature."], explanation: "In NTC thermistors, as temperature increases, resistance decreases. This is the basis of control in most modern HVAC systems." },
  { id:"calef_164", categoria:"CALEF_HORNOS", pregunta:"Un interruptor de límite alto (High Limit Switch) en un horno de gas está 'tripeando' (abriendo el circuito) frecuentemente. El filtro está limpio y el motor funciona. ¿Cuál es la causa capciosa más probable?", opciones:["El intercambiador de calor está excesivamente limpio y no retiene calor.", "Un orificio de gas demasiado pequeño que causa una llama 'pobre' y fría.", "Un intercambiador de calor agrietado que permite que el aire del soplador 'enfríe' la llama incorrectamente.", "Ductos de retorno insuficientes o demasiado pequeños para el CFM del soplador."], respuesta_correcta:3, explicacion:"Si los ductos de retorno son pequeños, no llega suficiente aire al intercambiador para absorber el calor generado, causando que el metal se sobrecaliente y abra el límite de seguridad." , question: "A high-limit switch on a gas furnace is tripping (opening the circuit) frequently. The filter is clean and the motor runs. What is the tricky most likely cause?", options: ["The heat exchanger is excessively clean and does not retain heat.", "A gas orifice that is too small, causing a 'lean' and cool flame.", "A cracked heat exchanger that allows the blower air to 'cool' the flame incorrectly.", "Return air ducts that are insufficient or too small for the blower's CFM."], explanation: "If the return ducts are too small, not enough air reaches the heat exchanger to absorb the generated heat, causing the metal to overheat and trip the safety limit." },
  { id:"calef_165", categoria:"CALEF_HORNOS", pregunta:"Un técnico encuentra que el intercambiador de calor secundario de un horno está cubierto de una sustancia blanca y escamosa. ¿Qué indica esto?", opciones:["Uso de tubería de PVC no apta para gases de combustión.", "Corrosión debida a que el condensado ácido no está siendo drenado correctamente, reaccionando con el metal.", "Es una acumulación normal de sales minerales presentes en el aire de combustión.", "Fuga de refrigerante de un serpentín de aire acondicionado instalado aguas arriba."], respuesta_correcta:1, explicacion:"El condensado de los hornos de alta eficiencia es ácido (pH 3-5). Si se estanca por drenajes mal diseñados, ataca el acero inoxidable del intercambiador secundario, creando sales de corrosión." , question: "A technician finds that the secondary heat exchanger of a furnace is covered with a white, flaky substance. What does this indicate?", options: ["Use of PVC piping that is not rated for combustion gases.", "Corrosion caused by acidic condensate not draining properly, reacting with the metal.", "It is a normal accumulation of mineral salts present in the combustion air.", "A refrigerant leak from an air conditioning coil installed upstream."], explanation: "The condensate from high-efficiency furnaces is acidic (pH 3-5). If it pools due to poorly designed drains, it attacks the stainless steel of the secondary heat exchanger, creating corrosion salts." },
  { id:"calef_166", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un interruptor de 'Roll-out' es de restablecimiento manual (manual reset) mientras que el 'High Limit' suele ser automático?", opciones:["Porque el 'Roll-out' indica una falla crítica de combustión o un intercambiador tapado que requiere inspección profesional obligatoria.", "Por una limitación en el diseño de los bimetales de seguridad.", "Para obligar al dueño de casa a aprender a reparar su propio equipo.", "El código NFPA 54 exige que todos los componentes de gas sean manuales."], respuesta_correcta:0, explicacion:"Un 'roll-out' significa que las llamas salieron de la cámara de combustión. Es una situación de alto peligro de incendio que no debe reanudarse sin que un técnico verifique la causa." , question: "Why is a 'Roll-out' switch a manual-reset device while the 'High Limit' is usually automatic?", options: ["Because the 'Roll-out' indicates a critical combustion failure or a plugged heat exchanger that requires mandatory professional inspection.", "Due to a limitation in the design of safety bimetallic elements.", "To force the homeowner to learn to repair their own equipment.", "NFPA 54 code requires all gas components to be manual."], explanation: "A 'roll-out' means flames exited the combustion chamber. It is a high fire danger situation that must not resume without a technician verifying the cause." },
  { id:"calef_167", categoria:"CALEF_HORNOS", pregunta:"Si un motor inductor de tiro inducido consume 1.2 amperios pero su placa dice '0.8 FLA', ¿cuál es la causa más probable si el voltaje es correcto?", opciones:["El motor está girando demasiado rápido debido a una falta de restricción en el venteo.", "El condensador de arranque del motor inductor está en cortocircuito.", "El intercambiador de calor está bloqueado, forzando al motor a trabajar más.", "El orificio del quemador es demasiado grande y calienta el motor por radiación."], respuesta_correcta:0, explicacion:"Capciosa: En ventiladores centrífugos, si no hay restricción (ej. chimenea desconectada), el motor mueve más masa de aire, lo que requiere más trabajo y eleva el amperaje." , question: "If an induced draft motor draws 1.2 amps but its nameplate says '0.8 FLA,' what is the most likely cause if the voltage is correct?", options: ["The motor is spinning too fast due to a lack of restriction in the venting.", "The inducer motor start capacitor is short-circuited.", "The heat exchanger is blocked, forcing the motor to work harder.", "The burner orifice is too large and is heating the motor by radiation."], explanation: "Tricky: In centrifugal fans, if there is no restriction (e.g., a disconnected flue), the motor moves more air mass, which requires more work and raises the amperage." },
  { id:"calef_168", categoria:"CALEF_HORNOS", pregunta:"¿Qué causa que una llama de gas natural 'levante' (lift) de los puertos del quemador?", opciones:["Baja presión de gas en el colector (manifold).", "Excesiva velocidad de la mezcla aire-gas (demasiada presión o exceso de aire primario).", "Obstrucción parcial en el tubo Venturi del quemador.", "Uso de un orificio de propano en una válvula de gas natural."], respuesta_correcta:1, explicacion:"Si la mezcla sale más rápido de lo que la llama puede quemarse, la llama se despega del quemador. Esto es peligroso porque puede causar una falla de encendido o liberar gas sin quemar." , question: "What causes a natural gas flame to 'lift' off the burner ports?", options: ["Low gas pressure at the manifold.", "Excessive velocity of the air-gas mixture (too much pressure or excess primary air).", "Partial obstruction in the Venturi tube of the burner.", "Use of a propane orifice on a natural gas valve."], explanation: "If the mixture exits faster than the flame can burn, the flame detaches from the burner. This is dangerous because it can cause an ignition failure or release unburned gas." },
  { id:"calef_169", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un interruptor de presión de aire (pressure switch) tiene dos mangueras en algunos hornos de alta eficiencia?", opciones:["Una para el gas y otra para el aire.", "Para medir la presión diferencial a través del recuperador o del inductor, asegurando un flujo de aire real y no solo presión estática.", "Como respaldo en caso de que una manguera se tape con condensado.", "Para permitir la entrada de aire atmosférico al diafragma del termostato."], respuesta_correcta:1, explicacion:"Al medir en dos puntos (diferencial), el control se asegura de que el aire realmente se está moviendo a través del sistema de venteo, lo cual es más seguro que medir un solo punto." , question: "Why does a pressure switch have two hoses on some high-efficiency furnaces?", options: ["One for gas and one for air.", "To measure the differential pressure across the collector or inducer, ensuring actual airflow and not just static pressure.", "As a backup in case one hose clogs with condensate.", "To allow atmospheric air into the thermostat diaphragm."], explanation: "By measuring at two points (differential), the control ensures that air is actually moving through the venting system, which is safer than measuring at a single point." },
  { id:"calef_170", categoria:"CALEF_HORNOS", pregunta:"Usted observa que las llamas de un horno de gas 'bailan' o cambian de forma cuando el soplador principal se enciende. ¿Qué diagnóstico es el más probable?", opciones:["El soplador está generando demasiada vibración en el piso.", "Intercambiador de calor agrietado; el aire del soplador está entrando a la cámara de combustión.", "La válvula de gas tiene un regulador de presión inestable.", "Es un efecto visual normal debido a la refracción de la luz en el aire en movimiento."], respuesta_correcta:1, explicacion:"Si el aire del soplador afecta la llama, hay una comunicación física entre ambos lados. Es una falla de seguridad crítica que requiere el reemplazo inmediato del intercambiador." , question: "You observe that the flames of a gas furnace 'dance' or change shape when the main blower turns on. What is the most likely diagnosis?", options: ["The blower is generating too much vibration on the floor.", "A cracked heat exchanger; the blower air is entering the combustion chamber.", "The gas valve has an unstable pressure regulator.", "This is a normal visual effect due to the refraction of light in moving air."], explanation: "If the blower air affects the flame, there is a physical breach between both sides. It is a critical safety failure that requires immediate heat exchanger replacement." },
  { id:"calef_171", categoria:"CALEF_HORNOS", pregunta:"¿Qué componente de seguridad detectaría una falla si el motor del soplador principal (indoor blower) se quema pero el horno sigue intentando calentar?", opciones:["El sensor de llama (flame sensor).", "El interruptor de límite alto (High Limit Switch).", "El interruptor de presión de aire (Pressure Switch).", "El sensor de temperatura de aire de retorno."], respuesta_correcta:1, explicacion:"Sin el soplador, el calor no se retira del intercambiador. La temperatura sube rápidamente hasta que el bimetal del 'High Limit' se abre, cortando la energía a la válvula de gas." , question: "What safety component would detect a failure if the main indoor blower motor burns out but the furnace keeps trying to heat?", options: ["The flame sensor.", "The high-temperature limit switch (High Limit).", "The air pressure switch.", "The return air temperature sensor."], explanation: "Without the blower, heat is not removed from the heat exchanger. The temperature rises rapidly until the bimetallic element of the 'High Limit' opens, cutting power to the gas valve." },
  { id:"calef_172", categoria:"CALEF_HORNOS", pregunta:"Un horno de gas moderno realiza un 'Self-Test' y detecta que el interruptor de presión (Pressure Switch) está CERRADO antes de que el motor inductor arranque. ¿Qué hace la placa de control?", opciones:["Inicia el ciclo de encendido normalmente asumiendo que el tiro es excelente.", "Bloquea el encendido (Lockout) porque el interruptor debería estar abierto sin flujo de aire; esto indica un interruptor pegado o un puente ilegal.", "Ignora el sensor y activa la válvula de gas por un periodo de seguridad de 5 segundos.", "Aumenta el voltaje al motor inductor para intentar abrir el contacto mecánicamente."], respuesta_correcta:1, explicacion:"Por seguridad, la placa debe ver que el interruptor pasa de ABIERTO a CERRADO. Si ya está cerrado, no puede validar que el motor inductor realmente está moviendo aire." , question: "A modern gas furnace performs a 'Self-Test' and detects that the pressure switch is CLOSED before the inducer motor starts. What does the control board do?", options: ["It starts the ignition sequence normally, assuming excellent draft.", "It locks out ignition because the switch should be open without airflow; this indicates a stuck switch or an illegal jumper.", "It ignores the sensor and activates the gas valve for a 5-second safety window.", "It increases voltage to the inducer motor to try to mechanically open the contact."], explanation: "For safety, the board must see the switch go from OPEN to CLOSED. If it is already closed, it cannot validate that the inducer motor is actually moving air." },
  { id:"calef_173", categoria:"CALEF_HORNOS", pregunta:"Durante la secuencia de encendido, el 'Hot Surface Igniter' (HSI) brilla intensamente, pero la válvula de gas nunca se abre. El técnico mide 24V en los terminales de la válvula. ¿Qué indica esto?", opciones:["La placa de control está defectuosa porque el HSI debería apagarse antes.", "La bobina de la válvula de gas está abierta (quemada) o el solenoide está mecánicamente trabado.", "El interruptor de presión se abrió justo en el momento del encendido.", "El sensor de llama detectó una llama falsa antes de abrir el gas."], respuesta_correcta:1, explicacion:"Si hay voltaje en la válvula (24V) pero no hay paso de gas, el problema es el actuador final (la válvula misma). Si el problema fuera un sensor o el interruptor de presión, la placa no enviaría los 24V." , question: "During the ignition sequence, the Hot Surface Igniter (HSI) glows brightly, but the gas valve never opens. The technician measures 24V at the valve terminals. What does this indicate?", options: ["The control board is defective because the HSI should turn off first.", "The gas valve solenoid coil is open (burned) or the solenoid is mechanically stuck.", "The pressure switch opened at the exact moment of ignition.", "The flame sensor detected a false flame before opening the gas."], explanation: "If there is voltage at the valve (24V) but no gas flow, the problem is the final actuator (the valve itself). If the issue were a sensor or the pressure switch, the board would not send the 24V." },
  { id:"calef_174", categoria:"CALEF_HORNOS", pregunta:"Un horno de 95% AFUE falla con un código de 'Pressure Switch Open'. El técnico nota que la manguera del interruptor tiene gotas de agua. ¿Cuál es el error de instalación más probable?", opciones:["El motor inductor está girando al revés.", "El venteo de PVC no tiene la pendiente (pitch) adecuada de 1/4\" por pie hacia el horno, permitiendo que el condensado se acumule en el colector.", "Se usó PVC de cédula 80 en lugar de cédula 40.", "El interruptor de presión está montado por debajo del nivel del quemador."], respuesta_correcta:1, explicacion:"En equipos de condensación, el agua debe fluir de regreso al drenaje del horno. Si el tubo de escape está nivelado o inclinado hacia afuera, el agua se estanca y bloquea el flujo de aire, abriendo el interruptor." , question: "A 95% AFUE furnace fails with a 'Pressure Switch Open' code. The technician notices water droplets in the pressure switch hose. What is the most likely installation error?", options: ["The inducer motor is spinning in reverse.", "The PVC flue does not have the proper 1/4-inch per foot slope back toward the furnace, allowing condensate to pool in the collector.", "Schedule 80 PVC was used instead of Schedule 40.", "The pressure switch is mounted below the burner level."], explanation: "In condensing equipment, water must flow back to the furnace drain. If the exhaust pipe is level or pitched outward, water collects and blocks airflow, opening the pressure switch." },
  { id:"calef_175", categoria:"CALEF_HORNOS", pregunta:"Un horno se enciende, la llama dura 3 segundos y se apaga. Se repite 3 veces y entra en Lockout. El sensor de llama está limpio y cableado. ¿Qué voltaje 'bias' debería medir entre el sensor y tierra?", opciones:["0V DC, ya que es un circuito de corriente, no de voltaje.", "Aproximadamente 80V a 120V AC (provenientes de la placa) para permitir la rectificación de la llama.", "24V DC constantes desde el transformador de control.", "Milivoltios generados por el calor de la llama (Efecto Seebeck)."], respuesta_correcta:1, explicacion:"La placa de control aplica un voltaje AC al sensor. Cuando hay llama, los electrones fluyen en una sola dirección hacia el quemador (rectificación), creando la señal DC que la placa reconoce." , question: "A furnace ignites, the flame lasts 3 seconds, and then it goes out. This repeats 3 times and the unit enters lockout. The flame sensor is clean and wired. What 'bias' voltage should you measure between the sensor and ground?", options: ["0V DC, since it is a current circuit, not a voltage circuit.", "Approximately 80V to 120V AC (from the control board) to allow flame rectification.", "A constant 24V DC from the control transformer.", "Millivolts generated by flame heat (Seebeck Effect)."], explanation: "The control board applies an AC voltage to the sensor. When there is a flame, electrons flow in one direction toward the burner (rectification), creating the DC signal the board recognizes." },
  { id:"calef_176", categoria:"CALEF_HORNOS", pregunta:"Usted mide 0V AC entre el terminal 'W' y 'C' en el tablero del horno, pero el termostato está en modo 'Heat' y marca 22°C con setpoint de 25°C. ¿Dónde está la falla?", opciones:["En el transformador de 24V del horno.", "En el termostato o en el cableado entre el termostato y el horno (circuito abierto).", "En el interruptor de límite alto que está abierto.", "La placa de control ha entrado en modo de ahorro de energía 'Deep Sleep'."], respuesta_correcta:1, explicacion:"Si el termostato 'pide' calor, debería cerrar el contacto R-W. Si no llegan 24V al terminal W del horno, la señal se perdió en el camino o el termostato no cerró el relé." , question: "You measure 0V AC between the 'W' terminal and 'C' on the furnace board, but the thermostat is in 'Heat' mode showing 72 degrees F with a setpoint of 77 degrees F. Where is the fault?", options: ["In the 24V transformer of the furnace.", "In the thermostat or in the wiring between the thermostat and the furnace (open circuit).", "In the high-limit switch, which is open.", "The control board has entered a 'Deep Sleep' energy-saving mode."], explanation: "If the thermostat is 'calling' for heat, it should close the R-W contact. If no 24V reaches the W terminal at the furnace, the signal was lost along the way or the thermostat did not close its relay." },
  { id:"calef_177", categoria:"CALEF_HORNOS", pregunta:"Un interruptor de presión (Pressure Switch) marca 'Closed' pero el motor inductor no ha arrancado. El técnico quita un cable del interruptor y el horno comienza su secuencia. ¿Qué sucede?", opciones:["El interruptor tiene los contactos pegados o hay un puente (jumper) que debe eliminarse.", "Es una función de autolimpieza de la placa de control.", "El motor inductor tiene un cortocircuito que 'engaña' al sensor.", "La presión atmosférica es tan alta que cerró el interruptor mecánicamente."], respuesta_correcta:0, explicacion:"La placa de control chequea que el switch esté ABIERTO antes de arrancar. Si está CERRADO, asume un fallo de seguridad (contactos soldados) y bloquea el sistema." , question: "A pressure switch shows 'Closed' but the inducer motor has not started. The technician removes a wire from the switch and the furnace begins its sequence. What is going on?", options: ["The switch has welded contacts or there is a jumper that must be removed.", "It is a self-cleaning function of the control board.", "The inducer motor has a short circuit that 'fools' the sensor.", "Atmospheric pressure is so high it mechanically closed the switch."], explanation: "The control board checks that the switch is OPEN before starting. If it is CLOSED, it assumes a safety fault (welded contacts) and locks out the system." },
  { id:"calef_178", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Ceramic Insulator' en un sensor de llama por ionización?", opciones:["Conducir la electricidad hacia el quemador.", "Evitar que la señal de microamperios se escape (se vaya a tierra) a través del chasis del horno antes de pasar por la llama.", "Aumentar la temperatura de la punta del sensor.", "Filtrar la radiación infrarroja de la llama."], respuesta_correcta:1, explicacion:"La señal de llama es tan débil que cualquier grieta en la porcelana (aislante) causará que la corriente fluya directamente al metal del horno, haciendo que la placa 'piense' que no hay llama." , question: "What is the function of the 'Ceramic Insulator' on a flame sensor (ionization type)?", options: ["To conduct electricity to the burner.", "To prevent the microamp signal from leaking to ground through the furnace chassis before passing through the flame.", "To increase the temperature of the sensor tip.", "To filter infrared radiation from the flame."], explanation: "The flame signal is so weak that any crack in the porcelain (insulator) will cause the current to flow directly to the furnace metal, making the board 'think' there is no flame." },
  { id:"calef_179", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama con puntas amarillas 'ahumadas' en un horno de gas?", opciones:["Combustión perfecta con alta eficiencia.", "Falta severa de aire primario, generando hollín y monóxido de carbono peligroso.", "Que el gas tiene demasiada presión y la llama es muy potente.", "Es el color normal del gas propano cuando hace mucho frío."], respuesta_correcta:1, explicacion:"El amarillo es carbón incandescente. Si hay hollín, el sistema está sucio y es ineficiente. Se debe ajustar el obturador de aire o limpiar los quemadores." , question: "What does a flame with yellow, 'sooty' tips indicate in a gas furnace?", options: ["Perfect combustion with high efficiency.", "Severe lack of primary air, producing soot and dangerous carbon monoxide.", "The gas has too much pressure and the flame is very powerful.", "This is the normal color of propane gas when it is very cold."], explanation: "Yellow indicates incandescent carbon particles. If there is soot, the system is dirty and inefficient. The air shutter must be adjusted or the burners must be cleaned." },
  { id:"calef_180", categoria:"CALEF_HORNOS", pregunta:"¿Por qué los hornos de alta eficiencia usan un intercambiador de calor secundario de acero inoxidable?", opciones:["Para que el horno brille más cuando el cliente lo vea.", "Porque el condensado que se forma es ácido y corroería el acero aluminizado normal en pocos meses.", "El acero inoxidable es un mejor conductor de calor que el cobre.", "Para reducir el peso total de la unidad."], respuesta_correcta:1, explicacion:"El agua de combustión tiene ácidos. El acero inoxidable '304' o '316' resiste esa corrosión, permitiendo que el horno dure 20 años en lugar de 2." , question: "Why do high-efficiency furnaces use a stainless steel secondary heat exchanger?", options: ["So the furnace looks shinier when the customer sees it.", "Because the condensate that forms is acidic and would corrode normal aluminized steel in a few months.", "Stainless steel is a better heat conductor than copper.", "To reduce the total weight of the unit."], explanation: "The combustion water contains acids. Stainless steel '304' or '316' resists that corrosion, allowing the furnace to last 20 years instead of 2." },
  { id:"calef_181", categoria:"CALEF_HORNOS", pregunta:"¿Qué es un 'Direct Spark Ignition' (DSI) y en qué se diferencia de un piloto intermitente?", opciones:["El DSI usa una cerilla electrónica manual.", "El DSI enciende el quemador principal directamente con una chispa de alta tensión, sin usar un piloto intermedio.", "El DSI solo funciona con gas propano.", "El DSI no requiere sensor de llama porque la chispa es constante."], respuesta_correcta:1, explicacion:"DSI es más rápido pero requiere una placa de control muy precisa para detectar la llama instantáneamente, ya que si falla, libera mucho gas rápidamente." , question: "What is 'Direct Spark Ignition' (DSI) and how does it differ from an intermittent pilot?", options: ["DSI uses a manual electronic match.", "DSI ignites the main burner directly with a high-voltage spark, without using an intermediate pilot.", "DSI only works with propane gas.", "DSI does not require a flame sensor because the spark is continuous."], explanation: "DSI is faster but requires a very precise control board to detect the flame instantly, because if it fails, it releases a large amount of gas quickly." },
  { id:"calef_182", categoria:"CALEF_HORNOS", pregunta:"¿Qué es el 'Thermal Stress' en un intercambiador de calor?", opciones:["Cuando el técnico se estresa por el calor del cuarto de máquinas.", "La expansión y contracción del metal causada por ciclos rápidos de calentamiento y enfriamiento, que puede llevar a grietas por fatiga.", "La presión del gas dentro del tubo.", "El peso del serpentín de aire acondicionado encima del horno."], respuesta_correcta:1, explicacion:"El metal es como un clip: si lo doblas mucho (calor/frío), se rompe. Por eso es vital que el flujo de aire sea el correcto para que el metal no se estire de más." , question: "What is 'Thermal Stress' in a heat exchanger?", options: ["When the technician gets stressed from the heat in the mechanical room.", "The expansion and contraction of metal caused by rapid heating and cooling cycles, which can lead to fatigue cracks.", "The gas pressure inside the tube.", "The weight of the air conditioning coil sitting on top of the furnace."], explanation: "Metal is like a paperclip: if you bend it back and forth enough (hot/cold), it breaks. That is why proper airflow is vital to prevent the metal from stretching too much." },
  { id:"calef_183", categoria:"CALEF_HORNOS", pregunta:"¿Qué sucede si el terminal de salida de un horno de condensación (PVC) queda enterrado bajo la nieve?", opciones:["El horno sigue funcionando pero gasta más gas.", "El interruptor de presión detectará la obstrucción y bloqueará el funcionamiento del horno por seguridad.", "El calor del gas derretirá la nieve y no pasará nada.", "El monóxido de carbono se filtrará por las tuberías de drenaje hacia los baños."], respuesta_correcta:1, explicacion:"Es una causa común de llamadas de servicio en invierno. La nieve bloquea el escape, el motor inductor no puede mover aire y el sensor de presión corta el sistema." , question: "What happens if the PVC exhaust terminal of a condensing furnace gets buried under snow?", options: ["The furnace keeps running but uses more gas.", "The pressure switch will detect the obstruction and lock out the furnace for safety.", "The heat from the flue gas will melt the snow and nothing will happen.", "Carbon monoxide will leak through the drain pipes into the bathrooms."], explanation: "This is a common cause of winter service calls. Snow blocks the exhaust, the inducer motor cannot move air, and the pressure switch shuts down the system." },
  { id:"calef_184", categoria:"CALEF_HORNOS", pregunta:"¿Qué es la 'Llama de Retorno' (Flashback) en un quemador?", opciones:["Cuando la llama se apaga de repente.", "Cuando la llama se quema dentro del mezclador o del orificio del quemador en lugar de quemarse en la punta.", "Una luz brillante que indica buena combustión.", "El reflejo de la llama en el intercambiador de calor."], respuesta_correcta:1, explicacion:"Es peligroso. Ocurre si el gas sale muy lento o hay mucho aire. El fuego viaja 'hacia atrás' buscando el combustible y puede derretir la válvula de gas o el quemador." , question: "What is 'Flashback' in a burner?", options: ["When the flame suddenly goes out.", "When the flame burns inside the mixer or burner orifice instead of at the burner tip.", "A bright light indicating good combustion.", "The reflection of the flame on the heat exchanger."], explanation: "This is dangerous. It occurs if the gas exits too slowly or there is too much air. The fire travels 'backward' seeking fuel and can melt the gas valve or the burner." },
  { id:"calef_185", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la causa técnica de que un intercambiador de calor 'zumba' o vibra cuando el quemador está encendido pero el soplador está apagado?", opciones:["Resonancia acústica de la llama dentro de las celdas (Flame resonance).", "Falta de conexión a tierra de la válvula de gas.", "El metal se está derritiendo por falta de flujo de aire.", "Interferencia de radiofrecuencia del termostato Wi-Fi."], respuesta_correcta:0, explicacion:"Es un fenómeno de acústica. La forma del intercambiador y la velocidad del gas crean una frecuencia de resonancia, similar a soplar una botella. Suele ajustarse variando la presión del gas." , question: "What is the technical cause of a heat exchanger 'humming' or vibrating when the burner is lit but the blower is off?", options: ["Acoustic resonance of the flame inside the cells (flame resonance).", "A missing ground connection on the gas valve.", "The metal is melting due to lack of airflow.", "Radio frequency interference from the Wi-Fi thermostat."], explanation: "It is an acoustic phenomenon. The shape of the heat exchanger and the gas velocity create a resonant frequency, similar to blowing across a bottle. It is usually corrected by adjusting the gas pressure." },
  { id:"calef_186", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Orificio de Calibración' (Burner Orifice)?", opciones:["Mezclar el aire primario con el gas.", "Controlar el volumen exacto de gas (BTU/h) que entra al quemador basándose en la presión del manifold.", "Actuar como un pararrayos para el sensor de llama.", "Aumentar la temperatura del gas antes de la ignición."], respuesta_correcta:1, explicacion:"Es el 'inyector'. El tamaño del agujero está calculado con precisión matemática para dejar pasar la cantidad justa de combustible para la potencia del horno." , question: "What is the function of the 'Burner Orifice'?", options: ["To mix primary air with the gas.", "To control the exact volume of gas (BTU/h) entering the burner based on the manifold pressure.", "To act as a lightning rod for the flame sensor.", "To increase the gas temperature before ignition."], explanation: "It is the 'injector.' The hole size is calculated with mathematical precision to allow exactly the right amount of fuel for the furnace's rated output." },
  { id:"calef_187", categoria:"CALEF_HORNOS", pregunta:"¿Por qué no se permite usar imprimante (primer) de color púrpura en algunos códigos de instalación de venteo de PVC?", opciones:["Porque el color púrpura bloquea la visión de los inspectores.", "Es una cuestión estética; se prefiere el primer transparente para no ensuciar la pared exterior.", "No hay prohibición técnica, de hecho, el color ayuda a verificar que se usó primer en todas las uniones por seguridad.", "El tinte púrpura debilita la estructura molecular del PVC a altas temperaturas."], respuesta_correcta:2, explicacion:"Capciosa: La mayoría de los códigos **exigen** que el primer sea visible (púrpura) para que el inspector sepa que la unión se ablandó químicamente antes del pegamento, asegurando una unión hermética a gases." , question: "Why is the use of purple primer prohibited by some codes for PVC flue pipe installations?", options: ["Because the purple color blocks the inspector's view.", "It is an aesthetic concern; clear primer is preferred to avoid staining the exterior wall.", "There is no technical prohibition; in fact, the color helps verify that primer was used on all joints for safety.", "The purple dye weakens the PVC molecular structure at high temperatures."], explanation: "Tricky: Most codes actually REQUIRE the primer to be visible (purple) so the inspector knows the joint was chemically softened before cementing, ensuring a gas-tight seal." },
  { id:"calef_188", categoria:"CALEF_HORNOS", pregunta:"Un sensor de llama mide 4 microamperios DC cuando la llama está presente. ¿Qué sucede si la llama se vuelve 'pobre' y se aleja del sensor?", opciones:["La señal sube a 10 microamperios.", "La señal cae por debajo del umbral de la placa (ej. 1 uA) y el horno se apaga por seguridad por pérdida de llama.", "El sensor se calienta más y compensa la señal.", "La placa de control aumenta el voltaje al ignitor."], respuesta_correcta:1, explicacion:"La ionización depende de que la llama toque físicamente el metal del sensor. Si la llama 'vuela' o es muy inestable, el circuito se rompe y el sistema se bloquea." , question: "A flame sensor reads 4 microamps DC when the flame is present. What happens if the flame becomes 'lean' and moves away from the sensor?", options: ["The signal rises to 10 microamps.", "The signal drops below the board's threshold (e.g., 1 microamp) and the furnace shuts down on loss of flame for safety.", "The sensor gets hotter and compensates the signal.", "The control board increases voltage to the igniter."], explanation: "Ionization depends on the flame physically touching the sensor's metal. If the flame 'floats' or is very unstable, the circuit breaks and the system locks out." },
  { id:"calef_189", categoria:"CALEF_HORNOS", pregunta:"¿Qué es el 'Dampener' barométrico y dónde se usa?", opciones:["En el retorno de aire para controlar la humedad.", "En el ducto de escape de calderas de aceite o gas de tiro natural para estabilizar el tiro de la chimenea ante cambios de viento.", "Dentro de la válvula de expansión para reducir el ruido.", "En el termostato para evitar cambios rápidos de temperatura."], respuesta_correcta:1, explicacion:"Es esa 'puerta' que oscila en el tubo de escape. Se abre o cierra sola con el aire de la habitación para que el quemador siempre tenga el mismo 'jalón' de aire sin importar el clima afuera." , question: "What is a 'Barometric Damper' and where is it used?", options: ["In the return air duct to control humidity.", "In the exhaust flue of natural draft oil or gas boilers to stabilize the chimney draft against wind changes.", "Inside the expansion valve to reduce noise.", "In the thermostat to prevent rapid temperature changes."], explanation: "It is that swinging 'door' in the exhaust pipe. It opens or closes on its own using room air so the burner always has consistent draft regardless of outdoor wind conditions." },
  { id:"calef_190", categoria:"CALEF_HORNOS", pregunta:"Si un sensor de llama toca el metal del quemador debido a un golpe, ¿qué reportará la placa de control?", opciones:["Llama perfecta (señal constante).", "Falla de encendido o 'Short to Ground' porque la corriente fluye directo a tierra sin la rectificación de la llama.", "Sobrecalentamiento del ignitor.", "Exceso de gas en el manifold."], respuesta_correcta:1, explicacion:"La placa necesita ver una señal rectificada (como un diodo). Un contacto directo es un cortocircuito. La placa sabe que eso no es una llama real y bloquea el gas." , question: "If a flame sensor touches the burner metal due to being bumped, what will the control board report?", options: ["Perfect flame (constant signal).", "Ignition failure or 'Short to Ground' because current flows directly to ground without flame rectification.", "Igniter overheating.", "Excess gas at the manifold."], explanation: "The board needs to see a rectified signal (like a diode). A direct contact is a short circuit. The board knows this is not a real flame and blocks the gas." },
  { id:"calef_191", categoria:"CALEF_HORNOS", pregunta:"¿Qué ocurre si la trampa de condensado (condensate trap) de un horno de 90% está seca al inicio de la temporada?", opciones:["El horno no encenderá porque el agua es necesaria para la llama.", "Los gases de combustión podrían escaparse a través del drenaje hacia la casa, o el interruptor de presión podría no cerrar por fuga de aire.", "El intercambiador de calor se oxidará en 24 horas.", "El motor inductor consumirá el triple de amperaje."], respuesta_correcta:1, explicacion:"La trampa actúa como el 'sifón' de un baño. Evita que el humo se salga por el tubo del agua. Siempre hay que cebarla con un poco de agua al hacer el mantenimiento anual." , question: "What happens if the condensate drain trap of a 90%+ furnace is dry at the start of the season?", options: ["The furnace will not ignite because water is necessary for the flame.", "Combustion gases could escape through the drain into the house, or the pressure switch may not close due to air leakage.", "The heat exchanger will oxidize within 24 hours.", "The inducer motor will draw triple the amperage."], explanation: "The trap works like a sink P-trap. If it is dry, furnace exhaust escapes through the drain. It should always be primed with a small amount of water during annual maintenance." },
  { id:"calef_192", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es el propósito del 'Anticipador de Calor' en un termostato mecánico antiguo?", opciones:["Predecir el clima del día siguiente.", "Generar un pequeño calor interno para que el termostato apague el horno justo antes de llegar al setpoint, evitando que la inercia térmica sobrecaliente la casa.", "Aumentar la sensibilidad del sensor de humedad.", "Reducir el consumo eléctrico del termostato."], respuesta_correcta:1, explicacion:"Sin el anticipador, el radiador sigue soltando calor después de que el horno apaga, y la casa terminaría a 24°C cuando querías 22°C. Es un control de 'frenado precoz'." , question: "What is the purpose of the 'Heat Anticipator' in an old mechanical thermostat?", options: ["To predict the next day's weather.", "To generate a small internal heat so the thermostat shuts off the furnace just before reaching the setpoint, preventing thermal inertia from overshooting the temperature.", "To increase the sensitivity of the humidity sensor.", "To reduce the thermostat's electrical consumption."], explanation: "Without the anticipator, the radiator keeps putting out heat after the furnace turns off, and the house would end up at 76 degrees F when you wanted 72. It is a 'pre-braking' control." },
  { id:"calef_193", categoria:"CALEF_HORNOS", pregunta:"En un sistema de 'Nitruro de Silicio', ¿por qué el ignitor es más pequeño que los antiguos de 'Carburo de Silicio'?", opciones:["Porque son más baratos de fabricar.", "Porque el material es mucho más denso y resistente, permitiendo alcanzar temperaturas más altas en un área menor sin romperse tan fácil.", "Para que el gas pase más rápido a su alrededor.", "Es una norma de la EPA para reducir el uso de cerámica."], respuesta_correcta:1, explicacion:"Los de nitruro son 'indestructibles' comparados con los viejos. Duran mucho más y no se rompen solo con tocarlos con los dedos." , question: "In a 'Silicon Nitride' igniter system, why is the igniter smaller than the old 'Silicon Carbide' ones?", options: ["Because they are cheaper to manufacture.", "Because the material is much denser and more durable, allowing it to reach higher temperatures in a smaller area without breaking as easily.", "So the gas flows faster around it.", "It is an EPA regulation to reduce ceramic use."], explanation: "Silicon nitride igniters are 'nearly indestructible' compared to the old ones. They last much longer and do not crack just from being touched by fingers." },
  { id:"calef_194", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la ventaja de un 'Sistema de Piloto Intermitente' sobre un 'Piloto Estacionario'?", opciones:["Que el piloto intermitente brilla más.", "Ahorro de energía, ya que el piloto solo se enciende cuando el termostato pide calor, en lugar de estar quemando gas todo el verano.", "Que no requiere sensor de llama.", "Que funciona mejor en altitudes elevadas."], respuesta_correcta:1, explicacion:"Un piloto prendido 24/7 gasta mucho gas al año sin necesidad. El intermitente usa una chispa para prenderse solo cuando hace falta." , question: "What is the advantage of an 'Intermittent Pilot' system over a 'Standing Pilot'?", options: ["The intermittent pilot burns brighter.", "Energy savings, since the pilot only ignites when the thermostat calls for heat, instead of burning gas all summer long.", "It does not require a flame sensor.", "It works better at high altitudes."], explanation: "A pilot burning 24/7 wastes a lot of gas per year for no reason. The intermittent pilot uses a spark to light only when needed." },
  { id:"calef_195", categoria:"CALEF_HORNOS", pregunta:"Un horno de gas muestra un código de falla de 'Límite de Roll-out Abierto'. ¿Qué acción física del sistema causó esto?", opciones:["El soplador principal está girando demasiado rápido.", "Las llamas salieron de la cámara de combustión hacia el compartimento de los quemadores, usualmente por un intercambiador tapado o falta de tiro.", "La presión del gas es demasiado baja para mantener la llama.", "El filtro de aire está tan limpio que no ofrece resistencia."], respuesta_correcta:1, explicacion:"Es una falla crítica. El fuego 'buscó' oxígeno afuera de donde debería estar. Este sensor es de restablecimiento manual porque un técnico DEBE inspeccionar por qué el fuego se salió de su lugar." , question: "A gas furnace displays a 'Roll-out Limit Open' fault code. What physical action of the system caused this?", options: ["The main blower is spinning too fast.", "Flames exited the combustion chamber into the burner compartment, usually due to a plugged heat exchanger or insufficient draft.", "The gas pressure is too low to sustain the flame.", "The air filter is so clean it offers no resistance."], explanation: "It is a critical failure. The fire 'searched' for oxygen outside of where it should be. This sensor is manual reset because a technician MUST inspect why the fire escaped its compartment." },
  { id:"calef_196", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Post-Purge' en la secuencia de un horno de gas?", opciones:["Limpiar los quemadores con aire antes de que se enciendan.", "Hacer funcionar el motor inductor después de que la llama se apaga para evacuar los gases residuales de combustión y enfriar el intercambiador.", "Aumentar la presión en los ductos para que el soplador no sufra.", "Cargar el capacitor del motor soplador para el siguiente ciclo."], respuesta_correcta:1, explicacion:"Seguridad ante todo. El post-purga asegura que no quede Monóxido de Carbono atrapado en el equipo y ayuda a eliminar el calor residual para proteger el metal." , question: "What is the function of 'Post-Purge' in the sequence of a gas furnace?", options: ["To clean the burners with air before they ignite.", "To run the inducer motor after the flame goes out to evacuate residual combustion gases and cool the heat exchanger.", "To increase duct pressure so the blower does not strain.", "To charge the blower motor capacitor for the next cycle."], explanation: "Safety first. Post-purge ensures that no carbon monoxide remains trapped in the equipment and helps remove residual heat to protect the metal." },
  { id:"calef_197", categoria:"CALEF_HORNOS", pregunta:"En un horno de flujo descendente (Downflow), ¿dónde suele ubicarse el interruptor de límite de alta temperatura?", opciones:["En el piso del armario.", "En el centro del intercambiador de calor, cerca de donde el aire caliente sale hacia el plenum inferior.", "Dentro del motor del soplador únicamente.", "En la manguera del interruptor de presión."], respuesta_correcta:1, explicacion:"El sensor debe estar donde el aire es más caliente. En un downflow, esto es en la parte baja, justo antes de que el aire entre a los ductos del piso." , question: "On a downflow furnace, where is the high-temperature limit switch typically located?", options: ["On the floor of the cabinet.", "In the center of the heat exchanger, near where the hot air exits toward the lower plenum.", "Inside the blower motor only.", "On the pressure switch hose."], explanation: "The sensor must be where the air is hottest. In a downflow unit, this is at the bottom, just before the air enters the floor ductwork." },
  { id:"calef_198", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la ventaja de un ignitor de 'Nitruro de Silicio' sobre uno de 'Carburo de Silicio'?", opciones:["Es mucho más resistente a las vibraciones y a la manipulación física, además de calentarse más rápido con menos energía.", "Es más grande y fácil de ver cuando brilla.", "No requiere voltaje de 120V para funcionar.", "Se puede limpiar con papel de lija si se ensucia."], respuesta_correcta:0, explicacion:"El carburo de silicio es frágil como el cristal. El nitruro de silicio es cerámico avanzado; aguanta golpes y dura mucho más en ciclos de encendido constantes." , question: "What is the advantage of a 'Silicon Nitride' igniter over a 'Silicon Carbide' igniter?", options: ["It is much more resistant to vibration and physical handling, and it heats up faster using less energy.", "It is larger and easier to see when it glows.", "It does not require 120V to operate.", "It can be cleaned with sandpaper if it gets dirty."], explanation: "Silicon carbide is fragile like glass. Silicon nitride is an advanced ceramic; it withstands impact and lasts much longer under constant ignition cycles." },
  { id:"calef_199", categoria:"CALEF_HORNOS", pregunta:"¿Qué es una 'Chimenea de Doble Pared' (Type B-Vent) y qué gas hay entre las paredes?", opciones:["Gas helio para que flote mejor.", "Aire en reposo (aislante térmico) para mantener los gases internos calientes y evitar que la pared exterior queme materiales combustibles cercanos.", "Vapor de agua para enfriar el sistema.", "Vacío absoluto creado en fábrica."], respuesta_correcta:1, explicacion:"El aire atrapado actúa como un termo. Mantiene el humo caliente para que suba rápido por la chimenea y permite que el tubo pase a solo 1 pulgada de la madera sin incendiar la casa." , question: "What is a 'Double-Wall Chimney' (Type B-Vent) and what gas is between the walls?", options: ["Helium gas so it floats better.", "Still air (thermal insulator) to keep the internal gases hot and prevent the outer wall from burning nearby combustible materials.", "Water vapor to cool the system.", "A factory-created absolute vacuum."], explanation: "The trapped air acts like a thermos. It keeps the exhaust hot so it rises quickly through the chimney and allows the pipe to be installed as close as 1 inch from wood without igniting the house." },
  { id:"calef_200", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un sensor de llama debe limpiarse con lana de acero fina o una almohadilla abrasiva suave y NO con papel de lija grueso?", opciones:["Porque el papel de lija es muy caro.", "El papel de lija deja residuos de arena (sílice) que, al calentarse, se convierten en cristal aislante, bloqueando la señal de microamperios nuevamente.", "Para no cambiar la forma aerodinámica del sensor.", "El sensor de llama se calibra por el peso del metal."], respuesta_correcta:1, explicacion:"El sílice de la lija es un aislante eléctrico. Si lijas con eso, crearás una capa de 'vidrio' invisible que impedirá que la placa detecte la llama, aunque el sensor parezca limpio." , question: "Why should a flame sensor be cleaned with fine steel wool or a soft abrasive pad and NOT coarse sandpaper?", options: ["Because sandpaper is too expensive.", "Sandpaper leaves sand (silica) residue that, when heated, turns into an insulating glass layer, blocking the microamp signal again.", "To avoid changing the aerodynamic shape of the sensor.", "The flame sensor is calibrated by the weight of its metal."], explanation: "The silica from sandpaper is an electrical insulator. If you sand with it, you will create an invisible 'glass' layer that prevents the board from detecting the flame, even though the sensor looks clean." },
  { id:"calef_201", categoria:"CALEF_HORNOS", pregunta:"¿Por qué los hornos de 80% de eficiencia (Categoría I) NO pueden ventearse con tubería de PVC?", opciones:["Porque el PVC es muy caro para esos hornos.", "Debido a que la temperatura de los gases de escape supera los 150°C, lo que derretiría y liberaría gases tóxicos del plástico.", "El PVC bloquea el tiro natural necesario para estos hornos.", "El gas natural reacciona químicamente con el polímero del PVC."], respuesta_correcta:1, explicacion:"Los hornos de 80% no condensan, por lo que su humo sale muy caliente. Solo los de alta eficiencia (90%+) enfrían tanto el humo que permiten el uso de plástico seguro." , question: "Why can 80% efficiency (Category I) furnaces NOT be vented with PVC pipe?", options: ["Because PVC is too expensive for those furnaces.", "Because the flue gas temperature exceeds 300 degrees F, which would melt the plastic and release toxic fumes.", "PVC blocks the natural draft needed for these furnaces.", "Natural gas reacts chemically with the PVC polymer."], explanation: "80% furnaces do not condense, so their exhaust exits very hot. Only high-efficiency (90%+) furnaces cool the exhaust enough to allow the safe use of plastic." },
  { id:"calef_202", categoria:"CALEF_HORNOS", pregunta:"¿Qué es un 'Venteo Directo' (Direct Vent / Two-Pipe System)?", opciones:["Un sistema que tira el humo directo al ático.", "Un diseño donde el horno toma el aire para la combustión directamente del exterior mediante un tubo y expulsa los gases por otro, sin usar aire de la casa.", "Cuando el humo sale por la misma rejilla del aire caliente.", "Un sistema que no requiere motor inductor."], respuesta_correcta:1, explicacion:"Es el sistema más seguro. No consume el oxígeno de la casa y no le afectan los químicos (como cloro o aerosoles) que pueda haber en el cuarto de máquinas." , question: "What is a 'Direct Vent' (Two-Pipe System)?", options: ["A system that exhausts flue gases directly into the attic.", "A design where the furnace draws combustion air directly from the outdoors through one pipe and expels gases through another, without using house air.", "When exhaust exits through the same register as the heated air.", "A system that does not require an inducer motor."], explanation: "It is the safest system. It does not consume oxygen from the house and is not affected by chemicals (like chlorine or aerosols) that may be present in the mechanical room." },
  { id:"calef_203", categoria:"CALEF_HORNOS", pregunta:"¿Cómo se calibra un sensor de temperatura tipo Termistor NTC?", opciones:["Girando un pequeño tornillo en la placa madre.", "No se calibra; se debe verificar su tabla de resistencia vs temperatura y reemplazarlo si los valores no coinciden.", "Sumergiéndolo en agua hirviendo para resetear su memoria.", "Cambiando las baterías del controlador DDC."], respuesta_correcta:1, explicacion:"Son resistencias variables fijas por su química. Si a 25°C no mide los ohmios que dice el manual (ej. 10k), el sensor está degradado y debe ir a la basura." , question: "How is an NTC thermistor temperature sensor calibrated?", options: ["By turning a small screw on the motherboard.", "It is not calibrated; you verify its resistance-vs-temperature table and replace it if the values do not match.", "By submerging it in boiling water to reset its memory.", "By changing the batteries in the DDC controller."], explanation: "These are variable resistors fixed by their chemistry. If at 77 degrees F it does not read the ohms specified in the manual (e.g., 10k), the sensor is degraded and must be discarded." },
  { id:"calef_204", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama azul con un cono interno bien definido y estable?", opciones:["Combustión incompleta con exceso de gas.", "Combustión perfecta con la mezcla ideal de aire primario y gas.", "Que el quemador está a punto de fundirse.", "Presencia de una fuga de monóxido de carbono."], respuesta_correcta:1, explicacion:"Es la llama de catálogo. Azul significa que no hay hollín. El cono estable significa que la velocidad del gas es la correcta. Es lo que todo técnico busca ajustar." , question: "What does a blue flame with a well-defined, stable inner cone indicate?", options: ["Incomplete combustion with excess gas.", "Perfect combustion with the ideal mixture of primary air and gas.", "The burner is about to melt.", "Presence of a carbon monoxide leak."], explanation: "This is the textbook flame. Blue means no soot. A stable cone means the gas velocity is correct. It is what every technician aims to achieve." },
  { id:"calef_205", categoria:"CALEF_HORNOS", pregunta:"¿Qué es el 'Límite de Condensación' en un horno de 80%?", opciones:["La temperatura máxima a la que el horno puede funcionar.", "El punto donde los gases de escape se enfrían tanto que el agua empieza a formarse en el intercambiador de acero aluminizado, destruyéndolo por corrosión.", "La presión máxima del gas en el quemador.", "El nivel de agua en la bandeja de drenaje."], respuesta_correcta:1, explicacion:"Por eso los hornos de 80% deben mantener el humo caliente. Si el humo se enfría mucho (ej. por ductos muy largos o fríos), el agua ácida se 'come' el metal del horno en poco tiempo." , question: "What is the 'Condensation Limit' in an 80% furnace?", options: ["The maximum temperature at which the furnace can operate.", "The point where the flue gases cool enough that water begins forming on the aluminized steel heat exchanger, destroying it through corrosion.", "The maximum gas pressure at the burner.", "The water level in the drain pan."], explanation: "That is why 80% furnaces must keep the exhaust hot. If the exhaust cools too much (e.g., due to very long or cold vent pipes), the acidic water 'eats' the furnace metal in a short time." },
  { id:"calef_206", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Flame Mirror' (espejo de llama) en algunos hornos comerciales?", opciones:["Para que el técnico se peine.", "Permitir la inspección visual de la llama y el ignitor sin tener que abrir la cámara de combustión sellada.", "Reflejar el calor hacia el intercambiador secundario.", "Para que el sensor óptico vea la llama desde dos ángulos."], respuesta_correcta:1, explicacion:"Es una ventana de seguridad. Te permite ver si la llama es azul o si el ignitor está brillando sin romper el sello de aire de la cámara, algo vital en sistemas de alta eficiencia." , question: "What is the function of the 'Flame Mirror' (sight glass) in some commercial furnaces?", options: ["So the technician can fix their hair.", "To allow visual inspection of the flame and igniter without opening the sealed combustion chamber.", "To reflect heat toward the secondary heat exchanger.", "So the optical sensor can view the flame from two angles."], explanation: "It is a safety window. It lets you see if the flame is blue or if the igniter is glowing without breaking the air seal of the chamber, which is vital in high-efficiency systems." },
  { id:"calef_207", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama que 'muerde' o es ruidosa (roaring flame)?", opciones:["Que el horno tiene mucha potencia.", "Excesiva presión de gas en el manifold o una pre-mezcla de aire primario muy agresiva; puede causar daños al intercambiador por calor excesivo.", "Es el sonido normal de un horno de alta eficiencia.", "Indica que el gas tiene mucha humedad."], respuesta_correcta:1, explicacion:"La llama debe ser silenciosa y estable. Si ruge, es porque hay demasiada energía concentrada en un punto pequeño. Esto puede crear 'puntos calientes' que agrietan el metal del horno." , question: "What does a 'biting' or noisy (roaring) flame indicate?", options: ["That the furnace has a lot of power.", "Excessive manifold gas pressure or an overly aggressive primary air premix; this can damage the heat exchanger from excessive heat.", "This is the normal sound of a high-efficiency furnace.", "It indicates the gas has a lot of moisture."], explanation: "The flame should be quiet and stable. If it roars, there is too much energy concentrated in a small area. This can create 'hot spots' that crack the furnace metal." },
  { id:"calef_208", categoria:"CALEF_HORNOS", pregunta:"¿Qué es un 'Conector de Chimenea' (Vent Connector) y por qué no puede pasar a través de paredes o techos?", opciones:["Es el tubo de PVC de los hornos modernos.", "Es el tubo de pared simple que conecta el horno a la chimenea principal; no debe atravesar estructuras porque su calor radiante podría incendiar la madera (combustibles) de la pared.", "Es un sensor de presión de aire.", "Sirve para drenar el agua de la lluvia fuera de la caldera."], respuesta_correcta:1, explicacion:"El tubo de pared simple se pone muy caliente. Para atravesar una pared, debes cambiar a un tubo 'B-Vent' (doble pared) que mantiene la superficie exterior más fría." , question: "What is a 'Vent Connector' and why can it not pass through walls or ceilings?", options: ["It is the PVC pipe used on modern furnaces.", "It is the single-wall pipe that connects the furnace to the main chimney; it must not penetrate structures because its radiant heat could ignite the wood (combustibles) in the wall.", "It is an air pressure sensor.", "It is used to drain rainwater away from the boiler."], explanation: "The single-wall pipe gets very hot. To pass through a wall, you must transition to a Type B-Vent (double-wall) pipe that keeps the outer surface cooler." },
  { id:"calef_209", categoria:"CALEF_HORNOS", pregunta:"Un sistema de 'Intermittent Pilot' (IP) genera chispa, pero el piloto no enciende. Usted escucha que la válvula de gas hace un 'click'. ¿Qué diagnóstico es el más probable?", opciones:["El sensor de llama está sucio.", "Tubería de suministro de piloto obstruida o presión de gas de entrada insuficiente para vencer el resorte de la válvula de piloto.", "El cable de alta tensión de la chispa tiene una fuga a tierra.", "El termostato no está pidiendo suficiente calor."], respuesta_correcta:1, explicacion:"Si hay chispa y hay click, la placa hizo su trabajo. El problema es físico: el gas no está llegando a la punta del piloto. Puede ser una araña que hizo un nido en el tubo del piloto." , question: "An 'Intermittent Pilot' (IP) system generates a spark, but the pilot does not light. You hear the gas valve 'click.' What is the most likely diagnosis?", options: ["The flame sensor is dirty.", "The pilot supply tube is obstructed or the inlet gas pressure is insufficient to overcome the pilot valve spring.", "The high-voltage spark wire has a ground leak.", "The thermostat is not calling for enough heat."], explanation: "If there is spark and there is a click, the board did its job. The problem is physical: gas is not reaching the pilot tip. It could be a spider that built a nest inside the pilot tube." },
  { id:"calef_210", categoria:"CALEF_HORNOS", pregunta:"¿Por qué el tubo de escape de PVC de un horno de alta eficiencia debe estar inclinado (pitched) hacia el horno y no hacia afuera?", opciones:["Para evitar que entre agua de lluvia.", "Para permitir que el condensado ácido fluya de regreso al drenaje interno del equipo y no se congele en la punta exterior formando carámbanos de hielo.", "Aumenta la velocidad de los gases mediante la gravedad.", "Es una regla estética para que el tubo no se vea caído desde la calle."], respuesta_correcta:1, explicacion:"Si el agua corre hacia afuera, se congela en la rejilla y bloquea el escape, apagando el horno en la noche más fría. El agua debe volver al horno para ser evacuada por el drenaje caliente." , question: "Why must the PVC exhaust pipe of a high-efficiency furnace be sloped (pitched) toward the furnace and not toward the outside?", options: ["To prevent rainwater from entering.", "To allow the acidic condensate to flow back to the furnace's internal drain and not freeze at the outdoor terminal forming icicles.", "It increases flue gas velocity through gravity.", "It is an aesthetic rule so the pipe does not look droopy from the street."], explanation: "If the water runs toward the outside, it freezes at the terminal and blocks the exhaust, shutting down the furnace on the coldest night. The water must return to the furnace to be evacuated through the heated drain." },
  { id:"calef_211", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Flame Deflector' en la cámara de combustión?", opciones:["Apagar la llama si es muy grande.", "Distribuir el calor de la llama de manera uniforme por las paredes del intercambiador para evitar puntos calientes (hot spots) que causen grietas prematuras.", "Reflejar la luz para que el técnico vea el ignitor.", "Aumentar la presión del aire primario."], respuesta_correcta:1, explicacion:"Sin deflectores, el fuego golpearía siempre el mismo punto del metal, estresándolo térmicamente hasta romperlo. El deflector hace que el calor 'bañe' todo el metal por igual." , question: "What is the function of the 'Flame Deflector' in the combustion chamber?", options: ["To extinguish the flame if it is too large.", "To distribute the flame heat evenly across the heat exchanger walls, preventing hot spots that cause premature cracks.", "To reflect light so the technician can see the igniter.", "To increase primary air pressure."], explanation: "Without deflectors, the fire would always hit the same spot on the metal, thermally stressing it until it cracks. The deflector ensures the heat 'bathes' all the metal equally." },
  { id:"calef_212", categoria:"CALEF_HORNOS", pregunta:"Usted observa una llama que es azul en la base pero tiene una punta amarilla brillante y constante. ¿Qué ajuste es el primero que debe intentar?", opciones:["Cambiar la válvula de gas completa.", "Abrir el obturador de aire primario (Air Shutter) para permitir que entre más oxígeno a la mezcla antes de la combustión.", "Cerrar el paso de gas a la mitad.", "Lijar los quemadores con papel de grano 40."], respuesta_correcta:1, explicacion:"Amarillo significa falta de aire (combustión rica). Al abrir el obturador, permites que el gas se mezcle con más aire, logrando esa llama azul limpia que no produce hollín." , question: "You observe a flame that is blue at the base but has a bright, constant yellow tip. What is the first adjustment to attempt?", options: ["Replace the entire gas valve.", "Open the primary air shutter to allow more oxygen into the mixture before combustion.", "Close the gas flow by half.", "Sand the burners with 40-grit sandpaper."], explanation: "Yellow means lack of air (rich combustion). By opening the shutter, you allow the gas to mix with more air, achieving that clean blue flame that does not produce soot." },
  { id:"calef_213", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Neutralizador de Condensado' en instalaciones comerciales?", opciones:["Hacer que el agua sea potable.", "Pasar el condensado ácido a través de piedras de mármol o caliza para elevar su pH antes de tirarlo al drenaje público, protegiendo las tuberías de la ciudad.", "Enfriar el agua antes de que toque el PVC.", "Añadir cloro para evitar el crecimiento de algas."], respuesta_correcta:1, explicacion:"El agua de estos hornos se 'come' el concreto y el hierro de las alcantarillas. El neutralizador convierte ese 'vinagre' químico en agua inofensiva para el medio ambiente." , question: "What is the function of the 'Condensate Neutralizer' in commercial installations?", options: ["To make the water drinkable.", "To pass the acidic condensate through marble or limestone chips to raise its pH before discharging it into the public drain, protecting city pipes.", "To cool the water before it contacts the PVC.", "To add chlorine to prevent algae growth."], explanation: "The water from these furnaces 'eats' concrete and iron in sewer lines. The neutralizer converts that chemical 'vinegar' into harmless water for the environment." },
  { id:"calef_214", categoria:"CALEF_HORNOS", pregunta:"¿Qué sucede si el motor inductor de tiro inducido tiene una aspa rota o sucia?", opciones:["El horno calienta un 10% más rápido.", "Causa vibración excesiva, ruido fuerte y puede reducir el flujo de aire de combustión lo suficiente para que el interruptor de presión no cierre.", "El sensor de llama se calibra automáticamente.", "El gas natural se vuelve más denso por la turbulencia."], respuesta_correcta:1, explicacion:"El inductor es el 'corazón' del tiro. Si no está balanceado, el ruido es insoportable y el aire de combustión no será el adecuado, causando fallas intermitentes." , question: "What happens if the induced draft motor has a broken or dirty blade?", options: ["The furnace heats 10% faster.", "It causes excessive vibration, loud noise, and can reduce combustion airflow enough that the pressure switch will not close.", "The flame sensor auto-calibrates.", "Natural gas becomes denser due to turbulence."], explanation: "The inducer is the 'heart' of the draft. If it is unbalanced, the noise is unbearable and the combustion airflow will be inadequate, causing intermittent failures." },
  { id:"calef_215", categoria:"CALEF_HORNOS", pregunta:"¿Qué es la 'Ionización de Llama' en términos sencillos?", opciones:["Cuando la llama se vuelve radiactiva.", "La capacidad de la llama para conducir una pequeña cantidad de electricidad (microamperios) al separar los electrones de las moléculas de gas caliente.", "El color azul de la combustión perfecta.", "Un proceso de limpieza de los quemadores mediante imanes."], respuesta_correcta:1, explicacion:"La llama es un cable. La placa manda electricidad, la llama la deja pasar, y la placa dice: 'Ah, hay fuego, puedo dejar el gas abierto'. Sin llama, no hay conducción." , question: "What is 'Flame Ionization' in simple terms?", options: ["When the flame becomes radioactive.", "The ability of the flame to conduct a small amount of electricity (microamps) by stripping electrons from the hot gas molecules.", "The blue color of perfect combustion.", "A process of cleaning burners using magnets."], explanation: "The flame is a wire. The board sends electricity, the flame lets it pass, and the board says: 'Ah, there is fire, I can keep the gas open.' Without a flame, there is no conduction." },
  { id:"calef_216", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica un olor a 'metal caliente' o 'polvo quemado' al encender la calefacción por primera vez en el año?", opciones:["Que el intercambiador de calor se está derritiendo.", "Es el polvo acumulado sobre el intercambiador durante el verano quemándose; es normal y suele desaparecer en 15-20 minutos.", "Una fuga masiva de gas natural.", "Que el motor del soplador necesita aceite de motor de auto."], respuesta_correcta:1, explicacion:"Es el 'olor a invierno'. El polvo de meses se carboniza al tocar el metal caliente. No es peligroso, solo molesto. Si el olor persiste por horas, entonces hay que investigar." , question: "What does a 'hot metal' or 'burning dust' smell indicate when turning on the heating for the first time of the year?", options: ["The heat exchanger is melting.", "It is dust accumulated on the heat exchanger during the summer burning off; it is normal and usually disappears within 15-20 minutes.", "A massive natural gas leak.", "The blower motor needs automotive oil."], explanation: "It is the 'smell of winter.' Months of dust carbonize when they touch the hot metal. It is not dangerous, just annoying. If the smell persists for hours, then investigation is needed." },
  { id:"calef_217", categoria:"CALEF_HORNOS", pregunta:"¿Qué es un 'Condensate Drain Trap' (trampa de drenaje) y por qué debe estar siempre con agua?", opciones:["Para que el agua no haga ruido al caer.", "Para crear un sello que impida que los gases de combustión peligrosos entren a la casa a través del tubo de drenaje.", "Aumenta la presión del motor inductor.", "Filtra los pelos de las mascotas que entran al horno."], respuesta_correcta:1, explicacion:"Es como el sifón de tu fregadero. Si está seco, el humo del horno se sale por ahí. Siempre hay que echarle un poco de agua al inicio de la temporada para cebarlo." , question: "What is a 'Condensate Drain Trap' and why must it always contain water?", options: ["So the water does not make noise when it drips.", "To create a seal that prevents dangerous combustion gases from entering the house through the drain tube.", "It increases the inducer motor pressure.", "It filters pet hair from entering the furnace."], explanation: "It works like your kitchen sink P-trap. If it is dry, furnace exhaust escapes through it. Always pour a little water in it at the start of the season to prime the seal." },
  { id:"calef_218", categoria:"CALEF_HORNOS", pregunta:"¿Qué sucede si el aire secundario es insuficiente en un horno de gas?", opciones:["La llama se vuelve azul brillante.", "La llama se 'estira', busca aire afuera del quemador y produce monóxido de carbono debido a la combustión incompleta.", "El motor del soplador consume menos amperaje.", "El gas natural se convierte en propano automáticamente."], respuesta_correcta:1, explicacion:"El aire secundario es el que rodea la llama. Sin él, el fuego no termina de quemarse bien. Es como tratar de correr una maratón respirando por un popote; te vas a ahogar." , question: "What happens if secondary air is insufficient in a gas furnace?", options: ["The flame turns bright blue.", "The flame 'stretches,' seeks air outside the burner, and produces carbon monoxide due to incomplete combustion.", "The blower motor draws less amperage.", "Natural gas automatically converts to propane."], explanation: "Secondary air is what surrounds the flame. Without it, the fire does not finish burning properly. It is like trying to run a marathon breathing through a straw; you suffocate." },
  { id:"calef_219", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una 'Mancha de Óxido' (rust) excesiva en el interior de un tubo de chimenea metálico?", opciones:["Que el metal es de mala calidad.", "Que los gases de combustión se están enfriando demasiado y condensando dentro del tubo, lo cual es señal de un diseño de chimenea incorrecto o falta de aire.", "Que ha llovido mucho ese año.", "Es una reacción normal con el nitrógeno del aire."], respuesta_correcta:1, explicacion:"Humo frío = agua ácida. Esa agua se come el metal. Si ves óxido, la chimenea no está 'jalando' bien el calor o el tubo es demasiado grande para el horno." , question: "What does excessive 'Rust' inside a metal chimney pipe indicate?", options: ["The metal is low quality.", "The flue gases are cooling too much and condensing inside the pipe, which is a sign of incorrect chimney design or insufficient draft.", "It rained a lot that year.", "It is a normal reaction with nitrogen in the air."], explanation: "Cool exhaust = acidic water. That water eats the metal. If you see rust, the chimney is not 'pulling' heat well or the pipe is oversized for the furnace." },
  { id:"calef_220", categoria:"CALEF_HORNOS", pregunta:"¿Qué es un 'Bloqueo por Falla de Ignición' (Ignition Lockout)?", opciones:["Cuando el cliente olvida la contraseña del termostato.", "Una medida de seguridad de la placa de control que deja de intentar encender el horno tras varios intentos fallidos, para evitar la acumulación peligrosa de gas.", "Cuando la válvula de gas se queda cerrada con llave.", "Un error en el Wi-Fi del equipo."], respuesta_correcta:1, explicacion:"Si el horno no prende en 3 veces, la placa dice 'basta'. Si siguiera mandando gas sin fuego, la casa podría explotar. Hay que quitar la luz para resetearlo tras arreglar el fallo." , question: "What is an 'Ignition Lockout'?", options: ["When the customer forgets the thermostat password.", "A control board safety measure that stops attempting to ignite the furnace after several failed tries, to prevent dangerous gas accumulation.", "When the gas valve gets locked with a key.", "An error in the equipment's Wi-Fi."], explanation: "If the furnace does not light in 3 tries, the board says 'enough.' If it kept sending gas without fire, the house could explode. Power must be cycled to reset it after fixing the fault." },
  { id:"calef_221", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica un color de llama 'verde' o 'púrpura' momentáneo?", opciones:["Que el gas es de muy alta calidad.", "Presencia de contaminantes químicos en el aire de combustión (como vapores de pintura, cloro o limpiadores) quemándose; es corrosivo para el intercambiador.", "Es el color normal en Navidad.", "Indica que el sensor de llama está nuevo."], respuesta_correcta:1, explicacion:"Si el cliente está pintando o usando cloro cerca del horno, la llama cambia de color. Esos químicos se vuelven ácidos al quemarse y pueden destruir el metal del horno en días." , question: "What does a momentary 'green' or 'purple' flame color indicate?", options: ["The gas is very high quality.", "The presence of chemical contaminants in the combustion air (such as paint fumes, chlorine, or cleaners) burning; this is corrosive to the heat exchanger.", "It is the normal color during the holidays.", "It indicates the flame sensor is new."], explanation: "If the customer is painting or using bleach near the furnace, the flame changes color. Those chemicals become acids when burned and can destroy the furnace metal in days." },
  { id:"calef_222", categoria:"CALEF_HORNOS", pregunta:"Durante la secuencia de encendido, el motor inductor arranca, el interruptor de presión cierra, pero el ignitor HSI nunca recibe 120V. ¿Qué componente revisaría después?", opciones:["El sensor de llama (flame rod).", "El relé de la placa de control o el interruptor de límite de alta temperatura (High Limit) que puede estar abierto.", "La presión del gas en el manifold de entrada.", "El capacitor del motor del soplador principal."], respuesta_correcta:1, explicacion:"Si los seguros primarios (presión) están bien, pero no hay ignición, es probable que la cadena de seguridad de alta temperatura esté rota o el relé de la placa esté fallando." , question: "During the ignition sequence, the inducer motor starts, the pressure switch closes, but the HSI igniter never receives 120V. What component would you check next?", options: ["The flame sensor (flame rod).", "The control board relay or the high-temperature limit switch (High Limit), which may be open.", "The gas manifold inlet pressure.", "The main blower motor capacitor."], explanation: "If the primary safeties (pressure) are satisfied but there is no ignition power, the high-temperature safety chain is likely broken or the board relay is failing." },
  { id:"calef_223", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Deflector de Calor' en el soplador de un horno de flujo horizontal?", opciones:["Aumentar la presión estática del sistema en un 20%.", "Proteger el motor del soplador y sus componentes eléctricos del calor radiante del intercambiador de calor cuando el quemador está encendido.", "Evitar que el aire de retorno se mezcle con el aire de suministro.", "Actuar como un soporte mecánico para el filtro de aire."], respuesta_correcta:1, explicacion:"En unidades horizontales, el motor está muy cerca del metal caliente. El deflector (escudo térmico) evita que el motor se 'cocine' por radiación infrarroja." , question: "What is the function of the 'Heat Shield' (deflector) on the blower of a horizontal furnace?", options: ["To increase the system's static pressure by 20%.", "To protect the blower motor and its electrical components from the radiant heat of the heat exchanger when the burner is firing.", "To prevent return air from mixing with supply air.", "To act as a mechanical support for the air filter."], explanation: "In horizontal units, the motor is very close to the hot metal. The deflector (heat shield) prevents the motor from being 'cooked' by infrared radiation." },
  { id:"calef_224", categoria:"CALEF_HORNOS", pregunta:"Un técnico encuentra que el tubo de PVC de entrada de aire (Intake) está escarchado por dentro en invierno. ¿Qué está ocurriendo?", opciones:["El aire exterior está demasiado frío para el sistema.", "Recirculación de gases de escape: el humo caliente sale y es succionado de inmediato por la entrada de aire cercana, condensándose y congelándose.", "Es una operación normal de los hornos de alta eficiencia en climas polares.", "El motor inductor está girando a demasiadas RPM."], respuesta_correcta:1, explicacion:"Si las puntas de los tubos están muy cerca, el horno 'respira' su propio humo. El vapor del escape se congela al entrar, bloqueando la respiración del equipo." , question: "A technician finds that the PVC air intake pipe is frosted on the inside during winter. What is occurring?", options: ["The outdoor air is too cold for the system.", "Exhaust gas recirculation: the hot exhaust exits and is immediately sucked back in by the nearby intake, condensing and freezing inside.", "This is normal operation of high-efficiency furnaces in polar climates.", "The inducer motor is spinning at too many RPM."], explanation: "If the pipe terminals are too close together, the furnace 'breathes' its own exhaust. The moisture from the exhaust freezes upon re-entry, blocking the equipment's air supply." },
  { id:"calef_225", categoria:"CALEF_HORNOS", pregunta:"Un sensor de llama reporta 0.5 microamperios. La placa requiere 1.0 microamperios mínimo. La llama es azul y toca el sensor. ¿Qué revisaría primero?", opciones:["Cambiar la válvula de gas por una de mayor presión.", "Limpiar el sensor de depósitos de óxido/sílice y verificar la integridad de la conexión de tierra del chasis.", "Instalar un ignitor de mayor potencia.", "Aumentar el tamaño de los orificios del quemador."], respuesta_correcta:1, explicacion:"Casi siempre es suciedad invisible. Una capa microscópica de óxido actúa como aislante. Limpiarlo restaura la señal original de inmediato." , question: "A flame sensor reports 0.5 microamps. The board requires a minimum of 1.0 microamp. The flame is blue and touching the sensor. What would you check first?", options: ["Replace the gas valve with a higher-pressure one.", "Clean the sensor of oxide/silica deposits and verify the integrity of the chassis ground connection.", "Install a higher-powered igniter.", "Increase the size of the burner orifices."], explanation: "It is almost always invisible contamination. A microscopic layer of oxide acts as an insulator. Cleaning it restores the original signal immediately." },
  { id:"calef_226", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Neutralizador de Presión' en un sistema de venteo concéntrico?", opciones:["Igualar la presión del gas natural con la del aire exterior.", "Asegurar que la presión en el terminal de escape y el de entrada de aire sea la misma bajo condiciones de viento fuerte, evitando bloqueos por presión diferencial.", "Filtrar el monóxido de carbono mediante un proceso químico pasivo.", "Reducir el ruido del soplador hacia el exterior de la casa."], respuesta_correcta:1, explicacion:"Si el viento sopla fuerte contra un solo tubo, el horno se apaga. Con el sistema concéntrico (un tubo dentro de otro), el viento empuja igual a ambos, manteniendo el equilibrio." , question: "What is the function of the 'Pressure Equalizer' in a concentric venting system?", options: ["To equalize natural gas pressure with outdoor air pressure.", "To ensure that pressure at the exhaust terminal and the air intake is the same under strong wind conditions, preventing lockouts due to differential pressure.", "To filter carbon monoxide through a passive chemical process.", "To reduce blower noise toward the exterior of the house."], explanation: "If wind blows hard against just one pipe, the furnace shuts down. With a concentric system (one pipe inside the other), the wind pushes both equally, maintaining balance." },
  { id:"calef_227", categoria:"CALEF_HORNOS", pregunta:"Usted encuentra un sensor de 'Roll-out' puenteado con un trozo de cable. ¿Cuál es la primera acción técnica obligatoria?", opciones:["Anotarlo en el reporte y seguir con la limpieza del filtro.", "Retirar el puente inmediatamente, deshabilitar el horno y encontrar la causa de por qué las llamas están saliendo de la cámara antes de ponerlo en marcha.", "Cambiar el puente por uno de calibre más grueso para mayor seguridad.", "Llamar al fabricante para pedir un sensor más resistente."], respuesta_correcta:1, explicacion:"Un puente en un sensor de seguridad es un intento de homicidio involuntario. El sensor está ahí para evitar incendios. Si saltó, es porque el equipo es peligroso." , question: "You find a Roll-out sensor that has been jumpered with a piece of wire. What is the first mandatory technical action?", options: ["Note it in the report and continue with the filter cleaning.", "Remove the jumper immediately, disable the furnace, and find the cause of why flames are escaping the combustion chamber before putting the unit back in service.", "Replace the jumper with a heavier-gauge wire for greater safety.", "Call the manufacturer to request a more resistant sensor."], explanation: "A jumper on a safety sensor is an act of potential involuntary harm. The sensor is there to prevent fires. If it tripped, the equipment is dangerous." },
  { id:"calef_228", categoria:"CALEF_HORNOS", pregunta:"En un quemador de gas, ¿qué indica la presencia de puntas anaranjadas que desaparecen al limpiar los quemadores con aire comprimido?", opciones:["Producción de Monóxido de Carbono letal.", "Incandescencia de partículas de polvo o minerales presentes en el aire primario; no es un problema de combustión per se.", "Que el gas natural tiene un exceso de vapor de agua.", "Falla inminente de la válvula de gas principal."], respuesta_correcta:1, explicacion:"El polvo (especialmente el de obras o mascotas) brilla al quemarse. Si tras limpiar desaparece, era solo suciedad ambiental y no falta de oxígeno." , question: "On a gas burner, what does the presence of orange tips that disappear after cleaning the burners with compressed air indicate?", options: ["Production of lethal carbon monoxide.", "Incandescence of dust or mineral particles present in the primary air; it is not a combustion problem per se.", "The natural gas has excess water vapor.", "Imminent failure of the main gas valve."], explanation: "Dust (especially from construction or pets) glows when it burns. If it disappears after cleaning, it was just environmental contamination and not a lack of oxygen." },
  { id:"calef_229", categoria:"CALEF_HORNOS", pregunta:"Un termostato tiene un ajuste de 'Ciclos por Hora' (CPH). Si se ajusta a un valor muy alto (ej. 12 CPH) en un horno de gas, ¿qué sucederá?", opciones:["La casa estará a una temperatura muy estable.", "El horno sufrirá un desgaste excesivo por arranques frecuentes y la eficiencia bajará debido a las pérdidas en los periodos de calentamiento y purga.", "El motor del soplador girará más rápido para compensar.", "Se reducirá el consumo de gas en un 15%."], respuesta_correcta:1, explicacion:"Cada vez que un horno arranca, gasta gas en purgar y calentar el metal. Si arranca 12 veces por hora, está perdiendo energía y quemando los relés innecesariamente." , question: "A thermostat has a 'Cycles Per Hour' (CPH) setting. If it is set to a very high value (e.g., 12 CPH) on a gas furnace, what will happen?", options: ["The house will be at a very stable temperature.", "The furnace will suffer excessive wear from frequent starts, and efficiency will drop due to losses during warm-up and purge periods.", "The blower motor will spin faster to compensate.", "Gas consumption will be reduced by 15%."], explanation: "Every time a furnace starts, it wastes gas on purging and heating the metal. If it starts 12 times per hour, it is wasting energy and burning out relays unnecessarily." },
  { id:"calef_230", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica el término 'Categoría III' en un sistema de calefacción según el código IFGC?", opciones:["Aparato de tiro natural con eficiencia menor al 70%.", "Aparato con presión positiva en el venteo (usa motor) y que no es de condensación (gases calientes).", "Un sistema que solo usa gas propano líquido.", "Equipos que se instalan únicamente en techos o exteriores."], respuesta_correcta:1, explicacion:"Son equipos especiales. Al tener presión positiva, el tubo de escape debe ser totalmente hermético (metal sellado o inoxidable) porque el humo no sube solo, el motor lo empuja." , question: "What does the term 'Category III' mean in a heating system according to the IFGC code?", options: ["A natural draft appliance with efficiency below 70%.", "An appliance with positive vent pressure (uses a motor) that is non-condensing (hot flue gases).", "A system that only uses liquid propane gas.", "Equipment that is installed only on rooftops or outdoors."], explanation: "These are special units. Having positive pressure means the exhaust pipe must be completely sealed (sealed metal or stainless) because the exhaust does not rise on its own -- the motor pushes it." },
  { id:"calef_231", categoria:"CALEF_HORNOS", pregunta:"Usted mide 15 microamperios en el sensor de llama. La placa marca falla de 'Llama Débil'. ¿Qué es lo más probable?", opciones:["El sensor está excesivamente limpio.", "Existe un cortocircuito interno en la placa de control que falsea la lectura o el sensor está tocando el chasis directamente (no hay rectificación).", "La válvula de gas tiene demasiada presión.", "El ignitor está brillando demasiado fuerte."], respuesta_correcta:1, explicacion:"Una lectura de 15 uA es anormalmente alta (lo normal son 2-6 uA). Si es tan alta, no es una señal de llama real, es un 'puente' eléctrico directo que la placa rechaza por seguridad." , question: "You measure 15 microamps at the flame sensor. The board shows a 'Weak Flame' fault. What is most likely happening?", options: ["The sensor is excessively clean.", "There is an internal short circuit in the control board that falsifies the reading, or the sensor is directly touching the chassis (no rectification).", "The gas valve has too much pressure.", "The igniter is glowing too brightly."], explanation: "A reading of 15 microamps is abnormally high (normal is 2-6 microamps). If it is that high, it is not a real flame signal -- it is a direct electrical 'bridge' that the board rejects for safety." },
  { id:"calef_232", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un horno de Categoría IV requiere una pendiente de 1/4\" hacia el equipo en su tubería de escape?", opciones:["Para que el gas salga más rápido.", "Para asegurar que el condensado corrosivo no se acumule en los codos y regrese a la trampa de drenaje del horno para ser eliminado.", "Facilita la instalación de los soportes de metal.", "Evita que los pájaros entren al tubo."], respuesta_correcta:1, explicacion:"Si dejas 'valles' en el tubo, el agua se queda ahí. Con el tiempo, el agua bloquea el paso del aire, el sensor de presión se abre y el horno se detiene." , question: "Why does a Category IV furnace require a 1/4\" slope toward the equipment on its exhaust piping?", options: ["So that the flue gas exits faster.", "To ensure that corrosive condensate does not accumulate in the elbows and returns to the furnace drain trap for proper disposal.", "It makes installing the metal hangers easier.", "It prevents birds from entering the pipe."], explanation: "If you leave low spots in the pipe, water collects there. Over time, the water blocks airflow, the pressure switch opens, and the furnace shuts down." },
  { id:"calef_233", categoria:"CALEF_HORNOS", pregunta:"¿Qué ocurre si el orificio del quemador está desalineado y el chorro de gas golpea la pared lateral del quemador (impingement)?", opciones:["La llama será más potente y azul.", "Combustión incompleta, producción de hollín y Monóxido de Carbono debido al enfriamiento de la llama antes de quemarse totalmente.", "El sensor de llama durará más tiempo.", "Aumenta la eficiencia del intercambiador de calor."], respuesta_correcta:1, explicacion:"La llama debe flotar en el aire. Si toca metal frío, el fuego se 'apaga' parcialmente (se enfría), dejando carbón sin quemar y gases tóxicos." , question: "What happens if the burner orifice is misaligned and the gas stream strikes the side wall of the burner (impingement)?", options: ["The flame will be more powerful and blue.", "Incomplete combustion, soot production, and carbon monoxide generation due to the flame cooling before it fully burns.", "The flame sensor will last longer.", "It increases heat exchanger efficiency."], explanation: "The flame must float freely in the air. If it touches cold metal, the fire partially extinguishes (cools), leaving unburned carbon and toxic gases." },
  { id:"calef_234", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es el propósito del 'Limitador de Tiro' (Barometric Damper) en una caldera de aceite?", opciones:["Aumentar la temperatura de la llama.", "Mantener un tiro constante y estable en la cámara de combustión independientemente de los cambios de viento o presión atmosférica exterior.", "Evitar que el aceite se derrame en el suelo.", "Reducir el consumo eléctrico del motor del quemador."], respuesta_correcta:1, explicacion:"El aceite necesita un tiro muy preciso. Si el viento 'jala' mucho humo, la llama se vuelve inestable. El damper se abre para 'dejar entrar aire' y calmar el jalón de la chimenea." , question: "What is the purpose of the Barometric Damper on an oil-fired boiler?", options: ["To increase the flame temperature.", "To maintain a constant and stable draft in the combustion chamber regardless of changes in wind or outdoor atmospheric pressure.", "To prevent oil from spilling on the floor.", "To reduce the electrical consumption of the burner motor."], explanation: "Oil requires a very precise draft. If the wind pulls too much flue gas, the flame becomes unstable. The damper opens to let room air in and calm the chimney pull." },
  { id:"calef_235", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama azul que se vuelve amarilla solo cuando el soplador principal se enciende?", opciones:["Que el soplador está enfriando demasiado la llama.", "Intercambiador de calor agrietado: el aire del soplador está entrando a la cámara de combustión y alterando la mezcla aire/gas. ¡Falla de seguridad crítica!", "Es una reacción normal de la ionización.", "El filtro de aire está demasiado limpio."], respuesta_correcta:1, explicacion:"Es la prueba definitiva de un horno roto. Si el aire de la casa 'sopla' el fuego, el humo del fuego entrará a la casa. Hay que apagar el equipo y condenarlo de inmediato." , question: "What does a blue flame that turns yellow only when the main blower turns on indicate?", options: ["The blower is cooling the flame too much.", "A cracked heat exchanger: supply air from the blower is entering the combustion chamber and altering the air/gas mixture. Critical safety failure!", "It is a normal ionization reaction.", "The air filter is too clean."], explanation: "This is the definitive test of a failed furnace. If household air is blowing on the fire, combustion gases will enter the living space. Shut the equipment down and condemn it immediately." },
  { id:"calef_236", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un terminal de venteo de PVC no debe ubicarse debajo de una ventana que se pueda abrir?", opciones:["Porque el ruido molestaría a los ocupantes.", "Riesgo de que el Monóxido de Carbono (CO) entre a la vivienda a través de la ventana abierta, causando intoxicación o muerte.", "El calor del gas podría derretir el marco de la ventana.", "La humedad del escape empañaría el vidrio constantemente."], respuesta_correcta:1, explicacion:"Seguridad básica de códigos. El humo del horno es veneno invisible. Nunca debe haber una entrada a la casa cerca de donde sale el escape del equipo." , question: "Why must a PVC vent terminal not be located beneath a window that can be opened?", options: ["Because the noise would disturb the occupants.", "Risk of carbon monoxide (CO) entering the dwelling through the open window, causing poisoning or death.", "The heat from the exhaust gas could melt the window frame.", "The moisture from the exhaust would fog the glass constantly."], explanation: "This is a basic code safety requirement. Furnace exhaust is an invisible poison. There must never be a building opening near the equipment exhaust termination." },
  { id:"calef_237", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es el propósito del 'Relé de Límite Auxiliar' en hornos de flujo descendente?", opciones:["Encender una luz de emergencia.", "Protección adicional contra incendios en caso de que el soplador falle, ya que el calor en estas unidades tiende a subir hacia los componentes de control.", "Aumentar el amperaje del ignitor.", "Controlar la humedad del gabinete."], respuesta_correcta:1, explicacion:"En un horno donde el aire va hacia abajo, si el motor para, el calor sube por instinto natural. El límite auxiliar evita que ese calor queme los cables y la placa electrónica." , question: "What is the purpose of the Auxiliary Limit Relay in downflow furnaces?", options: ["To turn on an emergency light.", "Additional fire protection in case the blower fails, since heat in these units tends to rise toward the control components.", "To increase the igniter amperage.", "To control cabinet humidity."], explanation: "In a downflow furnace, if the motor stops, heat naturally rises. The auxiliary limit prevents that heat from burning the wiring and the electronic control board." },
  { id:"calef_238", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama que es 'perezosa' y amarilla, y que tiende a salir de los quemadores (wavering)?", opciones:["Que el gas natural es muy rico en metano.", "Falta severa de tiro de la chimenea o un intercambiador de calor bloqueado; el humo no tiene a dónde ir y 'ahoga' el fuego.", "Es el efecto visual de un quemador de alta tecnología.", "Indica que el sensor de llama está mal posicionado."], respuesta_correcta:1, explicacion:"El fuego necesita moverse. Si se queda estancado y amarillo, es porque el humo le está quitando el lugar al oxígeno. Es una situación muy peligrosa que produce CO rápidamente." , question: "What does a lazy, yellow flame that tends to waver out of the burners indicate?", options: ["The natural gas is very rich in methane.", "Severe lack of chimney draft or a blocked heat exchanger; the flue gases have nowhere to go and are smothering the fire.", "It is the visual effect of a high-tech burner.", "It indicates the flame sensor is incorrectly positioned."], explanation: "Fire needs to move. If it stays stagnant and yellow, it means the flue gases are displacing the oxygen. This is a very dangerous situation that produces CO rapidly." },
  { id:"calef_239", categoria:"CALEF_HORNOS", pregunta:"Un horno de condensación falla con código de 'Pressure Switch' solo cuando hace mucho viento afuera. ¿Qué accesorio de venteo falta?", opciones:["Un motor inductor más potente.", "Una 'Tee de Venteo' o un terminal concéntrico diseñado para equilibrar las presiones de entrada y salida (wind baffle).", "Un sensor de CO2 en la chimenea.", "Aislamiento térmico en el tubo de PVC de 2 pulgadas."], respuesta_correcta:1, explicacion:"El viento puede crear presión positiva en el escape o negativa en la entrada. Si no están equilibrados, el interruptor de presión 'baila' y apaga el horno por seguridad." , question: "A condensing furnace fails with a Pressure Switch code only when it is very windy outside. What venting accessory is missing?", options: ["A more powerful inducer motor.", "A vent tee or concentric terminal designed to balance intake and exhaust pressures (wind baffle).", "A CO2 sensor in the chimney.", "Thermal insulation on the 2-inch PVC pipe."], explanation: "Wind can create positive pressure at the exhaust or negative pressure at the intake. If they are not balanced, the pressure switch fluctuates and shuts the furnace down for safety." },
  { id:"calef_240", categoria:"CALEF_HORNOS", pregunta:"Usted encuentra condensación (agua) dentro del intercambiador PRIMARIO de un horno de 80% de eficiencia. ¿Cuál es la causa?", opciones:["El horno es demasiado eficiente.", "El aire de retorno está demasiado frío (por debajo de 15°C) o el flujo de aire es excesivo, enfriando los gases por debajo de su punto de rocío.", "La válvula de gas tiene poca presión.", "El filtro de aire está tapado."], respuesta_correcta:1, explicacion:"Es un error grave. El agua en un intercambiador de acero aluminizado lo oxidará en meses. Suele pasar en casas que se dejan enfriar mucho y luego se prende el horno a tope." , question: "You find condensation (water) inside the PRIMARY heat exchanger of an 80% efficiency furnace. What is the cause?", options: ["The furnace is too efficient.", "The return air is too cold (below 59 degrees F) or the airflow is excessive, cooling the flue gases below their dew point.", "The gas valve has low pressure.", "The air filter is clogged."], explanation: "This is a serious error. Water in an aluminized steel heat exchanger will corrode it within months. It usually happens in homes that are allowed to get very cold and then the furnace is run at full capacity." },
  { id:"calef_241", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Purga de Gas' (Gas Bleeding) en un sistema de encendido por piloto?", opciones:["Limpiar la tubería de aire antes de que el gas llegue al piloto.", "Permitir que el exceso de presión de la válvula se escape de forma segura.", "No existe tal término en los manuales de HVAC modernos.", "Es un método para medir la densidad del gas natural."], respuesta_correcta:0, explicacion:"Cuando instalas un horno nuevo, los tubos están llenos de aire. Hay que 'purgar' ese aire para que el gas llegue al piloto, si no, la chispa nunca encenderá nada." , question: "What is the function of Gas Bleeding (purging) in a standing pilot ignition system?", options: ["To clear the air from the gas line before the gas reaches the pilot.", "To allow excess valve pressure to escape safely.", "No such term exists in modern HVAC manuals.", "It is a method for measuring natural gas density."], explanation: "When you install a new furnace, the gas lines are full of air. You must purge that air so the gas can reach the pilot; otherwise, the spark will never ignite anything." },
  { id:"calef_242", categoria:"CALEF_HORNOS", pregunta:"En un horno de condensación, ¿cuál es el síntoma de un intercambiador de calor secundario obstruido por suciedad?", opciones:["Llama azul muy brillante y estable.", "Tripeo del interruptor de límite alto y presencia de agua (condensado) que no drena, causando que el interruptor de presión se abra.", "El motor del soplador consume menos amperaje.", "El gas natural sale por el tubo de entrada de aire."], respuesta_correcta:1, explicacion:"El intercambiador secundario tiene pasajes muy estrechos. Si se tapa, el aire no pasa (calor) y el agua se queda atrapada (presión), deteniendo el equipo por dos vías de seguridad." , question: "In a condensing furnace, what is the symptom of a secondary heat exchanger clogged with dirt?", options: ["A very bright and stable blue flame.", "High limit switch tripping and condensate that fails to drain, causing the pressure switch to open.", "The blower motor draws less amperage.", "Natural gas exits through the air intake pipe."], explanation: "The secondary heat exchanger has very narrow passages. If it clogs, air cannot pass (heat) and water gets trapped (pressure), shutting the equipment down through two safety paths." },
  { id:"calef_243", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Escudo Térmico' (Heat Shield) en el motor del inductor de tiro?", opciones:["Aumentar la eficiencia del motor mediante calor inducido.", "Proteger los rodamientos y el devanado del motor del calor extremo de los gases de escape que pasan por la carcasa del soplador.", "Evitar que el técnico se queme al tocar el motor.", "Reflejar los rayos UV de la llama hacia el sensor."], respuesta_correcta:1, explicacion:"El motor inductor maneja humo a 200°C. Sin ese pequeño disco de metal que refleja el calor, el motor se derretiría internamente en pocas horas." , question: "What is the function of the Heat Shield on the inducer motor?", options: ["To increase motor efficiency through induced heat.", "To protect the bearings and windings from the extreme heat of the exhaust gases passing through the blower housing.", "To prevent the technician from getting burned when touching the motor.", "To reflect UV rays from the flame toward the sensor."], explanation: "The inducer motor handles flue gases at approximately 400 degrees F. Without that small metal disc that reflects heat, the motor would melt internally within a few hours." },
  { id:"calef_244", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama azul con 'destellos rojos' constantes en un horno de gas propano?", opciones:["Fuga masiva de monóxido de carbono.", "Presencia de partículas de polvo o humedad en el tanque de gas; usualmente es inofensivo si la llama base es estable y azul.", "Que el gas propano está a punto de acabarse.", "El sensor de llama necesita ser reemplazado por uno de oro."], respuesta_correcta:1, explicacion:"El propano suele tener más impurezas que el gas natural. Los destellos rojos son pequeñas 'basuritas' quemándose. Si el sensor de llama no se queja, no hay de qué preocuparse." , question: "What does a blue flame with constant red sparkles in a propane gas furnace indicate?", options: ["A massive carbon monoxide leak.", "Dust particles or moisture present in the gas tank; usually harmless if the base flame is stable and blue.", "The propane gas is about to run out.", "The flame sensor needs to be replaced with a gold one."], explanation: "Propane typically has more impurities than natural gas. The red sparkles are small particles burning up. If the flame sensor is not faulting, there is nothing to worry about." },
  { id:"calef_245", categoria:"CALEF_HORNOS", pregunta:"¿Qué es un 'Tiro Inverso' (Backdrafting) y por qué ocurre con mayor frecuencia en casas nuevas muy herméticas?", opciones:["Cuando el aire sale por la ventana en lugar de la chimenea.", "Cuando el aire de la casa está bajo presión negativa (por extractores de cocina o baño), lo que succiona los gases de combustión del horno hacia adentro de la vivienda.", "Un proceso de limpieza automática de la chimenea.", "Cuando el gas natural fluye hacia el medidor de la calle."], respuesta_correcta:1, explicacion:"Las casas modernas son tan selladas que si prendes el extractor de la cocina, 'chupas' aire por donde puedas, incluyendo el tubo de escape del horno. ¡Riesgo mortal de CO!" , question: "What is Backdrafting and why does it occur more frequently in tightly sealed new homes?", options: ["When air exits through the window instead of the chimney.", "When the house is under negative pressure (from kitchen or bathroom exhaust fans), which draws combustion gases from the furnace back into the dwelling.", "An automatic chimney cleaning process.", "When natural gas flows backward toward the street meter."], explanation: "Modern homes are so well sealed that if you turn on the kitchen range hood, air is pulled in from wherever possible, including the furnace exhaust pipe. This is a deadly CO hazard!" },
  { id:"calef_246", categoria:"CALEF_HORNOS", pregunta:"Usted nota que la llama del horno es azul, pero al cabo de unos minutos se vuelve amarillenta. ¿Qué está fallando?", opciones:["La válvula de gas se está calentando.", "Falta de aire de combustión en la habitación (confined space); el horno consume el oxígeno disponible y la combustión se degrada.", "El sensor de llama está mandando una señal errónea.", "El gas natural se está convirtiendo en metano líquido."], respuesta_correcta:1, explicacion:"Clásico problema en armarios cerrados. Al principio hay aire, pero el horno lo 'respira' todo. Si no hay rejillas hacia afuera, el fuego se sofoca y empieza a producir hollín y CO." , question: "You notice the furnace flame is blue, but after a few minutes it turns yellowish. What is failing?", options: ["The gas valve is heating up.", "Insufficient combustion air in the room (confined space); the furnace consumes the available oxygen and combustion degrades.", "The flame sensor is sending an erroneous signal.", "The natural gas is turning into liquid methane."], explanation: "This is a classic problem in enclosed closets. At first there is enough air, but the furnace uses it all up. Without ventilation openings to the outside, the fire suffocates and begins producing soot and CO." },
  { id:"calef_247", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica el término 'Tiro Natural' (Atmospheric Venting)?", opciones:["Que el horno no usa gas, solo aire del bosque.", "Que los gases de combustión suben por la chimenea debido únicamente a su baja densidad (calor) comparada con el aire frío, sin ayuda de ventiladores.", "Un sistema que usa el viento de las ventanas para funcionar.", "Cuando el soplador principal saca el humo por los ductos."], respuesta_correcta:1, explicacion:"Es la tecnología vieja (hornos de 70-80%). El humo flota porque está caliente. Si la chimenea está fría o tapada, el humo se queda en la casa. Muy peligroso si no hay mantenimiento." , question: "What does the term Atmospheric Venting (Natural Draft) mean?", options: ["The furnace does not use gas, only forest air.", "Combustion gases rise through the chimney solely due to their low density (heat) compared to the cooler surrounding air, without the aid of fans.", "A system that uses window wind to operate.", "When the main blower pushes flue gases through the ductwork."], explanation: "This is the older technology (70-80% furnaces). The flue gas floats because it is hot. If the chimney is cold or blocked, the flue gas stays in the house. Very dangerous without proper maintenance." },
  { id:"calef_248", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un 'Ignitor de Superficie Caliente' (HSI) es más eficiente energéticamente que un 'Piloto Estacionario'?", opciones:["Porque brilla con luz LED.", "Porque consume energía solo durante unos segundos en cada ciclo de encendido, mientras que un piloto quema gas las 24 horas del día.", "Aumenta la temperatura de la llama en un 15%.", "No requiere conexión a tierra para funcionar."], respuesta_correcta:1, explicacion:"Un piloto prendido todo el verano gasta unos $50-100 de gas al año sin calentar nada. El HSI es como una cerilla eléctrica que se apaga en cuanto cumple su misión." , question: "Why is a Hot Surface Igniter (HSI) more energy-efficient than a Standing Pilot?", options: ["Because it glows with LED light.", "Because it consumes energy only for a few seconds during each ignition cycle, while a standing pilot burns gas 24 hours a day.", "It increases flame temperature by 15%.", "It does not require a ground connection to operate."], explanation: "A pilot left burning all summer wastes roughly $50-100 in gas per year without heating anything. The HSI is like an electric match that turns off as soon as it has done its job." },
  { id:"calef_249", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama que se separa del quemador y parece que 'está flotando' (lifting flame)?", opciones:["Que el gas es de muy buena calidad.", "Velocidad del gas demasiado alta o exceso de presión en el manifold, superando la velocidad de ignición de la mezcla. ¡Riesgo de falla de encendido!", "El sensor de llama está perfectamente calibrado.", "Indica que el horno está funcionando en modo de alta eficiencia."], respuesta_correcta:1, explicacion:"Si el gas sale más rápido de lo que el fuego puede quemarlo, la llama 'vuela'. Es peligroso porque si se separa mucho, el sensor de llama corta el gas y el cliente se queda sin calefacción." , question: "What does a flame that lifts off the burner and appears to be floating indicate?", options: ["The gas is of very good quality.", "Excessive gas velocity or overpressure at the manifold, exceeding the ignition speed of the mixture. Risk of ignition failure!", "The flame sensor is perfectly calibrated.", "It indicates the furnace is operating in high-efficiency mode."], explanation: "If the gas exits faster than the fire can burn it, the flame lifts off. This is dangerous because if it separates too far, the flame sensor cuts the gas and the customer loses heating." },
  { id:"calef_250", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un terminal de escape de PVC debe tener una malla o rejilla de protección?", opciones:["Para que el gas salga con más presión.", "Evitar que pájaros, ardillas o escombros entren al tubo y bloqueen el flujo de aire, lo que causaría una falla de seguridad en el horno.", "Mejora la estética del exterior de la casa.", "Ayuda a condensar el vapor de agua más rápido."], respuesta_correcta:1, explicacion:"En otoño, las ardillas buscan lugares calientes. El tubo de escape es perfecto para ellas. Un nido ahí dentro significa una llamada de servicio el primer día de frío." , question: "Why must a PVC exhaust terminal have a screen or protective guard?", options: ["So the gas exits with more pressure.", "To prevent birds, squirrels, or debris from entering the pipe and blocking airflow, which would cause a safety failure in the furnace.", "It improves the aesthetics of the home exterior.", "It helps condense water vapor faster."], explanation: "In autumn, squirrels look for warm places. The exhaust pipe is perfect for them. A nest inside means a service call on the first cold day." },
  { id:"calef_251", categoria:"CALEF_HORNOS", pregunta:"¿Qué ocurre si se usa un orificio de Gas Natural con Gas Propano (LP)?", opciones:["El horno funcionará con una llama azul muy eficiente.", "La llama será masiva y peligrosa (overfiring), produciendo hollín, CO y posiblemente derritiendo el intercambiador de calor en minutos.", "El horno no encenderá porque el propano es más pesado.", "Se triplicará el tiempo de vida del ignitor."], respuesta_correcta:1, explicacion:"Peligro total. El orificio de gas natural es muy grande para el propano (que tiene más energía). Es como tratar de apagar un cigarrillo con una manguera de bomberos." , question: "What happens if a Natural Gas orifice is used with Propane (LP) gas?", options: ["The furnace will operate with a very efficient blue flame.", "The flame will be massive and dangerous (overfiring), producing soot, CO, and possibly melting the heat exchanger within minutes.", "The furnace will not ignite because propane is heavier.", "It will triple the igniter lifespan."], explanation: "Total danger. The natural gas orifice is far too large for propane (which has higher energy content). It is like trying to put out a cigarette with a fire hose." },
  { id:"calef_252", categoria:"CALEF_HORNOS", pregunta:"¿Qué es una 'Chimenea Compartida' y cuál es la regla técnica para conectar un horno y un calentador de agua?", opciones:["Cualquier tubo sirve si es de metal.", "El equipo más pequeño (calentador) debe conectarse por encima del equipo más grande (horno) en el conector vertical para asegurar un tiro correcto de ambos.", "No se pueden compartir chimeneas bajo ningún concepto.", "Deben conectarse exactamente al mismo nivel mediante una cruz de metal."], respuesta_correcta:1, explicacion:"Regla de oro de plomería y HVAC. Si el pequeño entra por debajo, el humo del grande lo 'bloqueará' y el calentador de agua empezará a tirar CO dentro de la casa." , question: "What is a Shared Chimney and what is the technical rule for connecting a furnace and a water heater?", options: ["Any metal pipe will work.", "The smaller appliance (water heater) must connect above the larger appliance (furnace) on the vertical connector to ensure proper draft for both.", "Chimney sharing is not permitted under any circumstance.", "They must be connected at exactly the same level using a metal cross fitting."], explanation: "This is a golden rule of plumbing and HVAC. If the smaller appliance enters below, the flue gases from the larger one will block it, and the water heater will begin spilling CO into the house." },
  { id:"calef_253", categoria:"CALEF_HORNOS", pregunta:"¿Qué sucede si el sensor de llama está demasiado lejos del quemador?", opciones:["La llama durará más tiempo encendida.", "El horno se apagará a los pocos segundos (falla de detección) porque el sensor no 'siente' el flujo de electrones de la llama de forma estable.", "El ignitor se calentará hasta derretirse.", "La válvula de gas abrirá con el doble de presión."], respuesta_correcta:1, explicacion:"El sensor debe estar 'bañado' en fuego. Si solo lo toca la punta o está lejos, la señal es débil y la placa, por seguridad, corta el gas creyendo que el fuego se apagó." , question: "What happens if the flame sensor is positioned too far from the burner?", options: ["The flame will stay on longer.", "The furnace will shut off within a few seconds (detection failure) because the sensor cannot consistently detect the electron flow from the flame.", "The igniter will overheat until it melts.", "The gas valve will open at double pressure."], explanation: "The sensor must be immersed in the flame. If only the tip touches it or it is too far away, the signal is weak and the control board, for safety, shuts off the gas, thinking the flame went out." },
  { id:"calef_254", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la temperatura máxima de operación recomendada para un venteo de PVC Cédula 40 en un horno de alta eficiencia?", opciones:["212°F (100°C).", "140°F (60°C); por encima de esto el PVC comienza a ablandarse y puede perder su integridad estructural.", "500°F (260°C) si se usa pegamento transparente.", "No hay límite mientras el motor inductor funcione."], respuesta_correcta:1, explicacion:"El PVC tiene límites térmicos bajos. Por eso solo se usa en hornos que 'roban' tanto calor que el humo sale casi tibio. Si el horno falla y el humo sale caliente, el tubo se dobla." , question: "What is the maximum recommended operating temperature for Schedule 40 PVC venting on a high-efficiency furnace?", options: ["212 degrees F (100 degrees C).", "140 degrees F (60 degrees C); above this the PVC begins to soften and can lose its structural integrity.", "500 degrees F (260 degrees C) if clear cement is used.", "There is no limit as long as the inducer motor is running."], explanation: "PVC has low thermal limits. That is why it is only used on furnaces that extract so much heat that the exhaust exits nearly lukewarm. If the furnace fails and the exhaust exits hot, the pipe will sag." },
  { id:"calef_255", categoria:"CALEF_HORNOS", pregunta:"Un horno realiza 3 intentos de ignición y se bloquea (Lockout). Usted nota que el ignitor brilla pero no hay llama. ¿Qué terminal de la válvula de gas debería medir primero?", opciones:["El terminal MV (Main Valve) para verificar si la placa está enviando los 24V necesarios durante la ventana de ignición.", "El terminal PV (Pilot Valve) aunque sea un sistema de ignición directa.", "La conexión a tierra del termostato.", "El sensor de temperatura de aire de retorno."], respuesta_correcta:0, explicacion:"Si brilla el ignitor, la placa funciona. Si no hay fuego, hay que ver si la placa le 'dice' a la válvula que se abra. Si hay 24V y no abre, la válvula está trabada o no hay gas." , question: "A furnace makes 3 ignition attempts and locks out. You notice the igniter glows but there is no flame. Which gas valve terminal should you check first?", options: ["The MV (Main Valve) terminal to verify whether the control board is sending the required 24V during the ignition window.", "The PV (Pilot Valve) terminal even though it is a direct ignition system.", "The thermostat ground connection.", "The return air temperature sensor."], explanation: "If the igniter glows, the board is working. If there is no fire, you need to check whether the board is telling the valve to open. If 24V is present and the valve does not open, it is stuck or there is no gas." },
  { id:"calef_256", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Filtro de Ruido' (EMI Filter) en la placa de control de un horno de alta ingeniería?", opciones:["Limpiar el aire de los ductos.", "Prevenir que las interferencias de la red eléctrica afecten los microprocesadores y asegurar que la señal de microamperios de la llama sea pura.", "Reducir el sonido del soplador hacia el interior de la casa.", "Aumentar el brillo del ignitor de superficie caliente."], respuesta_correcta:1, explicacion:"La electrónica moderna es sensible. Un motor viejo en la misma red puede 'ensuciar' la luz y causar que el horno se apague solo. El filtro limpia esa 'basura' eléctrica." , question: "What is the function of the EMI Filter (Noise Filter) on a high-end furnace control board?", options: ["To clean the air in the ductwork.", "To prevent electrical line interference from affecting the microprocessors and ensure that the microamp flame signal remains clean.", "To reduce blower noise inside the house.", "To increase the brightness of the hot surface igniter."], explanation: "Modern electronics are sensitive. An old motor on the same electrical circuit can introduce noise that causes the furnace to shut off on its own. The filter cleans that electrical interference." },
  { id:"calef_257", categoria:"CALEF_HORNOS", pregunta:"¿Qué es la 'Condensación Prematura' en una chimenea de metal de un horno de 80%?", opciones:["Cuando el agua se forma antes de que el horno encienda.", "El enfriamiento de los gases de combustión antes de salir de la chimenea, provocando que el agua ácida oxide el metal y apague el quemador.", "Un proceso que mejora la eficiencia del tiro natural.", "La acumulación de nieve en la punta de la chimenea."], respuesta_correcta:1, explicacion:"Humo frío = lluvia ácida interna. Si el tubo de la chimenea es muy largo o pasa por lugares fríos sin aislamiento, se pudre por dentro en un par de años." , question: "What is Premature Condensation in a metal chimney on an 80% furnace?", options: ["When water forms before the furnace fires.", "The cooling of combustion gases before they exit the chimney, causing acidic water to corrode the metal and extinguish the burner.", "A process that improves natural draft efficiency.", "The accumulation of snow at the chimney cap."], explanation: "Cold flue gas equals internal acid rain. If the chimney flue is too long or passes through cold areas without insulation, it rots from the inside within a couple of years." },
  { id:"calef_258", categoria:"CALEF_HORNOS", pregunta:"Un interruptor de 'Límite de Roll-out' se abre. Usted encuentra que el intercambiador de calor está limpio y el tiro es bueno. ¿Qué otra cosa revisaría?", opciones:["La presión del gas en el manifold, que podría ser excesiva (overfiring) causando que la llama sea más larga de lo diseñado.", "El color del filtro de aire del retorno.", "El voltaje del termostato Wi-Fi.", "La velocidad del soplador principal."], respuesta_correcta:0, explicacion:"Si metes demasiado gas, la llama 'crece'. Si crece demasiado, sale de la caja del intercambiador y calienta el sensor de roll-out, apagando el horno por riesgo de incendio." , question: "A Flame Roll-out Limit switch opens. You find the heat exchanger is clean and the draft is good. What else would you check?", options: ["The manifold gas pressure, which may be excessive (overfiring), causing the flame to be longer than designed.", "The color of the return air filter.", "The voltage of the Wi-Fi thermostat.", "The speed of the main blower."], explanation: "If you feed too much gas, the flame grows. If it grows too much, it escapes the heat exchanger enclosure and heats the roll-out sensor, shutting down the furnace due to fire risk." },
  { id:"calef_259", categoria:"CALEF_HORNOS", pregunta:"¿Qué es un 'Tiro Mecánico' (Power Vent) y en qué se diferencia de un horno de alta eficiencia?", opciones:["Usa un motor para sacar el humo, pero los gases siguen calientes y requieren chimenea metálica; no condensa agua.", "Es lo mismo que un horno de 95% AFUE.", "Funciona con baterías en caso de apagón.", "No requiere aire de combustión de la habitación."], respuesta_correcta:0, explicacion:"El Power Vent solo ayuda a empujar el humo. Como el humo sigue caliente, no puedes usar PVC. Es un paso intermedio entre la tecnología vieja y la nueva." , question: "What is Power Venting (Mechanical Draft) and how does it differ from a high-efficiency furnace?", options: ["It uses a motor to push the flue gas out, but the gases remain hot and require a metal chimney; it does not condense water.", "It is the same as a 95% AFUE furnace.", "It runs on batteries during a power outage.", "It does not require combustion air from the room."], explanation: "A power vent only helps push the flue gas out. Since the gas is still hot, you cannot use PVC. It is an intermediate step between old and new technology." },
  { id:"calef_260", categoria:"CALEF_HORNOS", pregunta:"Usted nota que la llama del horno es azul con una base naranja. El cliente acaba de remodelar y lijar pisos de madera. ¿Cuál es el diagnóstico?", opciones:["El horno tiene una fuga de gas metano.", "El polvo de madera fino en el aire está siendo aspirado por los quemadores y se quema en la llama; es temporal y no peligroso.", "El sensor de llama se está derritiendo.", "La válvula de gas está contaminada con aserrín."], respuesta_correcta:1, explicacion:"Cualquier cosa en el aire (polvo, laca, perfume) cambia el color del fuego. Una vez que el aire se limpie, la llama volverá a ser azul total." , question: "You notice the furnace flame is blue with an orange base. The customer has just remodeled and sanded hardwood floors. What is the diagnosis?", options: ["The furnace has a methane gas leak.", "Fine wood dust in the air is being drawn into the burners and burning in the flame; it is temporary and not dangerous.", "The flame sensor is melting.", "The gas valve is contaminated with sawdust."], explanation: "Anything in the air (dust, lacquer, perfume) changes the color of the fire. Once the air clears, the flame will return to full blue." },
  { id:"calef_261", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Fusible Térmico' en la placa de control de un horno?", opciones:["Proteger contra rayos y picos de voltaje.", "Prevenir un incendio en la placa de circuito impreso si un componente electrónico (como un relé) entra en cortocircuito masivo.", "Medir la temperatura del cuarto de máquinas.", "Asegurar que el ignitor no se enfríe demasiado rápido."], respuesta_correcta:1, explicacion:"Es el último recurso. Si la placa se vuelve loca y empieza a quemarse, el fusible corta todo antes de que el horno se convierta en una bola de fuego." , question: "What is the function of the Thermal Fuse on a furnace control board?", options: ["To protect against lightning and voltage spikes.", "To prevent a fire on the printed circuit board if an electronic component (such as a relay) goes into a massive short circuit.", "To measure the temperature of the mechanical room.", "To ensure the igniter does not cool down too quickly."], explanation: "It is the last resort. If the board malfunctions and starts burning, the fuse cuts everything before the furnace becomes a fireball." },
  { id:"calef_262", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica el término 'Tiro Forzado' (Forced Draft) y en qué se diferencia del tiro inducido?", opciones:["El ventilador está al final de la chimenea succionando.", "El ventilador está al principio del sistema 'empujando' el aire hacia los quemadores bajo presión positiva.", "No usa ventiladores, solo el calor de la llama.", "El aire de la casa se usa para enfriar los gases de escape."], respuesta_correcta:1, explicacion:"Forzado = Empujar. Inducido = Succionar. La mayoría de los hornos de casa son inducidos. El tiro forzado se ve más en calderas industriales grandes." , question: "What does the term Forced Draft mean and how does it differ from Induced Draft?", options: ["The fan is at the end of the chimney pulling air.", "The fan is at the beginning of the system pushing air into the burners under positive pressure.", "It uses no fans, only the heat of the flame.", "Household air is used to cool the exhaust gases."], explanation: "Forced means pushing. Induced means pulling. Most residential furnaces use induced draft. Forced draft is more common in large industrial boilers." },
  { id:"calef_263", categoria:"CALEF_HORNOS", pregunta:"Usted encuentra que la llama del horno es azul pero con 'chispas' blancas brillantes. ¿Qué indica?", opciones:["Fuga de monóxido de carbono inmediata.", "Polvo de aluminio o metal quemándose, o presencia de químicos de limpieza en el aire; puede ser corrosivo a largo plazo.", "Que el gas natural tiene un exceso de oxígeno puro.", "Es el color normal de un ignitor de nitruro de silicio."], respuesta_correcta:1, explicacion:"El blanco brillante suele ser metal o químicos. Si el cliente estuvo lijando ductos o limpiando con solventes fuertes cerca del horno, verás esos fuegos artificiales minúsculos." , question: "You find that the furnace flame is blue but has bright white sparks. What does this indicate?", options: ["An immediate carbon monoxide leak.", "Aluminum or metal dust burning, or the presence of cleaning chemicals in the air; it can be corrosive over the long term.", "The natural gas has an excess of pure oxygen.", "It is the normal color of a silicon nitride igniter."], explanation: "Bright white usually means metal or chemicals. If the customer has been sanding ductwork or cleaning with strong solvents near the furnace, you will see those tiny fireworks." },
  { id:"calef_264", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Interruptor de Puerta del Soplador'?", opciones:["Ahorrar energía apagando la luz del horno.", "Seguridad: corta toda la energía de 120V si se retira el panel frontal, evitando que el ventilador atrape los dedos del técnico o succione gases de combustión.", "Asegurar que la puerta esté bien cerrada para no perder presión.", "Reiniciar la placa de control automáticamente cada vez que se abre."], respuesta_correcta:1, explicacion:"Es para protegerte. Si quitas la tapa, el horno se muere. Evita accidentes con las aspas y, lo más importante, evita que el ventilador 'chupe' humo del quemador hacia la casa." , question: "What is the function of the Blower Door Safety Switch?", options: ["To save energy by turning off the furnace light.", "Safety: it cuts all 120V power when the front panel is removed, preventing the fan from catching the technician's fingers or drawing combustion gases into the supply air.", "To ensure the door is tightly sealed to avoid pressure loss.", "To automatically reset the control board every time the panel is opened."], explanation: "It is there to protect you. If you remove the cover, the furnace goes dead. It prevents blade injuries and, most importantly, prevents the blower from pulling burner flue gas into the house." },
  { id:"calef_265", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica el término 'Categoría I' en un horno de gas?", opciones:["Equipo de alta eficiencia con condensación de agua.", "Aparato de tiro natural que opera con presión negativa en el venteo y una temperatura de gases lo suficientemente alta para evitar la condensación interna.", "Un horno que solo puede instalarse en el exterior.", "Sistemas que usan electricidad como fuente primaria de calor."], respuesta_correcta:1, explicacion:"Es el horno 'normal' de los últimos 40 años. El humo sale caliente y sube solo por la chimenea. No usa tubos de plástico porque el calor los derretiría." , question: "What does the term Category I mean for a gas furnace?", options: ["A high-efficiency appliance with water condensation.", "A natural draft appliance that operates under negative pressure in the vent and a flue gas temperature high enough to prevent internal condensation.", "A furnace that can only be installed outdoors.", "Systems that use electricity as the primary heat source."], explanation: "This is the standard furnace of the last 40 years. The flue gas exits hot and rises on its own through the chimney. It cannot use plastic vent pipe because the heat would melt it." },
  { id:"calef_266", categoria:"CALEF_HORNOS", pregunta:"Usted encuentra una llama que 'baila' mucho y se apaga aleatoriamente. El motor inductor suena irregular. ¿Qué revisaría?", opciones:["La placa de control completa.", "El rodamiento del motor inductor o posibles obstrucciones en el tubo de venteo que causan un flujo de aire de combustión inestable.", "El color de las baterías del termostato.", "La presión del gas en el tanque exterior."], respuesta_correcta:1, explicacion:"Si el aire que 'jala' el humo es inestable, la llama será inestable. Es como tratar de mantener una vela encendida frente a un ventilador que falla; se apagará." , question: "You find a flame that dances significantly and shuts off randomly. The inducer motor sounds irregular. What would you check?", options: ["The entire control board.", "The inducer motor bearing or possible obstructions in the vent pipe causing unstable combustion airflow.", "The color of the thermostat batteries.", "The gas pressure in the outdoor tank."], explanation: "If the air pulling the flue gas is unstable, the flame will be unstable. It is like trying to keep a candle lit in front of a failing fan; it will blow out." },
  { id:"calef_267", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Interruptor de Límite de Temperatura de Retorno'?", opciones:["Asegurar que el aire de la casa esté a 22°C.", "Seguridad: apaga el horno si el aire que entra al equipo está demasiado caliente (ej. > 35°C), evitando que el intercambiador se sobrecaliente de inmediato.", "Cambiar la velocidad del soplador automáticamente.", "Medir la humedad del aire que viene de las habitaciones."], respuesta_correcta:1, explicacion:"Es un guardaespaldas extra. Si por alguna razón el aire de la casa ya viene muy caliente, el horno no puede añadirle más calor sin riesgo de derretirse." , question: "What is the function of the Return Air Temperature Limit Switch?", options: ["To ensure the room air is at 72 degrees F.", "Safety: it shuts the furnace off if the incoming air is too hot (e.g., above 95 degrees F), preventing the heat exchanger from overheating immediately.", "To automatically change the blower speed.", "To measure the humidity of the air coming from the rooms."], explanation: "It is an extra bodyguard. If for some reason the household air coming in is already very hot, the furnace cannot add more heat without risk of meltdown." },
  { id:"calef_268", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama que 'brinca' y se separa del quemador haciendo un sonido de 'pop-pop'?", opciones:["Que el gas natural tiene mucha presión.", "Mezcla de aire-gas inestable o quemadores sucios/oxidados que no permiten una velocidad de llama constante; riesgo de explosión pequeña.", "Es el sonido normal del modo de alta eficiencia.", "Indica que el sensor de llama está perfectamente limpio."], respuesta_correcta:1, explicacion:"Esos 'pops' son mini-explosiones. La llama se apaga y se vuelve a prender mil veces por segundo. Indica que el quemador necesita una limpieza profunda con cepillo de alambre." , question: "What does a flame that bounces and separates from the burner making a pop-pop sound indicate?", options: ["The natural gas has too much pressure.", "Unstable air-gas mixture or dirty/rusted burners that do not allow a constant flame speed; risk of small explosions.", "It is the normal sound of high-efficiency mode.", "It indicates the flame sensor is perfectly clean."], explanation: "Those pops are mini-explosions. The flame extinguishes and re-ignites thousands of times per second. It indicates the burner needs a thorough cleaning with a wire brush." },
  { id:"calef_269", categoria:"CALEF_HORNOS", pregunta:"Un horno de gas de alta eficiencia muestra un código de 'Falla de Llama' intermitente. El técnico nota que la trampa de condensado está parcialmente llena de sedimentos. ¿Cuál es el vínculo técnico?", opciones:["El sedimento actúa como un aislante eléctrico para el sensor de llama.", "El agua acumulada bloquea el flujo de gases de combustión o altera la presión en el quemador, causando una llama inestable que el sensor no puede leer consistentemente.", "El condensado sucio aumenta la resistencia del ignitor HSI.", "No hay vínculo; son sistemas totalmente independientes."], respuesta_correcta:1, explicacion:"Si el agua no sale, el humo no sale bien. Una llama que 'escupe' o fluctúa por falta de tiro no permite una rectificación de corriente estable hacia la placa de control." , question: "A high-efficiency gas furnace shows an intermittent Flame Failure code. The technician notices the condensate trap is partially filled with sediment. What is the technical connection?", options: ["The sediment acts as an electrical insulator for the flame sensor.", "Accumulated water blocks the combustion gas flow or alters pressure at the burner, causing an unstable flame that the sensor cannot read consistently.", "Dirty condensate increases the resistance of the HSI igniter.", "There is no connection; they are completely independent systems."], explanation: "If the water cannot drain, the flue gas cannot flow properly. A flame that sputters or fluctuates due to lack of draft does not allow a stable flame rectification signal back to the control board." },
  { id:"calef_270", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Restrictor de Orificio' en una válvula de gas de modulación infinitamente variable?", opciones:["Apagar el gas si la presión es muy alta.", "Permitir un control preciso del flujo de combustible en incrementos del 1% mediante un motor de pasos que ajusta el área efectiva de paso de gas.", "Mezclar el gas con nitrógeno para enfriar la llama.", "Actuar como un sensor de temperatura de respaldo."], respuesta_correcta:1, explicacion:"A diferencia de las válvulas de 1 o 2 etapas, la modulante es como un grifo electrónico que se abre exactamente lo que el termostato pide para mantener la casa a la misma temperatura." , question: "What is the function of the Metering Orifice in an infinitely variable modulating gas valve?", options: ["To shut off the gas if the pressure is too high.", "To allow precise fuel flow control in 1% increments using a stepper motor that adjusts the effective gas passage area.", "To mix the gas with nitrogen to cool the flame.", "To act as a backup temperature sensor."], explanation: "Unlike single- or two-stage valves, the modulating valve is like an electronic faucet that opens exactly the amount the thermostat requests to maintain a constant room temperature." },
  { id:"calef_271", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un horno de Categoría I no puede conectarse a un sistema de venteo compartido con un extractor de grasa de cocina industrial?", opciones:["Porque el humo del horno huele a comida.", "Riesgo de que la grasa acumulada se incendie con el calor de los gases de escape o que la presión del extractor cause un retroceso de Monóxido de Carbono.", "El código solo lo permite si el tubo es de acero quirúrgico.", "La grasa de cocina actúa como aislante y apaga el piloto del horno."], respuesta_correcta:1, explicacion:"Nunca mezcles escapes. El extractor de cocina empuja aire; si el horno es de tiro natural, el extractor empujará el humo del horno de regreso hacia adentro de la casa." , question: "Why can a Category I furnace not be connected to a shared vent system with a commercial kitchen grease exhaust?", options: ["Because the furnace exhaust smells like food.", "Risk that accumulated grease may ignite from the heat of the exhaust gases, or that the exhaust fan pressure causes carbon monoxide backdrafting.", "Code only allows it if the pipe is surgical-grade steel.", "Kitchen grease acts as an insulator and extinguishes the furnace pilot."], explanation: "Never mix exhaust systems. The kitchen exhaust pushes air; if the furnace relies on natural draft, the exhaust fan will push the furnace flue gas back into the building." },
  { id:"calef_272", categoria:"CALEF_HORNOS", pregunta:"Usted nota que las llamas del horno son azules pero 'ruidosas' (hissing sound) y tienen una base transparente muy alta. ¿Qué indica esto?", opciones:["Que el gas natural tiene un exceso de nitrógeno.", "Excesiva presión de gas en el manifold (Over-pressure) o un orificio de quemador demasiado pequeño que acelera el gas por encima de la velocidad de propagación de la llama.", "El sensor de llama está generando interferencia acústica.", "Es una señal de alta eficiencia estequiométrica."], respuesta_correcta:1, explicacion:"El gas está saliendo como un soplete. Esto estresa el metal del intercambiador y puede causar que la llama se apague sola por 'volar' lejos del quemador." , question: "You notice the furnace flames are blue but noisy (hissing sound) with a very tall transparent inner cone. What does this indicate?", options: ["The natural gas has an excess of nitrogen.", "Excessive manifold gas pressure (over-pressure) or a burner orifice that is too small, accelerating the gas above the flame propagation speed.", "The flame sensor is generating acoustic interference.", "It is a sign of high stoichiometric efficiency."], explanation: "The gas is coming out like a torch. This stresses the heat exchanger metal and can cause the flame to blow itself out by lifting away from the burner." },
  { id:"calef_273", categoria:"CALEF_HORNOS", pregunta:"Usted encuentra condensado de color amarillento/marrón saliendo de un horno de condensación. ¿Qué sospecha?", opciones:["Que el gas natural tiene colorante añadido.", "Corrosión severa en el intercambiador de calor secundario o en el bloque colector, indicando que el metal está siendo digerido por el ácido del condensado.", "Es una acumulación normal de polvo doméstico en el drenaje.", "Presencia de una fuga de aceite en el motor inductor."], respuesta_correcta:1, explicacion:"El condensado debería ser transparente como el agua. Si sale con color a óxido, el metal del horno se está deshaciendo por dentro. ¡Hora de cambiar el equipo!" , question: "You find yellowish/brown condensate draining from a condensing furnace. What do you suspect?", options: ["The natural gas has added colorant.", "Severe corrosion in the secondary heat exchanger or the collector box, indicating the metal is being dissolved by the acidic condensate.", "It is a normal accumulation of household dust in the drain.", "An oil leak in the inducer motor."], explanation: "Condensate should be clear like water. If it comes out with a rust color, the metal inside the furnace is disintegrating. Time to replace the equipment!" },
  { id:"calef_274", categoria:"CALEF_HORNOS", pregunta:"En un sistema de ignición por chispa, el electrodo genera arco pero el gas no enciende. Usted nota que la chispa es 'débil' y de color amarillento en lugar de azul/blanco. ¿Qué sospecha?", opciones:["Falta de presión de gas natural.", "Aislante de cerámica del electrodo agrietado o sucio, permitiendo que parte de la alta tensión se escape a tierra antes de llegar a la punta.", "El cable de la chispa es demasiado corto.", "La frecuencia de la red de 60Hz es inestable."], respuesta_correcta:1, explicacion:"Una chispa amarillenta es una chispa 'fría'. No tiene suficiente energía para encender el gas. Suele pasar por humedad o suciedad en el aislante de porcelana." , question: "In a spark ignition system, the electrode arcs but the gas does not ignite. You notice the spark is weak and yellowish instead of blue/white. What do you suspect?", options: ["Insufficient natural gas pressure.", "A cracked or dirty ceramic insulator on the electrode, allowing part of the high voltage to leak to ground before reaching the tip.", "The spark cable is too short.", "The 60 Hz line frequency is unstable."], explanation: "A yellowish spark is a cold spark. It does not have enough energy to ignite the gas. It usually occurs from moisture or dirt on the porcelain insulator." },
  { id:"calef_275", categoria:"CALEF_HORNOS", pregunta:"¿Qué es la 'Fatiga Térmica' en un intercambiador de calor de tipo tubular?", opciones:["Cuando el metal se cansa de estar caliente.", "El estrés mecánico acumulado por miles de ciclos de expansión y contracción que eventualmente causa grietas microscópicas en las soldaduras o curvas del metal.", "La pérdida de magnetismo del acero inoxidable.", "El aumento del peso del intercambiador debido al hollín."], respuesta_correcta:1, explicacion:"Es como doblar un clip muchas veces. Al final se rompe. Por eso los ciclos cortos (short-cycling) matan los hornos mucho antes de su tiempo de vida normal." , question: "What is Thermal Fatigue in a tubular heat exchanger?", options: ["When the metal gets tired of being hot.", "The accumulated mechanical stress from thousands of expansion and contraction cycles that eventually causes microscopic cracks in the welds or bends of the metal.", "The loss of magnetism in stainless steel.", "The increase in heat exchanger weight due to soot buildup."], explanation: "It is like bending a paper clip back and forth. Eventually it breaks. That is why short cycling kills furnaces much earlier than their normal service life." },
  { id:"calef_276", categoria:"CALEF_HORNOS", pregunta:"Usted observa que el tubo de venteo de PVC de un horno de alta eficiencia se ha 'pandeado' o caído entre los soportes. ¿Qué riesgo técnico existe?", opciones:["Solo es un problema estético menor.", "Acumulación de condensado en la zona baja (sag), lo que restringe el flujo de gases y provocará fallas intermitentes del interruptor de presión.", "El gas natural se acumulará en el pandeo del tubo.", "Aumento del ruido del motor inductor hacia el exterior."], respuesta_correcta:1, explicacion:"El agua debe fluir. Si el tubo se cuelga, el agua se queda ahí como en el sifón de un baño. El aire no puede pasar a través del agua y el horno se bloquea." , question: "You observe that the PVC vent pipe of a high-efficiency furnace has sagged or drooped between the hangers. What technical risk exists?", options: ["It is only a minor cosmetic issue.", "Condensate accumulation in the low spot (sag), which restricts flue gas flow and will cause intermittent pressure switch failures.", "Natural gas will collect in the sag of the pipe.", "Increased inducer motor noise toward the exterior."], explanation: "Water must flow. If the pipe sags, water pools there like a plumbing trap. Air cannot pass through the water and the furnace locks out." },
  { id:"calef_277", categoria:"CALEF_HORNOS", pregunta:"¿Qué sucede si el aire secundario entra en exceso a la cámara de combustión de un horno de tiro natural?", opciones:["La llama se vuelve más potente y azul.", "Enfría excesivamente el intercambiador de calor y los gases de escape, reduciendo la eficiencia y aumentando el riesgo de condensación ácida en la chimenea.", "El sensor de llama detectará una señal de 20 microamperios.", "El gas natural se quema dos veces más rápido."], respuesta_correcta:1, explicacion:"El aire 'sobrante' es un ladrón. Se lleva el calor del fuego hacia la chimenea antes de que el horno pueda entregarlo a la casa. Queremos el aire justo, ni más ni menos." , question: "What happens if excess secondary air enters the combustion chamber of a natural draft furnace?", options: ["The flame becomes more powerful and blue.", "It excessively cools the heat exchanger and flue gases, reducing efficiency and increasing the risk of acidic condensation in the chimney.", "The flame sensor will detect a 20 microamp signal.", "The natural gas burns twice as fast."], explanation: "Excess air is a thief. It carries heat from the fire up the chimney before the furnace can deliver it to the house. You want just the right amount of air, no more, no less." },
  { id:"calef_278", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Interruptor de Límite de Temperatura de la Carcasa' en un horno eléctrico?", opciones:["Evitar que el exterior del horno queme al técnico.", "Protección contra incendios si el motor del soplador falla; evita que el gabinete metálico alcance temperaturas que puedan encender materiales adyacentes.", "Medir el voltaje de las resistencias de nicromo.", "Controlar la humedad del ático donde está instalado el equipo."], respuesta_correcta:1, explicacion:"Las resistencias eléctricas pueden ponerse al rojo vivo en segundos. Este sensor garantiza que si el aire para, la energía se corte antes de que el metal se derrita." , question: "What is the function of the Cabinet Temperature Limit Switch in an electric furnace?", options: ["To prevent the outside of the furnace from burning the technician.", "Fire protection if the blower motor fails; it prevents the metal cabinet from reaching temperatures that could ignite adjacent combustible materials.", "To measure the voltage of the nichrome heating elements.", "To control the humidity of the attic where the unit is installed."], explanation: "Electric heating elements can glow red-hot in seconds. This sensor ensures that if the airflow stops, power is cut before the metal melts." },
  { id:"calef_279", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama que es azul pero tiene un 'velo' o 'niebla' naranja que la rodea (no puntas, sino un velo)?", opciones:["Que el gas natural tiene un exceso de helio.", "Alta humedad en el aire de combustión (ej. un humidificador ultrasónico funcionando cerca del horno); el agua en el aire cambia el espectro de luz de la llama.", "Indica que el intercambiador de calor se está derritiendo.", "Presencia de una fuga de refrigerante R-410A en el ambiente."], respuesta_correcta:1, explicacion:"Capciosa: El sodio y minerales en el aire (niebla de humidificador) reaccionan con el fuego. No es una falla del horno, es solo el 'color' del aire que está respirando." , question: "What does a blue flame surrounded by an orange haze or veil (not tips, but a veil) indicate?", options: ["The natural gas has an excess of helium.", "High humidity in the combustion air (e.g., an ultrasonic humidifier running near the furnace); the water in the air changes the light spectrum of the flame.", "It indicates the heat exchanger is melting.", "The presence of an R-410A refrigerant leak in the area."], explanation: "Tricky question: Sodium and minerals in the air (humidifier mist) react with the fire. It is not a furnace malfunction; it is simply the color of the air the furnace is breathing." },
  { id:"calef_280", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Termostato de Chimenea' (Spill Switch) en un horno de tiro natural?", opciones:["Medir la temperatura del aire exterior.", "Detección de gases de escape saliendo por la campana de tiro hacia la casa debido a una chimenea bloqueada; apaga el horno por seguridad ante riesgo de CO.", "Aumentar el brillo de la llama del piloto.", "Regular la velocidad del motor inductor de tiro."], respuesta_correcta:1, explicacion:"Es un centinela de calor. Si el humo no puede subir por el tubo, sale por la campana y calienta este switch. Es tu última línea de defensa contra el Monóxido de Carbono." , question: "What is the function of the Spill Switch (Chimney Thermostat) on a natural draft furnace?", options: ["To measure outdoor air temperature.", "To detect flue gases escaping through the draft hood into the living space due to a blocked chimney; it shuts the furnace down for safety due to CO risk.", "To increase the brightness of the pilot flame.", "To regulate the speed of the inducer motor."], explanation: "It is a heat sentinel. If the flue gas cannot rise through the pipe, it escapes through the draft hood and heats this switch. It is your last line of defense against carbon monoxide." },
  { id:"calef_281", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama azul que se vuelve 'amarilla y opaca' (luminous flame) repentinamente al aumentar la presión del gas?", opciones:["Que el horno ha alcanzado su máxima eficiencia calorífica.", "Falta de aire primario para la cantidad de combustible suministrado (combustión rica), produciendo hollín y CO de forma masiva.", "Es el color normal del gas natural de alta presión.", "Indica que el sensor de llama se ha autocalibrado."], respuesta_correcta:1, explicacion:"Amarillo = Carbón sin quemar. Si subes el gas pero no subes el aire, el fuego se ensucia. Es como meterle demasiada leña a una fogata pequeña: solo vas a sacar humo negro." , question: "What does a blue flame that suddenly becomes yellow and opaque (luminous flame) when gas pressure is increased indicate?", options: ["The furnace has reached its maximum heating efficiency.", "Insufficient primary air for the amount of fuel supplied (rich combustion), producing massive amounts of soot and CO.", "It is the normal color of high-pressure natural gas.", "It indicates the flame sensor has auto-calibrated."], explanation: "Yellow means unburned carbon. If you increase the gas but do not increase the air, the fire gets dirty. It is like adding too much wood to a small campfire: you only get black smoke." },
  { id:"calef_282", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama azul estable que se 'deforma' o se inclina hacia un lado solo cuando el soplador se enciende?", opciones:["Que el aire del soplador está muy limpio.", "Fisura o grieta en el intercambiador de calor; el aire de suministro está entrando a la cámara de combustión y 'empujando' la llama. ¡Peligro de CO!", "Es un efecto normal de magnetismo térmico.", "Indica que el filtro de aire es de alta eficiencia (MERV 13)."], respuesta_correcta:1, explicacion:"Esta es la prueba reina. Si el aire de la casa 'sopla' el fuego del quemador, el humo del fuego se está mezclando con el aire que respiras. ¡Apaga ese horno ya!" , question: "What does a stable blue flame that deflects or leans to one side only when the blower turns on indicate?", options: ["The supply air from the blower is very clean.", "A crack or fracture in the heat exchanger; supply air is entering the combustion chamber and pushing the flame. CO danger!", "It is a normal effect of thermal magnetism.", "It indicates the air filter is high efficiency (MERV 13)."], explanation: "This is the ultimate test. If the household air is pushing the burner flame, the flue gas is mixing with the air you breathe. Shut that furnace down now!" },
  { id:"calef_283", categoria:"CALEF_HORNOS", pregunta:"Un horno de gas muestra un código de 'Límite de Alta Temperatura'. El técnico nota que el soplador arranca pero se apaga a los 30 segundos, mientras el quemador sigue encendido. ¿Qué falla?", opciones:["El sensor de llama está sucio.", "Falla en el relé de retardo (Fan-Off Delay) de la placa de control o un protector térmico interno del motor del soplador que se abre por calor residual.", "La presión del gas es de 3.5 pulgadas de columna de agua.", "El filtro de aire está instalado al revés."], respuesta_correcta:1, explicacion:"Si el motor se rinde antes que el fuego, el metal se pondrá al rojo vivo. La placa debe mantener el aire soplando mientras haya calor. Si el motor se corta solo, el límite de seguridad actuará de inmediato." , question: "A gas furnace shows a High Temperature Limit code. The technician notices the blower starts but shuts off after 30 seconds while the burner stays on. What is the fault?", options: ["The flame sensor is dirty.", "A failed Fan-Off Delay relay on the control board or an internal thermal protector in the blower motor that opens due to residual heat.", "The gas pressure is 3.5 inches of water column.", "The air filter is installed backwards."], explanation: "If the motor gives up before the fire does, the metal will glow red-hot. The board must keep the air blowing as long as there is heat. If the motor cuts out on its own, the high limit safety will trip immediately." },
  { id:"calef_284", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un horno de Categoría III requiere sellador de alta temperatura (RTV) en todas las uniones de su chimenea metálica?", opciones:["Para que el tubo no se mueva con el viento.", "Debido a que el venteo opera bajo presión positiva; cualquier fuga liberaría gases de combustión letales (CO) directamente dentro de la estructura del edificio.", "Aumenta la velocidad del aire por el efecto de succión magnética.", "Es una norma estética para que la chimenea se vea profesional."], respuesta_correcta:1, explicacion:"En el tiro natural, si hay un agujero, el aire de la casa entra al tubo. En Categoría III, el motor 'empuja' el humo; si hay un agujero, el humo sale a la casa. El sellado es una cuestión de vida o muerte." , question: "Why does a Category III furnace require high-temperature sealant (RTV) on all joints of its metal chimney?", options: ["So the pipe does not move in the wind.", "Because the vent operates under positive pressure; any leak would release lethal combustion gases (CO) directly into the building structure.", "It increases air velocity through a magnetic suction effect.", "It is an aesthetic standard to make the chimney look professional."], explanation: "With natural draft, if there is a hole, room air enters the pipe. With Category III, the motor pushes the flue gas; if there is a hole, the flue gas exits into the house. Sealing is a matter of life and death." },
  { id:"calef_285", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama que es azul pero tiene una 'base' que no toca el quemador (está suspendida a 1 cm del metal)?", opciones:["Combustión de alta eficiencia estequiométrica.", "Velocidad de mezcla excesiva (Lifting Flame); el flujo de gas es más rápido que la velocidad de combustión, arriesgando un apagado por sensor de llama.", "Presencia de una fuga de gas en el manifold.", "El orificio del quemador es demasiado pequeño para la altitud local."], respuesta_correcta:1, explicacion:"La llama debe estar anclada al metal. Si 'vuela', es inestable. Puede que la presión de gas esté muy alta o que el aire primario sea demasiado, 'soplando' la llama lejos de su base." , question: "What does a blue flame with a base that does not touch the burner (suspended about half an inch above the metal) indicate?", options: ["High stoichiometric combustion efficiency.", "Excessive mixture velocity (Lifting Flame); gas flow is faster than the combustion speed, risking flame sensor shutdown.", "A gas leak at the manifold.", "The burner orifice is too small for the local altitude."], explanation: "The flame must be anchored to the metal. If it floats, it is unstable. Gas pressure may be too high or primary air may be excessive, blowing the flame away from its base." },
  { id:"calef_286", categoria:"CALEF_HORNOS", pregunta:"¿Qué es un 'Venteo Concéntrico' y cuál es su mayor ventaja técnica en instalaciones de pared lateral?", opciones:["Un tubo que gira en círculos para ahorrar espacio.", "Un diseño de tubo dentro de otro que requiere solo un agujero en la pared para entrada de aire y salida de escape, manteniendo el equilibrio de presiones ante el viento.", "Un sistema que filtra el CO2 mediante carbón activado.", "Permite usar mangueras flexibles de jardín en lugar de PVC."], respuesta_correcta:1, explicacion:"Es más limpio y seguro. Evita que la casa parezca una fábrica con tubos saliendo por todos lados. Además, si el viento sopla fuerte, afecta igual a la entrada y salida, por lo que el horno no se apaga." , question: "What is a Concentric Vent and what is its greatest technical advantage in sidewall installations?", options: ["A pipe that spirals to save space.", "A pipe-within-a-pipe design that requires only one wall penetration for both air intake and exhaust, maintaining pressure balance against wind.", "A system that filters CO2 using activated carbon.", "It allows the use of flexible garden hoses instead of PVC."], explanation: "It is cleaner and safer. It avoids making the house look like a factory with pipes everywhere. Also, if the wind blows hard, it affects both intake and exhaust equally, so the furnace does not shut down." },
  { id:"calef_287", categoria:"CALEF_HORNOS", pregunta:"Un interruptor de presión (Pressure Switch) se abre aleatoriamente. El técnico nota que la manguera tiene una pequeña grieta. ¿Cómo afecta esto al sistema?", opciones:["Aumenta la eficiencia del motor inductor.", "La fuga de aire impide que el interruptor 'sienta' el vacío real del inductor, provocando fallas intermitentes de seguridad y apagados del horno.", "El gas natural se escapa por la grieta hacia el cuarto.", "No afecta, el sensor solo mide la temperatura del aire."], respuesta_correcta:1, explicacion:"El sensor es muy sensible. Una grieta minúscula es suficiente para que el vacío se pierda. El horno 'cree' que la chimenea está tapada y corta el gas por precaución." , question: "A Pressure Switch opens randomly. The technician notices the sensing hose has a small crack. How does this affect the system?", options: ["It increases inducer motor efficiency.", "The air leak prevents the switch from sensing the actual vacuum from the inducer, causing intermittent safety faults and furnace shutdowns.", "Natural gas escapes through the crack into the room.", "It has no effect; the sensor only measures air temperature."], explanation: "The sensor is very sensitive. A tiny crack is enough to lose the vacuum. The furnace thinks the chimney is blocked and shuts off the gas as a precaution." },
  { id:"calef_288", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Termostato de Roll-out' y por qué se ubica cerca de los quemadores?", opciones:["Regular la temperatura del aire de suministro.", "Detectar llamas 'derramadas' fuera del intercambiador debido a falta de tiro o bloqueos; apaga el gas para evitar que el gabinete del horno se incendie.", "Encender el soplador si el ignitor falla.", "Medir la presión del gas natural en el quemador."], respuesta_correcta:1, explicacion:"Es tu seguro contra incendios. Si el fuego no entra al tubo y se sale hacia afuera, este sensor lo siente y corta todo. Es de reset manual para obligar a una revisión técnica." , question: "What is the function of the Flame Roll-out Switch and why is it located near the burners?", options: ["To regulate supply air temperature.", "To detect flames spilling outside the heat exchanger due to lack of draft or blockages; it shuts off the gas to prevent the furnace cabinet from catching fire.", "To ignite the blower if the igniter fails.", "To measure natural gas pressure at the burner."], explanation: "It is your fire insurance. If the flame does not enter the heat exchanger tubes and instead rolls outward, this sensor detects it and cuts everything. It has a manual reset to force a professional inspection." },
  { id:"calef_289", categoria:"CALEF_HORNOS", pregunta:"Usted mide una señal de llama de 0.2 microamperios DC. El horno se apaga a los 5 segundos. ¿Qué es lo más probable?", opciones:["El ignitor no está lo suficientemente caliente.", "Sensor de llama sucio, mal posicionado o con porcelana agrietada; la placa requiere usualmente > 1.0 uA para mantener la válvula de gas abierta.", "La presión del gas es excesiva para el sensor.", "El termostato tiene un cable suelto en el terminal 'C'."], respuesta_correcta:1, explicacion:"La placa 've' que hay fuego, pero la señal es tan débil que no confía en ella. Por seguridad, asume que la llama es inestable y corta el gas para evitar explosiones." , question: "You measure a flame signal of 0.2 microamps DC. The furnace shuts off after 5 seconds. What is the most likely cause?", options: ["The igniter is not hot enough.", "A dirty, mispositioned, or cracked-porcelain flame sensor; the control board typically requires more than 1.0 microamps to keep the gas valve open.", "The gas pressure is excessive for the sensor.", "The thermostat has a loose wire on the C terminal."], explanation: "The board sees that there is fire, but the signal is so weak that it does not trust it. For safety, it assumes the flame is unstable and cuts the gas to prevent an explosion." },
  { id:"calef_290", categoria:"CALEF_HORNOS", pregunta:"¿Qué es un 'Termostato de Bloqueo de Humos' (Vent Blockage Switch) en un horno de tiro inducido?", opciones:["Un sensor que mide el color del humo.", "Un dispositivo de seguridad (usualmente un interruptor térmico) montado en el soplador del inductor que apaga el horno si detecta calor excesivo debido a una chimenea tapada.", "Controla la humedad de la chimenea de PVC.", "Aumenta el voltaje del motor inductor si hay mucho viento."], respuesta_correcta:1, explicacion:"Si el tubo de escape se tapa, los gases calientes se quedan atrapados en el motor inductor. El motor se calienta de más, este switch lo siente y apaga todo antes de que algo se derrita." , question: "What is a Vent Blockage Switch on an induced draft furnace?", options: ["A sensor that measures the color of the flue gas.", "A safety device (usually a thermal switch) mounted on the inducer blower that shuts the furnace off if it detects excessive heat due to a blocked chimney.", "It controls the humidity of the PVC chimney.", "It increases inducer motor voltage when it is very windy."], explanation: "If the exhaust pipe is blocked, hot gases get trapped in the inducer motor. The motor overheats, this switch detects it, and shuts everything down before something melts." },
  { id:"calef_291", categoria:"CALEF_HORNOS", pregunta:"Usted nota que las llamas del horno se vuelven 'perezosas' y se inclinan hacia afuera del intercambiador. ¿Cuál es el diagnóstico de seguridad inmediato?", opciones:["Que el horno está entrando en modo de alta eficiencia.", "Intercambiador de calor bloqueado o chimenea tapada; los gases de combustión no pueden salir y están sofocando la llama. ¡Riesgo inminente de CO!", "El gas natural tiene un exceso de vapor de agua destilada.", "El motor del soplador está girando demasiado rápido."], respuesta_correcta:1, explicacion:"Si el humo no sale, el fuego se ahoga. Es como tratar de prender una fogata dentro de una caja cerrada. El humo saldrá por donde pueda, incluyendo tu sala de estar." , question: "You notice the furnace flames become lazy and lean outward from the heat exchanger. What is the immediate safety diagnosis?", options: ["The furnace is entering high-efficiency mode.", "Blocked heat exchanger or clogged chimney; combustion gases cannot exit and are smothering the flame. Imminent CO risk!", "The natural gas has an excess of distilled water vapor.", "The blower motor is spinning too fast."], explanation: "If the flue gas cannot exit, the fire suffocates. It is like trying to start a campfire inside a sealed box. The smoke will come out wherever it can, including your living room." },
  { id:"calef_292", categoria:"CALEF_HORNOS", pregunta:"¿Por qué está prohibido usar tubería de PVC 'Cellular Core' (núcleo de espuma) para el venteo de hornos de alta eficiencia?", opciones:["Porque el color blanco no combina con las casas modernas.", "No tiene la resistencia estructural ni térmica necesaria para soportar la presión del motor inductor y el calor de los gases, pudiendo agrietarse y fugar CO.", "El gas natural reacciona con la espuma interna y la disuelve.", "Es una norma para favorecer a los fabricantes de PVC sólido."], respuesta_correcta:1, explicacion:"El 'Cellular Core' es para drenaje de agua, no para gases. Bajo la presión y el calor del horno, ese tubo se debilita. Siempre usa PVC sólido Cédula 40." , question: "Why is it prohibited to use Cellular Core PVC pipe for venting high-efficiency furnaces?", options: ["Because the white color does not match modern homes.", "It lacks the structural and thermal strength needed to withstand the inducer motor pressure and flue gas heat, and can crack and leak CO.", "Natural gas reacts with the internal foam and dissolves it.", "It is a regulation designed to favor solid PVC manufacturers."], explanation: "Cellular Core PVC is designed for water drainage, not for flue gases. Under the pressure and heat of a furnace, that pipe weakens. Always use solid-wall Schedule 40 PVC." },
  { id:"calef_293", categoria:"CALEF_HORNOS", pregunta:"Usted nota que las llamas del horno 'bailan' significativamente solo cuando el soplador se enciende. ¿Qué prueba de seguridad debe realizar inmediatamente?", opciones:["Medir el amperaje del motor soplador.", "Prueba de Monóxido de Carbono en el aire de suministro y una inspección visual profunda del intercambiador de calor en busca de grietas o fracturas.", "Cambiar el filtro de aire por uno de carbón activo.", "Aumentar la presión del gas en la válvula principal."], respuesta_correcta:1, explicacion:"Si el aire de la casa afecta al fuego, hay un agujero en el metal que separa el fuego del aire. Es una falla de seguridad mortal y el horno debe condenarse." , question: "You notice the furnace flames dance significantly only when the blower turns on. What safety test must you perform immediately?", options: ["Measure the blower motor amperage.", "A carbon monoxide test on the supply air and a thorough visual inspection of the heat exchanger for cracks or fractures.", "Replace the air filter with an activated carbon one.", "Increase the gas pressure at the main valve."], explanation: "If the household air affects the fire, there is a hole in the metal that separates the fire from the air. It is a deadly safety failure and the furnace must be condemned." },
  { id:"calef_294", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es el propósito técnico de la 'Tee de Condensado' en la base de una chimenea vertical de Categoría I?", opciones:["Servir como punto de inspección para nidos de pájaros.", "Recoger el agua que se condensa durante el arranque en frío y permitir que se evapore o drene sin que caiga directamente sobre el intercambiador del horno.", "Mezclar el humo con aire fresco de la habitación.", "Reducir el diámetro de la chimenea para aumentar el tiro."], respuesta_correcta:1, explicacion:"Al principio, la chimenea está fría y el humo suelta agua. Esa agua es ácida. Si cae dentro del horno, lo oxida. La Tee de condensado es el 'paraguas' interno del equipo." , question: "What is the technical purpose of the Condensate Tee at the base of a Category I vertical chimney?", options: ["To serve as an inspection point for bird nests.", "To collect water that condenses during cold startup and allow it to evaporate or drain without falling directly onto the furnace heat exchanger.", "To mix flue gas with fresh room air.", "To reduce the chimney diameter to increase draft."], explanation: "At startup, the chimney is cold and the flue gas releases water. That water is acidic. If it falls into the furnace, it corrodes it. The condensate tee is the equipment's internal umbrella." },
  { id:"calef_295", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama que es azul con 'puntas' amarillas opacas y que produce un olor a hollín?", opciones:["Gas natural con bajo contenido de metano.", "Falta de aire secundario o quemadores sucios, resultando en una combustión incompleta que produce carbón (hollín) y monóxido de carbono.", "Es el color normal de un horno de 2 etapas en etapa baja.", "Indica que el sensor de llama está perfectamente limpio."], respuesta_correcta:1, explicacion:"Ese color amarillo es carbón ardiendo. Si hay carbón, hay veneno (CO). El horno necesita una limpieza de quemadores y un ajuste de aire urgente." , question: "What does a blue flame with opaque yellow tips that produces a soot smell indicate?", options: ["Natural gas with low methane content.", "Insufficient secondary air or dirty burners, resulting in incomplete combustion that produces carbon (soot) and carbon monoxide.", "It is the normal color of a two-stage furnace on low fire.", "It indicates the flame sensor is perfectly clean."], explanation: "That yellow color is burning carbon. Where there is carbon, there is poison (CO). The furnace needs an urgent burner cleaning and air adjustment." },
  { id:"calef_296", categoria:"CALEF_HORNOS", pregunta:"¿Qué sucede si el terminal de escape de PVC de un horno de condensación queda cubierto por la nieve?", opciones:["El calor del gas derretirá la nieve y el horno seguirá funcionando.", "El interruptor de presión (Pressure Switch) detectará la falta de flujo de aire y bloqueará el encendido del horno por seguridad.", "El monóxido de carbono se filtrará por las tuberías de drenaje.", "El motor inductor aumentará su velocidad al triple para vencer el bloqueo."], respuesta_correcta:1, explicacion:"Es la causa #1 de llamadas de servicio en tormentas de nieve. El sensor 'siente' que el aire no sale y corta el gas. Siempre hay que mantener los tubos de afuera despejados." , question: "What happens if the PVC exhaust terminal of a condensing furnace becomes covered by snow?", options: ["The heat from the gas will melt the snow and the furnace will keep running.", "The Pressure Switch will detect the lack of airflow and lock out the furnace ignition for safety.", "Carbon monoxide will seep through the drain piping.", "The inducer motor will increase its speed to three times normal to overcome the blockage."], explanation: "This is the number one cause of service calls during snowstorms. The sensor detects that air is not flowing and cuts the gas. Always keep the outdoor vent pipes clear." },
  { id:"calef_297", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Deflector de Llama' en el intercambiador de calor?", opciones:["Apagar la llama si el soplador falla.", "Distribuir el calor de la llama de forma uniforme contra las paredes del metal para maximizar la transferencia de calor y evitar puntos calientes (hot spots).", "Reflejar la luz para que el sensor de llama trabaje mejor.", "Evitar que el polvo de la casa entre a la zona de fuego."], respuesta_correcta:1, explicacion:"Sin deflectores, el fuego golpearía siempre el mismo punto del metal, estresándolo hasta que se agriete. El deflector hace que el calor 'bañe' todo el metal por igual." , question: "What is the function of the Flame Deflector inside the heat exchanger?", options: ["To extinguish the flame if the blower fails.", "To distribute flame heat evenly against the metal walls, maximizing heat transfer and preventing hot spots.", "To reflect light so the flame sensor works better.", "To prevent household dust from entering the combustion zone."], explanation: "Without deflectors, the fire would strike the same spot on the metal every time, stressing it until it cracks. The deflector ensures the heat washes over all the metal evenly." },
  { id:"calef_298", categoria:"CALEF_HORNOS", pregunta:"Un horno de 2 etapas se queda trabado en 'Etapa Baja' (Low Heat) aunque la casa esté a 15°C y el setpoint sea 22°C. ¿Qué puente (jumper) o switch revisaría?", opciones:["El interruptor de límite de alta temperatura.", "El switch de 'Stage Timing' en la placa de control, que puede estar configurado para ignorar el segundo stage si no hay un cable W2 conectado.", "El sensor de llama de ionización.", "La polaridad de los cables del motor inductor."], respuesta_correcta:1, explicacion:"Las placas modernas tienen un 'timer'. Si no tienes cable W2, la placa debe saber que ella misma debe subir a segunda etapa tras 10 minutos. Si el switch está mal puesto, nunca subirá." , question: "A two-stage furnace is stuck in Low Heat even though the house is at 59 degrees F and the setpoint is 72 degrees F. What jumper or switch would you check?", options: ["The high temperature limit switch.", "The Stage Timing switch on the control board, which may be configured to ignore the second stage if there is no W2 wire connected.", "The flame ionization sensor.", "The polarity of the inducer motor wires."], explanation: "Modern control boards have a timer. If you do not have a W2 wire, the board must know to ramp up to second stage on its own after about 10 minutes. If the switch is set wrong, it will never go to high fire." },
  { id:"calef_299", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica el término 'Tiro Balanceado' (Balanced Draft) en una caldera comercial?", opciones:["Que el peso de la caldera está bien distribuido en el suelo.", "Un sistema que usa tanto un ventilador de tiro forzado (entrada) como uno de tiro inducido (salida) para mantener la cámara de combustión a presión neutra.", "Cuando la chimenea tiene exactamente la misma altura que el edificio.", "Un sensor que equilibra el gas natural con el propano líquido."], respuesta_correcta:1, explicacion:"Es el control total. Metes aire y sacas humo con dos motores coordinados para que dentro del fuego no haya ni mucha presión ni mucho vacío. Es ingeniería de precisión." , question: "What does the term Balanced Draft mean in a commercial boiler?", options: ["The weight of the boiler is evenly distributed on the floor.", "A system that uses both a forced draft fan (inlet) and an induced draft fan (outlet) to maintain the combustion chamber at neutral pressure.", "When the chimney is exactly the same height as the building.", "A sensor that balances natural gas with liquid propane."], explanation: "This is total control. You push air in and pull flue gas out with two coordinated fans so that inside the firebox there is neither excessive pressure nor excessive vacuum. It is precision engineering." },
  { id:"calef_300", categoria:"CALEF_HORNOS", pregunta:"Usted encuentra una llama azul con un cono interno que 'vibra' (pulsing flame) y hace un sonido de baja frecuencia. ¿Cuál es el ajuste técnico?", opciones:["Cambiar el sensor de llama por uno de mayor longitud.", "Ajustar la relación aire-gas (gas pressure) o el orificio del quemador para evitar la resonancia acústica dentro del intercambiador de calor.", "Instalar un capacitor de marcha más grande en el soplador.", "No hacer nada, es el sonido normal de un horno potente."], respuesta_correcta:1, explicacion:"Es como un instrumento musical mal afinado. La llama crea una onda de sonido que rebota en el metal. Aparte de ser molesto, esa vibración puede agrietar el intercambiador con el tiempo." , question: "You find a blue flame with an inner cone that vibrates (pulsing flame) and makes a low-frequency hum. What is the technical adjustment?", options: ["Replace the flame sensor with a longer one.", "Adjust the air-gas ratio (gas pressure) or the burner orifice to eliminate the acoustic resonance inside the heat exchanger.", "Install a larger run capacitor on the blower.", "Do nothing; it is the normal sound of a powerful furnace."], explanation: "It is like a badly tuned musical instrument. The flame creates a sound wave that bounces off the metal. Besides being annoying, that vibration can crack the heat exchanger over time." },
  { id:"calef_301", categoria:"CALEF_HORNOS", pregunta:"Usted mide 0.5 microamperios en el sensor de llama. Al limpiar el sensor la señal no sube. ¿Qué es lo siguiente que revisaría?", opciones:["La presión del gas en el manifold de salida.", "La integridad del Neutro y la Tierra (referencia de cero); un Neutro con voltaje 'sucio' impedirá que la señal de ionización regrese a la placa correctamente.", "Cambiar el ignitor HSI por uno de 80V.", "Aumentar el tamaño del orificio del quemador."], respuesta_correcta:1, explicacion:"Si el sensor está limpio pero la señal es baja, el problema es el 'camino' de regreso. La electricidad necesita volver a la placa por la tierra del chasis. Si el cable está flojo, la señal se pierde." , question: "You measure 0.5 microamps at the flame sensor. After cleaning the sensor, the signal does not improve. What do you check next?", options: ["The manifold outlet gas pressure.", "The integrity of the Neutral and Ground (zero reference); a Neutral with dirty voltage will prevent the ionization signal from returning properly to the control board.", "Replace the HSI igniter with an 80V one.", "Increase the burner orifice size."], explanation: "If the sensor is clean but the signal is still low, the problem is the return path. The current needs to get back to the board through the chassis ground. If the wire is loose, the signal is lost." },
  { id:"calef_302", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un horno de condensación requiere una trampa de agua (Trap) en su línea de drenaje?", opciones:["Para que el agua no haga ruido al caer al desagüe.", "Evitar que los gases de combustión peligrosos (incluido el CO) se escapen a través del tubo de drenaje hacia la vivienda o el cuarto de máquinas.", "Aumentar la presión del motor inductor mediante el sello hidráulico.", "Filtrar las impurezas ácidas del condensado antes de tirarlo."], respuesta_correcta:1, explicacion:"Es igual que el sifón de tu baño. Impide que el humo del horno se salga por el tubo del drenaje. Si la trampa está seca, el aire de la casa se llenará de veneno." , question: "Why does a condensing furnace require a water trap in its drain line?", options: ["So the water does not make noise falling into the drain.", "To prevent dangerous combustion gases (including CO) from escaping through the drain tube into the living space or mechanical room.", "To increase inducer motor pressure through a water seal.", "To filter acidic impurities from the condensate before disposal."], explanation: "It is just like the P-trap under your bathroom sink. It prevents furnace flue gas from exiting through the drain pipe. If the trap dries out, the living space will fill with poison." },
  { id:"calef_303", categoria:"CALEF_HORNOS", pregunta:"Usted nota que las llamas del horno se 'separan' (lifting) de los quemadores solo cuando el aire exterior está muy frío. ¿Cuál es la causa?", opciones:["El gas natural se condensa en la tubería.", "El aire frío es más denso y rico en oxígeno, lo que aumenta la velocidad de combustión y la presión primaria; requiere un ajuste de la válvula de gas para invierno.", "El soplador está girando al revés.", "Es un fenómeno normal de criogénesis térmica."], respuesta_correcta:1, explicacion:"El aire frío 'empuja' más fuerte. Cambia la mezcla aire/gas y puede hacer que la llama se despegue. Es señal de que el sistema necesita un ajuste estacional." , question: "You notice the furnace flames lift off the burners only when the outdoor air is very cold. What is the cause?", options: ["The natural gas is condensing in the pipe.", "Cold air is denser and richer in oxygen, which increases the combustion velocity and primary air pressure; a seasonal gas valve adjustment is needed.", "The blower is spinning backwards.", "It is a normal phenomenon of thermal cryogenesis."], explanation: "Cold air pushes harder. It changes the air-gas mixture and can make the flame lift off. This is a sign that the system needs a seasonal adjustment." },
  { id:"calef_304", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Flame Mirror' (Espejo de inspección) en un intercambiador de calor sellado?", opciones:["Para que el técnico pueda peinarse mientras trabaja.", "Permitir la observación segura del patrón de llama y del ignitor sin comprometer el sello de presión de la cámara de combustión (Direct Vent).", "Reflejar el calor hacia el serpentín secundario.", "Aumentar la señal de microamperios mediante reflexión óptica."], respuesta_correcta:1, explicacion:"En sistemas sellados no puedes abrir la tapa para ver el fuego. El espejito o ventana te deja ver si el fuego es azul y sano sin apagar el horno." , question: "What is the function of the Flame Mirror (inspection window) on a sealed-combustion heat exchanger?", options: ["So the technician can groom while working.", "To allow safe observation of the flame pattern and igniter without compromising the pressure seal of the combustion chamber (Direct Vent).", "To reflect heat toward the secondary coil.", "To increase the microamp signal through optical reflection."], explanation: "On sealed systems you cannot open the cover to see the fire. The inspection mirror or window lets you verify that the flame is blue and healthy without shutting the furnace down." },
  { id:"calef_305", categoria:"CALEF_HORNOS", pregunta:"¿Qué es un 'B-Vent' y cuál es su limitación principal respecto a los materiales combustibles?", opciones:["Un tubo de plástico para drenar agua.", "Un sistema de doble pared con cámara de aire; requiere una distancia mínima de seguridad de 1 pulgada hacia cualquier material combustible (madera, papel).", "Un conector flexible para gas propano.", "Solo puede usarse en sistemas de tiro inducido de alta eficiencia."], respuesta_correcta:1, explicacion:"El B-Vent es el estándar para hornos de 80%. Aunque es doble pared, se calienta. Si lo pegas a la madera del ático, podrías causar un incendio por calor radiante." , question: "What is a B-Vent and what is its main limitation regarding combustible materials?", options: ["A plastic pipe for draining water.", "A double-wall pipe with an air gap; it requires a minimum clearance of 1 inch from any combustible material (wood, paper).", "A flexible connector for propane gas.", "It can only be used with high-efficiency induced draft systems."], explanation: "B-Vent is the standard for 80% furnaces. Even though it is double-wall, it gets hot. If you place it against attic wood, you could cause a fire from radiant heat." },
  { id:"calef_306", categoria:"CALEF_HORNOS", pregunta:"¿Qué sucede con la llama de un horno de gas si el 'Orificio' está agrandado por una limpieza agresiva con alambre?", opciones:["La llama se vuelve más azul y eficiente.", "El horno suministrará más gas de lo diseñado (Overfiring), sobrecalentando el intercambiador y produciendo monóxido de carbono por falta de oxígeno.", "La velocidad del gas disminuye y la llama se apaga sola.", "Aumenta la señal de microamperios del sensor de llama."], respuesta_correcta:1, explicacion:"Nunca limpies orificios con metal. Si agrandas el agujero, aunque sea un poquito, metes mucho más gas. El horno no está hecho para ese calor y se puede derretir." , question: "What happens to the furnace flame if the burner orifice has been enlarged by aggressive cleaning with a wire?", options: ["The flame becomes bluer and more efficient.", "The furnace will deliver more gas than designed (overfiring), overheating the heat exchanger and producing carbon monoxide due to insufficient oxygen.", "The gas velocity decreases and the flame goes out on its own.", "It increases the flame sensor microamp signal."], explanation: "Never clean orifices with metal. If you enlarge the hole even slightly, you allow far too much gas through. The furnace is not designed for that amount of heat and can melt." },
  { id:"calef_307", categoria:"CALEF_HORNOS", pregunta:"Un horno de gas enciende, la llama dura 4 segundos y se apaga. Se repite 3 veces y entra en Lockout. ¿Cuál es la falla más probable?", opciones:["La válvula de gas está fallando mecánicamente.", "El sensor de llama (Flame Rod) no detecta la llama debido a suciedad o falta de tierra, y la placa corta el gas por seguridad al no recibir señal de ionización.", "El motor inductor de tiro está girando muy lento.", "El termostato de pared está dañado."], respuesta_correcta:1, explicacion:"Clásico. La llama está ahí, pero la placa no la 've'. Como no quiere inundar la casa de gas, corta el paso a los pocos segundos. Limpia el sensor con una lija fina." , question: "A gas furnace ignites, the flame lasts 4 seconds, and it goes out. This repeats 3 times and the furnace enters Lockout. What is the most likely fault?", options: ["The gas valve is failing mechanically.", "The Flame Rod (flame sensor) is not detecting the flame due to dirt or a grounding issue, and the board cuts the gas for safety since it receives no ionization signal.", "The inducer motor is spinning too slowly.", "The wall thermostat is damaged."], explanation: "Classic issue. The flame is there, but the board cannot see it. Since the board does not want to flood the house with gas, it cuts the supply after a few seconds. Clean the sensor with fine emery cloth." },
  { id:"calef_308", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama azul con una 'punta naranja' que desaparece cuando el técnico apaga el humidificador ultrasónico de la casa?", opciones:["Producción masiva de monóxido de carbono.", "Presencia de minerales y sodio en el aire (niebla del humidificador) reaccionando con el fuego; es una reacción inofensiva de color espectral.", "Que el gas natural tiene un exceso de humedad destilada.", "El sensor de llama se ha recalibrado automáticamente."], respuesta_correcta:1, explicacion:"Los minerales del agua del humidificador brillan naranja en el fuego. No es mala combustión, es solo el color de los minerales quemándose." , question: "What does a blue flame with an orange tip that disappears when the technician turns off the household ultrasonic humidifier indicate?", options: ["Massive carbon monoxide production.", "Minerals and sodium in the air (humidifier mist) reacting with the fire; it is a harmless spectral color reaction.", "The natural gas has an excess of distilled moisture.", "The flame sensor has auto-recalibrated."], explanation: "Minerals in the humidifier water glow orange in the fire. It is not poor combustion; it is simply the color of the minerals burning." },
  { id:"calef_309", categoria:"CALEF_HORNOS", pregunta:"Usted encuentra que el tubo de PVC de escape tiene agua chorreando por las uniones. ¿Qué diagnóstico es el correcto?", opciones:["El horno está produciendo demasiada agua.", "Las uniones de PVC no fueron selladas con cemento solvente o se usó el tipo de pegamento incorrecto para venteo de gases.", "Es una purga normal de condensado del motor inductor.", "El tubo de escape es demasiado corto para el equipo."], respuesta_correcta:1, explicacion:"¡Grave! Si sale agua, también sale humo (CO). El técnico que lo instaló no pegó bien los tubos. Hay que sellar todo de nuevo con cemento de PVC real." , question: "You find that the PVC exhaust pipe has water dripping from the joints. What is the correct diagnosis?", options: ["The furnace is producing too much water.", "The PVC joints were not sealed with solvent cement or the wrong type of adhesive was used for flue gas venting.", "It is a normal condensate purge from the inducer motor.", "The exhaust pipe is too short for the equipment."], explanation: "Serious issue! If water is leaking out, flue gas (CO) is also leaking. The installer who put it together did not properly cement the pipe joints. Everything needs to be resealed with proper PVC solvent cement." },
  { id:"calef_310", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Fusible de 3 o 5 Amperios' en la placa electrónica de un horno?", opciones:["Proteger al motor del soplador de sobrecargas.", "Proteger el transformador de 24V y la placa de control contra cortocircuitos en el cableado del termostato o los accesorios de control.", "Ahorrar energía durante el modo de espera (standby).", "Medir el amperaje de la válvula de gas."], respuesta_correcta:1, explicacion:"Si juntas por error el cable rojo con el azul en el termostato, este fusible se sacrifica para que la placa electrónica no explote. Es barato de cambiar." , question: "What is the function of the 3- or 5-amp fuse on a furnace electronic control board?", options: ["To protect the blower motor from overloads.", "To protect the 24V transformer and the control board from short circuits in the thermostat wiring or control accessories.", "To save energy during standby mode.", "To measure the gas valve amperage."], explanation: "If you accidentally cross the red wire with the blue wire at the thermostat, this fuse sacrifices itself so the electronic board does not blow up. It is cheap to replace." },
  { id:"calef_311", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama 'verde' momentánea cuando el horno se enciende en un cuarto donde acaban de pintar?", opciones:["Combustión de alta pureza química.", "Presencia de vapores químicos (solventes, pinturas) en el aire de combustión reaccionando con la llama; es altamente corrosivo y peligroso.", "Que el quemador de cobre está funcionando bien.", "Falla del sensor de llama por ionización verde."], respuesta_correcta:1, explicacion:"¡Cuidado! Si el aire tiene químicos, el fuego se vuelve tóxico y ácido. Eso destruye el metal del horno en días y es peligroso respirarlo." , question: "What does a momentary green flame when the furnace ignites in a room that was just painted indicate?", options: ["High-purity chemical combustion.", "Chemical vapors (solvents, paints) in the combustion air reacting with the flame; it is highly corrosive and hazardous.", "The copper burner is functioning properly.", "A flame sensor failure due to green ionization."], explanation: "Caution! If the air contains chemicals, the fire becomes toxic and acidic. This destroys the furnace metal in days and is dangerous to breathe." },
  { id:"calef_312", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Interruptor de Límite Manual' (Manual Reset Limit) cerca del quemador?", opciones:["Permitir que el cliente apague el horno fácilmente.", "Seguridad contra llamas que se salen de la cámara (Roll-out); obliga a un técnico a revisar la causa antes de poder reiniciar el sistema.", "Cambiar la presión del gas de forma manual.", "Drenar el exceso de gas natural de la válvula."], respuesta_correcta:1, explicacion:"Si este switch salta, es porque hubo fuego donde no debía haberlo. No lo resetees sin investigar; podrías incendiar la casa si el problema sigue ahí." , question: "What is the function of the Manual Reset Limit Switch near the burner?", options: ["To allow the homeowner to easily turn off the furnace.", "Safety against flames escaping the combustion chamber (roll-out); it forces a technician to investigate the cause before the system can be restarted.", "To manually adjust gas pressure.", "To drain excess natural gas from the valve."], explanation: "If this switch trips, it means there was fire where there should not have been. Do not reset it without investigating; you could start a house fire if the problem persists." },
  { id:"calef_313", categoria:"CALEF_HORNOS", pregunta:"Usted nota que las llamas del horno son 'perezosas' y amarillentas. ¿Cuál es la causa técnica?", opciones:["Exceso de aire primario en la mezcla.", "Falta de oxígeno (aire primario o secundario) o presión de gas muy baja, provocando una combustión incompleta e ineficiente.", "Uso de gas propano en una válvula de gas natural.", "El sensor de llama está perfectamente limpio."], respuesta_correcta:1, explicacion:"Llama perezosa = llama sin aire. Es ineficiente y peligrosa porque empieza a crear hollín que tapa todo el horno y produce monóxido." , question: "You notice the furnace flames are lazy and yellowish. What is the technical cause?", options: ["Excess primary air in the mixture.", "Insufficient oxygen (primary or secondary air) or very low gas pressure, resulting in incomplete and inefficient combustion.", "Using propane in a natural gas valve.", "The flame sensor is perfectly clean."], explanation: "A lazy flame is a flame without enough air. It is inefficient and dangerous because it starts producing soot that clogs the entire furnace and generates carbon monoxide." },
  { id:"calef_314", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica el término 'Draft Hood' en un calentador de agua de gas?", opciones:["Una tapa para que no entre aire frío.", "Un dispositivo que permite la entrada de aire de dilución, estabiliza el tiro y evita que ráfagas de viento apaguen el quemador.", "Un sensor que mide la velocidad del gas.", "Una campana que atrapa el condensado ácido."], respuesta_correcta:1, explicacion:"Es ese 'sombrerito' abierto. Sirve para que los gases suban bien y para que, si el viento sopla hacia abajo, el aire salga por el lado y no apague el fuego." , question: "What does the term Draft Hood on a gas water heater refer to?", options: ["A cap to keep cold air out.", "A device that allows dilution air to enter, stabilizes the draft, and prevents wind gusts from extinguishing the burner.", "A sensor that measures gas velocity.", "A hood that captures acidic condensate."], explanation: "It is that open bell-shaped fitting. It helps the flue gases rise properly, and if the wind blows downward, the air exits through the side instead of extinguishing the flame." },
  { id:"calef_315", categoria:"CALEF_HORNOS", pregunta:"¿Qué sucede si el sensor de llama está tocando físicamente el quemador de metal?", opciones:["La señal de llama será más fuerte que nunca.", "La placa de control detectará un cortocircuito a tierra (Short to Ground) y bloqueará el horno por seguridad, ya que no puede rectificar la señal.", "El ignitor brillará con luz verde.", "El gas natural fluirá con el doble de velocidad."], respuesta_correcta:1, explicacion:"La placa espera una señal que pase 'a través' del fuego. Si el sensor toca el metal, es como si no hubiera fuego. La placa da error y no deja prender el gas." , question: "What happens if the flame sensor is physically touching the metal burner?", options: ["The flame signal will be stronger than ever.", "The control board will detect a short to ground and lock out the furnace for safety, because it cannot rectify the signal.", "The igniter will glow green.", "Natural gas will flow at double speed."], explanation: "The board expects a signal that passes through the fire. If the sensor touches the metal, it is as if there is no fire. The board faults and will not allow gas to flow." },
  { id:"calef_316", categoria:"CALEF_HORNOS", pregunta:"Un horno de gas moderno realiza un 'Self-Test' y detecta que el interruptor de presión (Pressure Switch) está CERRADO antes de que el motor inductor arranque. ¿Qué hace la placa de control?", opciones:["Inicia el ciclo de encendido normalmente asumiendo que el tiro es excelente.", "Bloquea el encendido (Lockout) porque el interruptor debería estar abierto sin flujo de aire; esto indica un interruptor pegado o un puente ilegal.", "Ignora el sensor y activa la válvula de gas por un periodo de seguridad de 5 segundos.", "Aumenta el voltaje al motor inductor para intentar abrir el contacto mecánicamente."], respuesta_correcta:1, explicacion:"Por seguridad, la placa debe ver que el interruptor pasa de ABIERTO a CERRADO. Si ya está cerrado, no puede validar que el motor inductor realmente está moviendo aire." , question: "A modern gas furnace performs a Self-Test and detects that the Pressure Switch is CLOSED before the inducer motor starts. What does the control board do?", options: ["It starts the ignition sequence normally, assuming the draft is excellent.", "It locks out ignition because the switch should be open with no airflow; this indicates a stuck switch or an illegal jumper.", "It ignores the sensor and activates the gas valve for a 5-second safety period.", "It increases voltage to the inducer motor to try to mechanically open the contact."], explanation: "For safety, the board must see the switch transition from OPEN to CLOSED. If it is already closed, it cannot verify that the inducer motor is actually moving air." },
  { id:"calef_317", categoria:"CALEF_HORNOS", pregunta:"Un horno de Categoría I se ventila a través de una chimenea de mampostería (ladrillo) exterior. ¿Por qué es obligatorio un revestimiento (liner) metálico?", opciones:["Para que el ladrillo no se ensucie con el hollín.", "Para evitar que los gases de combustión se enfríen demasiado rápido, condensen y destruyan el mortero del ladrillo por la acidez del condensado.", "Aumenta el tiro natural mediante la atracción magnética del metal.", "Es una norma puramente estética para igualar el color del techo."], respuesta_correcta:1, explicacion:"El ladrillo frío enfría el humo. El humo condensado tiene ácido carbónico que disuelve el cemento de los ladrillos, pudiendo causar que la chimenea colapse o fugue CO." , question: "A Category I furnace vents through an exterior masonry (brick) chimney. Why is a metal liner required?", options: ["To keep the brick from getting dirty with soot.", "To prevent the combustion gases from cooling too rapidly, condensing, and destroying the brick mortar with acidic condensate.", "It increases natural draft through magnetic attraction of the metal.", "It is a purely aesthetic standard to match the roof color."], explanation: "Cold brick cools the flue gas. The condensed flue gas contains carbonic acid that dissolves the cement between the bricks, potentially causing the chimney to collapse or leak CO." },
  { id:"calef_318", categoria:"CALEF_HORNOS", pregunta:"¿Qué componente de seguridad corta el gas si las llamas son succionadas hacia atrás por falta de aire primario (Flashback)?", opciones:["El sensor de llama de ionización.", "El interruptor de roll-out térmico (Flame Roll-out Switch).", "El termostato de la habitación.", "El interruptor de presión de aire del motor inductor."], respuesta_correcta:1, explicacion:"El roll-out switch está cerca de los quemadores. Si el fuego se sale de su lugar y calienta esta zona, el sensor se abre y bloquea el horno para evitar un incendio." , question: "Which safety component shuts off the gas if flames are drawn back due to insufficient primary air (flashback)?", options: ["The flame ionization sensor.", "The Flame Roll-out Switch (thermal roll-out switch).", "The room thermostat.", "The inducer motor air pressure switch."], explanation: "The roll-out switch is located near the burners. If fire escapes from its designated area and heats this zone, the sensor opens and locks out the furnace to prevent a fire." },
  { id:"calef_319", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un horno de 95% AFUE tiene dos intercambiadores de calor?", opciones:["Uno es para el gas y el otro para el aire acondicionado.", "El primario absorbe el calor sensible de la llama; el secundario enfría los gases hasta condensar el vapor de agua y recuperar el calor latente.", "Para tener un respaldo en caso de que el primero se agriete.", "Uno funciona con gas natural y el otro con propano líquido."], respuesta_correcta:1, explicacion:"Esa es la magia de la alta eficiencia. El segundo intercambiador (de acero inoxidable) extrae la energía que los hornos viejos tiraban por la chimenea en forma de vapor." , question: "Why does a 95% AFUE furnace have two heat exchangers?", options: ["One is for gas and the other is for air conditioning.", "The primary absorbs sensible heat from the flame; the secondary cools the gases until the water vapor condenses, recovering latent heat.", "As a backup in case the first one cracks.", "One runs on natural gas and the other on liquid propane."], explanation: "That is the magic of high efficiency. The secondary heat exchanger (stainless steel) extracts the energy that older furnaces wasted up the chimney as steam." },
  { id:"calef_320", categoria:"CALEF_HORNOS", pregunta:"¿Qué es un 'Draft Diverter' y dónde se encuentra?", opciones:["Es un interruptor en el termostato.", "Es la abertura en un horno de tiro natural que permite que el aire de la habitación se mezcle con los gases de escape para estabilizar el tiro de la chimenea.", "Un dispositivo dentro del motor inductor.", "Sirve para cambiar el sentido de giro del ventilador."], respuesta_correcta:1, explicacion:"Ese 'sombrerito' abierto arriba del horno es vital. Asegura que si hay una ráfaga de viento en la chimenea, la llama del quemador no se apague ni se salga de su lugar." , question: "What is a Draft Diverter and where is it located?", options: ["It is a switch on the thermostat.", "It is the opening on a natural draft furnace that allows room air to mix with the flue gases to stabilize the chimney draft.", "A device inside the inducer motor.", "It is used to reverse the fan rotation direction."], explanation: "That open bell-shaped fitting on top of the furnace is vital. It ensures that if there is a wind gust in the chimney, the burner flame does not blow out or roll out." },
  { id:"calef_321", categoria:"CALEF_HORNOS", pregunta:"Usted observa una llama azul que se vuelve 'perezosa' y amarilla cuando el soplador se enciende. ¿Qué indica esto?", opciones:["Combustión perfecta con alta eficiencia.", "Intercambiador de calor agrietado; el aire de la casa está entrando a la cámara de combustión y alterando la llama. ¡Peligro de CO!", "El filtro de aire está demasiado limpio.", "La presión del gas es muy baja."], respuesta_correcta:1, explicacion:"Esta es la prueba reina. Si el ventilador de la casa afecta al fuego, el metal está roto. El humo entrará a los ductos y la gente puede morir. Apaga el equipo de inmediato." , question: "You observe a blue flame that becomes lazy and yellow when the blower turns on. What does this indicate?", options: ["Perfect combustion with high efficiency.", "A cracked heat exchanger; household air is entering the combustion chamber and disrupting the flame. CO danger!", "The air filter is too clean.", "The gas pressure is too low."], explanation: "This is the ultimate test. If the household blower affects the fire, the metal is broken. Flue gas will enter the ductwork and people can die. Shut the equipment down immediately." },
  { id:"calef_322", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la ventaja de un 'Hot Surface Igniter' (HSI) de Nitruro de Silicio sobre uno de Carburo de Silicio?", opciones:["Es más barato de fabricar.", "Es mucho más duradero, resistente a golpes y vibraciones, y se calienta más rápido.", "Brilla con un color azul más bonito.", "No requiere 120V para funcionar."], respuesta_correcta:1, explicacion:"El Nitruro es la tecnología moderna. Los viejos de Carburo se rompían con solo tocarlos con el dedo o con la vibración del motor." , question: "What is the advantage of a Silicon Nitride Hot Surface Igniter (HSI) over a Silicon Carbide one?", options: ["It is cheaper to manufacture.", "It is far more durable, resistant to impact and vibration, and heats up faster.", "It glows with a nicer blue color.", "It does not require 120V to operate."], explanation: "Silicon nitride is the modern technology. The older silicon carbide igniters would break just from touching them with a finger or from motor vibration." },
  { id:"calef_323", categoria:"CALEF_HORNOS", pregunta:"¿Por qué los hornos de condensación usan tubos de PVC y los de 80% usan metal?", opciones:["Porque el PVC es más barato.", "Porque los de condensación tienen gases fríos (ácidos) que corroen el metal, y los de 80% tienen gases muy calientes que derretirían el PVC.", "El metal bloquea las ondas de radio del termostato.", "Es una cuestión de estética para diferenciar las eficiencias."], respuesta_correcta:1, explicacion:"Humo frío = plástico. Humo caliente = metal. Si pones metal en un horno de 95%, se oxidará en un mes. Si pones PVC en uno de 80%, causarás un incendio." , question: "Why do condensing furnaces use PVC vent pipe while 80% furnaces use metal?", options: ["Because PVC is cheaper.", "Because condensing furnaces produce cool, acidic flue gases that corrode metal, and 80% furnaces produce very hot flue gases that would melt PVC.", "Metal blocks radio waves from the thermostat.", "It is an aesthetic choice to differentiate efficiency levels."], explanation: "Cool flue gas equals plastic. Hot flue gas equals metal. If you put metal on a 95% furnace, it will corrode in a month. If you put PVC on an 80% furnace, you will cause a fire." },
  { id:"calef_324", categoria:"CALEF_HORNOS", pregunta:"¿Qué es el 'Monóxido de Carbono' (CO) y por qué es peligroso?", opciones:["Es un gas con olor a huevos podridos que marea.", "Es un gas incoloro, inodoro y altamente tóxico que desplaza el oxígeno en la sangre, causado por combustión incompleta.", "Es el gas que sale por el aire acondicionado cuando le falta carga.", "Es el humo azul que sale de los quemadores limpios."], respuesta_correcta:1, explicacion:"Es el asesino silencioso. Por eso cada horno debe ser inspeccionado anualmente. Si no huele y no se ve, no sabes que te está matando hasta que es tarde." , question: "What is Carbon Monoxide (CO) and why is it dangerous?", options: ["It is a gas that smells like rotten eggs and causes dizziness.", "It is a colorless, odorless, and highly toxic gas that displaces oxygen in the blood, caused by incomplete combustion.", "It is the gas that comes out of the air conditioner when it is low on charge.", "It is the blue smoke that comes out of clean burners."], explanation: "It is the silent killer. That is why every furnace should be inspected annually. If it has no smell and cannot be seen, you will not know it is killing you until it is too late." },
  { id:"calef_325", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica un color de llama 'naranja' constante en lugar de azul?", opciones:["Que el gas es de muy alta potencia.", "Presencia de polvo, minerales de un humidificador cercano o falta parcial de aire; si es amarilla opaca, es falta de aire severa y produce hollín.", "Es el color normal del gas propano.", "Indica que el sensor de llama está nuevo."], respuesta_correcta:1, explicacion:"Si es naranja brillante, suele ser polvo quemándose. Si es amarillo oscuro y opaco, es mala combustión (falta de oxígeno)." , question: "What does a constant orange flame color instead of blue indicate?", options: ["The gas is very high powered.", "Dust, minerals from a nearby humidifier, or a partial lack of air; if it is an opaque yellow, it indicates severe air deficiency and produces soot.", "It is the normal color of propane gas.", "It indicates the flame sensor is new."], explanation: "If it is a bright orange, it is usually dust particles burning. If it is a dark, opaque yellow, it is poor combustion (oxygen deficiency)." },
  { id:"calef_326", categoria:"CALEF_HORNOS", pregunta:"¿Qué es la 'Rectificación de Llama'?", opciones:["El proceso de limpiar los quemadores con un cepillo.", "Convertir una señal pequeña de AC en DC a través de la llama para confirmar a la placa que hay fuego seguro.", "Cambiar la dirección de la llama hacia el centro del tubo.", "Ajustar la presión del gas para que la llama no baile."], respuesta_correcta:1, explicacion:"La llama actúa como un diodo. Deja pasar la corriente en un solo sentido. La placa detecta este cambio y sabe que el fuego es real." , question: "What is Flame Rectification?", options: ["The process of cleaning the burners with a brush.", "Converting a small AC signal into DC through the flame to confirm to the control board that a safe fire is present.", "Redirecting the flame toward the center of the tube.", "Adjusting gas pressure so the flame does not dance."], explanation: "The flame acts as a diode. It allows current to pass in only one direction. The board detects this change and knows the fire is real." },
  { id:"calef_327", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica el término 'Tiro Inducido' (Induced Draft)?", opciones:["Que el humo sale por gravedad natural.", "Que un pequeño motor (inductor) succiona los gases de combustión a través del intercambiador y los empuja hacia la chimenea.", "Que el aire de la casa se usa para empujar el humo.", "Es un sistema que no requiere chimenea metálica."], respuesta_correcta:1, explicacion:"Es el estándar en hornos de 80% y 90%. El motorcito asegura que el humo siempre vaya hacia afuera, sin importar si hace viento o no." , question: "What does the term Induced Draft mean?", options: ["The flue gas exits by natural gravity.", "A small motor (inducer) pulls combustion gases through the heat exchanger and pushes them toward the chimney.", "Household air is used to push the flue gas.", "It is a system that does not require a metal chimney."], explanation: "This is the standard in 80% and 90% furnaces. The small motor ensures the flue gas always goes outside, regardless of whether it is windy or not." },
  { id:"calef_328", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Interruptor de Límite Alto' (High Limit Switch)?", opciones:["Regular la temperatura de la habitación.", "Seguridad: apaga el gas si el horno se calienta demasiado (ej. por un filtro tapado) para evitar que el metal se derrita o cause un incendio.", "Encender el ventilador cuando el fuego está listo.", "Medir la presión del gas natural en la calle."], respuesta_correcta:1, explicacion:"Es el ángel de la guarda del horno. Si el aire no se mueve, el horno se vuelve un soplete peligroso. El Limit Switch corta el fuego antes de que pase algo malo." , question: "What is the function of the High Limit Switch?", options: ["To regulate the room temperature.", "Safety: it shuts off the gas if the furnace overheats (e.g., due to a clogged filter) to prevent the metal from melting or causing a fire.", "To turn on the blower when the fire is ready.", "To measure the natural gas pressure at the street."], explanation: "It is the furnace's guardian angel. If the air is not moving, the furnace becomes a dangerous blowtorch. The limit switch cuts the fire before something bad happens." },
  { id:"calef_329", categoria:"CALEF_HORNOS", pregunta:"¿Qué es un 'Venteo de Doble Tubería' (Two-Pipe System) en hornos de 90%?", opciones:["Una tubería para el gas y otra para el agua.", "Un tubo saca el humo al exterior y el otro trae aire fresco de afuera para la combustión; es el sistema más seguro y eficiente.", "Sirve para ventear dos hornos a la vez por el mismo tubo.", "Es un sistema para casas con dos termostatos."], respuesta_correcta:1, explicacion:"Se llama 'Direct Vent'. No usa el aire de adentro de la casa. Esto evita que el horno se ensucie con el polvo de la casa y que 'robe' el aire caliente que acabas de pagar." , question: "What is a Two-Pipe Vent System (Direct Vent) on a 90%+ furnace?", options: ["One pipe for gas and another for water.", "One pipe exhausts the flue gas outdoors and the other brings fresh air from outside for combustion; it is the safest and most efficient system.", "It is used to vent two furnaces simultaneously through the same pipe.", "It is a system for homes with two thermostats."], explanation: "It is called Direct Vent. It does not use indoor air. This prevents the furnace from getting dirty with household dust and from stealing the warm air you already paid to heat." },
  { id:"calef_330", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica un zumbido fuerte en la válvula de gas cuando el horno enciende?", opciones:["Que el gas natural tiene mucha presión.", "Falla inminente de la bobina del solenoide de la válvula o un problema de bajo voltaje desde el transformador de control.", "Es el sonido normal de los hornos de alta ingeniería.", "Indica que el sensor de llama está mandando una señal muy fuerte."], respuesta_correcta:1, explicacion:"La válvula debe ser silenciosa. Si zumba, es que la parte eléctrica está vibrando porque no tiene fuerza para quedarse abierta. Toca revisar voltajes." , question: "What does a loud buzzing from the gas valve when the furnace ignites indicate?", options: ["The natural gas has too much pressure.", "An imminent solenoid coil failure in the gas valve or a low-voltage issue from the control transformer.", "It is the normal sound of high-end furnaces.", "It indicates the flame sensor is sending a very strong signal."], explanation: "The valve should be silent. If it buzzes, it means the electrical component is vibrating because it does not have enough power to stay fully open. Voltages need to be checked." },
  { id:"calef_331", categoria:"CALEF_HORNOS", pregunta:"¿Qué sucede si el tubo de escape de PVC tiene una 'barriga' o pandeo y se llena de agua?", opciones:["El agua ayuda a filtrar el humo.", "Bloquea el paso de los gases, el motor inductor no puede empujar el aire y el interruptor de presión apaga el horno.", "El motor inductor aumentará su velocidad al doble.", "El condensado se volverá menos ácido."], respuesta_correcta:1, explicacion:"El tubo debe estar inclinado hacia el horno. Si se cuelga y hace una 'U', el agua se queda ahí y tapa el tubo. El horno se bloquea y te quedas sin calor." , question: "What happens if the PVC exhaust pipe has a belly or sag that fills with water?", options: ["The water helps filter the flue gas.", "It blocks the passage of flue gases; the inducer motor cannot push the air, and the pressure switch shuts the furnace down.", "The inducer motor will double its speed.", "The condensate will become less acidic."], explanation: "The pipe must be sloped back toward the furnace. If it sags and forms a U-shape, water pools there and blocks the pipe. The furnace locks out and you lose heat." },
  { id:"calef_332", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un horno nunca debe operarse con el panel del soplador abierto?", opciones:["Porque hace mucho ruido.", "Riesgo de succionar gases de combustión directamente de la cámara y distribuirlos por toda la casa; además del peligro de las aspas en movimiento.", "El filtro de aire se ensucia más rápido.", "La placa de control se sobrecalienta por falta de flujo."], respuesta_correcta:1, explicacion:"Es una regla de oro. Si quitas la tapa, el ventilador 'chupa' aire de donde puede, incluyendo el humo del quemador. Por eso hay un switch de seguridad en la puerta." , question: "Why must a furnace never be operated with the blower panel open?", options: ["Because it makes too much noise.", "Risk of drawing combustion gases directly from the combustion chamber and distributing them throughout the house; plus the danger of exposed moving fan blades.", "The air filter gets dirty faster.", "The control board overheats due to lack of airflow."], explanation: "This is a golden rule. If you remove the cover, the blower pulls air from wherever it can, including flue gas from the burner. That is why there is a safety interlock switch on the door." },
  { id:"calef_333", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un intercambiador de calor de acero aluminizado falla más rápido que uno de acero inoxidable en un ambiente con alta humedad?", opciones:["Porque el aluminio atrae más el gas natural.", "Debido a que el recubrimiento de aluminio se degrada por la condensación ácida, permitiendo que el acero base se oxide y se perfore (picaduras).", "El acero inoxidable es un mejor conductor térmico por radiación.", "Es una cuestión de peso estructural en el gabinete."], respuesta_correcta:1, explicacion:"El acero aluminizado es bueno, pero si el horno condensa agua (aunque sea un poco), el ácido se 'come' el aluminio y luego el hierro. El inoxidable resiste esa corrosión química." , question: "Why does an aluminized steel heat exchanger fail faster than a stainless steel one in a high-humidity environment?", options: ["Because aluminum attracts more natural gas.", "Because the aluminum coating degrades from acidic condensation, allowing the base steel to oxidize and develop pitting corrosion.", "Stainless steel is a better thermal conductor by radiation.", "It is a matter of structural weight in the cabinet."], explanation: "Aluminized steel is good, but if the furnace condenses even a small amount of water, the acid eats through the aluminum and then the iron. Stainless steel resists that chemical corrosion." },
  { id:"calef_334", categoria:"CALEF_HORNOS", pregunta:"¿Cuál es la función del 'Anillo Restrictor' (Orifice Plate) en el motor inductor de algunos hornos de alta eficiencia?", opciones:["Reducir el ruido del motor hacia el exterior.", "Ajustar el flujo de aire de combustión exacto para la capacidad del horno (BTU), evitando un exceso de aire que baje la eficiencia.", "Prevenir que los pájaros entren al motor.", "Aumentar la temperatura de los gases de escape mediante fricción."], respuesta_correcta:1, explicacion:"Los motores inductores suelen ser genéricos para varios tamaños de hornos. El restrictor 'calibra' cuánta succión real necesita ese modelo específico para quemar bien el gas." , question: "What is the function of the Restrictor Ring (Orifice Plate) in the inducer motor of some high-efficiency furnaces?", options: ["To reduce motor noise toward the exterior.", "To calibrate the exact combustion airflow for the furnace capacity (BTU), preventing excess air that would lower efficiency.", "To prevent birds from entering the motor.", "To increase the flue gas temperature through friction."], explanation: "Inducer motors are often generic across several furnace sizes. The restrictor ring calibrates how much actual suction that specific model needs to burn the gas properly." },
  { id:"calef_335", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama que 'flota' y se separa del quemador haciendo un sonido de soplete (roaring)?", opciones:["Presión de gas excesiva en el manifold.", "Falta de aire primario mezclado con el gas antes de la ignición.", "Que el sensor de llama está demasiado limpio.", "El gas natural está mezclado con nitrógeno líquido."], respuesta_correcta:0, explicacion:"Si el gas sale con demasiada presión, sale más rápido de lo que el fuego puede quemarlo. La llama se 'despega' y puede apagarse sola, además de estresar el metal." , question: "What does a flame that floats and separates from the burner with a roaring torch sound indicate?", options: ["Excessive gas pressure at the manifold.", "Insufficient primary air mixed with the gas before ignition.", "The flame sensor is too clean.", "The natural gas is mixed with liquid nitrogen."], explanation: "If the gas exits at too much pressure, it comes out faster than the fire can burn it. The flame lifts off and can extinguish on its own, besides stressing the metal." },
  { id:"calef_336", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un horno de condensación no puede compartir el venteo de PVC con otro aparato de gas de tiro natural?", opciones:["Porque el PVC se vería feo junto al metal.", "La presión positiva del motor inductor del horno empujaría los gases de combustión (CO) hacia el interior de la casa a través del otro aparato.", "El condensado del horno apagaría el piloto del otro equipo.", "Es una norma para vender más tubería de plástico."], respuesta_correcta:1, explicacion:"El motor del horno 'empuja'. Si el otro equipo no tiene motor, el humo del horno se irá por el camino más fácil: hacia el interior de la casa por el otro aparato." , question: "Why can a condensing furnace not share its PVC vent with another natural draft gas appliance?", options: ["Because PVC would look unattractive next to metal.", "The positive pressure from the furnace inducer motor would push combustion gases (CO) into the living space through the other appliance.", "The furnace condensate would extinguish the other appliance's pilot.", "It is a regulation to sell more plastic pipe."], explanation: "The furnace motor pushes. If the other appliance has no motor, the furnace flue gas will take the path of least resistance: back into the house through the other appliance." },
  { id:"calef_337", categoria:"CALEF_HORNOS", pregunta:"Un horno muestra el código de 'Interruptor de Presión falló al abrir'. El técnico mide el switch y está cerrado con el horno apagado. ¿Qué es lo más probable?", opciones:["El motor inductor está girando por inercia.", "El switch está mecánicamente trabado (pegado) o hay un puente eléctrico ilegal entre los cables.", "La chimenea tiene un tiro natural excesivo.", "La placa de control necesita ser reseteada."], respuesta_correcta:1, explicacion:"La placa chequea que el switch esté ABIERTO antes de prender el inductor. Si está CERRADO sin aire, la placa sabe que el sensor no sirve y bloquea el sistema." , question: "A furnace shows a code for Pressure Switch failed to open. The technician measures the switch and it is closed with the furnace off. What is the most likely cause?", options: ["The inducer motor is spinning from inertia.", "The switch is mechanically stuck (welded contacts) or there is an illegal electrical jumper between the wires.", "The chimney has excessive natural draft.", "The control board needs to be reset."], explanation: "The board checks that the switch is OPEN before starting the inducer. If it is CLOSED without airflow, the board knows the sensor is faulty and locks the system out." },
  { id:"calef_338", categoria:"CALEF_HORNOS", pregunta:"Usted nota que las llamas del horno 'bailan' violentamente solo cuando el cliente abre la puerta del garaje. ¿Qué indica esto?", opciones:["Que el garaje está muy frío.", "Problema de presurización de la casa o falta de aire de combustión dedicado; el horno está compitiendo por aire con el exterior.", "El sensor de llama está captando ondas de radio del control del garaje.", "Es un fenómeno normal de inducción neumática."], respuesta_correcta:1, explicacion:"El horno necesita aire. Si al abrir una puerta grande el fuego cambia, es que el horno está 'sufriendo' para conseguir oxígeno. Necesita una entrada de aire de combustión propia." , question: "You notice the furnace flames dance violently only when the customer opens the garage door. What does this indicate?", options: ["The garage is too cold.", "A house pressurization problem or lack of dedicated combustion air; the furnace is competing for air with the outdoors.", "The flame sensor is picking up radio waves from the garage door opener.", "It is a normal phenomenon of pneumatic induction."], explanation: "The furnace needs air. If opening a large door changes the fire, the furnace is struggling to get oxygen. It needs its own dedicated combustion air intake." },
  { id:"calef_339", categoria:"CALEF_HORNOS", pregunta:"¿Por qué los tubos de escape de PVC de los hornos de alta eficiencia se vuelven quebradizos con el tiempo?", opciones:["Debido a la exposición constante a la luz del sol únicamente.", "Por el ataque químico del condensado ácido y los ciclos constantes de calor y frío que degradan los polímeros del plástico.", "El gas natural disuelve el pegamento del PVC.", "Porque el motor inductor los hace vibrar a 60 Hz."], respuesta_correcta:1, explicacion:"El PVC no es eterno. El calor y el ácido lo van 'secando'. Por eso en cada inspección hay que revisar que no tengan grietas por donde se escape el CO." , question: "Why do PVC exhaust pipes on high-efficiency furnaces become brittle over time?", options: ["Due to constant exposure to sunlight only.", "Due to the chemical attack of acidic condensate and the constant heat-cool cycles that degrade the plastic polymers.", "Natural gas dissolves the PVC cement.", "Because the inducer motor vibrates them at 60 Hz."], explanation: "PVC does not last forever. Heat and acid gradually dry it out. That is why every inspection should check for cracks where CO could escape." },
  { id:"calef_340", categoria:"CALEF_HORNOS", pregunta:"¿Qué sucede si el 'Orificio' del quemador de gas está sucio con una tela de araña?", opciones:["La llama será más azul y potente.", "El flujo de gas será turbulento y escaso, causando que el horno no encienda o que la llama sea pequeña y amarilla (mala mezcla).", "El sensor de llama se quemará por el exceso de calor local.", "La válvula de gas explotará por la contrapresión."], respuesta_correcta:1, explicacion:"A las arañas les encanta el olor del gas. Hacen nidos en los tubos pequeños. Eso bloquea el paso y es la causa de muchas fallas de encendido en el otoño." , question: "What happens if the burner gas orifice is fouled by a spider web?", options: ["The flame will be bluer and more powerful.", "The gas flow will be turbulent and reduced, causing the furnace to fail to ignite or produce a small, yellow flame (poor mixture).", "The flame sensor will burn up from localized excess heat.", "The gas valve will explode from back-pressure."], explanation: "Spiders love the smell of gas. They build nests in the small openings. This blocks the flow and is the cause of many ignition failures in the fall." },
  { id:"calef_341", categoria:"CALEF_HORNOS", pregunta:"¿Por qué los codos de 90° en el venteo de PVC deben minimizarse en el diseño de un horno?", opciones:["Porque el PVC se ve mejor en línea recta.", "Cada codo añade una restricción de flujo (longitud equivalente) que aumenta la carga sobre el motor inductor y puede causar fallas del interruptor de presión.", "El agua del condensado se estanca en los codos rectos.", "Aumenta la temperatura del aire de suministro excesivamente."], respuesta_correcta:1, explicacion:"Un codo es como un muro para el aire. Si pones 5 codos, es como si el tubo fuera 20 pies más largo. El motor inductor no tendrá fuerza para sacar el humo." , question: "Why should 90-degree elbows be minimized in a PVC vent system design for a furnace?", options: ["Because PVC looks better in straight runs.", "Each elbow adds flow restriction (equivalent length) that increases the load on the inducer motor and can cause pressure switch failures.", "Water from condensate stagnates in straight elbows.", "It excessively increases the supply air temperature."], explanation: "An elbow is like a wall for airflow. If you install 5 elbows, it is as if the pipe were 20 additional feet long. The inducer motor will not have enough force to push the flue gas out." },
  { id:"calef_342", categoria:"CALEF_HORNOS", pregunta:"Usted observa que las llamas del horno 'rugen' (roar) y son muy cortas y transparentes. ¿Cuál es la causa?", opciones:["Falta de presión de gas.", "Exceso de aire primario (mezcla muy pobre en combustible); la llama es muy caliente pero inestable y ruidosa.", "El gas natural tiene mucha humedad.", "El sensor de llama está mandando 10 microamperios."], respuesta_correcta:1, explicacion:"Es como un soplete industrial. Si le metes mucho aire a poco gas, la llama ruge y es azul pálido. Puede apagar el horno o desgastar el metal muy rápido." , question: "You observe that the furnace flames roar and are very short and transparent. What is the cause?", options: ["Insufficient gas pressure.", "Excess primary air (very lean fuel mixture); the flame is very hot but unstable and noisy.", "The natural gas has too much moisture.", "The flame sensor is reading 10 microamps."], explanation: "It is like an industrial torch. If you force too much air into too little gas, the flame roars and turns pale blue. It can shut the furnace down or wear the metal out very quickly." },
  { id:"calef_343", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica el término 'Tiro Mecánico' (Power Venting) en un calentador de agua?", opciones:["Que el agua se calienta con electricidad.", "Que usa un ventilador para forzar la salida de los gases de escape, permitiendo el uso de tubos de plástico o distancias largas horizontales.", "Que el quemador es de alta presión hidráulica.", "Es un sistema que no requiere aire de la habitación."], respuesta_correcta:1, explicacion:"Es el motorcito que ves arriba del calentador de agua. Permite sacar el humo por la pared en lugar de tener que hacer una chimenea hasta el techo." , question: "What does the term Power Venting on a water heater refer to?", options: ["The water is heated by electricity.", "It uses a fan to force the exhaust gases out, allowing the use of plastic vent pipe or long horizontal runs.", "The burner operates on high hydraulic pressure.", "It is a system that does not require room air."], explanation: "It is the small fan you see on top of the water heater. It allows the flue gas to be vented out through the wall instead of needing a chimney all the way to the roof." },
  { id:"calef_344", categoria:"CALEF_HORNOS", pregunta:"Usted encuentra que las llamas del horno son 'verdes' y el cliente dice que acaba de limpiar los muebles con un aerosol fuerte. ¿Cuál es el diagnóstico?", opciones:["El horno está quemando el cobre del intercambiador.", "Contaminación química del aire de combustión; los vapores del aerosol se están quemando y produciendo una reacción cromática y ácidos corrosivos.", "Es una señal de que el gas natural está muy limpio.", "El sensor de llama se ha recalibrado para gas propano."], respuesta_correcta:1, explicacion:"¡Ojo! Muchos químicos (cloro, aerosoles, pintura) cambian el color del fuego al quemarse. Esto es muy malo para el horno porque esos químicos se vuelven ácidos que pudren el metal." , question: "You find that the furnace flames are green and the customer says they just cleaned the furniture with a strong aerosol spray. What is the diagnosis?", options: ["The furnace is burning the copper in the heat exchanger.", "Chemical contamination of the combustion air; the aerosol vapors are burning and producing a chromatic reaction and corrosive acids.", "It is a sign that the natural gas is very clean.", "The flame sensor has recalibrated for propane gas."], explanation: "Be careful! Many chemicals (chlorine, aerosols, paint) change the color of fire when they burn. This is very bad for the furnace because those chemicals become acids that corrode the metal." },
  { id:"calef_345", categoria:"CALEF_HORNOS", pregunta:"¿Qué sucede si el terminal de entrada de aire (Intake) está muy cerca del escape (Exhaust) en un horno de condensación?", opciones:["El horno calentará el aire de entrada y será más eficiente.", "El horno 're-circulará' sus propios gases de combustión, lo que causará una llama pobre, falta de oxígeno y bloqueos constantes del sensor de llama.", "Aumentará la presión del gas en la válvula.", "El condensado se congelará en el interior del intercambiador."], respuesta_correcta:1, explicacion:"Se llama 'Cortocircuito de aire'. El horno respira su propio humo. Como el humo no tiene oxígeno, el fuego se apaga. Siempre debe haber una distancia mínima entre los tubos." , question: "What happens if the air intake terminal is too close to the exhaust terminal on a condensing furnace?", options: ["The furnace will heat the intake air and be more efficient.", "The furnace will recirculate its own combustion gases, causing a poor flame, oxygen starvation, and constant flame sensor lockouts.", "It will increase gas pressure at the valve.", "The condensate will freeze inside the heat exchanger."], explanation: "This is called air short-circuiting. The furnace breathes its own exhaust. Since exhaust has no oxygen, the fire goes out. There must always be a minimum separation distance between the pipes." },
  { id:"calef_346", categoria:"CALEF_HORNOS", pregunta:"¿Qué indica una llama azul con una 'base naranja' que desaparece al cabo de 5 minutos de funcionamiento?", opciones:["Que el horno se está reparando solo.", "Es el polvo acumulado en el quemador quemándose al inicio; una vez que se limpia por el calor, la llama vuelve a su estado azul puro.", "Indica una fuga de gas en la válvula solenoide.", "Es el síntoma de que el intercambiador está frío."], respuesta_correcta:1, explicacion:"El polvo se quema rápido. Es normal ver un poco de naranja al arrancar un horno que ha estado apagado varias horas. No es motivo de alarma." , question: "What does a blue flame with an orange base that disappears after 5 minutes of operation indicate?", options: ["The furnace is repairing itself.", "Dust accumulated on the burner is burning off at startup; once the heat clears it, the flame returns to pure blue.", "It indicates a gas leak at the solenoid valve.", "It is a symptom of a cold heat exchanger."], explanation: "Dust burns off quickly. It is normal to see a little orange when starting a furnace that has been off for several hours. It is not cause for alarm." },
  { id:"calef_347", categoria:"CALEF_HORNOS", pregunta:"¿Por qué un terminal de escape de PVC debe tener una malla o rejilla de protección?", opciones:["Para que el gas salga con más presión.", "Evitar que pájaros, ardillas o escombros entren al tubo y bloqueen el flujo de aire, lo que causaría una falla de seguridad en el horno.", "Mejora la estética del exterior de la casa.", "Ayuda a condensar el vapor de agua más rápido."], respuesta_correcta:1, explicacion:"En otoño, las ardillas buscan lugares calientes. El tubo de escape es perfecto para ellas. Un nido ahí dentro significa una llamada de servicio el primer día de frío." , question: "Why must a PVC exhaust terminal have a screen or protective guard?", options: ["So the gas exits with more pressure.", "To prevent birds, squirrels, or debris from entering the pipe and blocking airflow, which would cause a safety failure in the furnace.", "It improves the aesthetics of the home exterior.", "It helps condense water vapor faster."], explanation: "In autumn, squirrels look for warm places. The exhaust pipe is perfect for them. A nest inside means a service call on the first cold day." },
  { id:"calef_348", categoria:"CALEF_HORNOS", pregunta:"¿Qué sucede si el sensor de llama está demasiado lejos del quemador?", opciones:["La llama durará más tiempo encendida.", "El horno se apagará a los pocos segundos (falla de detección) porque el sensor no 'siente' el flujo de electrones de la llama de forma estable.", "El ignitor se calentará hasta derretirse.", "La válvula de gas abrirá con el doble de presión."], respuesta_correcta:1, explicacion:"El sensor debe estar 'bañado' en fuego. Si solo lo toca la punta o está lejos, la señal es débil y la placa, por seguridad, corta el gas creyendo que el fuego se apagó." , question: "What happens if the flame sensor is positioned too far from the burner?", options: ["The flame will stay on longer.", "The furnace will shut off within a few seconds (detection failure) because the sensor cannot consistently detect the electron flow from the flame.", "The igniter will overheat until it melts.", "The gas valve will open at double pressure."], explanation: "The sensor must be immersed in the flame. If only the tip touches it or it is too far away, the signal is weak and the board cuts the gas for safety, thinking the flame went out." },

  // -- Combustión y Venteo (349-405) --
  { id:"calef_349", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es el subproducto más peligroso de una llama de gas natural que 'parece' estar quemando bien (azul) pero tiene exceso de aire primario?", opciones:["Dióxido de carbono (CO2) excesivo.", "Aldehídos y posible desprendimiento de llama.", "Hollín negro sólido.", "Vapor de agua corrosivo."], respuesta_correcta:1, explicacion:"El exceso de aire primario puede 'levantar' la llama del quemador, causando una combustión incompleta que genera aldehídos antes de llegar a producir CO masivo." , question: "What is the most dangerous byproduct of a natural gas flame that appears to be burning well (blue) but has excess primary air?", options: ["Excessive carbon dioxide (CO2).", "Aldehydes and possible flame lift-off.", "Solid black soot.", "Corrosive water vapor."], explanation: "Excess primary air can lift the flame off the burner, causing incomplete combustion that generates aldehydes before reaching the point of massive CO production." },
  { id:"calef_350", categoria:"CALEF_COMBUSTION", pregunta:"En una caldera de condensación de alta eficiencia, ¿qué fenómeno físico permite alcanzar eficiencias superiores al 90% en comparación con una caldera estándar?", opciones:["El uso de quemadores de premezcla total con exceso de aire lambda 1.5.", "La recuperación del calor latente de vaporización mediante la licuación del vapor de agua en los gases de combustión.", "La eliminación total de la ventilación mecánica en el tiro de la chimenea.", "El incremento de la temperatura de llama adiabática mediante deflectores de cerámica refractaria de alta densidad."], respuesta_correcta:1, explicacion:"Las calderas de condensación enfrían los gases de escape hasta que el vapor de agua se condensa, liberando calor extra que las calderas convencionales desperdician por la chimenea." , question: "In a high-efficiency condensing boiler, what physical phenomenon allows efficiencies above 90% compared to a standard boiler?", options: ["The use of full premix burners with excess air lambda of 1.5.", "The recovery of latent heat of vaporization by condensing the water vapor in the combustion gases.", "The total elimination of mechanical ventilation in the chimney draft.", "The increase of the adiabatic flame temperature through high-density refractory ceramic deflectors."], explanation: "Condensing boilers cool the exhaust gases until the water vapor condenses, releasing extra heat that conventional boilers waste up the chimney." },
  { id:"calef_351", categoria:"CALEF_COMBUSTION", pregunta:"En un horno de Categoría IV (Alta eficiencia), el instalador nota que el drenaje de condensado está bloqueado. ¿Qué componente de seguridad detendrá el equipo de manera inmediata?", opciones:["El sensor de llama (Flame Sensor) por falta de ionización.", "El interruptor de presión de aire (Pressure Switch) al detectar agua en el inductor o restricción en el venteo.", "El fusible térmico del transformador de 24V.", "La válvula de gas mediante su termopar de respaldo."], respuesta_correcta:1, explicacion:"El condensado acumulado en el colector restringe el paso de aire o activa un sensor de nivel en la trampa, provocando que el pressure switch abra el circuito de control." , question: "In a Category IV (high-efficiency) furnace, the installer notices the condensate drain is blocked. Which safety component will stop the equipment immediately?", options: ["The flame sensor due to lack of ionization.", "The Pressure Switch, upon detecting water in the inducer or vent restriction.", "The thermal fuse on the 24V transformer.", "The gas valve via its backup thermocouple."], explanation: "Accumulated condensate in the collector restricts the airflow or activates a level sensor in the trap, causing the pressure switch to open the control circuit." },
  { id:"calef_352", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es el color de llama que indica la presencia de monóxido de carbono debido a la 'incandescencia' de partículas de carbón no quemadas?", opciones:["Azul brillante con puntas blancas.", "Azul con núcleo naranja suave.", "Amarillo o anaranjado brillante y opaco.", "Llama invisible (detección solo por infrarrojos)."], respuesta_correcta:2, explicacion:"Una llama amarilla indica combustión incompleta. El color amarillo es causado por partículas de hollín calentadas a incandescencia, lo cual es un subproducto de la falta de oxígeno." , question: "What flame color indicates the presence of carbon monoxide due to the incandescence of unburned carbon particles?", options: ["Bright blue with white tips.", "Blue with a soft orange core.", "Bright, opaque yellow or orange.", "Invisible flame (detectable only by infrared)."], explanation: "A yellow flame indicates incomplete combustion. The yellow color is caused by soot particles heated to incandescence, which is a byproduct of oxygen deficiency." },
  { id:"calef_353", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es la función primordial del 'Shielding' o blindaje en un sensor de llama por ionización?", opciones:["Protege al sensor del calor radiante de la llama para que no se derrita.", "Previene que el polvo de carbón interfiera con la señal de microamperios.", "Evita que las interferencias electromagnéticas (ruido) del motor del inductor falseen la señal de llama.", "Asegura que la llama toque únicamente la punta de porcelana del electrodo."], respuesta_correcta:2, explicacion:"La señal de ionización es extremadamente pequeña (2-10 microamperios DC). Cualquier ruido eléctrico de motores o transformadores de ignición puede ser interpretado como llama cuando no la hay (falsa seguridad)." , question: "What is the primary function of the shielding on a flame ionization sensor?", options: ["It protects the sensor from the radiant heat of the flame so it does not melt.", "It prevents carbon dust from interfering with the microamp signal.", "It prevents electromagnetic interference (noise) from the inducer motor from falsifying the flame signal.", "It ensures the flame touches only the porcelain tip of the electrode."], explanation: "The ionization signal is extremely small (2-10 microamps DC). Any electrical noise from motors or ignition transformers can be interpreted as a flame when none exists (false safety)." },
  { id:"calef_354", categoria:"CALEF_COMBUSTION", pregunta:"¿Por qué no se permite ventear un horno de gas de Categoría I (Tiro natural) en una chimenea de mampostería sin revestimiento (liner) metálico?", opciones:["Porque el ladrillo absorbe el calor y apaga la llama del quemador.", "Debido a que los gases se enfrían demasiado rápido, condensan ácido carbónico y destruyen el mortero de la chimenea.", "Por el riesgo de que las aves aniden en el ladrillo caliente.", "El Código Internacional de Gas (IFGC) lo prohíbe solo por razones estéticas de fachada."], respuesta_correcta:1, explicacion:"Los gases de combustión contienen vapor de agua. Si tocan paredes de ladrillo frías, condensan. El agua resultante es ácida y disuelve el cemento entre los ladrillos, causando colapsos o fugas de CO." , question: "Why is it not permitted to vent a Category I (natural draft) gas furnace into an unlined masonry chimney?", options: ["Because the brick absorbs heat and extinguishes the burner flame.", "Because the gases cool too quickly, condense carbonic acid, and destroy the chimney mortar.", "Due to the risk of birds nesting in the warm brick.", "The International Fuel Gas Code (IFGC) prohibits it only for facade aesthetic reasons."], explanation: "Combustion gases contain water vapor. When they contact cold brick walls, they condense. The resulting water is acidic and dissolves the cement between the bricks, causing collapse or CO leaks." },
  { id:"calef_355", categoria:"CALEF_COMBUSTION", pregunta:"¿Por qué un sensor de llama (flame rod) puede generar una señal de microamperios errática si la conexión a tierra (ground) del chasis del horno es deficiente, a pesar de que el quemador tiene una llama azul perfecta?", opciones:["Porque la ionización requiere un camino de retorno de baja impedancia a través del metal del quemador hacia la placa de control para completar el circuito de rectificación de llama.", "Debido a que el exceso de electrones en la llama satura el aislante de porcelana del sensor.", "La falta de tierra genera un campo magnético que desvía los iones fuera del rango de detección del electrodo.", "Es un fenómeno de capacitancia parásita que ocurre solo en hornos de 80% de eficiencia."], respuesta_correcta:0, explicacion:"La rectificación de llama usa la llama como un diodo. La corriente fluye del sensor a través de la llama hacia el quemador (tierra). Sin una buena tierra, el circuito no se completa y la placa 'cree' que no hay llama." , question: "Why can a flame sensor produce an erratic microamp signal if the furnace chassis ground is deficient, despite the burner having a perfect blue flame?", options: ["Because ionization requires a low-impedance return path through the burner metal to the control board to complete the flame rectification circuit.", "Because the excess electrons in the flame saturate the porcelain insulator of the sensor.", "The lack of ground generates a magnetic field that deflects ions outside the detection range of the electrode.", "It is a parasitic capacitance phenomenon that only occurs in 80% efficiency furnaces."], explanation: "Flame rectification uses the flame as a diode. Current flows from the sensor through the flame to the burner (ground). Without a good ground, the circuit does not complete and the board thinks there is no flame." },
  { id:"calef_356", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es la razón técnica por la cual un regulador de presión de gas natural debe tener un venteo (vent) orientado hacia abajo o protegido?", opciones:["Para permitir que el gas licuado escape en caso de sobrepresión.", "Evitar que la suciedad, el agua o el hielo bloqueen el diafragma, lo que impediría que el regulador responda a cambios de presión.", "Para que el técnico pueda oler el mercaptano más fácilmente a nivel del suelo.", "Es una norma estética para no interferir con la línea de visión del edificio."], respuesta_correcta:1, explicacion:"El diafragma del regulador necesita 'respirar' aire atmosférico para equilibrar la presión del gas. Si el venteo se tapa con hielo o nidos de insectos, el regulador puede quedar bloqueado en posición abierta o cerrada." , question: "What is the technical reason a natural gas pressure regulator must have its vent oriented downward or protected?", options: ["To allow liquefied gas to escape in case of overpressure.", "To prevent dirt, water, or ice from blocking the diaphragm, which would prevent the regulator from responding to pressure changes.", "So the technician can smell the mercaptan more easily at ground level.", "It is an aesthetic standard to avoid interfering with the building's line of sight."], explanation: "The regulator diaphragm needs to breathe atmospheric air to balance the gas pressure. If the vent is blocked by ice or insect nests, the regulator can get stuck in the open or closed position." },
  { id:"calef_357", categoria:"CALEF_COMBUSTION", pregunta:"¿Por qué el exceso de aire es necesario en un quemador de gas atmosférico, a pesar de que reduce ligeramente la eficiencia térmica?", opciones:["Para evitar la formación de CO (monóxido de carbono) asegurando que cada molécula de combustible encuentre oxígeno.", "Para enfriar el intercambiador de calor y evitar que se derrita el acero inoxidable.", "Para aumentar la velocidad de los gases y mejorar el tiro natural de la chimenea.", "Porque el nitrógeno del aire actúa como un catalizador en la reacción de oxidación."], respuesta_correcta:0, explicacion:"Sin exceso de aire (aire estequiométrico perfecto), cualquier turbulencia impediría que el gas se queme totalmente, generando CO, un gas letal e inodoro." , question: "Why is excess air necessary in an atmospheric gas burner, even though it slightly reduces thermal efficiency?", options: ["To prevent the formation of CO (carbon monoxide) by ensuring every fuel molecule finds oxygen.", "To cool the heat exchanger and prevent the stainless steel from melting.", "To increase gas velocity and improve the natural draft of the chimney.", "Because the nitrogen in the air acts as a catalyst in the oxidation reaction."], explanation: "Without excess air (perfect stoichiometric air), any turbulence would prevent the gas from burning completely, generating CO, a lethal and odorless gas." },
  { id:"calef_358", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué indica técnicamente una lectura de 15 ppm de Monóxido de Carbono (CO) en el aire ambiente de un cuarto de máquinas mientras el horno está operando a plena carga?", opciones:["Es una lectura normal de fondo en zonas urbanas industriales.", "Indica una posible interferencia del intercambiador de calor o un problema de tiro (backdrafting) que requiere investigación inmediata.", "Es el umbral de activación de los sensores de ionización de bajo costo.", "Representa la eficiencia estequiométrica del 99% en la mezcla aire-combustible."], respuesta_correcta:1, explicacion:"Aunque 15 ppm no es letal de inmediato, el aire ambiente en una casa no debería tener CO detectable. Indica que los gases de combustión están escapando del sistema de venteo o del intercambiador." , question: "What does a reading of 15 ppm of Carbon Monoxide (CO) in the ambient air of a mechanical room while the furnace is operating at full load technically indicate?", options: ["It is a normal background reading in industrial urban areas.", "It indicates a possible heat exchanger breach or a draft problem (backdrafting) that requires immediate investigation.", "It is the activation threshold for low-cost ionization sensors.", "It represents 99% stoichiometric efficiency in the air-fuel mixture."], explanation: "Although 15 ppm is not immediately lethal, ambient air in a home should have no detectable CO. It indicates that combustion gases are escaping from the venting system or the heat exchanger." },
  { id:"calef_359", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es el propósito del terminal 'Vent' en una válvula de gas combinada moderna?", opciones:["Permitir la salida de gas hacia el exterior en caso de rotura del diafragma interno.", "Actuar como un puerto de medición para la presión de entrada (Inlet Pressure).", "No existe tal terminal; las válvulas modernas son selladas al vacío.", "Es una conexión para el termopar de seguridad en hornos de pie."], respuesta_correcta:0, explicacion:"El venteo de la válvula permite que el aire entre y salga detrás del diafragma para que este se mueva libremente. Si el diafragma se rompe, el gas podría salir por ahí, por lo que a menudo se conecta al área del quemador piloto para que se queme de forma segura." , question: "What is the technical purpose of the Vent terminal on a modern combination gas valve?", options: ["To allow gas to exit safely in the event of an internal diaphragm rupture.", "To act as a measurement port for inlet pressure.", "No such terminal exists; modern valves are vacuum-sealed.", "It is a connection for the thermocouple safety device on standing pilot furnaces."], explanation: "The valve vent allows air to enter and exit behind the diaphragm so it can move freely. If the diaphragm ruptures, gas could exit through this port, which is why it is often piped to the pilot burner area to be burned safely." },
  { id:"calef_360", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es la temperatura aproximada de una llama de gas natural azul 'estable' en un quemador de premezcla?", opciones:["Aproximadamente 900°C (1650°F).", "Cerca de 1950°C (3540°F).", "Exactamente 540°C para evitar la formación de óxidos de nitrógeno.", "Varía según la presión atmosférica pero nunca supera los 200°C."], respuesta_correcta:1, explicacion:"La temperatura de llama adiabática del gas natural es muy alta. Los intercambiadores se diseñan para soportar este calor radiante y transferirlo al aire sin fundirse." , question: "What is the approximate temperature of a stable blue natural gas flame in a premix burner?", options: ["Approximately 1650 degrees F (900 degrees C).", "Approximately 3540 degrees F (1950 degrees C).", "Exactly 1000 degrees F to prevent nitrogen oxide formation.", "It varies with atmospheric pressure but never exceeds 400 degrees F."], explanation: "The adiabatic flame temperature of natural gas is very high. Heat exchangers are engineered to withstand this radiant heat and transfer it to the air without melting." },
  { id:"calef_361", categoria:"CALEF_COMBUSTION", pregunta:"¿Por qué los orificios de los quemadores para Gas Propano (LP) son mucho más pequeños que los de Gas Natural para la misma capacidad de BTU?", opciones:["Porque el propano tiene una densidad menor y fluye más rápido.", "Debido a que el propano tiene un contenido energético por pie cúbico mucho mayor (aprox. 2500 BTU vs 1000 BTU).", "Para evitar que el propano se licue en la punta del quemador.", "El propano requiere menos aire primario para una combustión estequiométrica."], respuesta_correcta:1, explicacion:"Como el propano es más 'rico' en energía, se necesita menos volumen de gas para producir el mismo calor. Si usas un orificio de gas natural con propano, crearás una llama gigante y peligrosa (overfiring)." , question: "Why are propane (LP) gas burner orifices much smaller than natural gas orifices for the same BTU capacity?", options: ["Because propane has a lower density and flows faster.", "Because propane has a much higher energy content per cubic foot (approximately 2,500 BTU vs. 1,000 BTU).", "To prevent the propane from liquefying at the burner tip.", "Propane requires less primary air for stoichiometric combustion."], explanation: "Because propane is richer in energy, less volume of gas is needed to produce the same heat. If you use a natural gas orifice with propane, you will create a giant, dangerous flame (overfiring)." },
  { id:"calef_362", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es la función del aceite POE (Polyoilester) en sistemas de calefacción con bomba de calor que usan R-410A?", opciones:["Sellar las fugas microscópicas en las uniones de soldadura fuerte.", "Lubricar el compresor y asegurar el retorno de aceite gracias a su miscibilidad con refrigerantes HFC.", "Actuar como un agente desecante para absorber la humedad del sistema.", "Aumentar el punto de ebullición del refrigerante en la línea de succión."], respuesta_correcta:1, explicacion:"A diferencia de los aceites minerales antiguos, el POE es altamente soluble en R-410A, permitiendo que el aceite viaje por todo el sistema y regrese al compresor sin estancarse." , question: "What is the function of POE (Polyolester) oil in heat pump heating systems using R-410A?", options: ["To seal microscopic leaks at brazed joints.", "To lubricate the compressor and ensure oil return thanks to its miscibility with HFC refrigerants.", "To act as a desiccant agent to absorb system moisture.", "To raise the boiling point of the refrigerant in the suction line."], explanation: "Unlike older mineral oils, POE is highly soluble in R-410A, allowing the oil to travel throughout the entire system and return to the compressor without stagnating." },
  { id:"calef_363", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué fenómeno ocurre si el tiro de una chimenea es 'excesivo' en un horno de tiro natural?", opciones:["La eficiencia aumenta porque los gases salen más rápido.", "La llama se vuelve inestable y se pierde calor útil por la chimenea, bajando la eficiencia térmica.", "El condensado se congela dentro del intercambiador de calor.", "Se genera un vacío que apaga el piloto por falta de nitrógeno."], respuesta_correcta:1, explicacion:"Un tiro demasiado fuerte 'jala' el calor fuera del intercambiador antes de que este pueda transferirlo al aire de la casa, desperdiciando combustible." , question: "What happens if the chimney draft is excessive on a natural draft furnace?", options: ["Efficiency increases because the gases exit faster.", "The flame becomes unstable and useful heat is lost up the chimney, lowering thermal efficiency.", "Condensate freezes inside the heat exchanger.", "A vacuum is created that extinguishes the pilot due to lack of nitrogen."], explanation: "An overly strong draft pulls heat out of the heat exchanger before it can be transferred to the household air, wasting fuel." },
  { id:"calef_364", categoria:"CALEF_COMBUSTION", pregunta:"Al realizar un análisis de combustión, usted mide un nivel de O2 (oxígeno) del 15%. ¿Qué indica esto sobre la mezcla aire-combustible en un horno de gas natural?", opciones:["La mezcla es perfecta ya que el aire contiene 21% de oxígeno.", "Hay un exceso de aire masivo, lo que enfría la llama y reduce drásticamente la eficiencia térmica.", "Indica que el intercambiador de calor está perforado y el aire del soplador se mezcla con los gases.", "El suministro de gas es insuficiente y la válvula está operando en baja presión."], respuesta_correcta:1, explicacion:"Un 15% de O2 en los gases de escape es demasiado alto (lo ideal es 6-9% para tiro natural o menos para alta eficiencia). Significa que estás calentando aire innecesario que se va por la chimenea." , question: "When performing a combustion analysis, you measure an O2 (oxygen) level of 15%. What does this indicate about the air-fuel mixture in a natural gas furnace?", options: ["The mixture is perfect since air contains 21% oxygen.", "There is massive excess air, which cools the flame and drastically reduces thermal efficiency.", "It indicates the heat exchanger is perforated and blower air is mixing with the combustion gases.", "The gas supply is insufficient and the valve is operating at low pressure."], explanation: "A 15% O2 reading in the flue gas is far too high (ideal is 6-9% for natural draft or lower for high efficiency). It means you are heating unnecessary air that goes straight up the chimney." },
  { id:"calef_365", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué es el 'Stack Effect' (Efecto Chimenea) en un edificio alto durante el invierno y cómo afecta a la calefacción?", opciones:["Es la acumulación de hollín en los ductos de ventilación.", "El aire caliente sube por el centro del edificio, creando una presión negativa en los pisos inferiores que succiona aire frío del exterior.", "La tendencia del refrigerante a migrar hacia el punto más alto del sistema.", "Un fallo en el tiro de la caldera causado por baja presión atmosférica."], respuesta_correcta:1, explicacion:"El aire caliente es menos denso y sube. En edificios altos, esto crea un vacío en la base, aumentando las infiltraciones de aire frío y forzando a los sistemas de los pisos bajos a trabajar más." , question: "What is the Stack Effect in a tall building during winter and how does it affect heating?", options: ["The accumulation of soot in the ventilation ducts.", "Warm air rises through the center of the building, creating negative pressure on lower floors that draws cold outside air in.", "The tendency of refrigerant to migrate to the highest point in the system.", "A boiler draft failure caused by low atmospheric pressure."], explanation: "Warm air is less dense and rises. In tall buildings, this creates a vacuum at the base, increasing cold air infiltration and forcing the lower-floor heating systems to work harder." },
  { id:"calef_366", categoria:"CALEF_COMBUSTION", pregunta:"¿Por qué un nivel de CO2 muy bajo en el análisis de combustión puede ser tan malo como un nivel de CO alto?", opciones:["Porque indica que el gas no se está quemando en absoluto.", "Indica un exceso de aire de dilución masivo, lo que significa que el calor se está yendo por la chimenea en lugar de quedarse en el intercambiador.", "El CO2 bajo causa que la llama se vuelva verde y tóxica.", "Significa que el sensor del analizador está agotado y necesita recalibración."], respuesta_correcta:1, explicacion:"En combustión, el CO2 es el producto 'bueno'. Si hay poco, es porque hay demasiado aire 'sobrante' diluyendo los productos, lo que arruina la eficiencia del equipo." , question: "Why can a very low CO2 level in a combustion analysis be just as bad as a high CO level?", options: ["Because it indicates the gas is not burning at all.", "It indicates massive excess dilution air, meaning heat is going up the chimney instead of staying in the heat exchanger.", "Low CO2 causes the flame to turn green and toxic.", "It means the analyzer sensor is depleted and needs recalibration."], explanation: "In combustion, CO2 is the good product. If there is too little, it is because there is too much excess air diluting the products, which ruins the equipment efficiency." },
  { id:"calef_367", categoria:"CALEF_COMBUSTION", pregunta:"En un horno de Categoría I, ¿qué sucede si el diámetro de la chimenea es demasiado grande para el BTU del equipo?", opciones:["El tiro mejora porque hay menos fricción en las paredes del tubo.", "Los gases se enfrían demasiado rápido, pierden su fuerza de flotación y el vapor de agua condensa, causando corrosión y fallas de tiro.", "La llama se vuelve demasiado rica en oxígeno y se apaga por exceso de ventilación.", "Se crea un vacío que succiona el gas de la válvula antes de que se queme."], respuesta_correcta:1, explicacion:"Una chimenea sobredimensionada no permite que los gases mantengan la temperatura necesaria para 'flotar' hacia afuera. El gas se estanca, se enfría y el agua ácida destruye el metal del venteo." , question: "In a Category I furnace, what happens if the chimney diameter is too large for the equipment BTU rating?", options: ["The draft improves because there is less friction against the pipe walls.", "The gases cool too rapidly, lose their buoyancy, and the water vapor condenses, causing corrosion and draft failure.", "The flame becomes too oxygen-rich and extinguishes from excessive ventilation.", "A vacuum is created that pulls gas from the valve before it can burn."], explanation: "An oversized chimney does not allow the gases to maintain the temperature needed to float upward. The gas stagnates, cools, and the acidic water destroys the vent metal." },
  { id:"calef_368", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué sucede con la formación de NOx (Óxidos de Nitrógeno) si la temperatura de la llama de un horno de gas aumenta excesivamente?", opciones:["La producción de NOx disminuye porque la combustión es más limpia.", "La producción de NOx aumenta drásticamente como subproducto térmico de la reacción del nitrógeno del aire.", "El NOx se convierte en vapor de agua inofensivo mediante pirólisis.", "No hay relación entre la temperatura de llama y los contaminantes gaseosos."], respuesta_correcta:1, explicacion:"El nitrógeno en el aire es inerte a bajas temperaturas, pero a altas temperaturas de llama reacciona con el oxígeno creando NOx, un contaminante regulado por agencias ambientales." , question: "What happens to NOx (Nitrogen Oxide) formation if the flame temperature in a gas furnace increases excessively?", options: ["NOx production decreases because combustion is cleaner.", "NOx production increases dramatically as a thermal byproduct of the reaction between nitrogen in the air and oxygen.", "NOx converts to harmless water vapor through pyrolysis.", "There is no relationship between flame temperature and gaseous pollutants."], explanation: "Nitrogen in the air is inert at low temperatures, but at high flame temperatures it reacts with oxygen to create NOx, a pollutant regulated by environmental agencies." },
  { id:"calef_369", categoria:"CALEF_COMBUSTION", pregunta:"¿Por qué las tuberías de gas natural (sediment trap/dirt leg) deben instalarse antes de la entrada a la válvula de gas?", opciones:["Para aumentar la presión estática del gas por gravedad.", "Para atrapar humedad, aceites y partículas sólidas que podrían dañar los asientos internos de la válvula de gas.", "Para permitir que el gas se expanda antes de la combustión.", "Como punto de conexión obligatorio para el manómetro de columna de agua."], respuesta_correcta:1, explicacion:"La 'pata de suciedad' usa la inercia: los contaminantes pesados caen al fondo del tubo mientras el gas ligero gira hacia la válvula, protegiendo los componentes delicados." , question: "Why must a sediment trap (dirt leg) be installed on the natural gas piping before the gas valve inlet?", options: ["To increase the static gas pressure by gravity.", "To trap moisture, oils, and solid particles that could damage the internal seats of the gas valve.", "To allow the gas to expand before combustion.", "As a mandatory connection point for the water column manometer."], explanation: "The dirt leg uses inertia: heavy contaminants fall to the bottom of the pipe while the lighter gas turns into the valve, protecting the delicate internal components." },
  { id:"calef_370", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué ocurre con la presión de gas en el manifold de un horno si el orificio del quemador está parcialmente obstruido por una rebaba de metal o suciedad?", opciones:["La presión en el manifold aumenta significativamente por encima de las 3.5\" w.c.", "La presión en el manifold permanece igual (asumiendo que el regulador funciona), pero el flujo de gas real (BTU/h) disminuye.", "La válvula de gas se bloquea electrónicamente al detectar una contrapresión.", "El regulador compensa automáticamente la obstrucción aumentando la presión de entrada."], respuesta_correcta:1, explicacion:"La presión del manifold es controlada por el regulador de la válvula. Una obstrucción después de la válvula es una restricción de flujo, no una señal para que el regulador cambie su presión de salida." , question: "What happens to the manifold gas pressure in a furnace if the burner orifice is partially obstructed by a metal burr or dirt?", options: ["The manifold pressure increases significantly above 3.5 inches w.c.", "The manifold pressure remains the same (assuming the regulator is working), but the actual gas flow (BTU/h) decreases.", "The gas valve electronically locks out upon detecting back-pressure.", "The regulator automatically compensates for the obstruction by increasing the inlet pressure."], explanation: "The manifold pressure is controlled by the valve regulator. An obstruction downstream of the valve is a flow restriction, not a signal for the regulator to change its outlet pressure." },
  { id:"calef_371", categoria:"CALEF_COMBUSTION", pregunta:"¿Por qué está estrictamente prohibido usar tubería de acero galvanizado para líneas de gas natural en muchas jurisdicciones?", opciones:["Porque el galvanizado es poroso y causa micro-fugas de metano.", "Debido a que el recubrimiento de zinc puede desprenderse internamente por la reacción con el gas y obstruir los orificios de la válvula.", "El acero galvanizado tiene una resistencia eléctrica muy baja para sistemas de tierra.", "Es una restricción puramente económica para favorecer la industria del hierro negro."], respuesta_correcta:1, explicacion:"El zinc del galvanizado reacciona con trazas de humedad o químicos en el gas, creando escamas que viajan por la tubería y bloquean los pequeños puertos de los pilotos y válvulas." , question: "Why is galvanized steel pipe strictly prohibited for natural gas lines in many jurisdictions?", options: ["Because galvanized pipe is porous and causes methane micro-leaks.", "Because the zinc coating can flake off internally from reacting with the gas and obstruct valve orifices.", "Galvanized steel has very low electrical resistance for grounding systems.", "It is a purely economic restriction to favor the black iron pipe industry."], explanation: "The zinc coating reacts with traces of moisture or chemicals in the gas, creating flakes that travel through the piping and block the small ports on pilots and valves." },
  { id:"calef_372", categoria:"CALEF_COMBUSTION", pregunta:"¿A qué nivel de concentración de CO (Monóxido de Carbono) un detector de grado comercial debe activar la alarma de evacuación inmediata según la norma UL 2034?", opciones:["A 10 ppm de forma instantánea.", "A 400 ppm en un tiempo de entre 4 y 15 minutos de exposición continua.", "Solo cuando el nivel de oxígeno baja del 18%.", "A 1,000 ppm después de una hora de detección."], respuesta_correcta:1, explicacion:"Los detectores UL están diseñados para evitar falsas alarmas por niveles bajos momentáneos (como el arranque de un auto), pero a 400 ppm el riesgo de muerte es alto y la alarma debe sonar rápidamente." , question: "At what concentration level of CO (Carbon Monoxide) must a commercial-grade detector trigger an immediate evacuation alarm per UL 2034?", options: ["At 10 ppm instantaneously.", "At 400 ppm within 4 to 15 minutes of continuous exposure.", "Only when the oxygen level drops below 18%.", "At 1,000 ppm after one hour of detection."], explanation: "UL-listed detectors are designed to avoid false alarms from brief low-level spikes (such as a car starting), but at 400 ppm the risk of death is high and the alarm must sound quickly." },
  { id:"calef_373", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es el propósito técnico de un 'Draft Hood' (campana de tiro) en un calentador de agua o caldera de tiro natural?", opciones:["Evitar que el viento exterior apague el piloto directamente.", "Neutralizar el efecto de un tiro excesivo y permitir que los productos de combustión escapen si hay una obstrucción momentánea en la chimenea.", "Aumentar la temperatura de los gases de escape mediante la mezcla con aire de la habitación.", "Actuar como un sensor de temperatura mecánico para la válvula de gas."], respuesta_correcta:1, explicacion:"El draft hood separa la combustión del tiro de la chimenea. Si hay un retroceso de aire (down-draft), el aire sale por la campana en lugar de apagar la llama del quemador principal." , question: "What is the technical purpose of a Draft Hood on a natural draft water heater or boiler?", options: ["To prevent outside wind from directly extinguishing the pilot.", "To neutralize the effect of excessive draft and allow combustion products to escape if there is a momentary chimney obstruction.", "To raise the flue gas temperature by mixing with room air.", "To act as a mechanical temperature sensor for the gas valve."], explanation: "The draft hood separates the combustion process from the chimney draft. If there is a downdraft, air exits through the hood instead of blowing out the main burner flame." },
  { id:"calef_374", categoria:"CALEF_COMBUSTION", pregunta:"Usted encuentra hollín (soot) negro en los quemadores de un horno de Gas Natural. ¿Qué elemento químico no se está suministrando en cantidad suficiente?", opciones:["Nitrógeno (N2).", "Oxígeno (O2) del aire primario o secundario.", "Hidrógeno (H2) derivado de la humedad ambiente.", "Dióxido de Carbono (CO2) del aire de dilución."], respuesta_correcta:1, explicacion:"El hollín es carbón puro sin quemar. Ocurre cuando hay 'combustión rica' (falta de oxígeno). El carbono no encuentra suficiente O2 para convertirse en CO2 y se deposita como sólido negro." , question: "You find black soot on the burners of a natural gas furnace. What chemical element is not being supplied in sufficient quantity?", options: ["Nitrogen (N2).", "Oxygen (O2) from primary or secondary air.", "Hydrogen (H2) derived from ambient moisture.", "Carbon Dioxide (CO2) from dilution air."], explanation: "Soot is pure unburned carbon. It occurs during rich combustion (oxygen deficiency). The carbon cannot find enough O2 to convert to CO2 and deposits as a black solid." },
  { id:"calef_375", categoria:"CALEF_COMBUSTION", pregunta:"¿Por qué el Gas Natural requiere una rejilla de ventilación cerca del techo y el Gas Propano (LP) requiere una cerca del suelo en un cuarto de máquinas?", opciones:["Por estética y facilidad de acceso para el técnico.", "Porque el Gas Natural es más ligero que el aire (sube) y el Propano es más pesado (cae), evitando acumulaciones explosivas en caso de fuga.", "Para permitir que el monóxido de carbono escape por gravedad diferencial.", "Debido a que el propano necesita más nitrógeno para enfriar la llama."], respuesta_correcta:1, explicacion:"La gravedad específica del Gas Natural es aprox. 0.60 (flota), mientras que la del Propano es 1.50 (se hunde). Las rejillas de seguridad deben estar donde el gas se acumularía." , question: "Why does Natural Gas require a ventilation grille near the ceiling and Propane (LP) require one near the floor in a mechanical room?", options: ["For aesthetics and technician accessibility.", "Because Natural Gas is lighter than air (rises) and Propane is heavier (sinks), preventing explosive accumulations in case of a leak.", "To allow carbon monoxide to escape through differential gravity.", "Because propane needs more nitrogen to cool the flame."], explanation: "The specific gravity of Natural Gas is approximately 0.60 (it floats), while Propane is 1.50 (it sinks). Safety ventilation openings must be placed where the gas would accumulate." },
  { id:"calef_376", categoria:"CALEF_COMBUSTION", pregunta:"Usted ve chispas anaranjadas en una llama azul de gas natural. ¿Qué está ocurriendo físicamente?", opciones:["Producción masiva de Monóxido de Carbono.", "Partículas de polvo doméstico quemándose en la llama (incandescencia de impurezas).", "Fuga de refrigerante R-22 cerca del quemador.", "El gas tiene un exceso de nitrógeno líquido."], respuesta_correcta:1, explicacion:"Las motas de polvo en el aire son aspiradas por el aire primario. Al quemarse, brillan en naranja. No es peligroso, a diferencia de una llama amarilla constante y opaca." , question: "You see orange sparks in a blue natural gas flame. What is physically occurring?", options: ["Massive carbon monoxide production.", "Household dust particles burning in the flame (incandescence of impurities).", "An R-22 refrigerant leak near the burner.", "The gas has an excess of liquid nitrogen."], explanation: "Dust specks in the air are drawn in by the primary air. When they burn, they glow orange. It is not dangerous, unlike a constant, opaque yellow flame." },
  { id:"calef_377", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué es un 'B-Vent' y por qué no puede usarse con hornos de condensación de alta eficiencia?", opciones:["Es un tubo de plástico que se derrite con el calor del gas.", "Es un tubo de doble pared de metal; el ácido del condensado corroería el aluminio interno casi de inmediato.", "Es una marca comercial prohibida por la EPA.", "Solo se puede usar en sistemas de calefacción por vapor de baja presión."], respuesta_correcta:1, explicacion:"El B-Vent está diseñado para gases secos y calientes. Los hornos modernos producen condensado ácido que requiere PVC, CPVC o polipropileno para no desintegrar el ducto." , question: "What is a B-Vent and why can it not be used with high-efficiency condensing furnaces?", options: ["It is a plastic pipe that melts from gas heat.", "It is a double-wall metal pipe; the acid in the condensate would corrode the internal aluminum almost immediately.", "It is a brand name prohibited by the EPA.", "It can only be used with low-pressure steam heating systems."], explanation: "B-Vent is designed for dry, hot flue gases. Modern furnaces produce acidic condensate that requires PVC, CPVC, or polypropylene to avoid disintegrating the vent." },
  { id:"calef_378", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué mide un técnico al conectar un manómetro al puerto de 'Inlet' de una válvula de gas mientras el horno está encendido?", opciones:["La presión que va hacia los quemadores.", "La presión de suministro que llega desde el medidor de la calle, asegurando que no caiga demasiado (drop) durante la demanda.", "La velocidad del gas en pies por segundo.", "La temperatura del gas natural licuado."], respuesta_correcta:1, explicacion:"Es vital medir la entrada bajo carga. Si la presión cae mucho al encender el horno, significa que la tubería de gas es muy pequeña o el regulador de la calle está fallando." , question: "What is a technician measuring when connecting a manometer to the Inlet port of a gas valve while the furnace is firing?", options: ["The pressure going to the burners.", "The supply pressure arriving from the street meter, ensuring it does not drop excessively during demand.", "The gas velocity in feet per second.", "The temperature of the liquefied natural gas."], explanation: "It is vital to measure the inlet under load. If the pressure drops significantly when the furnace fires, the gas piping is undersized or the street regulator is failing." },
  { id:"calef_379", categoria:"CALEF_COMBUSTION", pregunta:"¿Por qué no se debe usar aire comprimido para presurizar una bomba de calor en busca de fugas?", opciones:["Porque el aire es demasiado caro.", "Porque el oxígeno y la humedad del aire reaccionan con el aceite POE y pueden causar una explosión bajo presión con el aceite.", "El aire comprimido no sale por los agujeros pequeños.", "El nitrógeno es el único gas que brilla bajo luz UV."], respuesta_correcta:1, explicacion:"La seguridad es primero. El aire contiene humedad y oxígeno que contaminan el sistema. El nitrógeno seco es inerte, estable y seguro para pruebas de presión." , question: "Why should compressed air not be used to pressure-test a heat pump for leaks?", options: ["Because air is too expensive.", "Because the oxygen and moisture in air react with POE oil and can cause an explosion under pressure.", "Compressed air does not escape through small holes.", "Nitrogen is the only gas that glows under UV light."], explanation: "Safety first. Air contains moisture and oxygen that contaminate the system. Dry nitrogen is inert, stable, and safe for pressure testing." },
  { id:"calef_380", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué es un 'Interuptor de Tiro' (Draft Spill Switch) y dónde se encuentra?", opciones:["En el termostato, para apagar el ventilador.", "En la campana de tiro de un horno de categoría I; detecta si los gases de combustión calientes están saliendo hacia la habitación en lugar de ir por la chimenea.", "En la válvula de gas, para medir la presión.", "Dentro del motor inductor para detectar vibraciones."], respuesta_correcta:1, explicacion:"Es un seguro de vida. Si la chimenea se tapa, los gases calientes (con CO) salen por la campana, calientan este sensor y este apaga el horno." , question: "What is a Draft Spill Switch and where is it located?", options: ["On the thermostat, to shut off the fan.", "On the draft hood of a Category I furnace; it detects hot combustion gases escaping into the room instead of going up the chimney.", "On the gas valve, to measure pressure.", "Inside the inducer motor to detect vibrations."], explanation: "It is a lifesaver. If the chimney is blocked, hot gases (with CO) spill out of the draft hood, heat this sensor, and it shuts the furnace down." },
  { id:"calef_381", categoria:"CALEF_COMBUSTION", pregunta:"Un horno de gas de 80,000 BTU se instala en un armario pequeño de 5'x5'. ¿Qué se requiere obligatoriamente?", opciones:["Un detector de humo dentro del armario.", "Aire de combustión traído desde afuera o desde un espacio grande (confined space rules) mediante dos aberturas permanentes.", "Pintar el armario con pintura ignífuga.", "Un ventilador de techo para que el técnico no sude."], respuesta_correcta:1, explicacion:"El horno necesita 'respirar'. Si el cuarto es muy pequeño, consumirá todo el oxígeno, la llama se volverá amarilla y producirá monóxido de carbono mortal." , question: "An 80,000 BTU gas furnace is installed in a small 5-foot by 5-foot closet. What is mandatory?", options: ["A smoke detector inside the closet.", "Combustion air brought from outdoors or from a large adjoining space (confined space rules) through two permanent openings.", "Painting the closet with fire-retardant paint.", "A ceiling fan so the technician does not overheat."], explanation: "The furnace needs to breathe. If the room is too small, it will consume all the oxygen, the flame will turn yellow, and it will produce deadly carbon monoxide." },
  { id:"calef_382", categoria:"CALEF_COMBUSTION", pregunta:"¿Por qué un horno de gas nunca debe usarse sin su panel frontal (puerta del soplador) instalado?", opciones:["Porque se ve feo.", "Porque el soplador podría succionar gases de combustión directamente de la cámara y distribuirlos por toda la casa (backdrafting).", "Para evitar que el filtro se ensucie más rápido.", "Porque el ruido sería demasiado fuerte para los residentes."], respuesta_correcta:1, explicacion:"La puerta tiene un interruptor de seguridad (interlock switch) por una razón. Sin ella, el vacío del ventilador jala el humo del quemador hacia adentro de los ductos. Es una trampa mortal." , question: "Why must a gas furnace never be operated without its front panel (blower door) installed?", options: ["Because it looks bad.", "Because the blower could draw combustion gases directly from the combustion chamber and distribute them throughout the house (backdrafting).", "To prevent the filter from getting dirty faster.", "Because the noise would be too loud for the residents."], explanation: "The door has a safety interlock switch for a reason. Without it, the blower vacuum pulls flue gas from the burner into the ductwork. It is a deadly trap." },
  { id:"calef_383", categoria:"CALEF_COMBUSTION", pregunta:"En un análisis de combustión de gas natural, ¿por qué un nivel de O2 (Oxígeno) cercano al 0% es extremadamente peligroso?", opciones:["Porque indica que la llama se va a apagar por falta de combustible.", "Es signo de una combustión estequiométrica inestable que generará niveles masivos de Monóxido de Carbono (CO) por falta de aire en exceso.", "Indica que el nitrógeno se está convirtiendo en helio.", "El analizador de gases se calibró para gas propano por error."], respuesta_correcta:1, explicacion:"Para una combustión segura en HVAC, necesitamos aire en exceso (típicamente 6-9% de O2). El 0% de O2 significa que no hay margen de error y la producción de CO será letal." , question: "In a natural gas combustion analysis, why is an O2 (Oxygen) level near 0% extremely dangerous?", options: ["Because it indicates the flame is about to go out due to lack of fuel.", "It is a sign of unstable stoichiometric combustion that will generate massive levels of Carbon Monoxide (CO) due to insufficient excess air.", "It indicates nitrogen is converting to helium.", "The gas analyzer was calibrated for propane by mistake."], explanation: "For safe combustion in HVAC, we need excess air (typically 6-9% O2). Zero percent O2 means there is no margin for error and CO production will be lethal." },
  { id:"calef_384", categoria:"CALEF_COMBUSTION", pregunta:"Una válvula de gas de 'dos etapas' (Two-Stage) recibe 24V en el terminal W1 y 24V en el terminal W2. ¿Qué presión debería medir en el manifold?", opciones:["3.5\" w.c. constantes independientemente de la señal.", "Aproximadamente 1.7\" w.c. para la etapa baja y 3.5\" w.c. para la etapa alta (en gas natural).", "10\" w.c. para compensar la segunda etapa.", "0\" w.c. porque los voltajes se anulan entre sí."], respuesta_correcta:1, explicacion:"La segunda etapa (W2) activa un solenoide adicional o ajusta el regulador para entregar el flujo máximo de gas. W1 es solo para calefacción moderada y ahorro de combustible." , question: "A two-stage gas valve receives 24V on the W1 terminal and 24V on the W2 terminal. What pressure should you measure at the manifold?", options: ["A constant 3.5 inches w.c. regardless of the signal.", "Approximately 1.7 inches w.c. for the low stage and 3.5 inches w.c. for the high stage (on natural gas).", "10 inches w.c. to compensate for the second stage.", "0 inches w.c. because the voltages cancel each other out."], explanation: "The second stage (W2) activates an additional solenoid or adjusts the regulator to deliver the maximum gas flow. W1 is only for moderate heating and fuel savings." },
  { id:"calef_385", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué es un 'Hartford Loop' y para qué sirve?", opciones:["Un tipo de radiador circular.", "Una configuración de tubería en calderas de vapor que evita que el agua se escape de la caldera si hay una rotura en la línea de retorno.", "Un sensor de presión de alta precisión.", "Un sistema de purga automática para edificios altos."], respuesta_correcta:1, explicacion:"Es un invento clásico de seguridad. Si un tubo de retorno se rompe, el agua solo puede bajar hasta cierto nivel en la caldera, evitando que esta se quede seca y explote." , question: "What is a Hartford Loop and what is it used for?", options: ["A type of circular radiator.", "A piping configuration on steam boilers that prevents water from draining out of the boiler if there is a break in the return line.", "A high-precision pressure sensor.", "An automatic purging system for tall buildings."], explanation: "It is a classic safety invention. If a return pipe breaks, the water can only drop to a certain level in the boiler, preventing the boiler from running dry and exploding." },
  { id:"calef_386", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es el subproducto de la combustión que causa el olor a 'huevos podridos' si hay una fuga de gas?", opciones:["El Metano puro.", "El Monóxido de Carbono.", "El Mercaptano (Etantiol), un aditivo odorizante añadido intencionalmente por seguridad.", "El Dióxido de Azufre natural del gas."], respuesta_correcta:2, explicacion:"El gas natural es inodoro e incoloro. Sin el mercaptano, no sabríamos que hay una fuga hasta que fuera demasiado tarde. Es un seguro de vida químico." , question: "What combustion byproduct causes the rotten egg smell when there is a gas leak?", options: ["Pure methane.", "Carbon monoxide.", "Mercaptan (Ethanethiol), an odorant intentionally added for safety.", "Naturally occurring sulfur dioxide in the gas."], explanation: "Natural gas is odorless and colorless. Without mercaptan, we would not know there is a leak until it is too late. It is a chemical lifesaver." },
  { id:"calef_387", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es el propósito técnico de la 'Placa de Orificio' en un sistema de combustión de pre-mezcla total?", opciones:["Evitar que el gas se escape hacia el termostato.", "Crear una caída de presión controlada que permita al regulador de relación aire-gas inyectar la cantidad exacta de combustible según el flujo de aire del inductor.", "Aumentar la temperatura de la llama mediante fricción molecular.", "Filtrar las partículas de nitrógeno del aire primario."], respuesta_correcta:1, explicacion:"En sistemas de alta ingeniería, el gas 'sigue' al aire. La placa de orificio genera la señal de presión necesaria para que la válvula de gas sepa cuánto abrirse proporcionalmente." , question: "What is the technical purpose of the Orifice Plate in a full premix combustion system?", options: ["To prevent gas from escaping toward the thermostat.", "To create a controlled pressure drop that allows the air-gas ratio regulator to inject the exact amount of fuel based on the inducer airflow.", "To increase flame temperature through molecular friction.", "To filter nitrogen particles from the primary air."], explanation: "In high-engineering systems, the gas follows the air. The orifice plate generates the pressure signal needed for the gas valve to know how much to open proportionally." },
  { id:"calef_388", categoria:"CALEF_COMBUSTION", pregunta:"¿Por qué el aceite mineral no se puede usar con refrigerante R-410A en una bomba de calor moderna?", opciones:["Porque el aceite mineral brilla en la oscuridad con R-410A.", "Debido a que no es miscible (no se mezcla); el aceite se quedaría atrapado en el serpentín interior y el compresor moriría por falta de lubricación.", "El aceite mineral aumenta el punto de ebullición del refrigerante demasiado.", "Es una restricción de marketing para vender aceites POE más caros."], respuesta_correcta:1, explicacion:"El aceite debe viajar con el gas y volver al motor. Si no se mezclan, el aceite se queda 'tirado' en las tuberías y el compresor se queda seco y se traba." , question: "Why can mineral oil not be used with R-410A refrigerant in a modern heat pump?", options: ["Because mineral oil glows in the dark with R-410A.", "Because it is not miscible (does not mix); the oil would get trapped in the indoor coil and the compressor would die from lack of lubrication.", "Mineral oil raises the refrigerant boiling point too much.", "It is a marketing restriction to sell more expensive POE oils."], explanation: "The oil must travel with the refrigerant gas and return to the compressor. If they do not mix, the oil gets stranded in the piping and the compressor runs dry and seizes." },
  { id:"calef_389", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué sucede con el porcentaje de CO2 en los gases de escape si aumentamos el exceso de aire en el quemador?", opciones:["El CO2 aumenta porque hay más oxígeno para reaccionar.", "El CO2 disminuye por efecto de dilución (la misma cantidad de CO2 se reparte en un volumen de aire mayor).", "El CO2 se convierte en monóxido de carbono instantáneamente.", "No hay cambio porque el carbono viene del combustible, no del aire."], respuesta_correcta:1, explicacion:"Es pura matemática de mezclas. Al meter aire de más (que no participa en la reacción), 'aguas' los productos de combustión. Por eso un CO2 bajo suele indicar un exceso de aire ineficiente." , question: "What happens to the CO2 percentage in the flue gas if we increase the excess air at the burner?", options: ["CO2 increases because there is more oxygen to react.", "CO2 decreases due to the dilution effect (the same amount of CO2 is spread across a larger volume of air).", "CO2 instantly converts to carbon monoxide.", "There is no change because the carbon comes from the fuel, not the air."], explanation: "It is simple mixture math. By adding extra air (which does not participate in the reaction), you dilute the combustion products. That is why low CO2 usually indicates an inefficient excess of air." },
  { id:"calef_390", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué es la 'Dilución de Aire' y dónde ocurre en un horno de tiro natural?", opciones:["Ocurre en el quemador para enfriar la llama.", "Ocurre en el 'Draft Diverter' (campana de tiro), donde el aire de la habitación se mezcla con los gases calientes para estabilizar el tiro y enfriar la chimenea.", "Es cuando el gas natural se mezcla con el aire primario.", "Cuando el agua se mezcla con el metano en la tubería."], respuesta_correcta:1, explicacion:"Ese aire 'extra' que entra por la campana es vital. Ayuda a que el humo suba por la chimenea y evita que ráfagas de viento apaguen el quemador de golpe." , question: "What is Air Dilution and where does it occur in a natural draft furnace?", options: ["It occurs at the burner to cool the flame.", "It occurs at the Draft Diverter (draft hood), where room air mixes with the hot flue gases to stabilize the draft and cool the chimney.", "It is when natural gas mixes with primary air.", "When water mixes with methane in the piping."], explanation: "That extra air entering through the draft hood is vital. It helps the flue gas rise through the chimney and prevents wind gusts from suddenly extinguishing the burner." },
  { id:"calef_391", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es la función del nitrógeno en la combustión de un horno de gas?", opciones:["Actuar como combustible secundario de alta potencia.", "Ninguna útil; es un gas inerte que entra con el oxígeno, absorbe calor de la llama y se lo lleva por la chimenea, reduciendo la eficiencia.", "Ayuda a estabilizar la llama azul.", "Previene la formación de vapor de agua ácido."], respuesta_correcta:1, explicacion:"El nitrógeno es un 'pasajero' molesto. Ocupa el 78% del aire. Tenemos que calentarlo para que el oxígeno reaccione, pero el nitrógeno no aporta nada de fuego, solo pérdidas térmicas." , question: "What role does nitrogen play in the combustion of a gas furnace?", options: ["It acts as a high-power secondary fuel.", "No useful role; it is an inert gas that enters with the oxygen, absorbs heat from the flame, and carries it up the chimney, reducing efficiency.", "It helps stabilize the blue flame.", "It prevents the formation of acidic water vapor."], explanation: "Nitrogen is an unwanted passenger. It makes up 78% of the air. We have to heat it so the oxygen can react, but nitrogen contributes nothing to the fire, only thermal losses." },
  { id:"calef_392", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es el pH aproximado del condensado producido por un horno de gas de alta eficiencia (90%+) y qué material de drenaje es obligatorio?", opciones:["pH neutro (7.0); se puede usar cualquier tubería metálica.", "pH ácido (entre 3.0 y 5.0); se requiere tubería de plástico (PVC/CPVC) o acero inoxidable para evitar la corrosión por ácido carbónico y nítrico.", "pH básico (9.0); requiere cobre tipo L para neutralizar los iones.", "pH de 1.0 (ácido sulfúrico puro); solo se permite vidrio borosilicatado."], respuesta_correcta:1, explicacion:"El agua de combustión reacciona con los óxidos de nitrógeno y carbono. Si ese 'jugo' toca hierro o cobre, los deshace en un par de temporadas. El plástico es el estándar de oro aquí." , question: "What is the approximate pH of the condensate produced by a high-efficiency (90%+) gas furnace and what drain material is required?", options: ["Neutral pH (7.0); any metal piping can be used.", "Acidic pH (between 3.0 and 5.0); plastic piping (PVC/CPVC) or stainless steel is required to prevent corrosion from carbonic and nitric acid.", "Basic pH (9.0); Type L copper is required to neutralize the ions.", "pH of 1.0 (pure sulfuric acid); only borosilicate glass is permitted."], explanation: "Combustion water reacts with nitrogen and carbon oxides. If that liquid touches iron or copper, it corrodes them in a couple of seasons. Plastic piping is the gold standard here." },
  { id:"calef_393", categoria:"CALEF_COMBUSTION", pregunta:"Usted mide una presión de manifold de 3.5\" w.c. en un horno de gas natural, pero la llama parece 'pobre' y pequeña. ¿Qué debería revisar después?", opciones:["Aumentar la presión a 5.0\" w.c. para compensar.", "Verificar que el orificio del quemador sea el tamaño correcto y que no haya una obstrucción física (suciedad/insectos) entre la válvula y el quemador.", "Cambiar la polaridad del transformador de 24V.", "Limpiar el sensor de llama con un cepillo de alambre grueso."], respuesta_correcta:1, explicacion:"Si la presión es correcta pero no hay fuego, el problema es el 'caño'. Un orificio muy pequeño o tapado limitará el flujo de combustible aunque la presión de empuje sea la nominal." , question: "You measure a manifold pressure of 3.5 inches w.c. on a natural gas furnace, but the flame appears weak and small. What should you check next?", options: ["Increase the pressure to 5.0 inches w.c. to compensate.", "Verify that the burner orifice is the correct size and that there is no physical obstruction (dirt/insects) between the valve and the burner.", "Reverse the polarity of the 24V transformer.", "Clean the flame sensor with a coarse wire brush."], explanation: "If the pressure is correct but the fire is weak, the problem is the passage. An orifice that is too small or clogged will limit fuel flow even though the driving pressure is at its rated value." },
  { id:"calef_394", categoria:"CALEF_COMBUSTION", pregunta:"¿Por qué un regulador de Gas LP exterior tiene un orificio de ventilación (vent) mucho más grande que uno de Gas Natural residencial?", opciones:["Para que los pájaros no aniden dentro.", "Para permitir una respuesta rápida del diafragma ante los cambios drásticos de presión del tanque y evitar que el regulador se congele por la expansión del gas.", "No son más grandes, son exactamente iguales.", "El gas LP es más viscoso y necesita más aire para respirar."], respuesta_correcta:1, explicacion:"El LP se almacena a presiones muy altas. El regulador trabaja duro reduciendo esa presión. El venteo grande permite que el aire entre y salga rápido para que el diafragma no se bloquee." , question: "Why does an outdoor LP gas regulator have a much larger vent orifice than a residential natural gas regulator?", options: ["So birds do not nest inside.", "To allow rapid diaphragm response to the drastic pressure changes from the tank and prevent the regulator from freezing due to gas expansion.", "They are not larger; they are exactly the same.", "LP gas is more viscous and needs more air to breathe."], explanation: "LP is stored at very high pressures. The regulator works hard to reduce that pressure. The large vent allows air to enter and exit quickly so the diaphragm does not seize up." },
  { id:"calef_395", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es el síntoma físico inicial más común de intoxicación por Monóxido de Carbono en una vivienda con un horno defectuoso?", opciones:["Fiebre alta y tos seca.", "Dolor de cabeza leve, náuseas y somnolencia (síntomas similares a una gripe sin fiebre).", "Erupciones cutáneas en los brazos.", "Pérdida inmediata de la visión periférica."], respuesta_correcta:1, explicacion:"El CO es el 'asesino silencioso'. No huele, no sabe. La gente cree que tiene gripe, se va a dormir para descansar, y nunca vuelve a despertar porque el CO desplaza el oxígeno en la sangre." , question: "What is the most common initial physical symptom of Carbon Monoxide poisoning in a dwelling with a defective furnace?", options: ["High fever and dry cough.", "Mild headache, nausea, and drowsiness (symptoms resembling the flu without fever).", "Skin rash on the arms.", "Immediate loss of peripheral vision."], explanation: "CO is the silent killer. It has no smell and no taste. People think they have the flu, go to sleep to rest, and never wake up because CO displaces oxygen in the blood." },
  { id:"calef_396", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es la función del 'Automatic Air Vent' (purgador automático)?", opciones:["Meter aire al sistema para aumentar la presión.", "Dejar salir las burbujas de aire que viajan por el sistema sin que se escape el agua, manteniendo la circulación silenciosa.", "Controlar la temperatura del agua.", "Drenar el lodo de la caldera."], respuesta_correcta:1, explicacion:"Es una boya pequeña. Cuando hay aire, la boya baja y abre un agujerito para que salga. Cuando llega el agua, la boya sube y cierra el paso. Es mantenimiento automático." , question: "What is the function of an Automatic Air Vent?", options: ["To inject air into the system to increase pressure.", "To release trapped air bubbles traveling through the system without losing water, maintaining quiet circulation.", "To control water temperature.", "To drain sludge from the boiler."], explanation: "It is a small float. When air is present, the float drops and opens a small orifice to release it. When water arrives, the float rises and closes the orifice. It is automatic maintenance." },
  { id:"calef_397", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué es la 'Llama de Pre-mezcla' y en qué se diferencia de una 'Llama de Difusión'?", opciones:["La de pre-mezcla es siempre amarilla y la de difusión es azul.", "En la de pre-mezcla el gas y el aire se unen antes del puerto del quemador; en la de difusión el gas se quema al encontrar el aire en la atmósfera.", "La pre-mezcla solo se usa en estufas de cocina portátiles.", "No hay diferencia técnica, son términos comerciales de los fabricantes."], respuesta_correcta:1, explicacion:"Los hornos modernos usan pre-mezcla para controlar exactamente cuánto oxígeno entra al fuego, logrando una combustión mucho más limpia y eficiente (azul)." , question: "What is a Premix Flame and how does it differ from a Diffusion Flame?", options: ["The premix flame is always yellow and the diffusion flame is blue.", "In a premix flame, the gas and air are combined before the burner port; in a diffusion flame, the gas burns as it meets the air in the atmosphere.", "Premix flames are only used in portable kitchen stoves.", "There is no technical difference; they are manufacturer trade terms."], explanation: "Modern furnaces use premix to precisely control how much oxygen enters the fire, achieving much cleaner and more efficient combustion (blue flame)." },
  { id:"calef_398", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es el efecto de la 'Humedad Atmosférica' en la producción de Óxidos de Nitrógeno (NOx) durante la combustión de gas natural?", opciones:["Aumenta el NOx porque el agua aporta más oxígeno.", "Reduce la formación de NOx ya que el vapor de agua actúa como un sumidero térmico, bajando la temperatura pico de la llama.", "No tiene efecto, el NOx solo depende de la presión del gas.", "El vapor de agua convierte el NOx en ácido sulfúrico en el intercambiador."], respuesta_correcta:1, explicacion:"El NOx se forma por calor extremo. En días húmedos, la llama es ligeramente más fría porque parte de la energía se gasta en calentar el vapor de agua del aire, lo que genera menos contaminantes." , question: "What is the effect of Atmospheric Humidity on Nitrogen Oxide (NOx) production during natural gas combustion?", options: ["It increases NOx because the water provides more oxygen.", "It reduces NOx formation because the water vapor acts as a thermal sink, lowering the peak flame temperature.", "It has no effect; NOx depends only on gas pressure.", "The water vapor converts NOx to sulfuric acid in the heat exchanger."], explanation: "NOx forms from extreme heat. On humid days, the flame is slightly cooler because part of the energy is spent heating the water vapor in the air, which produces fewer pollutants." },
  { id:"calef_399", categoria:"CALEF_COMBUSTION", pregunta:"En un análisis de combustión, un nivel de CO (Monóxido de Carbono) que sube constantemente durante el ciclo indica:", opciones:["Que el horno se está 'asentando' térmicamente.", "Un intercambiador de calor que se agrieta al expandirse o un problema de falta de aire secundario que se agrava con el calor.", "Que el gas natural tiene un alto contenido de octanaje.", "Falla en el sensor de llama por ionización."], respuesta_correcta:1, explicacion:"El CO debe estabilizarse. Si sube y sube, el fuego se está quedando sin aire o el metal se está abriendo y dejando pasar aire del soplador que 'apaga' la llama parcialmente." , question: "In a combustion analysis, a CO (Carbon Monoxide) level that rises steadily throughout the cycle indicates:", options: ["The furnace is thermally settling in.", "A heat exchanger that is cracking as it expands, or a secondary air deficiency that worsens with heat.", "The natural gas has a high octane content.", "A flame ionization sensor failure."], explanation: "CO should stabilize. If it keeps climbing, the fire is running out of air or the metal is opening up and allowing blower air in, partially extinguishing the flame." },
  { id:"calef_400", categoria:"CALEF_COMBUSTION", pregunta:"¿Qué indica técnicamente una llama azul que se vuelve 'transparente' y ruidosa al aumentar la presión del gas?", opciones:["Combustión perfecta de alta velocidad.", "Exceso de velocidad de salida que puede causar que la llama se despegue (lift) y produzca monóxido de carbono por enfriamiento brusco (quenching).", "Que el gas natural tiene un 99% de pureza de metano.", "Falla en el regulador de presión de la calle."], respuesta_correcta:1, explicacion:"El fuego necesita tiempo para quemarse. Si lo 'empujas' muy rápido, se separa del quemador. Esto es inestable y puede apagar el horno o generar gases tóxicos." , question: "What does a blue flame that becomes transparent and noisy when gas pressure is increased technically indicate?", options: ["Perfect high-velocity combustion.", "Excessive exit velocity that can cause the flame to lift off and produce carbon monoxide through abrupt cooling (quenching).", "The natural gas is 99% pure methane.", "A failure in the street pressure regulator."], explanation: "Fire needs time to burn. If you push it too fast, it separates from the burner. This is unstable and can shut the furnace down or generate toxic gases." },
  { id:"calef_401", categoria:"CALEF_COMBUSTION", pregunta:"Usted mide un nivel de CO2 del 12% en un horno de gas natural. ¿Qué indica este valor?", opciones:["Que el horno tiene un exceso de aire masivo.", "Una combustión casi estequiométrica (perfecta) con muy poco exceso de aire; se debe vigilar que el Monóxido de Carbono no suba.", "Que el gas natural está mezclado con propano.", "Falla en el motor inductor de tiro."], respuesta_correcta:1, explicacion:"El CO2 alto es bueno para la eficiencia, pero peligroso para la seguridad. Significa que hay poco aire 'sobrante'. Un pequeño cambio en el clima podría causar mala combustión." , question: "You measure a CO2 level of 12% in a natural gas furnace. What does this value indicate?", options: ["The furnace has massive excess air.", "Near-stoichiometric (near-perfect) combustion with very little excess air; Carbon Monoxide levels must be closely monitored.", "The natural gas is mixed with propane.", "An inducer motor failure."], explanation: "High CO2 is good for efficiency but risky for safety. It means there is very little excess air. A small change in conditions could cause poor combustion." },
  { id:"calef_402", categoria:"CALEF_COMBUSTION", pregunta:"Usted mide un nivel de exceso de aire del 120% en un horno de gas. ¿Qué efecto tiene esto en el Punto de Rocío de los gases de escape?", opciones:["Aumenta el punto de rocío, facilitando la condensación.", "Disminuye el punto de rocío, reduciendo el riesgo de condensación en la chimenea pero bajando drásticamente la eficiencia térmica.", "Mantiene el punto de rocío constante en 54°C.", "Convierte el vapor de agua en hidrógeno puro."], respuesta_correcta:1, explicacion:"Al meter tanto aire 'sobrante', diluyes el vapor de agua. El agua ahora necesita estar mucho más fría para condensarse. Es bueno para la chimenea, pero malo para el recibo de gas." , question: "You measure an excess air level of 120% in a gas furnace. What effect does this have on the flue gas Dew Point?", options: ["It raises the dew point, facilitating condensation.", "It lowers the dew point, reducing the risk of condensation in the chimney but drastically lowering thermal efficiency.", "It maintains the dew point constant at 130 degrees F.", "It converts water vapor into pure hydrogen."], explanation: "By adding so much excess air, you dilute the water vapor. The water now needs to be much cooler to condense. It is good for the chimney but bad for the gas bill." },
  { id:"calef_403", categoria:"CALEF_COMBUSTION", pregunta:"Usted mide un nivel de Monóxido de Carbono (CO) de 400 ppm en los gases de escape de un horno de 80% AFUE. ¿Cuál es el diagnóstico?", opciones:["Es una lectura normal para hornos de tiro natural.", "Combustión extremadamente peligrosa e incompleta; indica falta de aire, presión de gas excesiva o un intercambiador de calor bloqueado/sucio.", "El gas natural tiene un exceso de metano puro.", "El analizador de gases necesita una batería nueva."], respuesta_correcta:1, explicacion:"Cualquier lectura por encima de 100 ppm 'air free' es preocupante. 400 ppm es una fábrica de veneno. Ese horno debe apagarse y repararse antes de que alguien se intoxique." , question: "You measure a Carbon Monoxide (CO) level of 400 ppm in the flue gas of an 80% AFUE furnace. What is the diagnosis?", options: ["It is a normal reading for natural draft furnaces.", "Extremely dangerous incomplete combustion; it indicates insufficient air, excessive gas pressure, or a blocked/dirty heat exchanger.", "The natural gas has excess pure methane.", "The gas analyzer needs a new battery."], explanation: "Any reading above 100 ppm air-free is concerning. 400 ppm is a poison factory. That furnace must be shut down and repaired before someone is poisoned." },
  { id:"calef_404", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es el efecto de la 'Llama Fría' (Flame Quenching) cuando el fuego toca el metal del intercambiador?", opciones:["Aumenta la transferencia de calor por conducción directa.", "La temperatura de la llama cae por debajo del punto de ignición, deteniendo la reacción química y produciendo depósitos de hollín y Monóxido de Carbono.", "El metal se vuelve más resistente debido al templado térmico.", "El sensor de llama detecta una señal de 10 microamperios."], respuesta_correcta:1, explicacion:"El fuego nunca debe tocar el metal. El metal está mucho más frío que la llama; si chocan, el carbono del gas no termina de quemarse y se vuelve 'humo negro' y veneno." , question: "What is the effect of Flame Quenching when the fire contacts the heat exchanger metal?", options: ["It increases heat transfer through direct conduction.", "The flame temperature drops below the ignition point, halting the chemical reaction and producing soot deposits and Carbon Monoxide.", "The metal becomes more resistant due to thermal tempering.", "The flame sensor detects a 10 microamp signal."], explanation: "The fire should never touch the metal. The metal is much cooler than the flame; if they collide, the carbon in the gas does not finish burning and turns into black smoke and poison." },
  { id:"calef_405", categoria:"CALEF_COMBUSTION", pregunta:"¿Cuál es el subproducto más abundante de la combustión perfecta de gas natural (Metano) además del Dióxido de Carbono?", opciones:["Monóxido de Carbono.", "Vapor de Agua ($H_2O$).", "Azufre elemental.", "Ozono troposférico."], respuesta_correcta:1, explicacion:"Por cada molécula de metano que quemas, produces dos de agua. Por eso los hornos de alta eficiencia gotean tanto agua por el drenaje: es pura química." , question: "What is the most abundant byproduct of perfect natural gas (Methane) combustion besides Carbon Dioxide?", options: ["Carbon Monoxide.", "Water Vapor (H2O).", "Elemental Sulfur.", "Tropospheric Ozone."], explanation: "For every molecule of methane you burn, you produce two molecules of water. That is why high-efficiency furnaces drip so much water from the drain: it is pure chemistry." },

  // -- Hidrónica y Calderas (406-517) --
  { id:"calef_406", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué ocurre con la presión estática en un ducto de suministro si la velocidad del aire aumenta bruscamente debido a una restricción local (Efecto Venturi)?", opciones:["La presión estática aumenta para compensar la pérdida de carga.", "La presión estática disminuye.", "Ambas presiones, estática y dinámica, aumentan proporcionalmente al cuadrado de la velocidad del fluido.", "La presión total del sistema se vuelve negativa respecto a la presión atmosférica del retorno."], respuesta_correcta:1, explicacion:"Según el principio de Bernoulli, si la velocidad (presión dinámica) aumenta, la presión estática debe disminuir para mantener la energía constante." , question: "What happens to the static pressure in a supply duct if the air velocity increases abruptly due to a local restriction (Venturi Effect)?", options: ["The static pressure increases to compensate for the pressure loss.", "The static pressure decreases.", "Both static and dynamic pressures increase proportionally to the square of the fluid velocity.", "The total system pressure becomes negative relative to the atmospheric pressure at the return."], explanation: "According to Bernoulli's principle, if velocity (dynamic pressure) increases, static pressure must decrease to maintain constant energy." },
  { id:"calef_407", categoria:"CALEF_HIDRONICA", pregunta:"En un sistema de calefacción hidrónica con radiadores, se instala un tanque de expansión. ¿Cuál es la función técnica de este tanque 'más allá' de recibir agua caliente?", opciones:["Aumentar la presión estática para que el agua llegue a los pisos superiores.", "Proveer un punto de presión constante (Punto de No Cambio) para que la bomba circule el fluido eficientemente.", "Actuar como un separador de microburbujas de aire mediante fuerza centrífuga.", "Almacenar energía térmica residual para periodos de 'peak-shaving'."], respuesta_correcta:1, explicacion:"El tanque de expansión establece el punto de presión neutra del sistema. La ubicación de la bomba respecto a este punto determina si la bomba suma o resta presión al sistema." , question: "In a hydronic heating system with radiators, an expansion tank is installed. What is the technical function of this tank beyond receiving hot water?", options: ["To increase the static pressure so water reaches the upper floors.", "To provide a constant pressure point (Point of No Pressure Change) so the circulator pump can move the fluid efficiently.", "To act as a micro-bubble air separator through centrifugal force.", "To store residual thermal energy for peak-shaving periods."], explanation: "The expansion tank establishes the neutral pressure point of the system. The pump's location relative to this point determines whether the pump adds or subtracts pressure from the system." },
  { id:"calef_408", categoria:"CALEF_HIDRONICA", pregunta:"En una unidad de split system, ¿por qué la línea de 'líquido' (la más delgada) está caliente al tacto durante el modo de calefacción?", opciones:["Porque transporta refrigerante en estado líquido a alta presión hacia la válvula de expansión exterior.", "Debido a la fricción interna del refrigerante al pasar por el filtro deshidratador.", "Porque técnicamente en modo calor funciona como una línea de descarga de vapor a alta presión.", "Por el calor radiante del compresor que se transmite por conducción metálica."], respuesta_correcta:2, explicacion:"Capciosa: En modo calor, la válvula reversible cambia los roles. La línea pequeña transporta el gas caliente del compresor hacia la unidad interior (que ahora es el condensador)." , question: "In a split system, why is the liquid line (the thinner one) hot to the touch during heating mode?", options: ["Because it carries high-pressure liquid refrigerant toward the outdoor expansion valve.", "Due to internal refrigerant friction passing through the filter-drier.", "Because in heating mode it technically functions as a high-pressure hot gas discharge line.", "Due to radiant heat from the compressor transmitted through metallic conduction."], explanation: "Tricky: In heating mode, the reversing valve swaps the roles. The small line carries hot gas from the compressor to the indoor unit (which is now the condenser)." },
  { id:"calef_409", categoria:"CALEF_HIDRONICA", pregunta:"En un sistema híbrido Solar-Bomba de Calor, ¿cuál es el beneficio técnico de precalentar el aire de entrada al evaporador exterior en invierno?", opciones:["Reduce el consumo de amperaje del motor del ventilador exterior.", "Aumenta la presión de succión, elevando el COP (Coefficient of Performance) del sistema.", "Evita que el aceite del compresor se carbonate por exceso de frío.", "Permite que la válvula reversible trabaje a menor presión diferencial."], respuesta_correcta:1, explicacion:"Al calentar el aire de entrada, el refrigerante evapora a una presión y temperatura más alta. El compresor trabaja menos (menor relación de compresión) para alcanzar la temperatura de condensación, subiendo la eficiencia." , question: "In a hybrid Solar-Heat Pump system, what is the technical benefit of preheating the air entering the outdoor evaporator in winter?", options: ["It reduces the amperage consumption of the outdoor fan motor.", "It raises the suction pressure, increasing the system COP (Coefficient of Performance).", "It prevents the compressor oil from carbonizing due to extreme cold.", "It allows the reversing valve to operate at a lower pressure differential."], explanation: "By heating the intake air, the refrigerant evaporates at a higher pressure and temperature. The compressor works less (lower compression ratio) to reach the condensing temperature, increasing efficiency." },
  { id:"calef_410", categoria:"CALEF_HIDRONICA", pregunta:"En un sistema de calefacción por suelo radiante, ¿por qué es imperativo instalar una válvula mezcladora termostática antes del colector (manifold)?", opciones:["Para aumentar la velocidad del fluido mediante el efecto Venturi.", "Para evitar que el agua a alta temperatura de la caldera dañe la estructura del suelo o degrade las tuberías de PEX.", "Porque el suelo radiante requiere agua a 180°F para ser eficiente en climas bajo cero.", "Para separar el aire del agua mediante un proceso de desaireación térmica."], respuesta_correcta:1, explicacion:"Las calderas suelen operar a temperaturas altas (140°F-180°F), pero el suelo radiante típicamente no debe exceder los 100°F-110°F para evitar grietas en el concreto y falta de confort térmico." , question: "In a radiant floor heating system, why is it imperative to install a thermostatic mixing valve before the manifold?", options: ["To increase fluid velocity through the Venturi effect.", "To prevent high-temperature water from the boiler from damaging the floor structure or degrading the PEX tubing.", "Because radiant floor heating requires 180 degrees F water to be efficient in below-zero climates.", "To separate air from water through a thermal deaeration process."], explanation: "Boilers typically operate at high temperatures (140-180 degrees F), but radiant floor heating should not exceed about 100-110 degrees F to prevent concrete cracking and thermal discomfort." },
  { id:"calef_411", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función técnica del acumulador de succión en una bomba de calor durante el cambio de modo frío a calor?", opciones:["Almacena refrigerante líquido excedente para evitar que entre al compresor durante las inestabilidades del ciclo.", "Actúa como un intercambiador de calor para sub-enfriar la línea de líquido.", "Filtra las impurezas sólidas antes de que el gas llegue a la válvula reversible.", "Mantiene la presión de aceite constante mediante una bomba de inyección interna."], respuesta_correcta:0, explicacion:"Al invertir el ciclo, grandes cantidades de líquido pueden desplazarse. El acumulador asegura que solo vapor llegue a la succión del compresor, evitando el golpe de líquido." , question: "What is the technical function of the suction accumulator in a heat pump during the switch from cooling to heating mode?", options: ["It stores excess liquid refrigerant to prevent it from entering the compressor during cycle instabilities.", "It acts as a heat exchanger to subcool the liquid line.", "It filters solid impurities before the gas reaches the reversing valve.", "It maintains constant oil pressure through an internal injection pump."], explanation: "When the cycle reverses, large amounts of liquid can shift. The accumulator ensures that only vapor reaches the compressor suction, preventing liquid slugging." },
  { id:"calef_412", categoria:"CALEF_HIDRONICA", pregunta:"Una bomba circuladora en un sistema de calefacción hace un ruido similar a 'canicas golpeando el metal'. ¿Cuál es la causa técnica?", opciones:["Rodamientos secos por falta de lubricación manual.", "Cavitación causada por una presión estática insuficiente en la entrada (succión) de la bomba.", "El impulsor está rozando contra el sedimento de magnetita acumulado.", "Flujo turbulento causado por un exceso de glicol en la mezcla."], respuesta_correcta:1, explicacion:"La cavitación ocurre cuando la presión cae por debajo de la presión de vapor del líquido, formando burbujas que colapsan violentamente contra el impulsor." , question: "A circulator pump in a heating system makes a sound like marbles hitting metal. What is the technical cause?", options: ["Dry bearings from lack of manual lubrication.", "Cavitation caused by insufficient static pressure at the pump inlet (suction).", "The impeller is rubbing against accumulated magnetite sediment.", "Turbulent flow caused by an excess of glycol in the mixture."], explanation: "Cavitation occurs when the pressure drops below the vapor pressure of the liquid, forming bubbles that collapse violently against the impeller." },
  { id:"calef_413", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es el propósito del fluido caloportador (glicol) en un sistema solar de circuito cerrado?", opciones:["Aumentar la viscosidad para que la bomba trabaje a menor velocidad.", "Evitar el congelamiento de las tuberías exteriores y prevenir la corrosión interna del colector.", "Absorber los rayos UV y convertirlos en energía infrarroja.", "Actuar como un aislante térmico en las tuberías de retorno."], respuesta_correcta:1, explicacion:"En climas fríos, el agua pura rompería los paneles al congelarse. El glicol baja el punto de congelación y contiene inhibidores de corrosión para proteger el cobre." , question: "What is the purpose of the heat transfer fluid (glycol) in a closed-loop solar thermal system?", options: ["To increase viscosity so the pump runs at a lower speed.", "To prevent freezing of the outdoor piping and prevent internal corrosion of the collector.", "To absorb UV rays and convert them to infrared energy.", "To act as thermal insulation in the return piping."], explanation: "In cold climates, pure water would freeze and burst the solar panels. Glycol lowers the freezing point and contains corrosion inhibitors to protect the copper." },
  { id:"calef_414", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Air Binding' en un sistema de radiadores de agua caliente?", opciones:["Un proceso de limpieza de tuberías usando aire a presión.", "Una condición donde una burbuja de aire atrapada impide la circulación del agua en un circuito, dejando el radiador frío.", "La mezcla intencional de aire y agua para mejorar la transferencia de calor convectiva.", "El uso de aire comprimido para accionar las válvulas de zona."], respuesta_correcta:1, explicacion:"El aire es menos denso que el agua y se acumula en los puntos altos. Si hay suficiente aire, la bomba no tiene suficiente fuerza (cabeza) para empujar el agua a través de la bolsa de aire, deteniendo el flujo." , question: "What is Air Binding in a hot water radiator system?", options: ["A process of cleaning piping using pressurized air.", "A condition where a trapped air bubble prevents water circulation in a circuit, leaving the radiator cold.", "The intentional mixing of air and water to improve convective heat transfer.", "The use of compressed air to actuate zone valves."], explanation: "Air is less dense than water and collects at high points. If enough air accumulates, the pump does not have enough head to push the water through the air pocket, stopping flow." },
  { id:"calef_415", categoria:"CALEF_HIDRONICA", pregunta:"Usted mide una Presión Estática Total Externa (TESP) de 0.90\" w.c. en un horno cuya placa especifica un máximo de 0.50\" w.c. ¿Qué consecuencia directa tiene esto?", opciones:["El flujo de aire (CFM) será mayor al diseño, enfriando demasiado el intercambiador.", "La vida útil del motor se reducirá y el intercambio de calor será ineficiente (posible tripeo de límite alto).", "La presión dinámica se convertirá en vacío en el retorno.", "El filtro de aire se limpiará solo por el efecto de succión incrementada."], respuesta_correcta:1, explicacion:"Una presión estática alta significa que el aire tiene dificultades para moverse. Menos aire pasando por el intercambiador significa que este se calienta demasiado, activando el límite de seguridad y forzando el motor." , question: "You measure a Total External Static Pressure (TESP) of 0.90 inches w.c. on a furnace whose nameplate specifies a maximum of 0.50 inches w.c. What is the direct consequence?", options: ["The airflow (CFM) will exceed the design, overcooling the heat exchanger.", "The motor lifespan will be shortened and heat exchange will be inefficient (possible high limit trip).", "The dynamic pressure will convert to vacuum at the return.", "The air filter will self-clean due to the increased suction effect."], explanation: "High static pressure means the air has difficulty moving. Less air passing over the heat exchanger means it overheats, tripping the safety limit and overworking the motor." },
  { id:"calef_416", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué se bloquea el ventilador exterior durante el ciclo de descongelación (defrost) en una bomba de calor?", opciones:["Para evitar que el motor del ventilador se moje con el agua derretida.", "Para acelerar el aumento de presión y temperatura en el serpentín exterior para derretir el hielo más rápido.", "Debido a que el compresor se apaga y no hay necesidad de flujo de aire.", "Para ahorrar energía eléctrica durante los 10 minutos que dura el proceso."], respuesta_correcta:1, explicacion:"Si el ventilador siguiera encendido, el aire frío exterior enfriaría el serpentín, retrasando el derretimiento del hielo. Al apagarlo, el calor del refrigerante se concentra en el metal del serpentín." , question: "Why is the outdoor fan blocked during the defrost cycle on a heat pump?", options: ["To prevent the fan motor from getting wet with melted water.", "To accelerate the rise in pressure and temperature at the outdoor coil to melt the ice faster.", "Because the compressor shuts off and there is no need for airflow.", "To save electrical energy during the 10-minute process."], explanation: "If the fan kept running, the cold outdoor air would cool the coil and delay ice melting. By shutting it off, the heat from the refrigerant concentrates on the coil metal." },
  { id:"calef_417", categoria:"CALEF_HIDRONICA", pregunta:"Si utiliza una mezcla de 50% propilenglicol en un sistema hidrónico, ¿qué ajuste debe hacer en el cálculo de la bomba circulatoria?", opciones:["Ninguno, el glicol fluye igual que el agua.", "Aumentar el tamaño de la bomba o las RPM, ya que el glicol es más viscoso y tiene menor capacidad de transporte de calor que el agua pura.", "Reducir la presión del tanque de expansión a la mitad.", "Cambiar todas las tuberías de cobre por tuberías de CPVC grado 80."], respuesta_correcta:1, explicacion:"El glicol es más 'pesado' y no absorbe calor tan bien como el agua. Necesitas bombear más volumen o con más fuerza para entregar la misma cantidad de BTUs al radiador." , question: "If you use a 50% propylene glycol mixture in a hydronic system, what adjustment must be made to the circulator pump calculation?", options: ["None; glycol flows the same as water.", "Increase the pump size or RPM, because glycol is more viscous and has a lower heat-carrying capacity than pure water.", "Reduce the expansion tank pressure by half.", "Change all copper piping to Schedule 80 CPVC."], explanation: "Glycol is thicker and does not absorb heat as well as water. You need to pump more volume or with more force to deliver the same amount of BTUs to the radiator." },
  { id:"calef_418", categoria:"CALEF_HIDRONICA", pregunta:"Usted sospecha que la válvula reversible de una bomba de calor tiene una fuga interna (bypass). ¿Cómo lo confirma técnicamente?", opciones:["Midiendo el amperaje del solenoide de la válvula.", "Comprobando la diferencia de temperatura entre la línea de succión y la línea de descarga del compresor en la propia válvula; una diferencia menor a 30°F sugiere bypass.", "Golpeando la válvula con un martillo de goma para ver si el ciclo cambia.", "Vaciando el refrigerante y pesándolo de nuevo."], respuesta_correcta:1, explicacion:"Si el gas caliente se filtra directamente a la succión dentro de la válvula, las temperaturas de las tuberías que no deberían tocarse se igualarán. Es la prueba definitiva de una válvula defectuosa." , question: "You suspect the reversing valve of a heat pump has an internal leak (bypass). How do you confirm it technically?", options: ["By measuring the solenoid amperage of the valve.", "By checking the temperature difference between the suction line and the discharge line at the valve itself; a difference of less than 30 degrees F suggests bypass.", "By hitting the valve with a rubber mallet to see if the cycle changes.", "By recovering the refrigerant and weighing it again."], explanation: "If hot gas leaks directly to the suction inside the valve, the temperatures of the lines that should not be touching will equalize. This is the definitive test for a defective valve." },
  { id:"calef_419", categoria:"CALEF_HIDRONICA", pregunta:"Si un tanque de expansión hidrónico tiene el diafragma roto y está lleno de agua (waterlogged), ¿qué síntoma observará en el sistema al encender la calefacción?", opciones:["La presión del sistema bajará a cero inmediatamente.", "La válvula de alivio de presión goteará o se abrirá cada vez que la caldera caliente el agua.", "La bomba circuladora consumirá menos amperaje de lo normal.", "El agua cambiará de color a un tono rojizo debido a la oxidación del aire atrapado."], respuesta_correcta:1, explicacion:"El agua no se comprime. Sin el colchón de aire del tanque de expansión, el aumento de volumen por calor eleva la presión instantáneamente por encima de los 30 PSI, activando la válvula de seguridad." , question: "If a hydronic expansion tank has a ruptured diaphragm and is waterlogged, what symptom will you observe when the heating is turned on?", options: ["The system pressure will drop to zero immediately.", "The pressure relief valve will drip or open each time the boiler heats the water.", "The circulator pump will draw less amperage than normal.", "The water will turn reddish due to oxidation from trapped air."], explanation: "Water does not compress. Without the air cushion in the expansion tank, the volume increase from heating raises the pressure instantly above 30 PSI, activating the safety valve." },
  { id:"calef_420", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué ocurre con la Presión Total de un sistema de ductos si la Presión Estática aumenta debido a una restricción pero la velocidad del aire disminuye proporcionalmente?", opciones:["La Presión Total se mantiene constante según la ecuación de Bernoulli.", "La Presión Total disminuye debido a las pérdidas por fricción y turbulencia convertidas en calor.", "Aumenta exponencialmente para compensar la falta de flujo.", "Se vuelve negativa en relación con la presión del plenum de retorno."], respuesta_correcta:1, explicacion:"La Presión Total es la suma de la Estática y la Dinámica. Aunque la estática suba, la energía perdida por fricción en la restricción hace que la suma total siempre sea menor después del obstáculo." , question: "What happens to the Total Pressure of a duct system if the Static Pressure increases due to a restriction but the air velocity decreases proportionally?", options: ["The Total Pressure remains constant per Bernoulli's equation.", "The Total Pressure decreases due to friction and turbulence losses converted to heat.", "It increases exponentially to compensate for the lack of flow.", "It becomes negative relative to the return plenum pressure."], explanation: "Total Pressure is the sum of Static and Dynamic. Even though static rises, the energy lost to friction at the restriction means the total is always lower after the obstruction." },
  { id:"calef_421", categoria:"CALEF_HIDRONICA", pregunta:"En una caldera de condensación, ¿cuál es el rango ideal de temperatura del agua de RETORNO para asegurar que el equipo condense realmente los gases?", opciones:["Por encima de los 80°C (180°F).", "Por debajo de los 54°C (130°F).", "Exactamente a la temperatura de ebullición del fluido caloportador.", "Entre 70°C y 75°C para maximizar la convección natural."], respuesta_correcta:1, explicacion:"Para que el vapor de agua en los gases de combustión se condense y libere su calor latente, el intercambiador debe estar más frío que el punto de rocío de los gases (aprox. 54°C)." , question: "In a condensing boiler, what is the ideal RETURN water temperature range to ensure the equipment actually condenses the flue gases?", options: ["Above 180 degrees F (80 degrees C).", "Below 130 degrees F (54 degrees C).", "Exactly at the boiling point of the heat transfer fluid.", "Between 158 and 167 degrees F to maximize natural convection."], explanation: "For the water vapor in the combustion gases to condense and release its latent heat, the heat exchanger must be cooler than the flue gas dew point (approximately 130 degrees F)." },
  { id:"calef_422", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué sucede con la presión de descarga de una bomba de calor si el filtro deshidratador de la línea de líquido se obstruye parcialmente?", opciones:["La presión de descarga sube debido a la acumulación de refrigerante en el condensador.", "La presión de descarga baja porque el compresor se queda sin flujo de refrigerante para bombear.", "Se estabiliza automáticamente por la apertura del puerto de bypass.", "La temperatura de la línea de líquido aumenta significativamente después del filtro."], respuesta_correcta:1, explicacion:"Capciosa: Al haber una restricción, el compresor no recibe suficiente vapor para comprimir, por lo que tanto la succión como la descarga tienden a bajar, aunque la temperatura de descarga suba por la alta relación de compresión." , question: "What happens to the discharge pressure of a heat pump if the liquid line filter-drier becomes partially clogged?", options: ["Discharge pressure rises due to refrigerant accumulation in the condenser.", "Discharge pressure drops because the compressor runs out of refrigerant flow to pump.", "It stabilizes automatically through the bypass port opening.", "The liquid line temperature rises significantly after the filter."], explanation: "Tricky: With a restriction, the compressor does not receive enough vapor to compress, so both suction and discharge pressures tend to drop, though the discharge temperature rises due to the high compression ratio." },
  { id:"calef_423", categoria:"CALEF_HIDRONICA", pregunta:"Un técnico instala una bomba circuladora 'sobredimensionada' en un sistema de calefacción de tubería pequeña. ¿Qué problema físico es más probable que ocurra?", opciones:["La bomba se quemará por falta de carga de trabajo.", "Erosión prematura de las tuberías y codos de cobre debido a la velocidad excesiva del fluido y ruido de flujo molesto.", "El agua circulará tan rápido que no tendrá tiempo de absorber calor en la caldera.", "Aumento del punto de congelación del fluido debido a la presión cinética."], respuesta_correcta:1, explicacion:"El agua a alta velocidad (más de 4 pies/segundo en residencial) actúa como un abrasivo, desgastando el cobre desde adentro, especialmente en los codos, además de causar silbidos en las válvulas." , question: "A technician installs an oversized circulator pump on a small-pipe heating system. What physical problem is most likely to occur?", options: ["The pump will burn out from lack of workload.", "Premature erosion of copper piping and elbows due to excessive fluid velocity, along with annoying flow noise.", "The water will circulate so fast it will not have time to absorb heat in the boiler.", "The fluid freezing point will increase due to kinetic pressure."], explanation: "Water at high velocity (above 4 feet per second in residential) acts as an abrasive, wearing the copper from the inside, especially at elbows, and causing whistling through valves." },
  { id:"calef_424", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función técnica del 'intercambiador de calor de línea de succión' (suction line heat exchanger) en sistemas de calefacción de baja temperatura?", opciones:["Enfriar el aceite del compresor antes de que llegue al cárter.", "Asegurar un sobrecalentamiento (superheat) adecuado para proteger el compresor y aumentar el subenfriamiento del líquido para mayor capacidad.", "Reducir la presión de descarga mediante la transferencia de calor radiante.", "Evitar que la línea de succión sude en ambientes con alta humedad relativa."], respuesta_correcta:1, explicacion:"Al intercambiar calor entre la línea de líquido caliente y la succión fría, garantizamos que el refrigerante entre al compresor 100% como vapor y que el líquido llegue a la expansión más frío, mejorando la eficiencia." , question: "What is the technical function of a Suction Line Heat Exchanger in low-temperature heating systems?", options: ["To cool the compressor oil before it reaches the crankcase.", "To ensure adequate superheat to protect the compressor and increase liquid subcooling for greater capacity.", "To reduce discharge pressure through radiant heat transfer.", "To prevent the suction line from sweating in high relative humidity environments."], explanation: "By exchanging heat between the warm liquid line and the cold suction line, we ensure the refrigerant enters the compressor as 100% vapor and the liquid reaches the expansion device cooler, improving efficiency." },
  { id:"calef_425", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función del 'Low Water Cut-Off' (LWCO) en una caldera de calefacción comercial?", opciones:["Mantener el nivel de agua constante mediante una bomba de alimentación.", "Apagar el quemador si el nivel de agua cae por debajo de un punto seguro, evitando que la caldera explote o se derrita.", "Drenar el exceso de agua si la presión sube de 30 PSI.", "Filtrar los lodos del fondo de la sección de hierro fundido."], respuesta_correcta:1, explicacion:"Una caldera encendida sin agua es una bomba de tiempo. El metal se sobrecalienta al rojo vivo; si se añade agua fría en ese estado, la vaporización instantánea causa una explosión catastrófica." , question: "What is the function of the Low Water Cut-Off (LWCO) on a commercial heating boiler?", options: ["To maintain a constant water level through a feed pump.", "To shut off the burner if the water level falls below a safe point, preventing the boiler from exploding or melting.", "To drain excess water if the pressure rises above 30 PSI.", "To filter sludge from the bottom of the cast iron sections."], explanation: "A boiler firing without water is a time bomb. The metal overheats to red-hot; if cold water is added in that state, instant vaporization causes a catastrophic explosion." },
  { id:"calef_426", categoria:"CALEF_HIDRONICA", pregunta:"En un sistema de calefacción por agua, ¿cuál es la función de una 'Válvula de Triple Propósito'?", opciones:["Regular temperatura, presión y humedad simultáneamente.", "Actuar como válvula de retención (check), válvula de aislamiento y válvula de equilibrio (balancing) en un solo cuerpo.", "Mezclar agua, glicol y aire para optimizar la entalpía.", "Conectar tres calderas en paralelo para carga secuencial."], respuesta_correcta:1, explicacion:"Estas válvulas ahorran espacio y costo en instalaciones comerciales, permitiendo funciones de control y mantenimiento en un solo punto de la tubería de descarga." , question: "In a hot water heating system, what is the function of a Triple Duty Valve?", options: ["To regulate temperature, pressure, and humidity simultaneously.", "To act as a check valve, shut-off valve, and balancing valve in a single body.", "To mix water, glycol, and air to optimize enthalpy.", "To connect three boilers in parallel for sequential loading."], explanation: "These valves save space and cost in commercial installations, providing control and maintenance functions at a single point on the discharge piping." },
  { id:"calef_427", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué componente decide cuándo una bomba de calor debe dejar de usar el compresor y pasar a usar 100% resistencias eléctricas (punto de equilibrio térmico)?", opciones:["El presostato de alta presión.", "El termostato de ambiente o la placa de control basándose en la temperatura exterior (Outdoor Ambient Sensor).", "La válvula reversible mediante un sensor de flujo.", "El acumulador de succión cuando detecta hielo."], respuesta_correcta:1, explicacion:"A medida que hace más frío afuera, la bomba de calor pierde capacidad. El sistema detecta que ya no puede mantener la casa y activa el 'Emergency Heat' o 'Auxiliary Heat'." , question: "What component determines when a heat pump should stop using the compressor and switch to 100% electric resistance heating (thermal balance point)?", options: ["The high-pressure switch.", "The room thermostat or control board based on the outdoor temperature (Outdoor Ambient Sensor).", "The reversing valve via a flow sensor.", "The suction accumulator when it detects ice."], explanation: "As it gets colder outside, the heat pump loses capacity. The system detects that it can no longer maintain the house temperature and activates Emergency Heat or Auxiliary Heat." },
  { id:"calef_428", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué ocurre en una caldera si el 'Diferencial' del Acuastato es demasiado pequeño (ej. 2 grados)?", opciones:["La caldera operará con una eficiencia del 100%.", "El equipo sufrirá de 'Short-Cycling' (arranques y paradas muy frecuentes), desperdiciando combustible y desgastando componentes.", "La presión del agua subirá por encima de 50 PSI.", "El quemador se quedará encendido permanentemente."], respuesta_correcta:1, explicacion:"El diferencial da 'espacio' para que el sistema trabaje. Si es muy pequeño, la caldera enciende por nada y apaga por nada, lo cual es ineficiente y dañino." , question: "What happens in a boiler if the Aquastat Differential is too small (e.g., 2 degrees)?", options: ["The boiler will operate at 100% efficiency.", "The equipment will short-cycle (very frequent starts and stops), wasting fuel and wearing out components.", "The water pressure will rise above 50 PSI.", "The burner will stay on permanently."], explanation: "The differential gives the system breathing room. If it is too small, the boiler fires for nothing and shuts off for nothing, which is inefficient and damaging." },
  { id:"calef_429", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Sub-enfriamiento' (Subcooling) y dónde se mide en modo calefacción (Heat Pump)?", opciones:["Es el enfriamiento del líquido por debajo de su punto de condensación; se mide a la salida del serpentín interior (que es el condensador).", "Es cuando la unidad exterior se congela en invierno.", "Se mide en la succión del compresor para evitar que se queme.", "Es la temperatura del aire en el retorno."], respuesta_correcta:0, explicacion:"El subcooling nos dice cuánto refrigerante líquido hay 'acumulado' en el condensador. En modo calor, el condensador es el serpentín de adentro de la casa." , question: "What is Subcooling and where is it measured in heating mode (Heat Pump)?", options: ["It is the cooling of the liquid below its condensation point; it is measured at the outlet of the indoor coil (which is the condenser).", "It is when the outdoor unit freezes in winter.", "It is measured at the compressor suction to prevent burnout.", "It is the temperature of the return air."], explanation: "Subcooling tells us how much liquid refrigerant has accumulated in the condenser. In heating mode, the condenser is the indoor coil." },
  { id:"calef_430", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué causa el 'Pounding' o 'Water Hammer' en una tubería de vapor?", opciones:["Que el vapor va demasiado lento.", "Vapor caliente encontrándose con condensado (agua) frío atrapado, lo que causa un colapso súbito del vapor y un choque de agua contra la tubería.", "El uso de tubería de hierro negro en lugar de cobre.", "Que la caldera tiene demasiada agua."], respuesta_correcta:1, explicacion:"Es ese ruido de 'golpes' fuertes. Es peligroso porque puede romper válvulas o codos de hierro fundido por el impacto del agua moviéndose a alta velocidad." , question: "What causes Pounding or Water Hammer in a steam pipe?", options: ["The steam is moving too slowly.", "Hot steam encountering trapped cold condensate (water), causing a sudden collapse of the steam and a water shock against the pipe wall.", "The use of black iron pipe instead of copper.", "The boiler has too much water."], explanation: "It is that loud banging noise. It is dangerous because it can crack valves or cast iron fittings from the impact of water moving at high velocity." },
  { id:"calef_431", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué sucede si la solenoide de la válvula reversible de una bomba de calor se quema en pleno invierno?", opciones:["El sistema se queda trabado en modo calefacción permanentemente.", "Depende de la marca, pero la mayoría fallará a modo refrigeración (aire acondicionado), dejando la casa fría.", "El compresor se invierte mecánicamente y sigue funcionando.", "El termostato cambiará automáticamente a gas natural."], respuesta_correcta:1, explicacion:"La mayoría de las válvulas reversibles (excepto marcas como Rheem/Ruud) necesitan energía para estar en modo calor. Si se rompe el cable o se quema la bobina, la válvula vuelve a su posición de 'descanso' (frío)." , question: "What happens if the reversing valve solenoid of a heat pump burns out in the middle of winter?", options: ["The system stays locked in heating mode permanently.", "Depending on the brand, most will default to cooling (air conditioning) mode, leaving the house cold.", "The compressor reverses mechanically and keeps running.", "The thermostat will automatically switch to natural gas."], explanation: "Most reversing valves (except brands like Rheem/Ruud) require power to stay in heating mode. If the wire breaks or the coil burns, the valve returns to its de-energized (cooling) position." },
  { id:"calef_432", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué la bomba circuladora debe instalarse 'descargando' después del tanque de expansión?", opciones:["Por estética de las tuberías.", "Para asegurar que la bomba sume su presión al sistema en lugar de restarla (Pump Away from the point of no pressure change).", "Para que el tanque de expansión no se caliente.", "Para evitar que el agua se mueva en sentido contrario."], respuesta_correcta:1, explicacion:"Es la regla de Dan Holohan. Si bombeas hacia el tanque, la presión en el sistema baja y puede entrar aire o causar cavitación. Siempre bombea alejándote del tanque." , question: "Why should the circulator pump be installed to discharge away from (after) the expansion tank?", options: ["For piping aesthetics.", "To ensure the pump adds its pressure to the system rather than subtracting it (Pump Away from the point of no pressure change).", "To keep the expansion tank from heating up.", "To prevent water from flowing in the wrong direction."], explanation: "This is the Dan Holohan rule. If you pump toward the tank, system pressure drops and can draw in air or cause cavitation. Always pump away from the tank." },
  { id:"calef_433", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Efecto de Pared' en un ducto de aire?", opciones:["Cuando el aire se detiene totalmente en el centro del ducto.", "La fricción entre el aire en movimiento y la superficie interna del ducto, lo que reduce la velocidad del aire cerca de las paredes.", "Cuando el ducto se colapsa por la presión negativa.", "La acumulación de polvo en las esquinas de los codos."], respuesta_correcta:1, explicacion:"El aire en el centro del tubo va más rápido que el de las orillas. Por eso, un ducto sucio o rugoso (como el flex duct estirado) frena mucho más el aire que un tubo de metal liso." , question: "What is the Boundary Layer Effect in an air duct?", options: ["When air stops completely in the center of the duct.", "The friction between moving air and the internal duct surface, which reduces air velocity near the walls.", "When the duct collapses from negative pressure.", "The accumulation of dust in the corners of elbows."], explanation: "Air in the center of the pipe moves faster than air at the edges. That is why a dirty or rough duct (like unstretched flex duct) slows air down much more than smooth metal." },
  { id:"calef_434", categoria:"CALEF_HIDRONICA", pregunta:"¿Cómo sabe una placa de control 'Time-Temp' cuándo iniciar un ciclo de descongelación?", opciones:["Cuando el termostato se lo pide.", "Cuando ha pasado un tiempo acumulado de funcionamiento del compresor (ej. 60 min) Y el sensor de temperatura del serpentín exterior está por debajo del punto de congelación.", "Cada vez que la temperatura exterior baja de 0°C.", "Por un sensor óptico que 've' el hielo en las aletas de aluminio."], respuesta_correcta:1, explicacion:"Combina tiempo y temperatura. No descongela si no ha trabajado suficiente tiempo o si el serpentín no está lo suficientemente frío para tener hielo." , question: "How does a Time-Temperature control board know when to initiate a defrost cycle?", options: ["When the thermostat requests it.", "When accumulated compressor run time has elapsed (e.g., 60 minutes) AND the outdoor coil temperature sensor is below the freezing point.", "Every time the outdoor temperature drops below 32 degrees F.", "Through an optical sensor that sees ice on the aluminum fins."], explanation: "It combines time and temperature. It does not defrost if the compressor has not run long enough or if the coil is not cold enough to have ice." },
  { id:"calef_435", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es el propósito de una 'Válvula de Zona'?", opciones:["Aumentar la presión del agua en una habitación.", "Permitir que el termostato de una habitación específica controle el flujo de agua caliente hacia sus radiadores independientemente del resto de la casa.", "Filtrar las impurezas de una zona específica de la caldera.", "Cambiar el agua de caliente a fría automáticamente."], respuesta_correcta:1, explicacion:"Es para el confort y ahorro. Si no usas el segundo piso, la válvula se cierra y no gastas energía calentando agua para esa zona." , question: "What is the purpose of a Zone Valve?", options: ["To increase water pressure to a room.", "To allow the thermostat of a specific room to control hot water flow to its radiators independently from the rest of the house.", "To filter impurities in a specific zone of the boiler.", "To automatically switch water from hot to cold."], explanation: "It is for comfort and savings. If you are not using the second floor, the valve closes and you do not waste energy heating water for that zone." },
  { id:"calef_436", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué un separador de aire (Air Picker/Scoop) debe instalarse en el punto más caliente del sistema de calefacción hidrónica?", opciones:["Porque el aire es más pesado cuando el agua está caliente.", "Debido a que la solubilidad del aire en el agua disminuye a medida que la temperatura aumenta, facilitando la liberación de burbujas.", "Para evitar que el agua se convierta en vapor dentro de la bomba.", "Es una norma estética para que coincida con la salida de la caldera."], respuesta_correcta:1, explicacion:"El agua caliente 'suelta' el aire más fácilmente. Al poner el separador ahí, capturamos las burbujas antes de que viajen a los radiadores y causen ruidos o bloqueos." , question: "Why must an air separator (air scoop) be installed at the hottest point in a hydronic heating system?", options: ["Because air is heavier when the water is hot.", "Because the solubility of air in water decreases as temperature increases, making it easier to release bubbles.", "To prevent water from turning to steam inside the pump.", "It is an aesthetic standard to match the boiler outlet."], explanation: "Hot water releases air more readily. By placing the separator there, we capture the bubbles before they travel to the radiators and cause noise or blockages." },
  { id:"calef_437", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué una válvula de expansión termostática (TXV) con 'ecualización externa' es necesaria en serpentines de calefacción de gran tamaño?", opciones:["Para medir la temperatura exterior con mayor precisión.", "Para compensar la caída de presión a través del serpentín y asegurar un sobrecalentamiento preciso en la salida.", "Permite que el refrigerante fluya en ambas direcciones sin usar válvulas check.", "Aumenta la presión de descarga del compresor en un 15%."], respuesta_correcta:1, explicacion:"En serpentines largos hay mucha caída de presión. La TXV necesita saber la presión real a la salida del evaporador (no a la entrada) para abrirse lo justo y no inundar el compresor." , question: "Why is a Thermostatic Expansion Valve (TXV) with external equalization necessary on large heating coils?", options: ["To measure the outdoor temperature more accurately.", "To compensate for the pressure drop across the coil and ensure accurate superheat at the outlet.", "It allows refrigerant to flow in both directions without check valves.", "It increases the compressor discharge pressure by 15%."], explanation: "Long coils have significant pressure drop. The TXV needs to know the actual pressure at the evaporator outlet (not the inlet) to open just the right amount and avoid flooding the compressor." },
  { id:"calef_438", categoria:"CALEF_HIDRONICA", pregunta:"Usted nota 'tizne' (soot) en el intercambiador de una caldera de aceite (oil boiler). ¿Qué ajuste es el más probable?", opciones:["Aumentar la presión de la bomba de aceite.", "Ajustar el flujo de aire (aire primario/secundario) y verificar que la boquilla (nozzle) no esté parcialmente obstruida o sea del ángulo incorrecto.", "Cambiar el termostato de la habitación.", "Instalar una bomba circuladora más potente."], respuesta_correcta:1, explicacion:"El hollín en aceite es falta de aire o mala atomización. Si la boquilla gotea o no pulveriza bien el aceite, la combustión es incompleta y ensucia todo de negro carbón." , question: "You notice soot on the heat exchanger of an oil boiler. What is the most likely adjustment needed?", options: ["Increase the oil pump pressure.", "Adjust the airflow (primary/secondary air) and verify that the nozzle is not partially clogged or is the wrong spray angle.", "Change the room thermostat.", "Install a more powerful circulator pump."], explanation: "Soot in oil systems means lack of air or poor atomization. If the nozzle is dripping or not properly atomizing the oil, combustion is incomplete and everything turns black with carbon." },
  { id:"calef_439", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué sucede si el orificio de retorno de aceite (metering orifice) en un acumulador de succión se tapa?", opciones:["El compresor se inundará de refrigerante líquido.", "El compresor fallará por falta de lubricación, ya que el aceite se quedará atrapado en el fondo del acumulador.", "La presión de alta subirá hasta disparar el interruptor.", "El sistema entrará en modo de descongelación infinito."], respuesta_correcta:1, explicacion:"El acumulador tiene un pequeño tubo en 'U' con un agujerito en el fondo para 'succionar' el aceite y devolverlo al motor. Si se tapa, el aceite se queda ahí y el compresor muere seco." , question: "What happens if the oil return metering orifice in a suction accumulator becomes clogged?", options: ["The compressor will flood with liquid refrigerant.", "The compressor will fail from lack of lubrication, because the oil will remain trapped at the bottom of the accumulator.", "The high-side pressure will rise until it trips the switch.", "The system will enter an infinite defrost cycle."], explanation: "The accumulator has a small U-tube with a tiny hole at the bottom to siphon oil and return it to the compressor. If it clogs, the oil stays there and the compressor runs dry and dies." },
  { id:"calef_440", categoria:"CALEF_HIDRONICA", pregunta:"¿Cómo se verifica que un tanque de expansión tipo diafragma tiene la precarga de aire correcta?", opciones:["Midiendo con un manómetro de llantas mientras el sistema está a 30 PSI.", "Se debe aislar el tanque del sistema y drenar la presión del agua antes de medir la presión de aire con un manómetro.", "Golpeando el tanque con un martillo; si suena 'hueco' está bien.", "Pesando el tanque para ver cuánto nitrógeno le queda."], respuesta_correcta:1, explicacion:"Si mides con la presión del agua activa, estarás midiendo la presión del agua, no la del aire. Hay que vaciar el lado del agua para ajustar la 'precarga' (usualmente 12 PSI)." , question: "How do you verify that a diaphragm-type expansion tank has the correct air precharge?", options: ["By measuring with a tire pressure gauge while the system is at 30 PSI.", "You must isolate the tank from the system and drain the water pressure before measuring the air pressure with a gauge.", "By tapping the tank with a hammer; if it sounds hollow, it is fine.", "By weighing the tank to see how much nitrogen remains."], explanation: "If you measure with the water pressure active, you are reading the water pressure, not the air pressure. The water side must be drained to properly adjust the precharge (typically 12 PSI)." },
  { id:"calef_441", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Calor de Vaporización' en una caldera de vapor?", opciones:["El calor que se necesita para subir la temperatura del agua de 20°C a 100°C.", "La enorme cantidad de energía necesaria para convertir el agua líquida en vapor sin cambiar su temperatura (a 100°C).", "La temperatura a la que el metal de la caldera se pone rojo.", "El calor que se pierde por la chimenea."], respuesta_correcta:1, explicacion:"Es calor latente. El vapor transporta muchísima energía gracias a este proceso, por eso los sistemas de vapor son tan potentes para calentar edificios grandes." , question: "What is the Latent Heat of Vaporization in a steam boiler?", options: ["The heat needed to raise water temperature from 68 degrees F to 212 degrees F.", "The enormous amount of energy required to convert liquid water into steam without changing its temperature (at 212 degrees F).", "The temperature at which the boiler metal turns red.", "The heat lost through the chimney."], explanation: "This is latent heat. Steam carries a tremendous amount of energy thanks to this process, which is why steam systems are so powerful for heating large buildings." },
  { id:"calef_442", categoria:"CALEF_HIDRONICA", pregunta:"¿A qué presión suele activarse la válvula de alivio en una caldera residencial de agua caliente estándar?", opciones:["15 PSI.", "30 PSI.", "125 PSI.", "500 PSI."], respuesta_correcta:1, explicacion:"El estándar para calderas hidrónicas residenciales es 30 PSI. Si la presión llega ahí (por un tanque de expansión malo), la válvula se abre para evitar que la caldera explote." , question: "At what pressure does the relief valve typically activate on a standard residential hot water boiler?", options: ["15 PSI.", "30 PSI.", "125 PSI.", "500 PSI."], explanation: "The standard for residential hydronic boilers is 30 PSI. If the pressure reaches that level (due to a bad expansion tank), the valve opens to prevent the boiler from exploding." },
  { id:"calef_443", categoria:"CALEF_HIDRONICA", pregunta:"En un sistema 'Dual Fuel', ¿cuándo debe apagarse la bomba de calor y encenderse el horno de gas?", opciones:["Cuando el cliente tenga frío.", "En el 'Punto de Equilibrio Térmico' (Balance Point), cuando la pérdida de calor de la casa supera la capacidad de la bomba de calor.", "Cada 30 minutos de forma alternada.", "Solo cuando la unidad exterior entra en modo de descongelación."], respuesta_correcta:1, explicacion:"Es el punto óptimo de eficiencia. El gas es más potente en frío extremo. El sistema cambia automáticamente para mantener el confort sin gastar electricidad de más en un compresor que ya no rinde." , question: "In a Dual Fuel system, when should the heat pump shut off and the gas furnace turn on?", options: ["When the customer feels cold.", "At the Thermal Balance Point, when the heat loss of the house exceeds the capacity of the heat pump.", "Every 30 minutes in alternating fashion.", "Only when the outdoor unit enters defrost mode."], explanation: "It is the optimal efficiency point. Gas is more powerful in extreme cold. The system switches automatically to maintain comfort without wasting electricity on a compressor that can no longer keep up." },
  { id:"calef_444", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Efecto de Escarcha' (Frosting) en una bomba de calor?", opciones:["Un proceso decorativo para las unidades exteriores.", "La formación de hielo en el serpentín exterior cuando la temperatura del refrigerante es menor a 0°C y menor al punto de rocío del aire exterior.", "Cuando el termostato se congela por dentro.", "La acumulación de polvo blanco en los filtros."], respuesta_correcta:1, explicacion:"Es normal en invierno. La humedad del aire se congela al tocar el serpentín frío. Por eso las bombas de calor tienen un ciclo de 'Defrost' para derretir ese hielo automáticamente." , question: "What is the Frosting Effect on a heat pump?", options: ["A decorative process on outdoor units.", "The formation of ice on the outdoor coil when the refrigerant temperature is below 32 degrees F and below the dew point of the outdoor air.", "When the thermostat freezes internally.", "The accumulation of white dust on the filters."], explanation: "It is normal in winter. The moisture in the air freezes on contact with the cold coil. That is why heat pumps have an automatic Defrost cycle to melt that ice." },
  { id:"calef_445", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Escalamiento' (Scaling) dentro de una caldera?", opciones:["El proceso de subir la temperatura grado a grado.", "La acumulación de minerales (calcio/magnesio) del agua en las paredes internas, lo que actúa como aislante y reduce la eficiencia y vida del equipo.", "La medición del tamaño de las tuberías.", "El cambio de presión según la altura del edificio."], respuesta_correcta:1, explicacion:"Es como el 'sarro' de una cafetera. Esa capa blanca impide que el calor del fuego pase al agua, haciendo que el metal se sobrecaliente y la caldera gaste mucho más gas." , question: "What is Scaling inside a boiler?", options: ["The process of gradually increasing the temperature.", "The accumulation of minerals (calcium/magnesium) from the water on the internal walls, which acts as an insulator and reduces equipment efficiency and lifespan.", "The measurement of pipe sizing.", "The change in pressure according to building height."], explanation: "It is like the limescale in a coffee maker. That white layer prevents heat from the fire from reaching the water, causing the metal to overheat and the boiler to consume much more gas." },
  { id:"calef_446", categoria:"CALEF_HIDRONICA", pregunta:"Usted escucha aire 'corriendo' por las tuberías (gurgling noise). ¿Qué debe hacer?", opciones:["Subir la temperatura de la caldera.", "Purgar el aire de los radiadores o del punto más alto del sistema usando las válvulas de purga.", "Cambiar la bomba circuladora.", "Vaciar todo el sistema y volverlo a llenar con agua destilada."], respuesta_correcta:1, explicacion:"Ese ruido de burbujas significa que hay aire atrapado. El aire impide que el agua caliente llegue a todos lados. Hay que sacarlo manualmente o con un purgador automático." , question: "You hear air rushing through the pipes (gurgling noise). What should you do?", options: ["Raise the boiler temperature.", "Bleed the air from the radiators or the highest point in the system using the bleeder valves.", "Replace the circulator pump.", "Drain the entire system and refill with distilled water."], explanation: "That bubbling noise means there is trapped air. Air prevents hot water from reaching all areas. It must be removed manually or with an automatic air vent." },
  { id:"calef_447", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Golpe de Ariete' en una línea de alimentación de agua de una caldera?", opciones:["Un sonido rítmico que indica que la bomba está lubricada.", "Una onda de choque de presión causada por el cierre repentino de una válvula, que puede romper tuberías y accesorios.", "El ruido de las burbujas de aire al pasar por el circulador.", "La expansión térmica de los radiadores de hierro fundido."], respuesta_correcta:1, explicacion:"El agua tiene masa e inercia. Si detienes el flujo de golpe, esa energía se convierte en un impacto mecánico violento contra las paredes del tubo." , question: "What is Water Hammer in a boiler feed water line?", options: ["A rhythmic sound indicating the pump is lubricated.", "A pressure shock wave caused by the sudden closing of a valve, which can rupture pipes and fittings.", "The sound of air bubbles passing through the circulator.", "The thermal expansion of cast iron radiators."], explanation: "Water has mass and inertia. If you stop the flow suddenly, that energy converts into a violent mechanical impact against the pipe walls." },
  { id:"calef_448", categoria:"CALEF_HIDRONICA", pregunta:"Usted instala una válvula de zona que tarda 30 segundos en abrirse. ¿Cómo sabe el horno que debe encender el quemador solo después de que la válvula esté abierta?", opciones:["Por un sensor de flujo en la tubería.", "Mediante el 'End Switch' (interruptor de fin de carrera) de la válvula de zona, que cierra el circuito de la caldera solo cuando el motor ha abierto la válvula.", "El termostato tiene un cronómetro interno.", "La caldera detecta la vibración del agua al moverse."], respuesta_correcta:1, explicacion:"Es un seguro mecánico. Si la caldera enciende antes de que el agua pueda circular, el intercambiador se sobrecalentaría en segundos. El End Switch garantiza que el camino esté despejado." , question: "You install a zone valve that takes 30 seconds to open. How does the furnace know to fire the burner only after the valve is open?", options: ["Through a flow sensor in the piping.", "Through the End Switch on the zone valve, which closes the boiler circuit only after the motor has fully opened the valve.", "The thermostat has an internal timer.", "The boiler detects the vibration of the water when it starts flowing."], explanation: "It is a mechanical safety interlock. If the boiler fires before water can circulate, the heat exchanger would overheat within seconds. The end switch ensures the path is clear." },
  { id:"calef_449", categoria:"CALEF_HIDRONICA", pregunta:"En modo calefacción, una bomba de calor tiene una presión de succión inusualmente alta y una descarga baja. El compresor está ruidoso. ¿Qué sospecha?", opciones:["Falta de refrigerante.", "Válvulas internas del compresor dañadas o 'leaking' (el gas se recircula en lugar de comprimirse).", "Filtro de aire muy limpio.", "La válvula reversible está en la posición correcta."], respuesta_correcta:1, explicacion:"Si el compresor no puede crear una diferencia de presión, es porque sus 'puertas' internas no sellan. Es como tratar de inflar una llanta con una bomba que tiene el empaque roto." , question: "In heating mode, a heat pump has unusually high suction pressure and low discharge pressure. The compressor is noisy. What do you suspect?", options: ["Low refrigerant charge.", "Damaged internal compressor valves that are leaking (the gas recirculates instead of being compressed).", "An overly clean air filter.", "The reversing valve is in the correct position."], explanation: "If the compressor cannot create a pressure differential, its internal valves are not sealing. It is like trying to inflate a tire with a pump that has a broken gasket." },
  { id:"calef_450", categoria:"CALEF_HIDRONICA", pregunta:"Usted encuentra que el agua de la caldera está 'negra como petróleo' y tiene un olor fétido. ¿Qué indica esto?", opciones:["Que el intercambiador de calor está filtrando aceite de motor.", "Presencia de magnetita y bacterias anaeróbicas por falta de tratamiento químico o filtración en un sistema viejo de hierro.", "Es el color normal del agua tratada con anticorrosivos modernos.", "Que la caldera está quemando carbón en lugar de gas."], respuesta_correcta:1, explicacion:"El lodo negro es óxido de hierro pulverizado (magnetita). Es abrasivo y destruye las bombas y válvulas. Requiere una limpieza profunda y adición de inhibidores de corrosión." , question: "You find that the boiler water is black as oil and has a foul smell. What does this indicate?", options: ["The heat exchanger is leaking motor oil.", "Magnetite and anaerobic bacteria from lack of chemical treatment or filtration in an old iron system.", "It is the normal color of water treated with modern anti-corrosion agents.", "The boiler is burning coal instead of gas."], explanation: "The black sludge is pulverized iron oxide (magnetite). It is abrasive and destroys pumps and valves. It requires a thorough system flush and the addition of corrosion inhibitors." },
  { id:"calef_451", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la diferencia entre un 'Acumulador de Succión' y un 'Receptor de Líquido'?", opciones:["Son el mismo componente con nombres distintos.", "El acumulador está en la línea de succión para proteger de líquido al compresor; el receptor está en la línea de líquido para almacenar refrigerante.", "El receptor se usa solo en modo calefacción.", "El acumulador filtra el aceite y el receptor filtra la humedad."], respuesta_correcta:1, explicacion:"Ubicación y propósito opuestos. El acumulador es el 'guardaespaldas' del compresor antes de la entrada. El receptor es el 'tanque de reserva' después de la salida del condensador." , question: "What is the difference between a Suction Accumulator and a Liquid Receiver?", options: ["They are the same component with different names.", "The accumulator is on the suction line to protect the compressor from liquid; the receiver is on the liquid line to store refrigerant.", "The receiver is only used in heating mode.", "The accumulator filters oil and the receiver filters moisture."], explanation: "Opposite locations and purposes. The accumulator is the compressor's bodyguard at the inlet. The receiver is the reserve tank after the condenser outlet." },
  { id:"calef_452", categoria:"CALEF_HIDRONICA", pregunta:"Usted instala una bomba circuladora en el retorno de una caldera. ¿Cuál es el riesgo si el tanque de expansión está lejos de la succión de la bomba?", opciones:["Que el agua se caliente demasiado rápido.", "Crear una zona de presión negativa que aspire aire por los purgadores automáticos o cause cavitación en la bomba.", "Que el motor de la bomba gire al revés por falta de presión.", "La caldera no podrá detectar el nivel de agua."], respuesta_correcta:1, explicacion:"La bomba debe 'alejarse' del punto de presión constante (tanque). Si bombea hacia el tanque desde lejos, la presión antes de la bomba cae, metiendo aire al sistema y rompiendo la circulación." , question: "You install a circulator pump on the boiler return. What is the risk if the expansion tank is far from the pump suction?", options: ["The water will heat up too quickly.", "It creates a negative pressure zone that draws air in through automatic vents or causes pump cavitation.", "The pump motor will spin backwards from lack of pressure.", "The boiler will not be able to detect the water level."], explanation: "The pump must pump away from the point of constant pressure (the tank). If you pump toward the tank from far away, the pressure before the pump drops, pulling air into the system and breaking circulation." },
  { id:"calef_453", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es un 'Vaso de Expansión Abierto' y dónde se encuentra?", opciones:["Un tanque de agua en el sótano que gotea constantemente.", "Un sistema antiguo donde el tanque de expansión estaba en el punto más alto de la casa (ático) abierto a la atmósfera; hoy es raro verlo.", "La válvula de llenado automático de la caldera.", "Un radiador sin tapa de purga."], respuesta_correcta:1, explicacion:"Eran los sistemas de antes de los años 50. Usaban la gravedad y la atmósfera para controlar la presión. Son ineficientes porque el agua se oxigena y corroe los tubos rápido." , question: "What is an Open Expansion Tank and where is it located?", options: ["A tank in the basement that constantly drips.", "An older system design where the expansion tank was at the highest point of the house (attic), open to the atmosphere; it is rarely seen today.", "The automatic fill valve on the boiler.", "A radiator without a bleeder valve cap."], explanation: "These were the systems from before the 1950s. They used gravity and atmosphere to control pressure. They are inefficient because the water absorbs oxygen and corrodes the piping quickly." },
  { id:"calef_454", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué el vapor se mueve a través de las tuberías de un edificio sin necesidad de una bomba circuladora?", opciones:["Porque el vapor es más ligero que el aire.", "Por la diferencia de presión creada por la caldera (generación de vapor) y el radiador (condensación del vapor), que actúa como un vacío.", "Gracias a la atracción gravitacional de la luna sobre el agua caliente.", "Porque el vapor es un gas noble que no tiene fricción."], respuesta_correcta:1, explicacion:"El vapor se 'empuja' solo hacia donde hay menos presión. Cuando el vapor llega al radiador frío y se vuelve agua, crea un vacío que 'jala' más vapor desde la caldera. Es ingeniería pura." , question: "Why does steam travel through a building's piping without needing a circulator pump?", options: ["Because steam is lighter than air.", "Because the pressure difference created by the boiler (steam generation) and the radiator (steam condensation), which acts as a vacuum, drives the flow.", "Due to the gravitational attraction of the moon on hot water.", "Because steam is a noble gas with no friction."], explanation: "Steam pushes itself toward lower-pressure areas. When the steam reaches a cold radiator and condenses back to water, it creates a vacuum that pulls more steam from the boiler. It is pure engineering." },
  { id:"calef_455", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es una 'Válvula Reductora de Presión' (Feed Valve) en una caldera?", opciones:["Una válvula para tirar el agua a la calle.", "Un componente que toma agua de la red de la ciudad (60-80 PSI) y la baja a 12-15 PSI para llenar la caldera automáticamente.", "La válvula que controla el flujo de gas hacia el quemador.", "Un sensor que mide la velocidad del agua."], respuesta_correcta:1, explicacion:"Mantiene la caldera llena. Si la presión de la casa entrara directo, la caldera explotaría. Esta válvula garantiza que el sistema siempre tenga agua a la presión segura de operación." , question: "What is a Pressure Reducing Valve (Feed Valve) on a boiler?", options: ["A valve to drain water to the street.", "A component that takes city water supply (60-80 PSI) and reduces it to 12-15 PSI to automatically fill the boiler.", "The valve that controls gas flow to the burner.", "A sensor that measures water velocity."], explanation: "It keeps the boiler full. If city pressure entered directly, the boiler would explode. This valve ensures the system always has water at a safe operating pressure." },
  { id:"calef_456", categoria:"CALEF_HIDRONICA", pregunta:"Usted encuentra una válvula de alivio que gotea constantemente en una caldera. El tanque de expansión suena 'lleno' al golpearlo. ¿Cuál es la reparación?", opciones:["Poner un tapón en la válvula de alivio.", "Reemplazar el tanque de expansión (diafragma roto) y luego la válvula de alivio si el sello se dañó por depósitos minerales.", "Bajar la temperatura de la caldera a 40°C.", "Abrir todas las llaves de purga de los radiadores."], respuesta_correcta:1, explicacion:"Si el tanque está lleno de agua, no hay colchón de aire. Al calentar el agua, la presión sube de golpe y abre la válvula. Cambiar la válvula sin cambiar el tanque no arreglará el problema." , question: "You find a constantly dripping pressure relief valve on a boiler. The expansion tank sounds full when tapped. What is the repair?", options: ["Put a plug in the relief valve.", "Replace the expansion tank (ruptured diaphragm) and then the relief valve if its seal was damaged by mineral deposits.", "Lower the boiler temperature to 104 degrees F.", "Open all the radiator bleeder valves."], explanation: "If the tank is full of water, there is no air cushion. When the water heats up, pressure spikes and opens the valve. Replacing the valve without replacing the tank will not fix the problem." },
  { id:"calef_457", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es la 'Longitud Equivalente' de un accesorio de ducto (como un codo de 90°)?", opciones:["La distancia física medida con una cinta métrica.", "La longitud de un ducto recto que causaría la misma caída de presión que el accesorio en cuestión.", "El diámetro del ducto multiplicado por Pi.", "La suma de todos los tornillos usados en la unión."], respuesta_correcta:1, explicacion:"Un codo frena el aire. En términos de presión, un codo de 90° puede equivaler a 30 pies de tubo recto. Si pones muchos codos, es como si tuvieras un ducto de kilómetros de largo." , question: "What is the Equivalent Length of a duct fitting (such as a 90-degree elbow)?", options: ["The physical distance measured with a tape measure.", "The length of straight duct that would cause the same pressure drop as the fitting in question.", "The duct diameter multiplied by Pi.", "The total number of screws used in the joint."], explanation: "An elbow slows air down. In pressure terms, a 90-degree elbow can be equivalent to 30 feet of straight pipe. If you install many elbows, it is as if you had a miles-long duct." },
  { id:"calef_458", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué ocurre si un radiador de agua caliente está inclinado hacia el lado opuesto de la válvula de purga?", opciones:["El agua circula más rápido.", "Se forma una bolsa de aire atrapada que no puede ser purgada, dejando una parte o todo el radiador frío.", "La presión del sistema sube a 50 PSI.", "El radiador se oxida por fuera."], respuesta_correcta:1, explicacion:"El aire siempre busca el punto más alto. Si la purga no es el punto más alto del radiador, el aire se queda 'atrapado' en la esquina elevada y no hay forma de sacarlo." , question: "What happens if a hot water radiator is tilted toward the side opposite the bleeder valve?", options: ["The water circulates faster.", "A trapped air pocket forms that cannot be bled, leaving part or all of the radiator cold.", "The system pressure rises to 50 PSI.", "The radiator rusts on the outside."], explanation: "Air always seeks the highest point. If the bleeder is not at the highest point of the radiator, the air gets trapped in the elevated corner and there is no way to remove it." },
  { id:"calef_459", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Fraccionamiento' en una mezcla de refrigerantes (como el R-410A) durante una fuga?", opciones:["Cuando el refrigerante se divide en átomos individuales.", "Cuando los componentes de la mezcla se evaporan a ritmos diferentes, cambiando la composición química del refrigerante restante en el sistema.", "Un proceso de filtración por capas de aceite.", "La congelación del refrigerante en la línea de líquido."], respuesta_correcta:1, explicacion:"El R-410A es una mezcla. Si hay una fuga pequeña, uno de los gases sale más rápido que el otro. Por eso se recomienda vaciar y cargar de nuevo en lugar de solo 'completar' la carga." , question: "What is Fractionation in a refrigerant blend (such as R-410A) during a leak?", options: ["When the refrigerant breaks down into individual atoms.", "When the components of the blend evaporate at different rates, changing the chemical composition of the remaining refrigerant in the system.", "A process of oil filtration by layers.", "The freezing of refrigerant in the liquid line."], explanation: "R-410A is a blend. During a slow leak, one gas escapes faster than the other. That is why it is recommended to recover and recharge completely rather than just topping off." },
  { id:"calef_460", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función del 'Acuastato'?", opciones:["Medir el nivel de agua en la caldera.", "Es el termostato de la caldera; controla cuándo encender y apagar el quemador para mantener la temperatura del agua dentro del rango deseado.", "Filtrar las impurezas químicas del agua.", "Bombear el agua hacia los pisos superiores."], respuesta_correcta:1, explicacion:"Es el cerebro térmico. Tú le dices 'quiero agua a 180°F' y el acuastato se encarga de que el fuego prenda y apague para no pasarse ni quedarse corto." , question: "What is the function of an Aquastat?", options: ["To measure the water level in the boiler.", "It is the boiler thermostat; it controls when to fire and shut off the burner to maintain the water temperature within the desired range.", "To filter chemical impurities from the water.", "To pump water to upper floors."], explanation: "It is the thermal brain. You set it to the desired water temperature and the aquastat turns the burner on and off to stay within range." },
  { id:"calef_461", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la ventaja de un sistema de tubería 'Serie Loop'?", opciones:["Es el más fácil de controlar habitación por habitación.", "Es el más económico de instalar (usa menos tubería), pero el último radiador siempre recibe agua más fría que el primero.", "Permite usar tuberías de plástico barato sin soporte.", "No requiere tanque de expansión."], respuesta_correcta:1, explicacion:"Es un solo tubo que pasa por todos. Lo malo es que el calor se va quedando en los primeros radiadores, y el pobre del final de la línea casi no calienta." , question: "What is the advantage of a Series Loop piping system?", options: ["It is the easiest to control room by room.", "It is the most economical to install (uses less piping), but the last radiator always receives cooler water than the first.", "It allows the use of cheap plastic piping without supports.", "It does not require an expansion tank."], explanation: "It is a single pipe that passes through all the radiators. The downside is that heat is used up in the first radiators, and the last one in line barely heats." },
  { id:"calef_462", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Emergency Heat' (Calor de Emergencia) en un termostato de bomba de calor?", opciones:["Un botón que llama a los bomberos.", "Un modo que bloquea el compresor y activa solo las resistencias eléctricas, usado cuando la bomba de calor falla mecánicamente.", "Un aumento del 50% en la velocidad del ventilador.", "Cuando el gas natural se mezcla con el aire acondicionado."], respuesta_correcta:1, explicacion:"Es tu plan B. Si el compresor se rompe un domingo, activas esto para no congelarte. Es caro de operar, pero te mantiene a salvo hasta que llegue el técnico." , question: "What is Emergency Heat on a heat pump thermostat?", options: ["A button that calls the fire department.", "A mode that locks out the compressor and activates only the electric resistance heaters, used when the heat pump has a mechanical failure.", "A 50% increase in fan speed.", "When natural gas is blended with air conditioning."], explanation: "It is your backup plan. If the compressor breaks on a Sunday, you activate this to keep from freezing. It is expensive to operate but keeps you safe until the technician arrives." },
  { id:"calef_463", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué sucede si una bomba circuladora gira 'en seco' (sin agua)?", opciones:["Se limpia por dentro.", "El sello mecánico y los rodamientos se sobrecalientan y se destruyen en minutos por falta de lubricación y enfriamiento del agua.", "Consume menos electricidad y dura más.", "El motor invierte su sentido de giro automáticamente."], respuesta_correcta:1, explicacion:"El agua es el lubricante de estas bombas. Nunca la prendas si el sistema no está lleno y purgado, o tendrás que comprar una bomba nueva mañana." , question: "What happens if a circulator pump runs dry (without water)?", options: ["It cleans itself internally.", "The mechanical seal and bearings overheat and are destroyed within minutes from lack of lubrication and cooling from the water.", "It uses less electricity and lasts longer.", "The motor automatically reverses its rotation."], explanation: "Water is the lubricant for these pumps. Never turn one on if the system is not full and bled, or you will be buying a new pump tomorrow." },
  { id:"calef_464", categoria:"CALEF_HIDRONICA", pregunta:"En un intercambiador de placas soldadas (Plate Heat Exchanger), ¿qué indica una diferencia de temperatura (Approach) mayor a 5°C entre el fluido primario y secundario?", opciones:["Que el sistema está operando a su máxima eficiencia de diseño.", "Incrustaciones calcáreas o suciedad en las placas que reducen la transferencia térmica (fouling).", "Que la bomba circuladora es demasiado potente para el sistema.", "Es un valor normal en sistemas de calefacción por suelo radiante."], respuesta_correcta:1, explicacion:"Un intercambiador eficiente debe tener temperaturas de salida muy cercanas. Si la brecha crece, significa que hay una barrera física (sarro o lodo) impidiendo el paso del calor." , question: "In a brazed plate heat exchanger, what does an approach temperature difference greater than 9 degrees F between the primary and secondary fluids indicate?", options: ["The system is operating at its maximum design efficiency.", "Scale or fouling on the plates that is reducing heat transfer.", "The circulator pump is too powerful for the system.", "It is a normal value in radiant floor heating systems."], explanation: "An efficient heat exchanger should have very close outlet temperatures. If the gap grows, it means there is a physical barrier (scale or sludge) preventing heat transfer." },
  { id:"calef_465", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué sucede en un sistema de calefacción por agua si el 'Tanque de Expansión' es demasiado pequeño para el volumen total del sistema?", opciones:["El agua circulará más lento debido a la masa térmica excesiva.", "La presión subirá rápidamente al calentar, causando aperturas frecuentes de la válvula de alivio aunque el sistema esté bien purgado.", "La caldera no podrá alcanzar los 80°C de temperatura de diseño.", "Se producirá un vacío en el punto de no cambio de presión."], respuesta_correcta:1, explicacion:"El agua se expande al calentarse. Si no hay suficiente 'espacio' (aire comprimible) en el tanque, la presión no tiene a dónde ir excepto por la válvula de seguridad." , question: "What happens in a hot water heating system if the Expansion Tank is too small for the total system volume?", options: ["The water will circulate more slowly due to excessive thermal mass.", "The pressure will rise rapidly when heating, causing frequent relief valve openings even though the system is properly bled.", "The boiler will not be able to reach the design temperature of 176 degrees F.", "A vacuum will form at the point of no pressure change."], explanation: "Water expands when heated. If there is not enough space (compressible air) in the tank, the pressure has nowhere to go except through the safety valve." },
  { id:"calef_466", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función técnica de un 'Separador de Aire Tangencial'?", opciones:["Aumentar la presión del agua mediante fuerza centrífuga.", "Crear un vórtice que reduce la velocidad del agua en el centro para permitir que las microburbujas de aire se separen y sean expulsadas por la parte superior.", "Evitar que el lodo de la caldera llegue a los radiadores.", "Mezclar el agua de suministro con la de retorno."], respuesta_correcta:1, explicacion:"Usa la física de los fluidos. Al hacer girar el agua, el aire (más ligero) se concentra en el centro del remolino, donde es más fácil sacarlo con una válvula de purga." , question: "What is the technical function of a Tangential Air Separator?", options: ["To increase water pressure through centrifugal force.", "To create a vortex that slows the water in the center, allowing micro-bubbles of air to separate and be expelled from the top.", "To prevent boiler sludge from reaching the radiators.", "To mix supply water with return water."], explanation: "It uses fluid physics. By spinning the water, the air (which is lighter) concentrates in the center of the vortex, where it is easy to remove with a vent valve." },
  { id:"calef_467", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función del 'Vaso de Expansión de Estilo Compresión' (sin diafragma)?", opciones:["Filtrar el agua de la caldera.", "Mantener un colchón de aire directamente en contacto con el agua para absorber la expansión; requiere mantenimiento para evitar que el aire se disuelva en el agua.", "Aumentar la velocidad del circulador.", "Drenar el exceso de agua al alcantarillado."], respuesta_correcta:1, explicacion:"Son los tanques de acero grandes de antes. El aire se acaba 'mezclando' con el agua con el tiempo, y el tanque se llena de agua, perdiendo su función. Hay que vaciarlos periódicamente." , question: "What is the function of a Compression-Style Expansion Tank (without a diaphragm)?", options: ["To filter boiler water.", "To maintain an air cushion in direct contact with the water to absorb expansion; it requires maintenance to prevent the air from dissolving into the water.", "To increase circulator speed.", "To drain excess water to the sewer."], explanation: "These are the large old steel tanks. The air gradually dissolves into the water over time, and the tank fills with water, losing its function. They must be drained periodically." },
  { id:"calef_468", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es una 'Caldera de Baja Masa' y cuál es su principal ventaja?", opciones:["Una caldera hecha de plástico ligero.", "Contiene muy poca agua (intercambiador de cobre o inoxidable), permitiendo responder casi instantáneamente a la demanda de calor sin desperdiciar energía calentando toneladas de hierro fundido.", "Se instala solo en el ático de los edificios.", "No requiere chimenea para funcionar."], respuesta_correcta:1, explicacion:"Es como un calentador de paso. Calienta solo lo que necesitas en el momento. Son muy eficientes pero requieren un flujo de agua muy preciso para no quemarse." , question: "What is a 'Low-Mass Boiler' and what is its main advantage?", options: ["A boiler made of lightweight plastic.", "It contains very little water (copper or stainless steel heat exchanger), allowing it to respond almost instantly to heat demand without wasting energy heating tons of cast iron.", "It is only installed in building attics.", "It does not require a flue to operate."], explanation: "It works like a tankless water heater. It heats only what you need at that moment. They are very efficient but require very precise water flow to avoid overheating." },
  { id:"calef_469", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función del 'Venteo Automático de Flotador'?", opciones:["Sacar el exceso de agua del sistema.", "Eliminar el aire atrapado en el sistema de tuberías de forma continua, usando una boya interna que abre una válvula cuando detecta aire en lugar de agua.", "Regular la presión del tanque de expansión.", "Filtrar las burbujas de vapor de la caldera."], respuesta_correcta:1, explicacion:"Es un centinela silencioso. Evita que tengas que ir radiador por radiador purgando aire. El aire sube, baja el flotador, sale el aire y listo." , question: "What is the function of the 'Automatic Float Vent'?", options: ["To remove excess water from the system.", "To continuously eliminate trapped air from the piping system, using an internal float that opens a valve when it detects air instead of water.", "To regulate the expansion tank pressure.", "To filter steam bubbles from the boiler."], explanation: "It is a silent sentinel. It prevents you from having to go radiator by radiator bleeding air. The air rises, the float drops, the air escapes, and the job is done." },
  { id:"calef_470", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué la 'Presión Estática Mínima' de una caldera de 3 pisos debe ser mayor que la de una caldera de un solo piso?", opciones:["Para que el agua no se oxide con la altura.", "Para vencer la presión hidrostática y asegurar que haya presión positiva en el radiador más alto, evitando que entre aire o que el agua hierva a baja temperatura.", "Porque las bombas de los edificios altos son de corriente directa.", "El código exige 5 PSI extra por cada ventana del edificio."], respuesta_correcta:1, explicacion:"El agua pesa. Cada pie de altura resta 0.433 PSI. Si no subes la presión en el sótano, el radiador del tercer piso estará en vacío y nunca calentará bien." , question: "Why must the 'Minimum Static Pressure' of a 3-story boiler be higher than that of a single-story boiler?", options: ["So that the water does not corrode with height.", "To overcome hydrostatic pressure and ensure positive pressure at the highest radiator, preventing air ingress or the water boiling at low temperature.", "Because pumps in tall buildings run on direct current.", "Code requires 5 PSI extra per building window."], explanation: "Water has weight. Each foot of height reduces pressure by 0.433 PSI. If you do not raise the pressure in the basement, the third-floor radiator will be under vacuum and will never heat properly." },
  { id:"calef_471", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es el propósito de un 'Loop de Expansión' en una tubería larga de vapor o agua caliente?", opciones:["Para que el agua se mezcle mejor.", "Permitir que la tubería se estire y contraiga físicamente por el calor sin romper los soportes, codos o la propia caldera (fatiga mecánica).", "Aumentar la presión estática mediante la gravedad centrífuga.", "Servir como trampa para el lodo y la magnetita."], respuesta_correcta:1, explicacion:"El metal crece cuando se calienta. En 100 pies de tubo, el cobre puede crecer más de una pulgada. Sin el loop (esa curva en forma de U), el tubo empujaría la pared o se doblaría." , question: "What is the purpose of an 'Expansion Loop' in a long steam or hot water pipe?", options: ["To improve water mixing.", "To allow the pipe to physically expand and contract due to heat without breaking supports, elbows, or the boiler itself (mechanical fatigue).", "To increase static pressure through centrifugal gravity.", "To serve as a trap for sludge and magnetite."], explanation: "Metal expands when heated. Over 100 feet of pipe, copper can grow more than one inch. Without the loop (that U-shaped bend), the pipe would push against the wall or buckle." },
  { id:"calef_472", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es la 'Relación de Compresión' y cómo afecta a la vida del compresor en calefacción?", opciones:["La diferencia de temperatura entre el interior y el exterior.", "La relación entre la presión absoluta de descarga y la de succión; si es muy alta (ej. > 10:1), el compresor se sobrecalienta y falla.", "El diámetro del pistón comparado con la biela.", "La cantidad de aceite comparada con el refrigerante."], respuesta_correcta:1, explicacion:"Es el esfuerzo del compresor. En días muy fríos, la succión es bajísima y la descarga alta. Ese 'salto' de presión genera un calor que carboniza el aceite y quema el motor." , question: "What is the 'Compression Ratio' and how does it affect compressor life in heating?", options: ["The temperature difference between indoors and outdoors.", "The ratio between the absolute discharge pressure and the suction pressure; if it is too high (e.g., > 10:1), the compressor overheats and fails.", "The piston diameter compared to the connecting rod.", "The amount of oil compared to the refrigerant."], explanation: "It represents the compressor's effort. On very cold days, suction pressure is extremely low and discharge pressure is high. That pressure jump generates heat that carbonizes the oil and burns out the motor." },
  { id:"calef_473", categoria:"CALEF_HIDRONICA", pregunta:"Usted instala una válvula de zona motorizada. El sistema tiene calor en todas las zonas aunque los termostatos estén apagados. ¿Qué sucedió?", opciones:["La caldera tiene demasiada potencia.", "La palanca de anulación manual (manual override) de la válvula está trabada en posición 'OPEN' o la válvula tiene basura que impide el cierre.", "Las bombas circuladoras están instaladas al revés.", "El termostato está enviando una señal de milivoltios fantasma."], respuesta_correcta:1, explicacion:"Si hay calor sin demanda, el 'tapón' de la válvula no está sellando. A veces los técnicos olvidan quitar el seguro de instalación que mantiene la válvula abierta." , question: "You install a motorized zone valve. The system has heat in all zones even though the thermostats are off. What happened?", options: ["The boiler has too much capacity.", "The manual override lever on the valve is stuck in the 'OPEN' position, or the valve has debris preventing it from closing.", "The circulator pumps are installed backwards.", "The thermostat is sending a phantom millivolt signal."], explanation: "If there is heat without demand, the valve plug is not sealing. Sometimes technicians forget to remove the installation safety that keeps the valve open." },
  { id:"calef_474", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué un sistema hidrónico con tuberías de PEX sin barrera de oxígeno es un error grave en calefacción con radiadores de hierro?", opciones:["Porque el plástico PEX se derrite a 80°C.", "Porque el oxígeno atraviesa las paredes del plástico y corroe los componentes de hierro y acero desde adentro, destruyendo la caldera en pocos años.", "Aumenta la presión del sistema debido a la permeabilidad gaseosa.", "El agua toma un sabor amargo que daña las válvulas."], respuesta_correcta:1, explicacion:"El PEX normal deja pasar oxígeno. Ese oxígeno en el agua es como ácido para el hierro fundido. En calefacción, siempre se usa PEX con 'Oxygen Barrier' (capa de EVOH)." , question: "Why is using PEX tubing without an oxygen barrier a serious mistake in a heating system with cast iron radiators?", options: ["Because PEX plastic melts at 80 degrees Celsius.", "Because oxygen permeates through the plastic walls and corrodes the iron and steel components from within, destroying the boiler in just a few years.", "It increases system pressure due to gas permeability.", "The water develops a bitter taste that damages the valves."], explanation: "Standard PEX allows oxygen to pass through. That oxygen in the water acts like acid on cast iron. In heating systems, PEX with an 'Oxygen Barrier' (EVOH layer) must always be used." },
  { id:"calef_475", categoria:"CALEF_HIDRONICA", pregunta:"En una bomba de calor, ¿qué componente es responsable de asegurar que el compresor no reciba refrigerante líquido en modo calefacción?", opciones:["La válvula de expansión.", "El acumulador de succión, que atrapa el líquido y solo permite que el vapor pase hacia el compresor.", "El filtro deshidratador de doble flujo.", "El sensor de alta presión de descarga."], respuesta_correcta:1, explicacion:"En invierno, el refrigerante no siempre se evapora bien afuera. El acumulador es el 'cubeta' que guarda el líquido hasta que se evapore, salvando las válvulas del compresor." , question: "In a heat pump, which component is responsible for ensuring that the compressor does not receive liquid refrigerant in heating mode?", options: ["The expansion valve.", "The suction accumulator, which traps liquid and only allows vapor to pass toward the compressor.", "The bi-directional filter drier.", "The high-pressure discharge sensor."], explanation: "In winter, the refrigerant does not always evaporate fully outdoors. The accumulator is the reservoir that holds the liquid until it evaporates, protecting the compressor valves." },
  { id:"calef_476", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función del 'Deflector de Aire' (Air Scoop) en una línea de suministro de caldera?", opciones:["Aumentar la velocidad del agua mediante aerodinámica.", "Reducir la velocidad del agua localmente para permitir que las burbujas de aire floten hacia arriba y sean capturadas por una purga automática.", "Evitar que el agua caliente queme las tuberías de plástico.", "Filtrar las partículas de óxido antes de que lleguen a la bomba."], respuesta_correcta:1, explicacion:"El aire es el enemigo del silencio y del calor en hidrónica. El Air Scoop es el 'atrapaburbujas' básico de cualquier instalación profesional." , question: "What is the function of the 'Air Scoop' in a boiler supply line?", options: ["To increase water velocity through aerodynamics.", "To locally reduce water velocity so air bubbles can float upward and be captured by an automatic vent.", "To prevent hot water from damaging plastic piping.", "To filter rust particles before they reach the pump."], explanation: "Air is the enemy of silence and heat in hydronic systems. The air scoop is the basic bubble catcher in any professional installation." },
  { id:"calef_477", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es una 'Válvula de Llenado Rápido' (Fast Fill) y cuándo debe usarse?", opciones:["Para llenar una piscina con agua de la caldera.", "Una función de la válvula reductora que permite meter agua a alta presión para llenar y purgar el sistema rápidamente durante la instalación o mantenimiento.", "Solo se usa en sistemas de vapor de alta presión.", "Para inyectar gas natural líquido en la caldera."], respuesta_correcta:1, explicacion:"Sirve para ahorrar tiempo. En lugar de esperar a que el agua entre goteando a 12 PSI, abres el 'Fast Fill' y llenas todo el edificio en minutos para buscar fugas y sacar el aire." , question: "What is a 'Fast Fill Valve' and when should it be used?", options: ["To fill a swimming pool with boiler water.", "A feature on the pressure reducing valve that allows high-pressure water in to fill and purge the system quickly during installation or maintenance.", "It is only used in high-pressure steam systems.", "To inject liquefied natural gas into the boiler."], explanation: "It saves time. Instead of waiting for water to trickle in at 12 PSI, you open the fast fill and charge the entire building in minutes to check for leaks and purge the air." },
  { id:"calef_478", categoria:"CALEF_HIDRONICA", pregunta:"En modo calefacción, una bomba de calor tiene hielo solo en la parte inferior del serpentín exterior. ¿Qué indica?", opciones:["Que el sistema está funcionando al 100%.", "Baja carga de refrigerante o una restricción parcial en el dispositivo de expansión exterior (TXV/Orificio).", "Que el ventilador exterior está girando demasiado rápido.", "Es una señal de que el aceite está muy frío."], respuesta_correcta:1, explicacion:"El hielo debe ser parejo. Si solo hay una franja abajo, es porque el refrigerante 'se acaba' (se evapora del todo) antes de recorrer todo el serpentín. Falta gas." , question: "In heating mode, a heat pump has ice only on the bottom portion of the outdoor coil. What does this indicate?", options: ["The system is operating at 100 percent.", "Low refrigerant charge or a partial restriction in the outdoor expansion device (TXV/orifice).", "The outdoor fan is spinning too fast.", "It is a sign that the oil is too cold."], explanation: "Ice should be even across the coil. If there is only a strip at the bottom, it means the refrigerant runs out (fully evaporates) before traveling through the entire coil. The system is low on charge." },
  { id:"calef_479", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Punto de No Cambio de Presión' (PONPC) en un sistema hidrónico?", opciones:["El terminal del termostato de la caldera.", "La conexión del tanque de expansión al sistema; es el único lugar donde la presión se mantiene constante sin importar si la bomba está encendida o apagada.", "La salida de la válvula de alivio de 30 PSI.", "El punto medio exacto de la tubería de suministro."], respuesta_correcta:1, explicacion:"Es el ancla de presión. Por eso la bomba debe 'alejarse' de este punto para que la presión en el resto del sistema suba y no baje, evitando que entre aire." , question: "What is the 'Point of No Pressure Change' (PONPC) in a hydronic system?", options: ["The boiler thermostat terminal.", "The connection point of the expansion tank to the system; it is the only location where pressure remains constant regardless of whether the pump is on or off.", "The outlet of the 30 PSI relief valve.", "The exact midpoint of the supply piping."], explanation: "It is the pressure anchor. That is why the pump must pump away from this point so that pressure in the rest of the system rises rather than drops, preventing air ingestion." },
  { id:"calef_480", categoria:"CALEF_HIDRONICA", pregunta:"Usted instala una caldera de condensación. ¿Por qué se requiere un 'Separador Hidráulico' (Low Loss Header) si hay múltiples bombas de zona?", opciones:["Para que el agua no se mezcle con el aire.", "Para desacoplar el flujo de la caldera del flujo de las zonas, evitando que las bombas interfieran entre sí y garantizando el flujo mínimo en el intercambiador.", "Aumenta la presión de la caldera a 50 PSI.", "Sirve para drenar el lodo de forma automática."], respuesta_correcta:1, explicacion:"Es un 'puente' de paz. Permite que la bomba de la caldera mueva su agua y las bombas de la casa muevan la suya sin pelearse por el flujo. Es vital para calderas modernas." , question: "You install a condensing boiler. Why is a 'Hydraulic Separator' (Low-Loss Header) required when there are multiple zone pumps?", options: ["To prevent water from mixing with air.", "To decouple the boiler flow from the zone flows, preventing the pumps from interfering with each other and ensuring minimum flow through the heat exchanger.", "It increases boiler pressure to 50 PSI.", "It drains sludge automatically."], explanation: "It is a peace bridge. It allows the boiler pump to move its water and the house pumps to move theirs without fighting over flow. It is essential for modern boilers." },
  { id:"calef_481", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué un radiador de hierro fundido tarda tanto en calentar y tanto en enfriar comparado con un ducto de aire?", opciones:["Debido a su alta inercia térmica; la masa de hierro debe absorber mucha energía antes de empezar a radiarla al cuarto.", "Porque el hierro fundido repele los electrones de calor.", "El agua viaja a una velocidad menor a 1 pie por segundo.", "El aire de los ductos está presurizado a 10 PSI."], respuesta_correcta:0, explicacion:"Es como un termo gigante. Tarda en 'agarrar' calor, pero una vez que está caliente, sigue soltando calor por horas aunque la caldera se apague. Es muy confortable." , question: "Why does a cast iron radiator take so long to heat up and so long to cool down compared to a forced-air duct?", options: ["Due to its high thermal inertia; the iron mass must absorb a large amount of energy before it begins radiating it into the room.", "Because cast iron repels heat electrons.", "The water travels at less than 1 foot per second.", "Duct air is pressurized at 10 PSI."], explanation: "It works like a giant thermos. It takes a while to absorb heat, but once it is hot, it continues releasing heat for hours even after the boiler shuts off. It provides very comfortable heating." },
  { id:"calef_482", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es el propósito de una 'Válvula de Retención' (Check Valve) en un sistema de múltiples bombas?", opciones:["Aumentar la presión del agua en un 10%.", "Evitar el flujo inverso de agua caliente hacia zonas que no están pidiendo calor (Gravity Flow), lo que causaría sobrecalentamiento de cuartos apagados.", "Filtrar el aire de las tuberías de cobre.", "Regular la temperatura de la caldera automáticamente."], respuesta_correcta:1, explicacion:"Sin esta válvula, una bomba prendida podría empujar agua hacia atrás por otros tubos. Tendrías radiadores calientes en cuartos donde el termostato dice que está apagado." , question: "What is the purpose of a 'Check Valve' in a multi-pump hydronic system?", options: ["To increase water pressure by 10 percent.", "To prevent reverse flow of hot water into zones that are not calling for heat (gravity flow), which would cause overheating in rooms that are supposed to be off.", "To filter air from copper piping.", "To automatically regulate the boiler temperature."], explanation: "Without this valve, a running pump could push water backwards through other pipes. You would have hot radiators in rooms where the thermostat says the zone is off." },
  { id:"calef_483", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función del 'Acuastato de Inmersión'?", opciones:["Medir el nivel de agua en la piscina.", "Sentir la temperatura real del agua dentro de la caldera mediante una sonda sumergida, controlando el quemador para evitar sobrecalentamientos.", "Regular la humedad del cuarto de máquinas.", "Filtrar los lodos del fondo de la caldera."], respuesta_correcta:1, explicacion:"Es el termostato que 'toca' el agua. Es el jefe de la caldera; si el agua llega a 80°C, él apaga el fuego aunque el termostato de la casa siga pidiendo calor." , question: "What is the function of the 'Immersion Aquastat'?", options: ["To measure the water level in a pool.", "To sense the actual water temperature inside the boiler via a submerged probe, controlling the burner to prevent overheating.", "To regulate the humidity in the mechanical room.", "To filter sludge from the bottom of the boiler."], explanation: "It is the thermostat that touches the water. It is the boss of the boiler; if the water reaches 180 degrees Fahrenheit, it shuts off the flame even if the house thermostat is still calling for heat." },
  { id:"calef_484", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función de la 'Válvula de Zona Inalámbrica'?", opciones:["Funciona sin agua mediante magnetismo.", "Permite controlar el flujo de agua hacia un radiador mediante una señal de radio desde el termostato, sin necesidad de cables entre ambos.", "Se conecta directo al Wi-Fi para predecir el clima.", "Ahorra energía al no usar motores eléctricos."], respuesta_correcta:1, explicacion:"Es la tecnología moderna. Ideal para casas viejas donde no quieres romper paredes para pasar cables. El termostato le dice 'ábrete' por radio y la válvula obedece." , question: "What is the function of a 'Wireless Zone Valve'?", options: ["It operates without water using magnetism.", "It allows controlling the flow of water to a radiator via a radio signal from the thermostat, eliminating the need for wiring between the two.", "It connects directly to Wi-Fi to predict the weather.", "It saves energy by not using electric motors."], explanation: "It is modern technology. Ideal for older homes where you do not want to break open walls to run wires. The thermostat tells the valve to open via radio and the valve complies." },
  { id:"calef_485", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué es crítico el uso de un 'Sifón' (Pigtail) en la conexión de un manómetro de presión de una caldera de vapor?", opciones:["Para que el manómetro no vibre con la bomba.", "Para crear un sello de agua condensada que proteja los componentes internos del manómetro del contacto directo con el vapor vivo a alta temperatura.", "Aumentar la precisión de la lectura mediante el efecto Venturi.", "Evitar que el aire del cuarto entre a la caldera."], respuesta_correcta:1, explicacion:"El vapor vivo derretiría o descalibraría el manómetro. El tubo en espiral atrapa agua fría que actúa como un 'colchón' térmico de protección." , question: "Why is the use of a 'Pigtail' (siphon) critical when connecting a pressure gauge to a steam boiler?", options: ["To prevent the gauge from vibrating with the pump.", "To create a seal of condensed water that protects the internal components of the gauge from direct contact with live steam at high temperature.", "To increase reading accuracy through the Venturi effect.", "To prevent room air from entering the boiler."], explanation: "Live steam would melt or de-calibrate the gauge. The coiled tube traps cool water that acts as a thermal cushion of protection." },
  { id:"calef_486", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Límite de Velocidad de Erosión' en tuberías de cobre de un sistema de calefacción hidrónica?", opciones:["La velocidad a la que el agua se convierte en vapor.", "La velocidad máxima (típicamente 4-5 pies/seg) por encima de la cual el agua comienza a desgastar mecánicamente las paredes internas del tubo y los codos.", "El punto donde la bomba consume el doble de amperaje.", "La velocidad necesaria para limpiar el lodo de la caldera."], respuesta_correcta:1, explicacion:"El agua a alta velocidad actúa como lija. Si la bomba es muy grande para el tubo, el cobre se volverá tan delgado que aparecerán fugas por 'picaduras' en pocos años." , question: "What is the 'Erosion Velocity Limit' in copper piping of a hydronic heating system?", options: ["The velocity at which water turns into steam.", "The maximum velocity (typically 4-5 feet per second) above which water begins to mechanically wear away the inner walls of the tube and elbows.", "The point where the pump draws double the amperage.", "The velocity needed to flush sludge from the boiler."], explanation: "High-velocity water acts like sandpaper. If the pump is oversized for the pipe, the copper will become so thin that pinhole leaks will appear within a few years." },
  { id:"calef_487", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es la 'Temperatura de Inyección de Vapor' (Vapor Injection) en compresores de bomba de calor de clima ártico?", opciones:["Cuando se inyecta agua al compresor para enfriarlo.", "Una técnica donde se introduce refrigerante gaseoso a media presión en el scroll para aumentar la capacidad calorífica y eficiencia en temperaturas bajo cero.", "El calor generado por la fricción de los pistones.", "Un método para derretir el hielo del serpentín exterior sin usar la válvula reversible."], respuesta_correcta:1, explicacion:"Es tecnología de punta. Permite que la bomba de calor siga funcionando a -25°C con una eficiencia aceptable, algo que los compresores normales no pueden hacer." , question: "What is 'Vapor Injection Temperature' in arctic-climate heat pump compressors?", options: ["When water is injected into the compressor to cool it.", "A technique where intermediate-pressure gaseous refrigerant is introduced into the scroll to increase heating capacity and efficiency at sub-zero temperatures.", "The heat generated by piston friction.", "A method to melt ice from the outdoor coil without using the reversing valve."], explanation: "It is cutting-edge technology. It allows the heat pump to keep operating at minus 25 degrees Celsius with acceptable efficiency, something standard compressors cannot do." },
  { id:"calef_488", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Efecto de Absorción' en un sistema de calefacción hidrónica de circuito cerrado?", opciones:["Cuando el metal de la caldera absorbe el calor del fuego.", "La capacidad del agua fría de retener más aire disuelto que el agua caliente; al calentar el agua, el aire se libera y forma burbujas molestas.", "Un proceso donde el glicol absorbe la humedad de la habitación.", "La succión que genera la bomba circuladora en el retorno."], respuesta_correcta:1, explicacion:"Por eso purgas el aire cuando la caldera está caliente. El agua caliente es como un refresco tibio: suelta todo el gas (aire) de inmediato." , question: "What is the 'Absorption Effect' in a closed-loop hydronic heating system?", options: ["When the boiler metal absorbs heat from the flame.", "The ability of cold water to hold more dissolved air than hot water; when the water is heated, the air is released and forms troublesome bubbles.", "A process where glycol absorbs room humidity.", "The suction the circulator pump generates on the return."], explanation: "That is why you bleed air when the boiler is hot. Hot water is like a warm soda: it releases all its gas (air) immediately." },
  { id:"calef_489", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función del 'Deflector de Flujo' (Flow Baffle) dentro de una caldera seccional de hierro fundido?", opciones:["Evitar que el agua se escape por la chimenea.", "Dirigir el agua hacia las superficies más calientes y crear turbulencia para maximizar la transferencia de calor y evitar puntos de ebullición localizados.", "Reducir el peso total del agua dentro de la caldera.", "Servir como soporte para el quemador de gas."], respuesta_correcta:1, explicacion:"Sin deflectores, el agua pasaría 'de largo' por el centro. El deflector obliga al agua a 'tocar' las paredes calientes para que se lleve todo el calor del fuego." , question: "What is the function of the 'Flow Baffle' inside a cast iron sectional boiler?", options: ["To prevent water from escaping through the flue.", "To direct water toward the hottest surfaces and create turbulence to maximize heat transfer and prevent localized boiling.", "To reduce the total weight of water inside the boiler.", "To serve as a support for the gas burner."], explanation: "Without baffles, water would pass straight through the center. The baffle forces the water to contact the hot walls so it absorbs all the heat from the flame." },
  { id:"calef_490", categoria:"CALEF_HIDRONICA", pregunta:"En modo calefacción, ¿por qué se utiliza una válvula de expansión diferente a la de modo refrigeración?", opciones:["Porque el refrigerante cambia de dirección.", "Debido a que las cargas térmicas y las presiones de operación en invierno requieren un orificio de tamaño diferente para mantener el sobrecalentamiento correcto.", "El aceite se vuelve más espeso en invierno y requiere válvulas más grandes.", "Para evitar que el compresor gire en sentido contrario."], respuesta_correcta:1, explicacion:"Calentar una casa a 0°C es muy diferente a enfriarla a 35°C. El sistema necesita 'ajustar' el flujo de refrigerante de forma específica para cada estación." , question: "In heating mode, why is a different expansion valve used than in cooling mode?", options: ["Because the refrigerant changes direction.", "Because the thermal loads and operating pressures in winter require a differently sized orifice to maintain proper superheat.", "The oil becomes thicker in winter and requires larger valves.", "To prevent the compressor from spinning in reverse."], explanation: "Heating a house at 0 degrees Celsius is very different from cooling it at 35 degrees Celsius. The system needs to adjust the refrigerant flow specifically for each season." },
  { id:"calef_491", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función de una 'Válvula Reguladora de Presión Diferencial' en un sistema de bombas de velocidad variable?", opciones:["Aumentar la presión de la caldera a 100 PSI.", "Mantener una presión constante entre el suministro y el retorno, evitando ruidos de flujo y protegiendo las bombas cuando muchas válvulas de zona se cierran.", "Drenar el agua caliente si supera los 90°C.", "Mezclar el agua con aire para mejorar la eficiencia."], respuesta_correcta:1, explicacion:"Es el 'amortiguador' del sistema. Si todas las habitaciones se calientan y cierran sus tubos, el agua no tiene a dónde ir. Esta válvula abre un camino de alivio para que la bomba no sufra." , question: "What is the function of a 'Differential Pressure Regulating Valve' in a variable-speed pump system?", options: ["To increase boiler pressure to 100 PSI.", "To maintain a constant pressure between supply and return, preventing flow noise and protecting the pumps when many zone valves close.", "To drain hot water if it exceeds 194 degrees Fahrenheit.", "To mix water with air to improve efficiency."], explanation: "It is the system's shock absorber. If all rooms heat up and close their zones, the water has nowhere to go. This valve opens a relief path so the pump does not suffer." },
  { id:"calef_492", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función de una 'Válvula de Llenado Automático' con desconector (Backflow Preventer)?", opciones:["Hacer que el agua de la caldera sepa mejor.", "Mantener la presión mínima de la caldera y evitar que el agua sucia de la calefacción regrese a la red de agua potable de la casa en caso de caída de presión.", "Regular el flujo de gas hacia el quemador principal.", "Drenar el agua caliente de forma automática cada 24 horas."], respuesta_correcta:1, explicacion:"Seguridad sanitaria. El agua de la caldera tiene óxido y químicos. Esta válvula deja entrar agua limpia pero prohíbe que el 'agua negra' de los radiadores salga por tu grifo." , question: "What is the function of an 'Automatic Fill Valve' with a Backflow Preventer?", options: ["To make the boiler water taste better.", "To maintain the minimum boiler pressure and prevent dirty heating water from flowing back into the domestic potable water supply in the event of a pressure drop.", "To regulate gas flow to the main burner.", "To drain hot water automatically every 24 hours."], explanation: "It is a sanitary safety device. Boiler water contains rust and chemicals. This valve allows clean water in but prevents the contaminated water from the radiators from reaching your faucet." },
  { id:"calef_493", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función del 'Sub-enfriador Interetapa' en una bomba de calor de CO2 (R-744) para climas extremadamente fríos?", opciones:["Convertir el gas en hielo para almacenamiento térmico.", "Aumentar el efecto refrigerante y reducir la temperatura de descarga del compresor en el ciclo transcrítico, permitiendo calentar agua a 80°C con aire exterior a -20°C.", "Eliminar el nitrógeno del refrigerante líquido.", "Actuar como un silenciador para las válvulas de expansión."], respuesta_correcta:1, explicacion:"El CO2 es un refrigerante increíble pero difícil de manejar. El sub-enfriador permite que el sistema trabaje en condiciones donde un gas normal (como el R-410A) simplemente dejaría de calentar." , question: "What is the function of the 'Interstage Subcooler' in a CO2 (R-744) heat pump for extremely cold climates?", options: ["To convert gas into ice for thermal storage.", "To increase the refrigerating effect and reduce the compressor discharge temperature in the transcritical cycle, enabling water heating to 176 degrees Fahrenheit with outdoor air at minus 4 degrees Fahrenheit.", "To remove nitrogen from the liquid refrigerant.", "To act as a silencer for the expansion valves."], explanation: "CO2 is an incredible but difficult-to-manage refrigerant. The subcooler allows the system to operate in conditions where a conventional refrigerant like R-410A would simply stop providing heat." },
  { id:"calef_494", categoria:"CALEF_HIDRONICA", pregunta:"Usted escucha ruidos de 'crujido' (crackling) dentro de una caldera de hierro fundido. ¿Qué fenómeno físico está ocurriendo?", opciones:["El metal se está expandiendo normalmente.", "Ebullición localizada o 'nucleada' debido a depósitos de sarro en el intercambiador que impiden que el agua enfríe el metal, creando burbujas de vapor que colapsan.", "El soplador de aire está mal balanceado.", "La presión del tanque de expansión es de 12 PSI."], respuesta_correcta:1, explicacion:"Es como una cafetera vieja. El sarro actúa como un aislante; el metal debajo del sarro se pone tan caliente que hierve el agua instantáneamente, causando esos ruidos de 'golpeteo' o 'crujido'." , question: "You hear 'crackling' noises inside a cast iron boiler. What physical phenomenon is occurring?", options: ["The metal is expanding normally.", "Localized or nucleate boiling caused by scale deposits on the heat exchanger that prevent water from cooling the metal, creating vapor bubbles that collapse violently.", "The combustion blower is out of balance.", "The expansion tank pressure is 12 PSI."], explanation: "It is like an old coffee percolator. The scale acts as an insulator; the metal beneath the scale gets so hot that it boils the water instantly, causing those knocking or crackling sounds." },
  { id:"calef_495", categoria:"CALEF_HIDRONICA", pregunta:"Usted instala una 'Válvula de Mezcla Termostática' en una caldera. ¿Cuál es su propósito primordial en un sistema de radiadores de hierro fundido?", opciones:["Hacer que el agua sea potable.", "Mantener la temperatura del agua de retorno por encima de 54°C (130°F) para prevenir la condensación corrosiva de los gases dentro de la caldera.", "Aumentar la presión del sistema a 30 PSI constantes.", "Drenar el aire de los radiadores de forma automática."], respuesta_correcta:1, explicacion:"Las calderas viejas odian el agua fría. Si el retorno viene muy frío, el humo se condensa y el ácido se 'come' el hierro. La válvula mezcla agua caliente de salida con la fría de entrada para proteger el equipo." , question: "You install a 'Thermostatic Mixing Valve' on a boiler. What is its primary purpose in a cast iron radiator system?", options: ["To make the water potable.", "To keep the return water temperature above 130 degrees Fahrenheit to prevent corrosive condensation of flue gases inside the boiler.", "To increase system pressure to a constant 30 PSI.", "To automatically bleed air from the radiators."], explanation: "Older boilers hate cold water. If the return comes back too cold, the flue gases condense and the acid eats away the iron. The valve mixes hot supply water with the cold return to protect the equipment." },
  { id:"calef_496", categoria:"CALEF_HIDRONICA", pregunta:"Usted encuentra una caldera hidrónica donde el circulador está en el suministro y el tanque de expansión en el retorno. ¿Qué problema de presión genera esto?", opciones:["Aumenta la eficiencia de los radiadores.", "La bomba 'succiona' del tanque de expansión, creando una caída de presión en todo el edificio que puede causar la entrada de aire por los purgadores (Air Ingestion).", "El agua cambiará de sentido de giro aleatoriamente.", "No genera ningún problema si la caldera es de hierro fundido."], respuesta_correcta:1, explicacion:"Siempre se debe bombear 'lejos' del tanque de expansión. Si bombeas hacia el sistema desde el tanque, la presión sube. Si bombeas alejándote del tanque pero este está lejos, la presión baja y el aire entra." , question: "You find a hydronic boiler where the circulator is on the supply and the expansion tank is on the return. What pressure problem does this create?", options: ["It increases radiator efficiency.", "The pump draws suction from the expansion tank, creating a pressure drop throughout the building that can cause air ingestion through the air vents.", "The water will randomly change its flow direction.", "It causes no problem if the boiler is cast iron."], explanation: "You should always pump away from the expansion tank. If you pump toward the system from the tank, pressure rises. If you pump away from the tank but the tank is far away, pressure drops and air enters the system." },
  { id:"calef_497", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función técnica de un 'Tanque de Expansión de Estilo Diafragma' comparado con uno de tanque abierto?", opciones:["Ocupa más espacio en el cuarto de máquinas.", "Separa físicamente el aire del agua mediante una membrana de goma, evitando que el aire se disuelva en el agua y cause corrosión o ruidos en las tuberías.", "Filtra los sedimentos de la caldera automáticamente.", "Mantiene el agua a una temperatura de 100°C constantes."], respuesta_correcta:1, explicacion:"Es el estándar moderno. Al no tocarse el aire y el agua, no tienes que estar 'purgando' el sistema cada mes y el hierro de los radiadores dura mucho más tiempo sin oxidarse." , question: "What is the technical function of a 'Diaphragm-Style Expansion Tank' compared to an open-type tank?", options: ["It takes up more space in the mechanical room.", "It physically separates air from water using a rubber membrane, preventing air from dissolving into the water and causing corrosion or pipe noise.", "It automatically filters sediment from the boiler.", "It keeps the water at a constant 212 degrees Fahrenheit."], explanation: "It is the modern standard. Because the air and water never make contact, you do not have to bleed the system every month, and the iron in the radiators lasts much longer without rusting." },
  { id:"calef_498", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es la 'Inyección de Líquido' en un compresor de calefacción y cuándo se activa?", opciones:["Se usa para limpiar el compresor por dentro con refrigerante.", "Inyectar una pequeña cantidad de refrigerante líquido en el puerto de succión para enfriar el motor del compresor cuando las temperaturas de descarga son peligrosamente altas.", "Es un método para aumentar el amperaje durante el arranque.", "Sirve para lubricar los pistones en modo de descongelación."], respuesta_correcta:1, explicacion:"En días de mucho frío, el compresor se calienta horrores tratando de sacar calor del aire. El sistema le 'rocía' un poco de líquido frío para que no se queme por dentro." , question: "What is 'Liquid Injection' in a heating compressor and when does it activate?", options: ["It is used to clean the compressor internally with refrigerant.", "Injecting a small amount of liquid refrigerant into the suction port to cool the compressor motor when discharge temperatures become dangerously high.", "It is a method to increase amperage during startup.", "It lubricates the pistons during the defrost cycle."], explanation: "On extremely cold days, the compressor overheats trying to extract heat from the air. The system sprays a small amount of cool liquid to keep it from burning up internally." },
  { id:"calef_499", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es una 'Caldera de Condensación de Pre-mezcla' y cómo logra eficiencias del 95%+?", opciones:["Usa electricidad y gas al mismo tiempo para calentar.", "Mezcla el aire y el gas con precisión milimétrica antes del quemador y enfría los gases de escape por debajo de 54°C para recuperar el calor latente del vapor de agua.", "No usa chimenea, los gases se disuelven en el agua de la calefacción.", "Funciona con un ciclo de refrigeración inverso interno."], respuesta_correcta:1, explicacion:"Es la maravilla moderna. En lugar de tirar el vapor de agua caliente por el techo, lo vuelve agua líquida y le roba todo ese calor extra para calentar tu casa." , question: "What is a 'Pre-Mix Condensing Boiler' and how does it achieve efficiencies of 95 percent or higher?", options: ["It uses both electricity and gas simultaneously to heat.", "It mixes air and gas with pinpoint precision before the burner and cools the exhaust gases below 130 degrees Fahrenheit to recover the latent heat from the water vapor.", "It has no flue; the gases dissolve into the heating water.", "It operates with an internal reverse refrigeration cycle."], explanation: "It is a modern engineering marvel. Instead of sending hot water vapor up the chimney, it turns that vapor back into liquid water and captures all that extra heat to warm your home." },
  { id:"calef_500", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué el aire atrapado en un radiador de hierro fundido impide que este caliente la habitación?", opciones:["Porque el aire es un conductor térmico mejor que el agua.", "Porque el aire ocupa el espacio donde debería estar el agua caliente, y al ser un pésimo conductor térmico, actúa como un aislante dentro del radiador.", "El aire oxida el agua y le quita el calor.", "El peso del aire frena la bomba circuladora de la caldera."], respuesta_correcta:1, explicacion:"El agua caliente no puede entrar si hay aire estorbando. Como el aire no transporta bien el calor, el radiador se queda frío y tú también. Por eso hay que purgar." , question: "Why does trapped air in a cast iron radiator prevent it from heating the room?", options: ["Because air is a better thermal conductor than water.", "Because the air occupies the space where hot water should be, and since air is a very poor thermal conductor, it acts as insulation inside the radiator.", "The air oxidizes the water and removes its heat.", "The weight of the air slows down the boiler circulator pump."], explanation: "Hot water cannot enter if air is blocking the way. Since air does not transfer heat well, the radiator stays cold and so do you. That is why you need to bleed it." },
  { id:"calef_501", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es el 'Agua de Alimentación' (Make-up Water) en una caldera de vapor y por qué debe minimizarse?", opciones:["Es el agua que se usa para limpiar la caldera por fuera.", "Es agua nueva que entra para reponer la que se pierde; debe minimizarse porque trae oxígeno y minerales frescos que causan corrosión e incrustaciones internas.", "Sirve para enfriar el vapor antes de que llegue a los radiadores.", "Es el agua que se mezcla con el combustible para reducir el NOx."], respuesta_correcta:1, explicacion:"Cada vez que metes agua nueva de la llave, metes 'sarro' y oxígeno. Si tu sistema gasta mucha agua, tu caldera se morirá por corrosión interna muy rápido." , question: "What is 'Make-up Water' in a steam boiler and why must it be minimized?", options: ["It is water used to clean the outside of the boiler.", "It is fresh water that enters to replace water lost from the system; it must be minimized because it brings in fresh oxygen and minerals that cause internal corrosion and scale.", "It cools the steam before it reaches the radiators.", "It is water mixed with fuel to reduce NOx emissions."], explanation: "Every time you add fresh tap water, you introduce scale-forming minerals and oxygen. If your system consumes a lot of make-up water, the boiler will die from internal corrosion very quickly." },
  { id:"calef_502", categoria:"CALEF_HIDRONICA", pregunta:"Usted nota que la bomba de condensado de una caldera de vapor hace un ruido de 'gravilla' (gravel noise). ¿Qué está sucediendo físicamente?", opciones:["Hay piedras reales dentro de la tubería de retorno.", "Cavitación: el agua está tan caliente que se convierte en vapor en la succión de la bomba, y las burbujas colapsan violentamente contra el impulsor.", "El motor de la bomba está girando a 5000 RPM.", "La trampa de vapor está dejando pasar aire frío."], respuesta_correcta:1, explicacion:"Si el agua de retorno está cerca de hervir, la succión de la bomba la hace 'explotar' en burbujas de vapor. Al estallar esas burbujas, golpean el metal como si fueran piedras." , question: "You notice that the condensate pump on a steam boiler makes a 'gravel' noise. What is happening physically?", options: ["There are actual rocks inside the return pipe.", "Cavitation: the water is so hot that it flashes into vapor at the pump suction, and the bubbles collapse violently against the impeller.", "The pump motor is running at 5000 RPM.", "The steam trap is allowing cold air to pass through."], explanation: "If the return water is near boiling, the pump's suction causes it to flash into vapor bubbles. When those bubbles collapse, they hammer the metal as if they were stones." },
  { id:"calef_503", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué el 'Hielo en el Fondo' (Ice bridging) del serpentín exterior es más peligroso que una capa fina de escarcha pareja?", opciones:["Porque el hielo del fondo es más difícil de ver.", "Puede doblar las aletas de aluminio, romper los tubos de cobre por expansión y bloquear el drenaje del agua derretida, causando una falla catastrófica del serpentín.", "Aumenta el amperaje del compresor en un 50%.", "El hielo del fondo atrae rayos durante las tormentas de invierno."], respuesta_correcta:1, explicacion:"El hielo acumulado abajo se convierte en un bloque sólido. El agua de arriba no puede salir, se congela también y al expandirse tiene tanta fuerza que dobla el cobre como si fuera papel." , question: "Why is 'Ice Bridging' at the bottom of the outdoor coil more dangerous than a thin, even layer of frost?", options: ["Because ice at the bottom is harder to see.", "It can bend the aluminum fins, crack the copper tubes by expansion, and block the drain for meltwater, causing catastrophic coil failure.", "It increases compressor amperage by 50 percent.", "Bottom ice attracts lightning during winter storms."], explanation: "Accumulated ice at the bottom becomes a solid block. The meltwater from above cannot drain, freezes as well, and as it expands it has enough force to bend copper tubing like paper." },
  { id:"calef_504", categoria:"CALEF_HIDRONICA", pregunta:"En un sistema de calefacción hidrónica, ¿qué es el 'Differential Pressure Bypass Valve' (DPBV)?", opciones:["Una válvula para drenar el exceso de agua caliente.", "Un componente que protege la bomba circuladora abriendo un camino corto cuando muchas válvulas de zona se cierran, evitando que la bomba sufra por falta de flujo.", "Regula la temperatura de la caldera mediante un bimetal.", "Aumenta la presión del tanque de expansión a 30 PSI."], respuesta_correcta:1, explicacion:"Es la válvula de alivio de la bomba. Si todas las zonas se cierran, el agua no tiene a dónde ir y la bomba se quemaría. Esta válvula 'salva' a la bomba dándole un escape." , question: "In a hydronic heating system, what is the 'Differential Pressure Bypass Valve' (DPBV)?", options: ["A valve to drain excess hot water.", "A component that protects the circulator pump by opening a short path when many zone valves close, preventing the pump from suffering due to lack of flow.", "It regulates the boiler temperature using a bimetallic element.", "It increases the expansion tank pressure to 30 PSI."], explanation: "It is the pump's relief valve. If all zones close, the water has nowhere to go and the pump would burn out. This valve saves the pump by giving it an escape path." },
  { id:"calef_505", categoria:"CALEF_HIDRONICA", pregunta:"Usted encuentra que la válvula de alivio de 30 PSI de una caldera gotea. La presión del sistema es de 15 PSI. ¿Cuál es el diagnóstico?", opciones:["El tanque de expansión está lleno de agua.", "Asiento de la válvula de alivio sucio o dañado por sedimentos; la válvula no está sellando y debe ser reemplazada.", "La caldera está calentando demasiado rápido.", "Es una purga normal de aire del sistema."], respuesta_correcta:1, explicacion:"Si gotea con presión baja, la válvula está 'picada' o tiene basurita en el empaque. Ya no sirve. Cámbiala antes de que inunde el sótano." , question: "You find that the 30 PSI relief valve on a boiler is dripping. The system pressure is 15 PSI. What is the diagnosis?", options: ["The expansion tank is waterlogged.", "The relief valve seat is dirty or damaged by sediment; the valve is not sealing and must be replaced.", "The boiler is heating too quickly.", "It is a normal air purge from the system."], explanation: "If it drips at low pressure, the valve is pitted or has debris on the seal. It no longer works. Replace it before it floods the basement." },
  { id:"calef_506", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función del 'Hartford Loop' en una caldera de vapor de baja presión?", opciones:["Controlar la temperatura de los radiadores.", "Evitar que la caldera se quede sin agua (dry fire) si hay una rotura en la línea de retorno de condensado, protegiendo el intercambiador de una explosión.", "Aumentar la presión del vapor mediante un lazo gravitacional.", "Servir como purga automática de aire del sistema."], respuesta_correcta:1, explicacion:"Es una trampa de seguridad física. Si un tubo de retorno se rompe, el agua de la caldera solo puede bajar hasta cierto punto, salvando al equipo de quemarse vacío." , question: "What is the function of the 'Hartford Loop' in a low-pressure steam boiler?", options: ["To control the temperature of the radiators.", "To prevent the boiler from running dry (dry fire) if there is a break in the condensate return line, protecting the heat exchanger from an explosion.", "To increase steam pressure through a gravitational loop.", "To serve as an automatic air vent for the system."], explanation: "It is a physical safety trap. If a return pipe breaks, the boiler water can only drain down to a certain level, saving the equipment from firing dry." },
  { id:"calef_507", categoria:"CALEF_HIDRONICA", pregunta:"En modo calefacción, una bomba de calor tiene una presión de succión bajísima y el serpentín exterior está totalmente congelado en 5 minutos. ¿Qué falla?", opciones:["El compresor está fallando internamente.", "Fallo del ventilador exterior o del sistema de descongelación (Defrost Control), impidiendo que el serpentín absorba calor del aire ambiente.", "Hay exceso de refrigerante en el sistema.", "La válvula reversible está trabada en modo frío."], respuesta_correcta:1, explicacion:"Si el ventilador no sopla aire sobre el serpentín, el refrigerante se pone helado y congela la humedad del aire al instante. Sin aire, no hay calor que mover." , question: "In heating mode, a heat pump has extremely low suction pressure and the outdoor coil freezes solid within 5 minutes. What is the failure?", options: ["The compressor is failing internally.", "Failure of the outdoor fan or the defrost control system, preventing the coil from absorbing heat from the ambient air.", "There is an overcharge of refrigerant in the system.", "The reversing valve is stuck in cooling mode."], explanation: "If the fan is not blowing air across the coil, the refrigerant becomes extremely cold and instantly freezes the moisture from the air. Without airflow, there is no heat to move." },
  { id:"calef_508", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función del 'Automatic Feed Valve' en una caldera de agua caliente?", opciones:["Meter gas natural a la caldera automáticamente.", "Mantener el nivel de agua y la presión mínima del sistema (típicamente 12 PSI) inyectando agua de la red cuando detecta una caída de presión.", "Aumentar la temperatura del agua a 100°C.", "Drenar el lodo de la caldera cada 24 horas."], respuesta_correcta:1, explicacion:"Es la que llena la caldera sola. Si hay una pequeña fuga, esta válvula mete agua para que el equipo no se quede seco y explote." , question: "What is the function of the 'Automatic Feed Valve' in a hot water boiler?", options: ["To feed natural gas to the boiler automatically.", "To maintain the water level and minimum system pressure (typically 12 PSI) by injecting city water when it detects a pressure drop.", "To raise the water temperature to 212 degrees Fahrenheit.", "To drain sludge from the boiler every 24 hours."], explanation: "It fills the boiler on its own. If there is a small leak, this valve adds water so the equipment does not run dry and risk an explosion." },
  { id:"calef_509", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué un radiador de agua caliente gotea por la válvula de purga después de usarla?", opciones:["Porque el aire está lubricando la válvula.", "Suciedad o cal acumulada en el asiento de la válvula que impide un cierre hermético después de haber sido manipulada.", "La presión del sistema es demasiado baja.", "Es una función de seguridad para liberar vapor."], respuesta_correcta:1, explicacion:"A veces, al abrir una válvula vieja, la basura se mete en el sello. Hay que intentar cerrarla con fuerza o cambiar la tapita de purga." , question: "Why does a hot water radiator drip from the bleed valve after it has been used?", options: ["Because the air is lubricating the valve.", "Dirt or mineral scale accumulated on the valve seat preventing a tight seal after it has been operated.", "The system pressure is too low.", "It is a safety feature to release steam."], explanation: "Sometimes, when you open an old valve, debris gets into the seal. You need to try closing it firmly or replace the bleed cap." },
  { id:"calef_510", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué sucede con la Presión Total de un sistema de ductos si la Presión Estática sube debido a una restricción pero la velocidad del aire disminuye proporcionalmente?", opciones:["La Presión Total se mantiene constante según la ecuación de Bernoulli.", "La Presión Total disminuye debido a las pérdidas por fricción y turbulencia convertidas en calor.", "Aumenta exponencialmente para compensar la falta de flujo.", "Se vuelve negativa en relación con la presión del plenum de retorno."], respuesta_correcta:1, explicacion:"La Presión Total es la suma de la Estática y la Dinámica. Aunque la estática suba, la energía perdida por fricción en la restricción hace que la suma total siempre sea menor después del obstáculo." , question: "What happens to the Total Pressure in a duct system if Static Pressure rises due to a restriction but the air velocity decreases proportionally?", options: ["Total Pressure remains constant according to Bernoulli's equation.", "Total Pressure decreases due to friction and turbulence losses converted to heat.", "It increases exponentially to compensate for the lack of flow.", "It becomes negative relative to the return plenum pressure."], explanation: "Total Pressure is the sum of Static and Dynamic pressure. Although static pressure rises, the energy lost to friction in the restriction means the total sum is always lower after the obstruction." },
  { id:"calef_511", categoria:"CALEF_HIDRONICA", pregunta:"¿Cuál es la función del 'Tanque de Expansión' en un sistema de calefacción de agua caliente?", opciones:["Almacenar agua extra para cuando falte en la red.", "Proveer un colchón de aire comprimible para absorber el aumento de volumen del agua al calentarse, evitando que la presión rompa las tuberías.", "Aumentar la temperatura del agua mediante compresión hidrostática.", "Filtrar los sedimentos antes de que lleguen a la bomba circuladora."], respuesta_correcta:1, explicacion:"El agua no se comprime. Al calentarse, se expande. Sin el tanque de expansión, la presión subiría instantáneamente y dispararía la válvula de alivio." , question: "What is the function of the 'Expansion Tank' in a hot water heating system?", options: ["To store extra water for when the supply runs low.", "To provide a compressible air cushion that absorbs the increase in water volume as it heats, preventing the pressure from rupturing the piping.", "To raise the water temperature through hydrostatic compression.", "To filter sediment before it reaches the circulator pump."], explanation: "Water does not compress. When heated, it expands. Without the expansion tank, pressure would rise instantly and trip the relief valve." },
  { id:"calef_512", categoria:"CALEF_HIDRONICA", pregunta:"En modo calefacción, una bomba de calor tiene un sobrecalentamiento (Superheat) de 0°C en la entrada del compresor. ¿Cuál es el riesgo?", opciones:["El compresor se enfriará demasiado y no calentar la casa.", "Inundación de líquido (Slugged compressor); el refrigerante líquido entrará al compresor, pudiendo romper las válvulas o el scroll ya que los líquidos no se comprimen.", "Aumento de la eficiencia del condensador interior.", "El aceite del compresor se volverá demasiado espeso."], respuesta_correcta:1, explicacion:"Superheat de 0° significa que el gas todavía es líquido. El compresor es una bomba de gas; si le metes líquido, es como tratar de comprimir una roca: algo se va a romper." , question: "In heating mode, a heat pump has a superheat of 0 degrees at the compressor inlet. What is the risk?", options: ["The compressor will cool too much and fail to heat the house.", "Liquid flood-back (slugged compressor); liquid refrigerant will enter the compressor and can break the valves or scroll since liquids are incompressible.", "Increased efficiency of the indoor condenser.", "The compressor oil will become too thick."], explanation: "A superheat of zero means the refrigerant is still liquid. The compressor is a gas pump; if you feed it liquid, it is like trying to compress a rock -- something will break." },
  { id:"calef_513", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es una 'Válvula de Zona' y para qué sirve?", opciones:["Para aumentar la presión en el baño.", "Permite controlar la temperatura de diferentes habitaciones de forma independiente abriendo o cerrando el flujo de agua caliente.", "Es un filtro para zonas de agua dura.", "Sirve para purgar el aire de toda la casa a la vez."], respuesta_correcta:1, explicacion:"Es confort y ahorro. Si no usas el cuarto de invitados, la válvula se cierra y no gastas gas calentando agua para ese cuarto." , question: "What is a 'Zone Valve' and what is it used for?", options: ["To increase pressure in the bathroom.", "It allows controlling the temperature of different rooms independently by opening or closing the flow of hot water.", "It is a filter for hard water areas.", "It is used to bleed air from the entire house at once."], explanation: "It provides comfort and savings. If you are not using the guest room, the valve closes and you do not waste gas heating water for that room." },
  { id:"calef_514", categoria:"CALEF_HIDRONICA", pregunta:"¿A qué presión suele abrirse la válvula de alivio en una caldera hidrónica residencial estándar?", opciones:["15 PSI.", "30 PSI.", "125 PSI.", "500 PSI."], respuesta_correcta:1, explicacion:"El estándar de oro es 30 PSI. Si la presión llega ahí, la válvula se abre para evitar que la caldera se convierta en una bomba." , question: "At what pressure does the relief valve typically open on a standard residential hydronic boiler?", options: ["15 PSI.", "30 PSI.", "125 PSI.", "500 PSI."], explanation: "The gold standard is 30 PSI. If pressure reaches that level, the valve opens to prevent the boiler from becoming a bomb." },
  { id:"calef_515", categoria:"CALEF_HIDRONICA", pregunta:"En una bomba de calor, ¿cuál es la función de la 'Válvula de Retención' (Check Valve) en paralelo con el dispositivo de expansión?", opciones:["Aumentar la presión del refrigerante en un 10%.", "Permitir que el refrigerante circule libremente en una dirección (bypass) durante un modo y sea forzado a través de la expansión en el modo opuesto.", "Evitar que el aceite se mezcle con el gas de succión.", "Regular la temperatura del condensador exterior."], respuesta_correcta:1, explicacion:"Como el refrigerante cambia de dirección entre verano e invierno, necesitamos que pase por la válvula de expansión en un sentido y que 'se salte' la válvula en el otro." , question: "In a heat pump, what is the function of the 'Check Valve' in parallel with the expansion device?", options: ["To increase refrigerant pressure by 10 percent.", "To allow refrigerant to flow freely in one direction (bypass) during one mode and force it through the expansion device in the opposite mode.", "To prevent oil from mixing with the suction gas.", "To regulate the temperature of the outdoor condenser."], explanation: "Since the refrigerant changes direction between summer and winter, it needs to pass through the expansion valve in one direction and bypass it in the other." },
  { id:"calef_516", categoria:"CALEF_HIDRONICA", pregunta:"¿Por qué un sistema de calefacción hidrónica debe purgarse con la bomba apagada en edificios de varios pisos?", opciones:["Para que el técnico no se moje.", "Para evitar que la bomba mantenga las burbujas de aire en circulación o las rompa en microburbujas difíciles de capturar en los radiadores altos.", "La bomba consume demasiada energía durante la purga.", "Para que la válvula de alivio de 30 PSI no se abra."], respuesta_correcta:1, explicacion:"Con la bomba apagada, el aire sube por gravedad al punto más alto. Es ahí donde abres la válvula y el aire sale rápido. Si la bomba corre, el aire 'juega a las escondidas' por todos los tubos." , question: "Why must a hydronic heating system be purged with the pump off in multi-story buildings?", options: ["So the technician does not get wet.", "To prevent the pump from keeping air bubbles in circulation or breaking them into microbubbles that are difficult to capture in the upper radiators.", "The pump uses too much energy during purging.", "To prevent the 30 PSI relief valve from opening."], explanation: "With the pump off, air rises by gravity to the highest point. That is where you open the valve and the air escapes quickly. If the pump is running, the air plays hide and seek throughout the pipes." },
  { id:"calef_517", categoria:"CALEF_HIDRONICA", pregunta:"¿Qué es una 'Válvula de Llenado Rápido' (Fast Fill) y cuándo debe usarse?", opciones:["Para llenar una piscina con agua de la caldera.", "Una función de la válvula reductora que permite meter agua a alta presión para llenar y purgar el sistema rápidamente durante la instalación o mantenimiento.", "Solo se usa en sistemas de vapor de alta presión.", "Para inyectar gas natural líquido en la caldera."], respuesta_correcta:1, explicacion:"Sirve para ahorrar tiempo. En lugar de esperar a que el agua entre goteando a 12 PSI, abres el 'Fast Fill' y llenas todo el edificio en minutos para buscar fugas y sacar el aire." , question: "What is a 'Fast Fill Valve' and when should it be used?", options: ["To fill a swimming pool with boiler water.", "A feature on the pressure reducing valve that allows high-pressure water in to fill and purge the system quickly during installation or maintenance.", "It is only used in high-pressure steam systems.", "To inject liquefied natural gas into the boiler."], explanation: "It saves time. Instead of waiting for water to trickle in at 12 PSI, you open the fast fill and charge the entire building in minutes to check for leaks and purge the air." },

  // -- Termodinámica y Psicrometría (518-692) --
  { id:"calef_518", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Si un horno eléctrico de 10kW se alimenta con el 90% de su voltaje nominal, cuánta energía entrega?", opciones:["9.0 kW debido a la caída lineal de tensión.", "8.1 kW porque la potencia varía con el cuadrado del voltaje.", "10 kW pero tarda más tiempo en calentar.", "11.1 kW por compensación de impedancia térmica."], respuesta_correcta:1, explicacion:"Ley de Joule: P = V²/R. Si el voltaje cae a 0.9, la potencia cae a 0.9², es decir, 0.81 o 81%." , question: "If a 10 kW electric furnace is powered at 90 percent of its rated voltage, how much energy does it deliver?", options: ["9.0 kW due to the linear voltage drop.", "8.1 kW because power varies with the square of the voltage.", "10 kW but it takes longer to heat.", "11.1 kW due to thermal impedance compensation."], explanation: "Joule's Law: P = V squared / R. If voltage drops to 0.9, power drops to 0.9 squared, which is 0.81 or 81 percent." },
  { id:"calef_519", categoria:"CALEF_TERMODINAMICA", pregunta:"En un sistema de bomba de calor en modo calefacción, ¿qué componente actúa tecnicamente como el dispositivo de rechazo de calor?", opciones:["El evaporador exterior.", "La válvula de expansión termostática.", "El serpentín interior (condensador).", "El acumulador de succión."], respuesta_correcta:2, explicacion:"En modo calefacción, el ciclo se invierte y el serpentín interno se convierte en el condensador, rechazando calor hacia el espacio habitado." , question: "In a heat pump system in heating mode, which component technically acts as the heat rejection device?", options: ["The outdoor evaporator.", "The thermostatic expansion valve.", "The indoor coil (condenser).", "The suction accumulator."], explanation: "In heating mode, the cycle reverses and the indoor coil becomes the condenser, rejecting heat into the occupied space." },
  { id:"calef_520", categoria:"CALEF_TERMODINAMICA", pregunta:"Si calentamos aire sensiblemente sin añadir humedad, ¿qué sucede con la temperatura de punto de rocío?", opciones:["Aumenta proporcionalmente a la temperatura seca.", "Disminuye porque el aire se vuelve más 'seco'.", "Se mantiene constante.", "Se iguala a la temperatura de bulbo húmedo."], respuesta_correcta:2, explicacion:"El punto de rocío solo depende de la cantidad de vapor de agua real en el aire. El calentamiento sensible no añade ni quita agua, por lo tanto, el punto de rocío no cambia." , question: "If we heat air sensibly without adding moisture, what happens to the dew point temperature?", options: ["It increases proportionally with the dry bulb temperature.", "It decreases because the air becomes 'drier.'", "It remains constant.", "It equals the wet bulb temperature."], explanation: "The dew point depends only on the actual amount of water vapor in the air. Sensible heating neither adds nor removes water; therefore, the dew point does not change." },
  { id:"calef_521", categoria:"CALEF_TERMODINAMICA", pregunta:"Se instala una bomba de calor en un clima donde la temperatura exterior es de -15°C. El sistema cuenta con 'Defrost Control'. ¿Por qué el aire que sale por las rejillas interiores se siente frío durante el ciclo de descongelación si las resistencias auxiliares están apagadas?", opciones:["Porque el sistema invierte la válvula de cuatro vías y extrae calor del interior para derretir el hielo exterior, actuando esencialmente como aire acondicionado.", "Debido al efecto Joule-Thomson inverso que ocurre en el evaporador de expansión directa.", "Es una percepción psicrométrica debida a la baja humedad relativa del aire calentado previamente.", "El compresor se detiene y solo funciona el ventilador interior por inercia térmica."], respuesta_correcta:0, explicacion:"En defrost, la unidad exterior se convierte en evaporador y la interior en condensador inverso (enfriando la casa). Por eso se suelen activar los 'heat strips' para compensar ese aire frío." , question: "A heat pump is installed in a climate where the outdoor temperature is minus 15 degrees Celsius. The system has a 'Defrost Control.' Why does the air coming out of the indoor registers feel cold during the defrost cycle if the auxiliary heat strips are off?", options: ["Because the system reverses the four-way valve and extracts heat from the interior to melt the outdoor ice, essentially running as an air conditioner.", "Due to the inverse Joule-Thomson effect occurring in the direct-expansion evaporator.", "It is a psychrometric perception caused by the low relative humidity of the previously heated air.", "The compressor stops and only the indoor fan runs on thermal inertia."], explanation: "During defrost, the outdoor unit becomes the condenser and the indoor unit reverses to cooling mode. That is why heat strips are typically activated to offset that cold air." },
  { id:"calef_522", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted añade un humidificador de vapor a un sistema de ductos. Si la temperatura de bulbo seco permanece constante pero aumenta la humedad relativa del 20% al 50%, ¿qué sucede con la entalpía del aire?", opciones:["Permanece constante porque no se ha alterado la temperatura sensible.", "Disminuye debido al enfriamiento evaporativo latente dentro de la bota del ducto.", "Aumenta.", "Se reduce el volumen específico del aire, aumentando la densidad pero manteniendo la energía total del sistema según la primera ley."], respuesta_correcta:2, explicacion:"La entalpía es la suma del calor sensible y el calor latente. Al añadir vapor de agua, estás añadiendo energía (calor latente), por lo que la entalpía total sube." , question: "You add a steam humidifier to a duct system. If the dry bulb temperature stays constant but relative humidity rises from 20 percent to 50 percent, what happens to the air enthalpy?", options: ["It remains constant because no sensible temperature change occurred.", "It decreases due to latent evaporative cooling inside the duct boot.", "It increases.", "The specific volume decreases, increasing density while maintaining total system energy per the first law."], explanation: "Enthalpy is the sum of sensible heat and latent heat. By adding water vapor, you are adding energy (latent heat), so the total enthalpy rises." },
  { id:"calef_523", categoria:"CALEF_TERMODINAMICA", pregunta:"Si un técnico mide una temperatura de bulbo seco de 22°C y una temperatura de bulbo húmedo de 22°C en el retorno de calefacción, ¿cuál es el estado del aire?", opciones:["El aire tiene una humedad relativa del 0% (Aire totalmente seco).", "El sistema está en equilibrio térmico pero la humedad es indeterminada.", "El aire está al 100% de humedad relativa (Punto de saturación).", "Existe un error en el termómetro digital ya que estas temperaturas nunca pueden ser iguales."], respuesta_correcta:2, explicacion:"Cuando la temperatura seca y húmeda coinciden, el aire no puede absorber más humedad; el bulbo húmedo no se enfría por evaporación, indicando saturación total." , question: "If a technician measures a dry bulb temperature of 72 degrees Fahrenheit and a wet bulb temperature of 72 degrees Fahrenheit at the heating return, what is the state of the air?", options: ["The air has 0 percent relative humidity (completely dry air).", "The system is in thermal equilibrium but humidity is indeterminate.", "The air is at 100 percent relative humidity (saturation point).", "There is a thermometer error because these temperatures can never be equal."], explanation: "When the dry bulb and wet bulb temperatures are identical, the air cannot absorb any more moisture; the wet bulb does not cool through evaporation, indicating complete saturation." },
  { id:"calef_524", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué sucede con el superheat (sobrecalentamiento) de una bomba de calor en modo calefacción si el soplador interior falla pero el compresor sigue encendido?", opciones:["El sobrecalentamiento aumenta drásticamente porque no hay flujo de aire.", "El sobrecalentamiento cae hacia cero, arriesgando un retorno de líquido al compresor (slugging).", "El sistema se estabiliza gracias a la válvula de expansión electrónica (EEV).", "La presión de succión sube hasta que se activa el interruptor de alta presión."], respuesta_correcta:1, explicacion:"En modo calor, el serpentín interior es el condensador. Si el ventilador falla, el refrigerante no entrega calor, no se condensa bien y vuelve al compresor en un estado inestable, bajando el sobrecalentamiento en la succión (que en este modo es el serpentín exterior)." , question: "What happens to the superheat of a heat pump in heating mode if the indoor blower fails but the compressor keeps running?", options: ["Superheat increases dramatically because there is no airflow.", "Superheat drops toward zero, risking liquid flood-back to the compressor (slugging).", "The system stabilizes thanks to the electronic expansion valve (EEV).", "Suction pressure rises until the high-pressure switch trips."], explanation: "In heating mode, the indoor coil is the condenser. If the blower fails, the refrigerant does not reject its heat, does not condense properly, and returns to the compressor in an unstable state, lowering suction superheat (which in this mode is at the outdoor coil)." },
  { id:"calef_525", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué sucede con el flujo de aire (CFM) si duplicamos la velocidad de rotación (RPM) de un ventilador centrífugo en un sistema de ductos con resistencia constante?", opciones:["El CFM aumenta exactamente al doble (relación lineal).", "El CFM aumenta cuatro veces debido a la ley del cuadrado de la velocidad.", "El CFM aumenta ocho veces siguiendo la ley del cubo de la potencia.", "El flujo se mantiene igual pero la presión estática se triplica."], respuesta_correcta:0, explicacion:"Según las Leyes de los Ventiladores (Fan Laws), el flujo (CFM) es directamente proporcional al cambio de RPM. Sin embargo, la presión aumenta al cuadrado y la potencia al cubo." , question: "What happens to the airflow (CFM) if we double the rotation speed (RPM) of a centrifugal fan in a duct system with constant resistance?", options: ["CFM increases exactly to double (linear relationship).", "CFM increases four times due to the velocity squared law.", "CFM increases eight times following the cube power law.", "Flow remains the same but static pressure triples."], explanation: "According to the Fan Laws, airflow (CFM) is directly proportional to the change in RPM. However, pressure increases by the square and power increases by the cube." },
  { id:"calef_526", categoria:"CALEF_TERMODINAMICA", pregunta:"En un banco de resistencias de 20kW secuenciado, un técnico mide el amperaje y nota que es más alto de lo nominal cuando el sistema arranca en un ambiente a -10°C. ¿A qué se debe esto?", opciones:["A la mayor densidad del aire frío que enfría más rápido el nicromo.", "Al coeficiente de temperatura de la resistencia; el metal frío tiene menor resistencia eléctrica y por ende mayor consumo inicial.", "A un error de calibración del secuenciador de estado sólido.", "Al efecto de inducción electromagnética del gabinete metálico del horno."], respuesta_correcta:1, explicacion:"Casi todos los metales (incluido el nicromo de las resistencias) tienen un coeficiente de temperatura positivo: a menor temperatura, menor resistencia ($R$), lo que resulta en una corriente ($I$) mayor según $I = V/R$." , question: "In a 20 kW sequenced resistance bank, a technician measures higher-than-rated amperage when the system starts in a minus 10 degrees Celsius environment. What causes this?", options: ["The greater density of cold air that cools the nichrome faster.", "The temperature coefficient of resistance; cold metal has lower electrical resistance and therefore higher initial current draw.", "A calibration error in the solid-state sequencer.", "The electromagnetic induction effect from the furnace's metal cabinet."], explanation: "Nearly all metals (including the nichrome in heating elements) have a positive temperature coefficient: at lower temperatures, resistance is lower, resulting in higher current per Ohm's Law (I = V/R)." },
  { id:"calef_527", categoria:"CALEF_TERMODINAMICA", pregunta:"Se utiliza un deshumidificador químico (sílica gel) en un sistema de calefacción industrial. El aire sale con menos humedad pero más caliente. ¿Cómo se llama este proceso?", opciones:["Enfriamiento evaporativo inverso.", "Adsorción adiabática.", "Condensación por contacto térmico.", "Humidificación latente negativa."], respuesta_correcta:1, explicacion:"En la adsorción química, el vapor de agua libera su calor latente al ser atrapado por el químico. Ese calor se transfiere al aire como calor sensible, aumentando su temperatura sin añadir energía externa." , question: "A chemical desiccant dehumidifier (silica gel) is used in an industrial heating system. The air exits with less humidity but at a higher temperature. What is this process called?", options: ["Reverse evaporative cooling.", "Adiabatic adsorption.", "Contact thermal condensation.", "Negative latent humidification."], explanation: "In chemical adsorption, the water vapor releases its latent heat when captured by the desiccant. That heat is transferred to the air as sensible heat, raising its temperature without adding external energy." },
  { id:"calef_528", categoria:"CALEF_TERMODINAMICA", pregunta:"En un hospital, se requiere mantener una humedad relativa del 50% con una temperatura de 22°C. Si el serpentín de pre-calefacción calienta el aire exterior de -5°C a 15°C sin humidificación, ¿qué sucede con el Volumen Específico del aire?", opciones:["Disminuye porque el aire se vuelve más denso al alejarse del punto de rocío.", "Aumenta, ya que el aire se expande al absorber energía sensible.", "Se mantiene constante porque la relación de humedad (grains/lb) no ha cambiado.", "Cae a cero en la escala de Mollier."], respuesta_correcta:1, explicacion:"El volumen específico es el inverso de la densidad. Al calentar el aire, las moléculas se separan (se expanden), ocupando más espacio por unidad de masa." , question: "In a hospital, a relative humidity of 50 percent must be maintained at 72 degrees Fahrenheit. If the preheat coil heats outdoor air from 23 degrees Fahrenheit to 59 degrees Fahrenheit without humidification, what happens to the Specific Volume of the air?", options: ["It decreases because the air becomes denser as it moves away from the dew point.", "It increases because the air expands as it absorbs sensible energy.", "It remains constant because the humidity ratio (grains per pound) has not changed.", "It drops to zero on the Mollier diagram."], explanation: "Specific volume is the inverse of density. When air is heated, the molecules spread apart (expand), occupying more space per unit of mass." },
  { id:"calef_529", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué sucede con la temperatura de descarga de un compresor si la presión de succión baja drásticamente debido a una restricción en el filtro deshidratador?", opciones:["La temperatura de descarga baja porque hay menos masa de refrigerante para calentar.", "La temperatura de descarga sube debido al aumento en la relación de compresión y el calor de fricción.", "Se mantiene constante ya que el condensador regula la salida térmica.", "El refrigerante se vuelve subenfriado antes de entrar al pistón o scroll."], respuesta_correcta:1, explicacion:"Al bajar la presión de succión, el compresor debe trabajar más para alcanzar la presión de alta. Esto aumenta la relación de compresión, lo que eleva exponencialmente la temperatura del gas de descarga." , question: "What happens to the discharge temperature of a compressor if suction pressure drops drastically due to a restriction in the filter drier?", options: ["Discharge temperature drops because there is less refrigerant mass to heat.", "Discharge temperature rises due to the increased compression ratio and friction heat.", "It remains constant because the condenser regulates the thermal output.", "The refrigerant becomes subcooled before entering the piston or scroll."], explanation: "When suction pressure drops, the compressor must work harder to reach the high-side pressure. This increases the compression ratio, which exponentially raises the discharge gas temperature." },
  { id:"calef_530", categoria:"CALEF_TERMODINAMICA", pregunta:"Si un cliente se queja de 'estática eléctrica' y garganta seca en invierno con calefacción por aire forzado, ¿qué valor psicrométrico debe revisar el técnico?", opciones:["La temperatura de bulbo húmedo únicamente.", "La humedad relativa, que probablemente esté por debajo del 20%.", "La entalpía total del retorno.", "El punto de rocío del aire exterior que entra por infiltración."], respuesta_correcta:1, explicacion:"El aire caliente tiene una mayor capacidad de retener humedad. Si no se añade agua, la humedad relativa cae drásticamente, causando sequedad y acumulación de electricidad estática." , question: "If a customer complains of 'static electricity' and dry throat in winter with forced-air heating, which psychrometric value should the technician check?", options: ["The wet bulb temperature only.", "The relative humidity, which is likely below 20 percent.", "The total enthalpy of the return air.", "The dew point of the outdoor air entering through infiltration."], explanation: "Warm air has a greater capacity to hold moisture. If no water is added, relative humidity drops dramatically, causing dryness and static electricity buildup." },
  { id:"calef_531", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué efecto tiene instalar un codo de 90 grados directamente en la descarga de un soplador sin un tramo recto de ducto?", opciones:["Aumenta el CFM debido al efecto de aceleración centrífuga.", "Genera un fenómeno de 'System Effect' que reduce drásticamente el rendimiento del ventilador y aumenta el ruido.", "Mejora la mezcla de aire caliente y frío antes de llegar a los plenums.", "No tiene efecto si el ducto es de lámina galvanizada de calibre 24."], respuesta_correcta:1, explicacion:"El aire necesita un tramo recto para estabilizar su perfil de velocidad. Un codo inmediato crea turbulencia que el ventilador no puede vencer eficientemente, desperdiciando energía." , question: "What effect does installing a 90-degree elbow directly at the blower discharge without a straight duct section have?", options: ["It increases CFM due to the centrifugal acceleration effect.", "It creates a 'System Effect' that drastically reduces fan performance and increases noise.", "It improves the mixing of hot and cold air before reaching the plenums.", "It has no effect if the duct is made of 24-gauge galvanized sheet metal."], explanation: "The air needs a straight section to stabilize its velocity profile. An immediate elbow creates turbulence that the fan cannot efficiently overcome, wasting energy." },
  { id:"calef_532", categoria:"CALEF_TERMODINAMICA", pregunta:"Si enfriamos aire por debajo de su punto de rocío y luego lo recalentamos sensiblemente a su temperatura original, ¿qué ha cambiado en su estado final?", opciones:["La entalpía es mayor debido al calor latente ganado.", "La humedad absoluta (ratio de humedad) es menor.", "La densidad del aire ha disminuido permanentemente por la pérdida de moléculas de hidrógeno.", "El aire ahora es aire saturado seco según la carta de Carrier."], respuesta_correcta:1, explicacion:"Al enfriar por debajo del punto de rocío, el agua se condensa y sale del aire. Al recalentarlo, la temperatura es igual pero hay menos agua total, por lo que la humedad absoluta bajó." , question: "If we cool air below its dew point and then sensibly reheat it back to its original temperature, what has changed in its final state?", options: ["The enthalpy is higher due to latent heat gained.", "The absolute humidity (humidity ratio) is lower.", "The air density has permanently decreased from the loss of hydrogen molecules.", "The air is now saturated dry air per the Carrier chart."], explanation: "By cooling below the dew point, water condenses and leaves the air. Upon reheating, the temperature is the same but there is less total moisture, so the absolute humidity has decreased." },
  { id:"calef_533", categoria:"CALEF_TERMODINAMICA", pregunta:"Al calcular la carga de calefacción, ¿por qué el Manual J de ACCA no incluye las 'ganancias internas' (luces, personas, electrodomésticos) como crédito, a diferencia del cálculo de refrigeración?", opciones:["Porque se asume el 'peor escenario' (noche fría, casa vacía) para asegurar que el sistema pueda mantener la temperatura de diseño.", "Debido a que el calor de los electrodomésticos es calor latente y no sensible.", "Para sobredimensionar el equipo y compensar las fugas de los ductos.", "Es un error metodológico que se corrigió en la versión 8 del manual."], respuesta_correcta:0, explicacion:"En calefacción, el diseño se hace para cuando no hay sol ni gente adentro. Si contaras el calor de la gente y luego la casa está vacía, el horno no tendría capacidad suficiente para calentar la estructura." , question: "When calculating the heating load, why does ACCA Manual J not include 'internal gains' (lights, people, appliances) as a credit, unlike the cooling calculation?", options: ["Because it assumes the 'worst case scenario' (cold night, empty house) to ensure the system can maintain the design temperature.", "Because the heat from appliances is latent heat, not sensible heat.", "To oversize the equipment to compensate for duct leakage.", "It is a methodological error corrected in version 8 of the manual."], explanation: "The heating design is based on when there is no sun and no one is home. If you counted the heat from occupants and then the house were empty, the furnace would not have enough capacity to heat the structure." },
  { id:"calef_534", categoria:"CALEF_TERMODINAMICA", pregunta:"Un sistema de bomba de calor tiene una restricción en la válvula de expansión (TXV) de la unidad interior. ¿Cómo se manifiesta esto en el modo de calefacción?", opciones:["Alta presión de succión y baja presión de descarga.", "Baja presión de succión y bajo sobrecalentamiento en el compresor.", "No afecta en absoluto porque la TXV interior suele ser puenteada (bypassed) por una válvula check en modo calefacción.", "Causa que el acumulador de succión se congele debido a la inundación de líquido."], respuesta_correcta:2, explicacion:"En modo calor, la TXV interior no se usa para expandir; el refrigerante fluye por un bypass hacia el serpentín interior (que es el condensador). La expansión ocurre en la unidad exterior." , question: "A heat pump system has a restriction in the indoor unit TXV. How does this manifest in heating mode?", options: ["High suction pressure and low discharge pressure.", "Low suction pressure and low superheat at the compressor.", "It has no effect at all because the indoor TXV is typically bypassed by a check valve in heating mode.", "It causes the suction accumulator to freeze due to liquid flood-back."], explanation: "In heating mode, the indoor TXV is not used for expansion; the refrigerant flows through a bypass toward the indoor coil (which is the condenser). The expansion occurs at the outdoor unit." },
  { id:"calef_535", categoria:"CALEF_TERMODINAMICA", pregunta:"Un termostato Nest o Ecobee se reinicia constantemente cuando el horno intenta encender. El técnico mide 24V en el transformador. ¿Cuál es el problema?", opciones:["Falta de un cable 'C' (común), lo que causa que el termostato 'robe' energía del circuito de la válvula de gas, perdiendo voltaje cuando la válvula se activa.", "El termostato es incompatible con la frecuencia de 60Hz del hogar.", "La batería interna del termostato está cargada al revés.", "El Wi-Fi interfiere con el triac de salida de la señal de calor (W)."], respuesta_correcta:0, explicacion:"Sin cable común, estos termostatos se alimentan a través del circuito de carga. Al activarse el relé de calor, el camino de alimentación se cierra y el termostato se queda sin energía momentáneamente." , question: "A Nest or Ecobee thermostat keeps rebooting when the furnace tries to fire. The technician measures 24 volts at the transformer. What is the problem?", options: ["A missing 'C' (common) wire, which causes the thermostat to steal power from the gas valve circuit, losing voltage when the valve energizes.", "The thermostat is incompatible with the household 60 Hz frequency.", "The internal battery is installed in reverse.", "The Wi-Fi interferes with the heat signal (W) output triac."], explanation: "Without a common wire, these thermostats power themselves through the load circuit. When the heating relay activates, the power path closes and the thermostat momentarily loses power." },
  { id:"calef_536", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué ocurre con el calor sensible de un espacio si instalamos un humidificador de atomización (spray de agua fría) en lugar de uno de vapor?", opciones:["El calor sensible aumenta para compensar la humedad.", "El calor sensible disminuye porque el agua toma energía del aire para evaporarse (enfriamiento evaporativo).", "La entalpía total del aire se duplica instantáneamente.", "No hay cambio en el calor sensible, solo en el calor latente de la mezcla."], respuesta_correcta:1, explicacion:"El agua líquida necesita calor para convertirse en vapor. Ese calor lo extrae del aire circundante, bajando su temperatura seca (proceso adiabático)." , question: "What happens to the sensible heat of a space if we install a cold-water atomizing humidifier instead of a steam humidifier?", options: ["Sensible heat increases to compensate for the humidity.", "Sensible heat decreases because the water draws energy from the air to evaporate (evaporative cooling).", "The total enthalpy of the air doubles instantly.", "There is no change in sensible heat, only in the latent heat of the mixture."], explanation: "Liquid water needs heat to become vapor. It extracts that heat from the surrounding air, lowering its dry bulb temperature (an adiabatic process)." },
  { id:"calef_537", categoria:"CALEF_TERMODINAMICA", pregunta:"En un sistema de calefacción por zonas (zoning), ¿qué componente evita que la presión estática suba demasiado cuando solo una zona pequeña está pidiendo calor?", opciones:["Un sensor de velocidad en el motor ECM.", "Un damper de alivio (Barometric Bypass Damper).", "Un termostato maestro que apaga el horno por tiempo.", "La rejilla de retorno, que se expande térmicamente."], respuesta_correcta:1, explicacion:"El bypass damper se abre cuando detecta exceso de presión, recirculando el aire sobrante hacia el retorno para evitar ruidos y daños al motor por restricción." , question: "In a zone heating system, which component prevents static pressure from rising too high when only one small zone is calling for heat?", options: ["A speed sensor on the ECM motor.", "A barometric bypass damper.", "A master thermostat that shuts off the furnace on a timer.", "The return grille, which expands thermally."], explanation: "The bypass damper opens when it detects excess pressure, recirculating the surplus air back to the return to prevent noise and motor damage from restriction." },
  { id:"calef_538", categoria:"CALEF_TERMODINAMICA", pregunta:"En un manejador de aire con calefacción eléctrica, ¿cuál es el propósito técnico de los 'fusing' o fusibles internos en cada etapa de 5kW o 10kW?", opciones:["Proteger el termostato de un retorno de alta tensión.", "Cumplir con el NEC que exige que ninguna carga individual de calefacción exceda los 48 amperios sin protección dedicada.", "Evitar que el motor del soplador se queme si una resistencia entra en cortocircuito.", "Actuar como un límite de temperatura secundario por si el bimetal falla."], respuesta_correcta:1, explicacion:"El Código Eléctrico Nacional (NEC) limita las subdivisiones de circuitos de calefacción eléctrica a 48A. Por eso, bancos grandes se dividen en circuitos menores protegidos por fusibles internos." , question: "In an air handler with electric heating, what is the technical purpose of the internal fuses on each 5 kW or 10 kW stage?", options: ["To protect the thermostat from a high-voltage kick-back.", "To comply with the NEC, which requires that no individual heating load exceed 48 amperes without dedicated protection.", "To prevent the blower motor from burning if a heating element short-circuits.", "To act as a secondary temperature limit in case the bimetal switch fails."], explanation: "The National Electrical Code (NEC) limits subdivisions of electric heating circuits to 48 amps. That is why large banks are divided into smaller circuits protected by internal fuses." },
  { id:"calef_539", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué es más difícil calentar una casa con un 90% de humedad relativa que una con un 30% a la misma temperatura inicial?", opciones:["Porque el agua en el aire tiene un calor específico mucho más alto que el aire seco, requiriendo más energía para subir cada grado.", "Debido a que el aire húmedo es más denso y el soplador mueve menos masa.", "La humedad bloquea la radiación infrarroja de los registros de calefacción.", "Es un mito; la humedad solo afecta la sensación térmica, no la carga de energía sensible."], respuesta_correcta:0, explicacion:"El agua requiere mucha energía para calentarse. El aire húmedo tiene una mayor 'capacidad calorífica', por lo que el horno debe entregar más BTUs para elevar la temperatura de esa masa de aire." , question: "Why is it harder to heat a house at 90 percent relative humidity than one at 30 percent at the same starting temperature?", options: ["Because water in the air has a much higher specific heat than dry air, requiring more energy to raise each degree.", "Because humid air is denser and the blower moves less mass.", "Humidity blocks the infrared radiation from the heating registers.", "It is a myth; humidity only affects the perceived comfort, not the sensible energy load."], explanation: "Water requires a lot of energy to heat. Humid air has a higher heat capacity, so the furnace must deliver more BTUs to raise the temperature of that air mass." },
  { id:"calef_540", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué se siente un 'chorro de aire frío' al inicio de un ciclo de calefacción en un sistema de bomba de calor, incluso si el compresor ya arrancó?", opciones:["Debido a que el refrigerante tarda en alcanzar su presión de condensación y calentar la masa metálica del serpentín interior.", "El motor del ventilador gira al revés durante los primeros 30 segundos.", "Es una purga intencional de aire viciado exigida por el estándar ASHRAE 62.1.", "La válvula de expansión está congelada internamente por humedad en el sistema."], respuesta_correcta:0, explicacion:"A diferencia del gas, que genera calor casi inmediato por llama, la bomba de calor debe mover energía. El aire que pasa por el serpentín aún frío se siente como una corriente de aire molesta (cold blow)." , question: "Why is a 'cold air blast' felt at the beginning of a heating cycle in a heat pump system, even though the compressor has already started?", options: ["Because the refrigerant takes time to reach its condensing pressure and warm the thermal mass of the indoor coil.", "The blower motor spins in reverse during the first 30 seconds.", "It is an intentional stale air purge required by ASHRAE Standard 62.1.", "The expansion valve is internally frozen due to moisture in the system."], explanation: "Unlike gas, which generates almost instant heat through a flame, the heat pump must move energy. Air passing over the still-cold coil feels like an annoying cold draft (cold blow)." },
  { id:"calef_541", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué los hornos eléctricos de alta potencia utilizan contactores en lugar de relés de placa simples para manejar las resistencias?", opciones:["Para permitir la inversión de fases en caso de emergencia.", "Debido a la alta carga inductiva que generan las resistencias de nicromo.", "Para manejar de forma segura las altas corrientes (Amperaje) que fundirían las pistas de una placa de circuito impreso estándar.", "Porque los contactores son más silenciosos en aplicaciones residenciales."], respuesta_correcta:2, explicacion:"Una resistencia de 10kW a 240V maneja unos 42 amperios. Ningún relé miniatura de placa electrónica puede soportar ese calor y flujo de electrones sin evaporarse." , question: "Why do high-wattage electric furnaces use contactors instead of simple relay boards to control the heating elements?", options: ["To allow phase reversal in an emergency.", "Due to the high inductive load generated by the nichrome elements.", "To safely handle the high currents (amperage) that would melt the traces on a standard printed circuit board.", "Because contactors are quieter in residential applications."], explanation: "A 10 kW element at 240 volts draws about 42 amps. No miniature PCB relay can withstand that level of heat and current flow without being destroyed." },
  { id:"calef_542", categoria:"CALEF_TERMODINAMICA", pregunta:"En un ciclo de bomba de calor, ¿cuál es el término técnico para el calor que se añade al refrigerante en el evaporador por encima de su temperatura de saturación?", opciones:["Calor Latente de Condensación.", "Sobrecalentamiento (Superheat).", "Subenfriamiento (Subcooling).", "Entalpía de formación adiabática."], respuesta_correcta:1, explicacion:"El Superheat asegura que no entre líquido al compresor. Es el aumento de temperatura del vapor una vez que todo el líquido se ha evaporado." , question: "In a heat pump cycle, what is the technical term for the heat added to the refrigerant in the evaporator above its saturation temperature?", options: ["Latent heat of condensation.", "Superheat.", "Subcooling.", "Adiabatic enthalpy of formation."], explanation: "Superheat ensures that no liquid enters the compressor. It is the temperature increase of the vapor once all the liquid has evaporated." },
  { id:"calef_543", categoria:"CALEF_TERMODINAMICA", pregunta:"Si la temperatura de Bulbo Seco es de 20°C y la de Bulbo Húmedo es de 10°C, ¿qué indica esto sobre la capacidad del aire para absorber humedad?", opciones:["El aire está saturado y no puede absorber más agua.", "El aire tiene una gran capacidad de absorción (humedad relativa baja).", "Existe un riesgo inminente de condensación en las ventanas de cristal sencillo.", "La presión de vapor de agua es igual a la presión atmosférica local."], respuesta_correcta:1, explicacion:"Cuanto mayor es la diferencia (depresión del bulbo húmedo) entre la temperatura seca y la húmeda, más seco está el aire y más sediento de agua se encuentra." , question: "If the dry bulb temperature is 68 degrees Fahrenheit and the wet bulb temperature is 50 degrees Fahrenheit, what does this indicate about the air's ability to absorb moisture?", options: ["The air is saturated and cannot absorb more water.", "The air has a large absorption capacity (low relative humidity).", "There is an imminent risk of condensation on single-pane windows.", "The water vapor pressure equals the local atmospheric pressure."], explanation: "The greater the difference (wet bulb depression) between the dry bulb and wet bulb temperatures, the drier the air is and the more moisture-hungry it becomes." },
  { id:"calef_544", categoria:"CALEF_TERMODINAMICA", pregunta:"Si un horno de gas tiene una entrada (input) de 100,000 BTU y una salida (output) de 80,000 BTU, ¿cuál es su AFUE?", opciones:["90% debido a las pérdidas estacionales.", "80% basado en la relación directa de transferencia de calor.", "125% según la ley de conservación de la masa.", "78% restando el consumo del motor del soplador."], respuesta_correcta:1, explicacion:"Eficiencia = (Salida / Entrada) * 100. En este caso simple: (80,000 / 100,000) = 0.80 o 80%." , question: "If a gas furnace has an input of 100,000 BTU and an output of 80,000 BTU, what is its AFUE?", options: ["90 percent due to seasonal losses.", "80 percent based on the direct heat transfer ratio.", "125 percent per the law of conservation of mass.", "78 percent after subtracting the blower motor consumption."], explanation: "Efficiency equals (Output divided by Input) times 100. In this straightforward case: (80,000 / 100,000) = 0.80 or 80 percent." },
  { id:"calef_545", categoria:"CALEF_TERMODINAMICA", pregunta:"En un centro de datos, se requiere 'Enfriamiento Gratuito' (Economizador). Si el aire exterior está a 10°C con 90% de HR y el retorno está a 25°C con 20% de HR, ¿qué riesgo técnico existe al mezclarlos?", opciones:["No hay riesgo, la mezcla siempre será una media aritmética simple.", "Riesgo de condensación o formación de niebla dentro del gabinete de mezcla si el punto de rocío de la mezcla supera la temperatura de las superficies metálicas.", "El aire resultante será demasiado seco y generará descargas electrostáticas masivas en los servidores.", "Aumento súbito de la presión estática debido a la diferencia de densidades moleculares."], respuesta_correcta:1, explicacion:"Al mezclar dos masas de aire con humedades muy distintas, la línea de mezcla en la carta psicrométrica puede cruzar la curva de saturación, provocando que el agua se condense en forma de niebla antes de llegar al serpentín." , question: "In a data center, 'Free Cooling' (economizer) is required. If outdoor air is at 50 degrees Fahrenheit with 90 percent RH and return air is at 77 degrees Fahrenheit with 20 percent RH, what technical risk exists when mixing them?", options: ["There is no risk; the mixture is always a simple arithmetic average.", "Risk of condensation or fog formation inside the mixing box if the dew point of the mixture exceeds the temperature of the metal surfaces.", "The resulting air will be too dry and generate massive electrostatic discharges in the servers.", "A sudden increase in static pressure due to the difference in molecular densities."], explanation: "When mixing two air masses with very different humidity levels, the mixing line on the psychrometric chart can cross the saturation curve, causing water to condense as fog before reaching the coil." },
  { id:"calef_546", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un horno de gas de 100,000 BTU instalado en Denver (5,280 pies) entrega menos calor real que el mismo horno en Miami (nivel del mar) si no se ajustan los orificios?", opciones:["Porque el gas natural tiene una densidad mayor en altitud.", "Debido a que el aire es menos denso, hay menos masa de oxígeno para la combustión y menos masa de aire para transportar el calor por los ductos.", "La presión atmosférica baja aumenta el punto de ebullición del condensado.", "El ventilador centrífugo gira más despacio debido a la falta de resistencia del aire."], respuesta_correcta:1, explicacion:"En altitud, el aire es menos denso. Hay menos moléculas de O2 por pie cúbico, lo que requiere 'derating' (reducción de capacidad) del equipo para evitar una combustión rica en combustible y generación de CO." , question: "Why does a 100,000 BTU gas furnace installed in Denver (5,280 feet elevation) deliver less actual heat than the same furnace in Miami (sea level) if the orifices are not adjusted?", options: ["Because natural gas has a higher density at altitude.", "Because the air is less dense, there is less oxygen mass for combustion and less air mass to transport heat through the ducts.", "Lower atmospheric pressure increases the boiling point of condensate.", "The centrifugal fan spins slower due to the lack of air resistance."], explanation: "At altitude, the air is thinner. There are fewer O2 molecules per cubic foot, which requires derating (capacity reduction) of the equipment to avoid a fuel-rich burn and generation of CO." },
  { id:"calef_547", categoria:"CALEF_TERMODINAMICA", pregunta:"En un sistema de calefacción por vapor, ¿cuál es la función del 'Venteo de Aire' (Air Vent) en los radiadores de una sola tubería?", opciones:["Permitir que el vapor escape si la presión es demasiado alta.", "Expulsar el aire atrapado para que el vapor pueda entrar al radiador; se cierra automáticamente cuando detecta el calor del vapor.", "Inyectar aire fresco para mejorar la humedad relativa del cuarto.", "Regular la velocidad del condensado de regreso a la caldera."], respuesta_correcta:1, explicacion:"Si el radiador está lleno de aire, el vapor no puede entrar. La válvula de aire permanece abierta hasta que el vapor caliente expande un elemento bimetálico o de alcohol interno, sellando el radiador." , question: "In a steam heating system, what is the function of the 'Air Vent' on single-pipe radiators?", options: ["To allow steam to escape if pressure is too high.", "To expel trapped air so steam can enter the radiator; it closes automatically when it senses the heat of the steam.", "To inject fresh air to improve the room's relative humidity.", "To regulate the speed of condensate returning to the boiler."], explanation: "If the radiator is full of air, steam cannot enter. The air vent remains open until the hot steam expands an internal bimetallic or alcohol element, sealing the radiator." },
  { id:"calef_548", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué define técnicamente el 'Límite de Carnot' en una bomba de calor que opera en invierno?", opciones:["La temperatura máxima a la que el refrigerante se descompone químicamente.", "La eficiencia máxima teórica posible determinada exclusivamente por las temperaturas absolutas de la fuente caliente y la fría.", "El punto donde el compresor consume más vatios de los que entrega en BTUs.", "La presión crítica donde el gas se convierte en fluido supercrítico sin pasar por líquido."], respuesta_correcta:1, explicacion:"El ciclo de Carnot establece que ninguna máquina térmica puede ser más eficiente que lo que permiten sus límites de temperatura (Kelvin). Es el 'techo' de eficiencia para cualquier HVAC." , question: "What technically defines the 'Carnot Limit' for a heat pump operating in winter?", options: ["The maximum temperature at which the refrigerant decomposes chemically.", "The maximum theoretical efficiency possible, determined solely by the absolute temperatures of the hot source and the cold source.", "The point where the compressor consumes more watts than it delivers in BTUs.", "The critical pressure where gas becomes a supercritical fluid without passing through the liquid phase."], explanation: "The Carnot cycle establishes that no heat engine can be more efficient than what its temperature limits (in Kelvin) allow. It is the efficiency ceiling for any HVAC system." },
  { id:"calef_549", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué sucede con la Humedad Relativa de una casa si el horno de gas tiene una fuga en el intercambiador y mezcla aire de combustión con el aire de la casa?", opciones:["La humedad relativa baja porque la llama seca el aire.", "La humedad relativa aumenta drásticamente debido a que el vapor de agua es un subproducto masivo de la combustión del metano.", "Se mantiene constante pero el nivel de nitrógeno sube.", "El punto de rocío cae por debajo de los 0°C inmediatamente."], respuesta_correcta:1, explicacion:"Al quemar $CH_4$, se produce $CO_2$ y $H_2O$. Si esos gases entran a la casa, la humedad sube (y el CO, lo cual es letal), provocando condensación excesiva en ventanas." , question: "What happens to the Relative Humidity in a home if the gas furnace has a cracked heat exchanger and mixes combustion air with the house air?", options: ["Relative humidity drops because the flame dries the air.", "Relative humidity rises drastically because water vapor is a major byproduct of methane combustion.", "It stays constant but the nitrogen level increases.", "The dew point drops below 32 degrees Fahrenheit immediately."], explanation: "Burning methane (CH4) produces CO2 and H2O. If those gases enter the house, humidity rises (and CO as well, which is lethal), causing excessive condensation on windows." },
  { id:"calef_550", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es la diferencia técnica entre Calor Sensible y Calor Latente en el contexto de un humidificador de horno?", opciones:["El sensible cambia la temperatura; el latente cambia el estado físico (agua a vapor) sin cambiar la temperatura.", "El latente es el calor que se siente en la piel; el sensible es el que mide el termostato.", "No hay diferencia, ambos se miden en grados Celsius.", "El sensible es para gas natural y el latente para calefacción eléctrica."], respuesta_correcta:0, explicacion:"Para humidificar, necesitamos añadir calor latente (energía para evaporar agua). Esto no sube la temperatura de la casa, pero sí la energía total (entalpía) del aire." , question: "What is the technical difference between Sensible Heat and Latent Heat in the context of a furnace humidifier?", options: ["Sensible heat changes the temperature; latent heat changes the physical state (water to vapor) without changing the temperature.", "Latent heat is the heat felt on the skin; sensible heat is what the thermostat measures.", "There is no difference; both are measured in degrees Celsius.", "Sensible heat is for natural gas and latent heat is for electric heating."], explanation: "To humidify, you need to add latent heat (energy to evaporate water). This does not raise the room temperature, but it does increase the total energy (enthalpy) of the air." },
  { id:"calef_551", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es el 'aspect ratio' ideal para un ducto de suministro de calefacción para minimizar la fricción?", opciones:["10:1 (Muy ancho y plano).", "1:1 (Cuadrado o redondo).", "4:1 (Rectangular alargado).", "Cualquier medida es igual si el material es fibra de vidrio."], respuesta_correcta:1, explicacion:"Un ducto cuadrado o redondo ofrece la mayor área con el menor perímetro (superficie de fricción). Los ductos muy planos pierden mucha presión por el roce del aire con las paredes." , question: "What is the ideal aspect ratio for a heating supply duct to minimize friction?", options: ["10:1 (very wide and flat).", "1:1 (square or round).", "4:1 (elongated rectangular).", "Any dimension is the same if the material is fiberglass."], explanation: "A square or round duct offers the greatest cross-sectional area with the smallest perimeter (friction surface). Very flat ducts lose a lot of pressure from the air rubbing against the walls." },
  { id:"calef_552", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es el 'Slip' en un motor de inducción de una manejadora de aire?", opciones:["Cuando la correa de transmisión se resbala en la polea.", "La diferencia entre la velocidad del campo magnético (síncrona) y la velocidad real del rotor.", "Un error en el software del termostato.", "La pérdida de aceite en los rodamientos sellados."], respuesta_correcta:1, explicacion:"Si no hubiera 'slip', no habría inducción. El rotor siempre debe girar un poco más lento que el campo magnético para poder generar torque." , question: "What is 'Slip' in an induction motor of an air handler?", options: ["When the drive belt slips on the pulley.", "The difference between the speed of the magnetic field (synchronous speed) and the actual rotor speed.", "A software error in the thermostat.", "Oil loss from the sealed bearings."], explanation: "If there were no slip, there would be no induction. The rotor must always turn slightly slower than the magnetic field in order to generate torque." },
  { id:"calef_553", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué el calor radiante (como un piso térmico) se siente más cómodo a 20°C que el aire forzado a 22°C?", opciones:["Porque el aire forzado destruye los iones negativos del ambiente.", "Debido a que el calor radiante calienta los objetos y personas directamente, reduciendo la pérdida de calor corporal por radiación hacia las paredes frías.", "El aire forzado siempre está contaminado con polvo.", "Es una sugestión psicológica por el costo del equipo."], respuesta_correcta:1, explicacion:"Nosotros perdemos calor hacia las superficies frías. Si el piso y las paredes están tibios (radiante), nuestro cuerpo se siente bien aunque el aire esté un poco más fresco." , question: "Why does radiant heat (such as a heated floor) feel more comfortable at 68 degrees Fahrenheit than forced air at 72 degrees Fahrenheit?", options: ["Because forced air destroys negative ions in the environment.", "Because radiant heat warms objects and people directly, reducing the body's radiant heat loss toward cold walls.", "Forced air is always contaminated with dust.", "It is a psychological suggestion related to the cost of the equipment."], explanation: "We lose heat to cold surfaces. If the floor and walls are warm (radiant heat), our body feels comfortable even though the air is a bit cooler." },
  { id:"calef_554", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es el volumen aproximado de aire necesario para quemar perfectamente 1 pie cúbico de Gas Natural?", opciones:["1 pie cúbico de aire.", "10 pies cúbicos de aire.", "100 pies cúbicos de aire.", "0.5 pies cúbicos de aire puro."], respuesta_correcta:1, explicacion:"Relación aproximada 10:1. Si no hay suficiente espacio o ventilación, el horno 'se ahoga' y produce monóxido de carbono." , question: "What is the approximate volume of air needed to perfectly combust 1 cubic foot of natural gas?", options: ["1 cubic foot of air.", "10 cubic feet of air.", "100 cubic feet of air.", "0.5 cubic feet of pure air."], explanation: "The approximate ratio is 10:1. If there is not enough space or ventilation, the furnace is starved of oxygen and produces carbon monoxide." },
  { id:"calef_555", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un filtro de aire de alta eficiencia (MERV 13) puede causar que un horno se apague por límite alto?", opciones:["Porque el filtro desprende químicos que apagan la llama.", "Porque ofrece demasiada resistencia al aire (presión estática alta), reduciendo el flujo de aire que enfría el intercambiador de calor.", "El filtro MERV 13 calienta el aire por fricción molecular.", "No puede pasar, los filtros siempre ayudan a la eficiencia."], respuesta_correcta:1, explicacion:"Filtro muy tupido = menos aire. Menos aire = el metal del horno se pone al rojo vivo y el sensor de seguridad corta el gas para evitar un incendio." , question: "Why can a high-efficiency air filter (MERV 13) cause a furnace to shut off on high limit?", options: ["Because the filter releases chemicals that extinguish the flame.", "Because it creates too much resistance to airflow (high static pressure), reducing the airflow that cools the heat exchanger.", "The MERV 13 filter heats the air through molecular friction.", "It cannot happen; filters always help efficiency."], explanation: "A very restrictive filter means less air. Less air means the furnace metal overheats and the safety limit switch cuts the gas to prevent a fire." },
  { id:"calef_556", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cómo afecta un aumento de altitud al punto de ebullición del agua en una caldera?", opciones:["El agua hierve a una temperatura más alta.", "El agua hierve a una temperatura más baja debido a la menor presión atmosférica.", "No afecta, el agua siempre hierve a 100°C.", "La altitud solo afecta a los gases, no a los líquidos."], respuesta_correcta:1, explicacion:"En las montañas, hay menos aire 'empujando' el agua. Las moléculas escapan más fácil. Esto afecta los ajustes de presión y temperatura en sistemas de vapor." , question: "How does an increase in altitude affect the boiling point of water in a boiler?", options: ["Water boils at a higher temperature.", "Water boils at a lower temperature due to reduced atmospheric pressure.", "It does not matter; water always boils at 212 degrees Fahrenheit.", "Altitude only affects gases, not liquids."], explanation: "In the mountains, there is less air pressing down on the water. The molecules escape more easily. This affects the pressure and temperature settings on steam systems." },
  { id:"calef_557", categoria:"CALEF_TERMODINAMICA", pregunta:"En un sistema de calefacción eléctrica por etapas, ¿cuál es el riesgo de que todas las resistencias enciendan exactamente al mismo tiempo?", opciones:["Que el aire salga demasiado caliente y queme las rejillas.", "Un pico de corriente (Inrush Current) masivo que puede disparar el interruptor principal o causar caídas de voltaje en la casa (parpadeo de luces).", "Que el motor del ventilador gire más rápido por inducción magnética.", "No hay riesgo, así es como funcionan todos los hornos eléctricos."], respuesta_correcta:1, explicacion:"Por eso se usan secuenciadores o relés de retardo. Encienden una resistencia de 5kW, esperan 30 segundos, y luego la siguiente. Así la carga eléctrica es gradual." , question: "In a staged electric heating system, what is the risk of all heating elements energizing at exactly the same time?", options: ["The air will come out too hot and burn the registers.", "A massive inrush current spike that can trip the main breaker or cause voltage drops in the house (lights flickering).", "The blower motor will spin faster due to electromagnetic induction.", "There is no risk; that is how all electric furnaces work."], explanation: "That is why sequencers or time-delay relays are used. They energize one 5 kW element, wait 30 seconds, then the next. This way the electrical load ramps up gradually." },
  { id:"calef_558", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Presión Estática Total Externa' (TESP)?", opciones:["La presión del aire afuera de la casa.", "La resistencia total que el soplador debe vencer, incluyendo el filtro, el serpentín de aire acondicionado y todos los ductos de suministro y retorno.", "La presión dentro del tanque de expansión.", "El peso del metal de los ductos."], respuesta_correcta:1, explicacion:"Es como la presión arterial del sistema. Si es muy alta, el motor sufre y el flujo de aire cae. Se mide con un manómetro antes y después del horno." , question: "What is 'Total External Static Pressure' (TESP)?", options: ["The air pressure outside the house.", "The total resistance the blower must overcome, including the filter, the air conditioning coil, and all supply and return ductwork.", "The pressure inside the expansion tank.", "The weight of the metal ductwork."], explanation: "It is like the blood pressure of the system. If it is too high, the motor struggles and airflow drops. It is measured with a manometer before and after the furnace." },
  { id:"calef_559", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué fenómeno ocurre si el aire de retorno de una calefacción está a 15°C con 80% de HR y el intercambiador de calor del horno está a 75°C?", opciones:["Condensación inmediata en la cara exterior del intercambiador.", "Calentamiento sensible puro; la humedad relativa cae drásticamente mientras la humedad absoluta permanece constante.", "Evaporación latente del nitrógeno residual.", "Aumento del punto de rocío del aire de suministro por encima de los 40°C."], respuesta_correcta:1, explicacion:"Al calentar el aire sin añadir agua, la capacidad de retener vapor aumenta pero la cantidad de agua es la misma. El aire se vuelve 'más seco' en términos relativos." , question: "What phenomenon occurs when return air at 59 degrees Fahrenheit with 80 percent RH meets a furnace heat exchanger at 167 degrees Fahrenheit?", options: ["Immediate condensation on the outer face of the heat exchanger.", "Pure sensible heating; relative humidity drops dramatically while absolute humidity remains constant.", "Latent evaporation of residual nitrogen.", "An increase in the supply air dew point above 104 degrees Fahrenheit."], explanation: "When air is heated without adding moisture, its capacity to hold vapor increases but the actual amount of water stays the same. The air becomes much 'drier' in relative terms." },
  { id:"calef_560", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué ocurre con la curva de rendimiento de un ventilador si la presión estática del sistema es menor a la diseñada (ductos muy grandes)?", opciones:["El motor se quemará por bajo consumo de amperaje.", "El flujo de aire (CFM) aumentará excesivamente, lo que puede causar ruido de aire y que el motor se sobrecargue por mover demasiada masa.", "La temperatura del aire de suministro subirá peligrosamente.", "El ventilador entrará en un estado de 'Stall' o pérdida de sustentación."], respuesta_correcta:1, explicacion:"Menos resistencia = más aire. Mover más aire requiere más trabajo (HP). Si el ducto es muy libre, el motor puede superar su amperaje nominal (FLA) y disparar el protector térmico." , question: "What happens to the performance curve of a fan if the system static pressure is lower than designed (oversized ducts)?", options: ["The motor will burn from low amperage draw.", "Airflow (CFM) increases excessively, which can cause air noise and cause the motor to overload from moving too much mass.", "The supply air temperature will rise dangerously.", "The fan will enter a 'stall' or aerodynamic loss condition."], explanation: "Less resistance means more air. Moving more air requires more work (HP). If the duct is too open, the motor can exceed its full load amperage (FLA) and trip the thermal protector." },
  { id:"calef_561", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Temperatura de Llama Adiabática'?", opciones:["La temperatura de la llama medida con un termopar de contacto.", "La temperatura teórica máxima que alcanzaría una llama si no se perdiera calor hacia el ambiente durante la combustión.", "El punto donde la llama se vuelve invisible al ojo humano.", "La temperatura mínima necesaria para encender el gas propano."], respuesta_correcta:1, explicacion:"Es un valor de diseño. En la vida real, la llama siempre es más fría porque pierde calor hacia el intercambiador y el aire circundante." , question: "What is the 'Adiabatic Flame Temperature'?", options: ["The flame temperature measured with a contact thermocouple.", "The maximum theoretical temperature a flame would reach if no heat were lost to the surroundings during combustion.", "The point at which the flame becomes invisible to the human eye.", "The minimum temperature needed to ignite propane gas."], explanation: "It is a design value. In real life, the flame is always cooler because it loses heat to the heat exchanger and the surrounding air." },
  { id:"calef_562", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un sistema de calefacción por aire forzado puede resecar la madera de los muebles si la humedad absoluta (grains of moisture) es la misma adentro que afuera?", opciones:["Porque el horno inyecta ozono que degrada la celulosa.", "Debido a que al subir la temperatura, la humedad relativa baja; el aire 'seco' busca equilibrio extrayendo humedad de los objetos porosos.", "La velocidad del aire arranca las moléculas de agua por fricción mecánica.", "El filtro de aire atrapa las gotas de agua microscópicas."], respuesta_correcta:1, explicacion:"El aire caliente tiene una 'sed' mayor de agua (mayor capacidad). Al calentar el aire frío del exterior sin humidificarlo, este se vuelve agresivo y absorbe agua de donde pueda: muebles, plantas y piel." , question: "Why can a forced-air heating system dry out wooden furniture if the absolute humidity (grains of moisture) is the same indoors as outdoors?", options: ["Because the furnace injects ozone that degrades cellulose.", "Because raising the temperature lowers the relative humidity; the 'dry' air seeks equilibrium by extracting moisture from porous objects.", "The velocity of the air strips water molecules through mechanical friction.", "The air filter traps microscopic water droplets."], explanation: "Warm air has a greater thirst for water (higher capacity). When you heat cold outdoor air without humidifying it, it becomes aggressive and absorbs moisture from wherever it can: furniture, plants, and skin." },
  { id:"calef_563", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Presión Dinámica' en un ducto de calefacción?", opciones:["La presión que ejerce el aire contra las paredes del ducto.", "La presión causada por la velocidad del movimiento del aire; es la diferencia entre la Presión Total y la Presión Estática.", "La presión que genera el compresor en el refrigerante.", "El peso del aire en reposo dentro del plenum."], respuesta_correcta:1, explicacion:"Es la energía cinética del aire. Se mide apuntando el tubo Pitot hacia la dirección del flujo. A más velocidad, más presión dinámica." , question: "What is 'Dynamic Pressure' in a heating duct?", options: ["The pressure the air exerts against the duct walls.", "The pressure caused by the velocity of the moving air; it is the difference between Total Pressure and Static Pressure.", "The pressure the compressor generates on the refrigerant.", "The weight of the air at rest inside the plenum."], explanation: "It is the kinetic energy of the air. It is measured by pointing the Pitot tube in the direction of airflow. The higher the velocity, the greater the dynamic pressure." },
  { id:"calef_564", categoria:"CALEF_TERMODINAMICA", pregunta:"Un cliente instala un humidificador de bypass. ¿Cuál es el peligro de conectarlo al agua caliente en lugar de fría si el ducto de retorno es de plástico?", opciones:["Ninguno, el agua caliente mejora la evaporación.", "Riesgo de crecimiento bacteriano excesivo (Legionella) si la temperatura del agua se mantiene en el rango de incubación dentro del ducto.", "El vapor derretirá el filtro de aire inmediatamente.", "El agua caliente tiene menos minerales y no humidifica bien."], respuesta_correcta:1, explicacion:"Aunque evapora mejor, el agua estancada tibia es un nido de bacterias. Se recomienda agua caliente solo si el ciclo de calefacción es corto o si el sistema se drena totalmente." , question: "A customer installs a bypass humidifier. What is the danger of connecting it to hot water instead of cold water if the return duct is plastic?", options: ["None; hot water improves evaporation.", "Risk of excessive bacterial growth (Legionella) if the water temperature stays in the incubation range inside the duct.", "The steam will melt the air filter immediately.", "Hot water has fewer minerals and does not humidify well."], explanation: "Although hot water evaporates better, warm stagnant water is a breeding ground for bacteria. Hot water is recommended only if the heating cycle is short or if the system drains completely." },
  { id:"calef_565", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es la rugosidad relativa de un ducto flexible (flex duct) comparada con un ducto de lámina galvanizada?", opciones:["Es menor porque el plástico es más liso.", "Es mucho mayor, especialmente si no está totalmente estirado, lo que aumenta la pérdida de fricción drásticamente.", "Es idéntica si ambos tienen el mismo diámetro.", "El flex duct no tiene rugosidad por ser un material compuesto."], respuesta_correcta:1, explicacion:"Las espirales de alambre del flex duct crean turbulencia. Si el técnico deja el ducto con 'curvas' o arrugas, el flujo de aire puede caer a la mitad comparado con un tubo rígido." , question: "What is the relative roughness of flexible duct (flex duct) compared to galvanized sheet metal duct?", options: ["It is lower because plastic is smoother.", "It is much higher, especially if it is not fully stretched, which drastically increases friction loss.", "It is identical if both have the same diameter.", "Flex duct has no roughness because it is a composite material."], explanation: "The wire spirals in flex duct create turbulence. If the installer leaves the duct with bends or wrinkles, airflow can drop to half compared to a rigid metal duct." },
  { id:"calef_566", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué nivel de humedad relativa (HR) mínima se recomienda para evitar la supervivencia de virus en el aire interior en invierno?", opciones:["10%.", "Entre el 40% y el 60%.", "Lo más cercano al 100% posible.", "La humedad no afecta a los virus."], respuesta_correcta:1, explicacion:"En aire muy seco (menos del 40%), los virus flotan más tiempo y nuestras mucosas se secan. Mantener un nivel medio ayuda a que las partículas caigan al suelo y nuestras defensas funcionen." , question: "What minimum relative humidity (RH) level is recommended to reduce airborne virus survival indoors during winter?", options: ["10 percent.", "Between 40 percent and 60 percent.", "As close to 100 percent as possible.", "Humidity does not affect viruses."], explanation: "In very dry air (below 40 percent), viruses stay airborne longer and our mucous membranes dry out. Maintaining a moderate level helps particles settle to the floor and keeps our defenses working." },
  { id:"calef_567", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted mide un CFM de 1200 en un sistema de 3 toneladas. Al cambiar el filtro sucio por uno nuevo, el CFM sube a 1400. ¿Qué sucedió con la presión estática?", opciones:["Aumentó proporcionalmente.", "Bajó la presión estática total externa (TESP) porque se eliminó la restricción del filtro sucio.", "Se mantuvo igual porque los ductos no cambiaron.", "El motor entró en modo de torque constante."], respuesta_correcta:1, explicacion:"Filtro limpio = menos resistencia. Menos resistencia = menor presión estática. Y como resultado, el ventilador puede mover más masa de aire (CFM)." , question: "You measure 1,200 CFM on a 3-ton system. After replacing the dirty filter with a new one, CFM rises to 1,400. What happened to the static pressure?", options: ["It increased proportionally.", "The total external static pressure (TESP) dropped because the filter restriction was eliminated.", "It stayed the same because the ductwork did not change.", "The motor went into constant torque mode."], explanation: "A clean filter means less resistance. Less resistance means lower static pressure. As a result, the fan can move more air mass (CFM)." },
  { id:"calef_568", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted escucha un chirrido metálico (high pitched squeal) que varía con las RPM del motor soplador. ¿Cuál es el diagnóstico?", opciones:["El motor tiene un problema eléctrico de fases.", "Los rodamientos (bearings) están secos o fallando; el metal está rozando contra metal.", "El filtro de aire está vibrando en su base.", "La rueda del soplador está perfectamente balanceada."], respuesta_correcta:1, explicacion:"Es un aviso de muerte inminente. El rodamiento ha perdido su lubricación. Si no se cambia o lubrica pronto, el motor se trabará y se quemará." , question: "You hear a high-pitched metallic squeal that varies with the blower motor RPM. What is the diagnosis?", options: ["The motor has an electrical phase problem.", "The bearings are dry or failing; metal is rubbing against metal.", "The air filter is vibrating in its frame.", "The blower wheel is perfectly balanced."], explanation: "It is a warning of imminent failure. The bearing has lost its lubrication. If it is not replaced or lubricated soon, the motor will seize and burn out." },
  { id:"calef_569", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué se prefieren los retornos de aire en las paredes bajas para calefacción en climas muy fríos?", opciones:["Para que sea más fácil aspirar el suelo.", "Para capturar el aire más frío y denso que se acumula en el suelo y llevarlo al horno para recalentarlo, mejorando la circulación.", "Para evitar que el aire caliente se escape por el techo.", "Es puramente por diseño arquitectónico moderno."], respuesta_correcta:1, explicacion:"El aire frío 'cae'. Si lo succionas desde abajo, obligas al aire caliente del techo a bajar, mezclando mejor la temperatura de la habitación y evitando pies fríos." , question: "Why are low-wall air returns preferred for heating in very cold climates?", options: ["To make vacuuming the floor easier.", "To capture the coldest, densest air that accumulates at floor level and carry it to the furnace for reheating, improving circulation.", "To prevent warm air from escaping through the ceiling.", "It is purely a modern architectural design choice."], explanation: "Cold air sinks. If you pull it from below, you force the warm air at the ceiling to descend, mixing the room temperature better and preventing cold feet." },
  { id:"calef_570", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es el 'Aire Primario' en un quemador de gas?", opciones:["El primer aire que sale por las rejillas.", "El aire que se mezcla con el gas **antes** de llegar a la llama, controlado por el obturador del quemador.", "El aire que rodea la llama para terminar la combustión.", "El aire que aspira el motor inductor."], respuesta_correcta:1, explicacion:"Es el aire que el gas 'succiona' al pasar por el orificio. Si ajustas mal este aire, la llama se vuelve amarilla o se apaga." , question: "What is 'Primary Air' in a gas burner?", options: ["The first air that exits the registers.", "The air that mixes with the gas before reaching the flame, controlled by the burner shutter.", "The air that surrounds the flame to complete combustion.", "The air drawn in by the inducer motor."], explanation: "It is the air that the gas entrains as it passes through the orifice. If this air is adjusted incorrectly, the flame turns yellow or blows out." },
  { id:"calef_571", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un cliente siente 'escalofríos' en una casa a 21°C si la humedad relativa es solo del 15%?", opciones:["Porque el termostato está mintiendo.", "Debido a la rápida evaporación de la humedad de su piel, lo cual es un proceso que enfría el cuerpo (evaporative cooling).", "Porque hay fantasmas térmicos en los ductos.", "A esa humedad el aire se vuelve un conductor eléctrico de calor."], respuesta_correcta:1, explicacion:"El aire seco es un ladrón de agua. Al evaporar el sudor microscópico de nuestra piel, nos roba calor. Si subes la humedad al 40%, el cliente sentirá calor a los mismos 21°C." , question: "Why does a customer feel 'chills' in a house at 70 degrees Fahrenheit if the relative humidity is only 15 percent?", options: ["Because the thermostat is lying.", "Due to the rapid evaporation of moisture from the skin, which is a process that cools the body (evaporative cooling).", "Because there are thermal ghosts in the ducts.", "At that humidity, air becomes an electrical conductor of heat."], explanation: "Dry air is a moisture thief. By evaporating the microscopic perspiration from our skin, it robs us of heat. If you raise the humidity to 40 percent, the customer will feel warm at the same 70 degrees." },
  { id:"calef_572", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué sucede con el Coeficiente de Rendimiento (COP) de una bomba de calor si la temperatura exterior cae de 5°C a -10°C?", opciones:["El COP aumenta porque el compresor trabaja con mayor diferencia de presión.", "El COP disminuye drásticamente debido a que la relación de compresión aumenta y la masa de calor disponible en el aire exterior se reduce.", "Se mantiene constante gracias a la válvula de expansión electrónica (EEV).", "El COP se vuelve infinito al entrar en modo de calor auxiliar."], respuesta_correcta:1, explicacion:"A menor temperatura exterior, el compresor debe esforzarse mucho más para extraer el poco calor disponible. Gastas más electricidad para obtener la misma energía térmica." , question: "What happens to the Coefficient of Performance (COP) of a heat pump if the outdoor temperature drops from 41 degrees Fahrenheit to 14 degrees Fahrenheit?", options: ["COP increases because the compressor works with a greater pressure difference.", "COP decreases drastically because the compression ratio increases and the available heat mass in the outdoor air is reduced.", "COP remains constant thanks to the electronic expansion valve (EEV).", "COP becomes infinite when the system enters auxiliary heat mode."], explanation: "The lower the outdoor temperature, the harder the compressor must work to extract the little available heat. You spend more electricity for the same thermal output." },
  { id:"calef_573", categoria:"CALEF_TERMODINAMICA", pregunta:"Si un sistema de calefacción introduce demasiado aire fresco exterior sin pre-calentarlo, ¿qué efecto tiene sobre la Humedad Relativa interior en un día de -5°C?", opciones:["La HR sube porque el aire de afuera está muy húmedo.", "La HR cae a niveles peligrosamente bajos (menores al 10%) una vez que ese aire se calienta a 22°C adentro.", "No hay cambio, la humedad es una propiedad intrínseca del edificio.", "El aire se satura y se forma niebla en los ductos de retorno."], respuesta_correcta:1, explicacion:"El aire frío contiene casi nada de agua. Al calentarlo, su 'capacidad' crece pero el agua sigue siendo la misma. Esto reseca los ojos, la piel y las vías respiratorias de los ocupantes." , question: "If a heating system introduces too much fresh outdoor air without preheating it, what effect does it have on indoor Relative Humidity on a 23-degree-Fahrenheit day?", options: ["RH rises because the outdoor air is very humid.", "RH drops to dangerously low levels (below 10 percent) once that air is heated to 72 degrees Fahrenheit indoors.", "There is no change; humidity is an intrinsic property of the building.", "The air saturates and fog forms in the return ducts."], explanation: "Cold air contains almost no water. When heated, its capacity grows but the moisture stays the same. This dries out the eyes, skin, and respiratory passages of the occupants." },
  { id:"calef_574", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted mide una presión estática de 0.4\" en el suministro y -0.4\" en el retorno. ¿Cuál es la TESP (Presión Estática Total Externa)?", opciones:["0.0\" porque las presiones se anulan.", "0.8\" w.c. (se toma el valor absoluto de la suma de ambas presiones).", "0.16\" w.c. según la ley de las potencias centrífugas.", "No se puede calcular sin saber el tamaño del filtro."], respuesta_correcta:1, explicacion:"La presión estática total es la diferencia de presión que el ventilador debe vencer. Es la suma de la 'fuerza para empujar' y la 'fuerza para succionar' (ignora los signos negativos)." , question: "You measure a static pressure of 0.4 inches w.c. on the supply side and minus 0.4 inches w.c. on the return side. What is the TESP (Total External Static Pressure)?", options: ["0.0 inches because the pressures cancel each other out.", "0.8 inches w.c. (the absolute values of both pressures are added together).", "0.16 inches w.c. per the centrifugal power law.", "It cannot be calculated without knowing the filter size."], explanation: "Total external static pressure is the pressure difference the fan must overcome. It is the sum of the push force and the pull force (disregard the negative signs)." },
  { id:"calef_575", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es el 'Efecto de Enfriamiento por Evaporación' en un intercambiador de calor secundario de un horno de condensación?", opciones:["Cuando el agua se congela dentro del horno.", "No existe; en realidad ocurre lo opuesto: la condensación libera calor latente que el intercambiador absorbe para mejorar la eficiencia.", "Es cuando el soplador enfría el agua del drenaje.", "Un proceso que reduce la temperatura de la llama mediante vapor."], respuesta_correcta:1, explicacion:"Capciosa: Al pasar de vapor a líquido (condensación), el agua libera energía. El horno atrapa esa energía extra que en hornos viejos se desperdiciaba por la chimenea." , question: "What is the 'Evaporative Cooling Effect' in the secondary heat exchanger of a condensing furnace?", options: ["When water freezes inside the furnace.", "It does not exist; in fact the opposite occurs: condensation releases latent heat that the heat exchanger absorbs to improve efficiency.", "It is when the blower cools the drain water.", "A process that reduces the flame temperature using steam."], explanation: "This is a trick question: when vapor turns to liquid (condensation), the water releases energy. The furnace captures that extra energy that older furnaces wasted up the flue." },
  { id:"calef_576", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué los ductos de calefacción en el ático deben estar aislados con al menos R-8 en climas fríos?", opciones:["Para evitar que el metal se oxide con la nieve.", "Para minimizar la pérdida de calor sensible hacia el ático frío, asegurando que el aire llegue caliente a las rejillas y evitando condensación interna.", "Para que los ratones no muerdan el metal.", "Aumenta la velocidad del aire mediante el efecto térmico."], respuesta_correcta:1, explicacion:"Si el aire sale del horno a 50°C y viaja por un tubo de metal frío a -5°C, llegará frío a la habitación. El aislamiento mantiene la energía donde pertenece: dentro del ducto." , question: "Why must heating ducts in the attic be insulated to at least R-8 in cold climates?", options: ["To prevent the metal from rusting due to snow.", "To minimize sensible heat loss to the cold attic, ensuring the air arrives warm at the registers and preventing internal condensation.", "To keep rodents from chewing on the metal.", "It increases air velocity through the thermal effect."], explanation: "If the air leaves the furnace at 120 degrees Fahrenheit and travels through a cold metal duct at 23 degrees Fahrenheit, it will arrive cool at the room. Insulation keeps the energy where it belongs: inside the duct." },
  { id:"calef_577", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es el riesgo de sobre-humidificar una casa en invierno (ej. mantener 60% HR a -10°C exterior)?", opciones:["Que el horno se oxide por dentro.", "Condensación masiva dentro de las paredes y ventanas, lo que provoca moho (mold) y pudrición de la estructura de madera.", "Que el aire se vuelva demasiado pesado para el ventilador.", "Aumento del riesgo de estática eléctrica destructiva."], respuesta_correcta:1, explicacion:"El agua siempre busca el frío. Si hay mucha humedad adentro, el vapor atraviesa el tablaroca, toca la madera fría de la estructura y se convierte en agua líquida, pudriendo la casa en silencio." , question: "What is the risk of over-humidifying a house in winter (e.g., maintaining 60 percent RH at minus 10 degrees Celsius outdoors)?", options: ["The furnace will rust internally.", "Massive condensation inside walls and on windows, which leads to mold growth and rotting of the wood structure.", "The air becomes too heavy for the blower.", "Increased risk of destructive static electricity."], explanation: "Water always seeks the cold. If there is too much humidity inside, the vapor passes through the drywall, contacts the cold framing, and turns into liquid water, silently rotting the house." },
  { id:"calef_578", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Inestabilidad del Ventilador' (Fan Surge)?", opciones:["Cuando el motor acelera y desacelera sin control.", "Una condición donde el ventilador no puede vencer la presión estática y el aire 'rebota' o fluye hacia atrás intermitentemente, causando vibración y ruido fuerte.", "Cuando el capacitor de marcha está muy grande.", "Un aumento súbito del voltaje en los terminales del motor."], respuesta_correcta:1, explicacion:"Ocurre cuando el ducto está muy obstruido. El ventilador 'pierde el agarre' del aire y este golpea las aspas hacia atrás. Es muy destructivo para los rodamientos y el motor." , question: "What is 'Fan Surge' (fan instability)?", options: ["When the motor accelerates and decelerates uncontrollably.", "A condition where the fan cannot overcome the static pressure and the air bounces back or flows in reverse intermittently, causing vibration and loud noise.", "When the run capacitor is oversized.", "A sudden increase in voltage at the motor terminals."], explanation: "It occurs when the ductwork is severely obstructed. The fan loses its grip on the air and the air pushes back against the blades. It is very destructive to the bearings and motor." },
  { id:"calef_579", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es el 'Sub-enfriamiento' en la línea de líquido y para qué sirve?", opciones:["Enfriar el líquido para que no queme al técnico.", "Garantizar que el refrigerante llegue 100% en estado líquido a la válvula de expansión, maximizando la capacidad del serpentín.", "Reducir la presión de alta para ahorrar electricidad.", "Es el enfriamiento del aceite del compresor."], respuesta_correcta:1, explicacion:"Si el líquido llega con burbujas de gas (flash gas) a la válvula, el serpentín no enfría ni calienta bien. El subcooling nos dice que el condensador hizo bien su trabajo." , question: "What is 'Subcooling' in the liquid line and what is it used for?", options: ["To cool the liquid so it does not burn the technician.", "To ensure the refrigerant arrives at the expansion valve 100 percent in liquid state, maximizing the coil capacity.", "To reduce the high-side pressure to save electricity.", "It is the cooling of the compressor oil."], explanation: "If the liquid arrives at the valve with gas bubbles (flash gas), the coil cannot heat or cool effectively. Subcooling tells us the condenser did its job properly." },
  { id:"calef_580", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Estratificación del Aire' y cómo afecta a la calefacción?", opciones:["Cuando el aire se vuelve eléctrico.", "La tendencia del aire caliente a quedarse en el techo y el frío en el suelo, creando una diferencia de temperatura incómoda en la misma habitación.", "Un proceso de filtración por capas de carbón activado.", "El estudio de los virus según la altura del edificio."], respuesta_correcta:1, explicacion:"Es el enemigo del confort. Puedes tener el termostato a 22°C (a la altura del pecho), pero tener los pies a 18°C y la cabeza a 26°C. Se soluciona con una buena mezcla de aire." , question: "What is 'Air Stratification' and how does it affect heating?", options: ["When the air becomes electrically charged.", "The tendency of warm air to stay at the ceiling and cold air at the floor, creating an uncomfortable temperature difference within the same room.", "A multi-layer activated carbon filtration process.", "The study of viruses based on building height."], explanation: "It is the enemy of comfort. You can have the thermostat set to 72 degrees Fahrenheit (at chest height), but the floor could be at 65 and the ceiling at 80. It is solved with proper air mixing." },
  { id:"calef_581", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es un 'Plenum de Retorno'?", opciones:["La caja metálica donde el aire caliente sale hacia la casa.", "La caja o cámara de aire donde todos los ductos de retorno se juntan antes de entrar al filtro y al soplador del horno.", "Un tipo de ventilador de alta presión.", "El tubo que saca el humo hacia la chimenea."], respuesta_correcta:1, explicacion:"Es el 'pulmón' de entrada. Si es muy pequeño, el soplador se 'ahoga', el flujo de aire cae y el horno se sobrecalienta. Debe ser siempre de un tamaño generoso." , question: "What is a 'Return Plenum'?", options: ["The metal box where warm air exits toward the house.", "The box or air chamber where all return ducts converge before the air enters the filter and the furnace blower.", "A type of high-pressure fan.", "The pipe that carries flue gases to the chimney."], explanation: "It is the intake lung. If it is too small, the blower is starved of air, airflow drops, and the furnace overheats. It must always be generously sized." },
  { id:"calef_582", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué el aire de suministro de calefacción no debe salir a más de 55°C (130°F) en aplicaciones residenciales?", opciones:["Porque derretiría los ductos de plástico.", "Para evitar quemaduras al contacto con las rejillas y prevenir que el aire se vuelva demasiado ligero, causando que suba al techo instantáneamente (estratificación).", "El gas natural no puede calentar el aire a más de esa temperatura.", "Aumenta el riesgo de explosión por polvo doméstico."], respuesta_correcta:1, explicacion:"Si el aire sale demasiado caliente, se va directo al techo y tus pies siguen fríos. Además, el metal de las rejillas puede quemar a un niño o mascota si está a más de 60°C." , question: "Why should the heating supply air not exit at more than 130 degrees Fahrenheit in residential applications?", options: ["Because it would melt plastic ductwork.", "To prevent contact burns at the registers and to keep the air from becoming so light that it rises straight to the ceiling (stratification).", "Natural gas cannot heat air above that temperature.", "It increases the risk of explosion from household dust."], explanation: "If the air exits too hot, it shoots straight to the ceiling and your feet stay cold. Additionally, the register metal can burn a child or pet if it exceeds 140 degrees Fahrenheit." },
  { id:"calef_583", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted instala un horno en una ciudad a 2,500 metros sobre el nivel del mar. ¿Cómo afecta la menor densidad del aire al motor del soplador si es de tipo PSC?", opciones:["El motor se calienta más porque el aire es más pesado.", "El motor consume menos amperaje (realiza menos trabajo al mover menos masa de aire) pero corre el riesgo de no enfriar adecuadamente el intercambiador de calor.", "El motor girará a la mitad de las RPM nominales por falta de fricción.", "El capacitor de marcha se cargará al doble de voltaje debido al aire enrarecido."], respuesta_correcta:1, explicacion:"A gran altura, el aire es 'delgado'. El ventilador 'agarra' menos masa, por lo que el motor se esfuerza menos. El peligro es que, al haber menos aire, el horno se sobrecaliente aunque el motor esté 'descansado'." , question: "You install a furnace in a city at 8,200 feet above sea level. How does the lower air density affect the blower motor if it is a PSC type?", options: ["The motor runs hotter because the air is heavier.", "The motor draws less amperage (does less work moving less air mass) but risks inadequately cooling the heat exchanger.", "The motor will run at half its rated RPM due to lack of friction.", "The run capacitor will charge to double the voltage due to the thin air."], explanation: "At high altitude, the air is thin. The blower grabs less mass, so the motor works less. The danger is that with less air, the furnace may overheat even though the motor seems relaxed." },
  { id:"calef_584", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un humidificador de vapor (Steam Humidifier) consume mucha más electricidad que uno de panel evaporativo convencional?", opciones:["Porque el ventilador del humidificador de vapor es más grande.", "Porque debe suministrar el 'Calor Latente de Evaporación' para hervir el agua, rompiendo los enlaces moleculares para convertirla en gas antes de inyectarla al flujo de aire.", "Debido a que el vapor tiene una resistencia eléctrica intrínseca mayor.", "El costo es el mismo, es una percepción errónea de los recibos de luz."], respuesta_correcta:1, explicacion:"Hervir agua requiere muchísima energía (540 calorías por gramo). El panel evaporativo usa el calor 'gratis' del horno, pero el de vapor debe generar su propio calor eléctrico." , question: "Why does a steam humidifier consume much more electricity than a conventional evaporative pad humidifier?", options: ["Because the steam humidifier fan is larger.", "Because it must supply the latent heat of vaporization to boil the water, breaking molecular bonds to convert it to steam before injecting it into the airstream.", "Because steam has a higher intrinsic electrical resistance.", "The cost is the same; it is a misperception from the electricity bills."], explanation: "Boiling water requires enormous energy (970 BTU per pound). The evaporative pad uses the furnace's free heat, but the steam humidifier must generate its own electric heat." },
  { id:"calef_585", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué sucede con la temperatura de 'Bulbo Húmedo' si mantenemos la temperatura seca constante pero aumentamos la Humedad Relativa?", opciones:["La temperatura de bulbo húmedo disminuye.", "La temperatura de bulbo húmedo aumenta hasta igualar a la seca en el punto de saturación (100% HR).", "Se mantiene constante porque la energía total no cambia.", "Desaparece de la carta psicrométrica."], respuesta_correcta:1, explicacion:"A más humedad, menos evaporación puede ocurrir en el termómetro húmedo. Por lo tanto, el bulbo húmedo no se enfría tanto y su temperatura sube." , question: "What happens to the Wet Bulb temperature if we keep the dry bulb temperature constant but increase the Relative Humidity?", options: ["The wet bulb temperature decreases.", "The wet bulb temperature increases until it equals the dry bulb at the saturation point (100 percent RH).", "It remains constant because total energy does not change.", "It disappears from the psychrometric chart."], explanation: "The more humidity there is, the less evaporation occurs on the wet bulb thermometer. Therefore, the wet bulb does not cool down as much and its temperature rises." },
  { id:"calef_586", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Presión de Vapor' en un sistema de calefacción hidrónica?", opciones:["La presión a la que el agua hierve a una temperatura determinada.", "La fuerza del agua contra el tanque de expansión.", "La velocidad del vapor en los radiadores de hierro.", "La presión del gas natural antes del regulador."], respuesta_correcta:0, explicacion:"Si la presión del sistema cae por debajo de la presión de vapor, el agua se convierte en burbujas de vapor (cavitación), lo cual destruye las bombas circuladoras rápidamente." , question: "What is 'Vapor Pressure' in a hydronic heating system?", options: ["The pressure at which water boils at a given temperature.", "The force of water against the expansion tank.", "The speed of steam in cast iron radiators.", "The pressure of natural gas before the regulator."], explanation: "If the system pressure drops below the vapor pressure, the water turns into steam bubbles (cavitation), which quickly destroys the circulator pumps." },
  { id:"calef_587", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es la función de una 'Bota de Registro' (Register Boot) en un sistema de ductos?", opciones:["Limpiar el calzado del técnico antes de entrar.", "Transicionar el flujo de aire desde un ducto redondo u ovalado hacia una rejilla rectangular en la pared o suelo, minimizando la turbulencia.", "Almacenar el exceso de presión estática.", "Actuar como un filtro secundario de partículas grandes."], respuesta_correcta:1, explicacion:"Es una pieza de adaptación. Si no se usa o está mal instalada, el aire rebota y hace ruido, reduciendo la cantidad de calor que llega a la habitación." , question: "What is the function of a 'Register Boot' in a duct system?", options: ["To clean the technician's footwear before entering.", "To transition the airflow from a round or oval duct to a rectangular register in the wall or floor, minimizing turbulence.", "To store excess static pressure.", "To act as a secondary filter for large particles."], explanation: "It is an adapter fitting. If it is missing or poorly installed, the air bounces and makes noise, reducing the amount of heat reaching the room." },
  { id:"calef_588", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué se recomienda un nivel de Humedad Relativa del 35% en lugar del 50% cuando afuera hay temperaturas bajo cero?", opciones:["Para ahorrar agua en el humidificador.", "Para evitar que la humedad condense y se congele en el interior de las ventanas y paredes frías, causando daños estructurales por moho e hielo.", "El aire seco transporta el calor de forma más eficiente.", "Los virus prefieren el aire seco para reproducirse."], respuesta_correcta:1, explicacion:"Es el compromiso entre confort y seguridad de la casa. Si tienes 50% de humedad y afuera hace mucho frío, tus ventanas 'llorarán' y el agua arruinará el marco y la pared." , question: "Why is a Relative Humidity level of 35 percent recommended instead of 50 percent when outdoor temperatures are below freezing?", options: ["To save water in the humidifier.", "To prevent moisture from condensing and freezing on the inside of windows and cold walls, causing structural damage from mold and ice.", "Dry air transports heat more efficiently.", "Viruses prefer dry air to reproduce."], explanation: "It is the compromise between comfort and building safety. If you maintain 50 percent humidity and it is very cold outside, your windows will weep and the water will damage the frames and walls." },
  { id:"calef_589", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué el aire caliente se acumula en el techo de una habitación?", opciones:["Porque el techo es de madera.", "Porque es menos denso que el aire frío (las moléculas están más separadas), lo que lo hace más liviano y propenso a flotar.", "Por la atracción estática de las luces del techo.", "Debido a que el ventilador siempre sopla hacia arriba."], respuesta_correcta:1, explicacion:"Es pura física de densidades. El aire frío es 'pesado' y cae. Si no mueves el aire con un ventilador, tendrás la cabeza caliente y los pies congelados." , question: "Why does warm air accumulate at the ceiling of a room?", options: ["Because the ceiling is made of wood.", "Because it is less dense than cold air (the molecules are farther apart), making it lighter and prone to float upward.", "Due to static attraction from the ceiling lights.", "Because the blower always blows upward."], explanation: "It is simple density physics. Cold air is heavy and sinks. If you do not circulate the air with a fan, you will have a hot head and frozen feet." },
  { id:"calef_590", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es un 'Ducto de Retorno Dedicado'?", opciones:["Un ducto que solo funciona los domingos.", "Un camino directo de aire desde una habitación específica hacia el horno, garantizando que esa habitación tenga una circulación perfecta.", "Un tubo que saca el aire sucio al exterior.", "La rejilla que está encima del horno."], respuesta_correcta:1, explicacion:"Mucha gente tiene problemas de calor porque cierran la puerta de su cuarto y el aire no puede salir. Un retorno dedicado soluciona eso de raíz." , question: "What is a 'Dedicated Return Duct'?", options: ["A duct that only works on Sundays.", "A direct air path from a specific room to the furnace, ensuring that room has proper circulation.", "A pipe that exhausts dirty air outdoors.", "The grille located on top of the furnace."], explanation: "Many people have heating problems because they close the bedroom door and the air has no way out. A dedicated return solves that at the root." },
  { id:"calef_591", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Presión Atmosférica Estándar' a nivel del mar?", opciones:["0 PSI.", "14.7 PSI.", "100 PSI.", "30 PSI."], respuesta_correcta:1, explicacion:"Es el peso del aire que tenemos encima. Todo en HVAC se basa en esta presión. Si subes a una montaña, la presión baja y todos tus cálculos de gas deben cambiar." , question: "What is 'Standard Atmospheric Pressure' at sea level?", options: ["0 PSI.", "14.7 PSI.", "100 PSI.", "30 PSI."], explanation: "It is the weight of the air above us. Everything in HVAC is based on this pressure. If you go up a mountain, the pressure drops and all your gas calculations must change." },
  { id:"calef_592", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es la principal desventaja del ducto de fibra de vidrio (duct board) comparado con el de metal?", opciones:["Es más pesado.", "Puede absorber humedad y olores, y es más difícil de limpiar si llega a crecer moho en su interior.", "Es mucho más caro.", "No aísla el sonido del ventilador."], respuesta_correcta:1, explicacion:"El metal es liso y fácil de lavar. La fibra es porosa. Si se moja por una fuga o falta de mantenimiento, se convierte en un nido de bacterias difícil de arreglar." , question: "What is the main disadvantage of fiberglass duct board compared to metal ductwork?", options: ["It is heavier.", "It can absorb moisture and odors, and is harder to clean if mold grows inside it.", "It is much more expensive.", "It does not dampen the fan noise."], explanation: "Metal is smooth and easy to clean. Fiberglass is porous. If it gets wet from a leak or lack of maintenance, it becomes a breeding ground for bacteria that is difficult to remediate." },
  { id:"calef_593", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Temperatura Operativa'?", opciones:["La temperatura del motor del horno.", "Un promedio entre la temperatura del aire y la temperatura radiante de las paredes; define cómo se siente realmente una persona.", "La temperatura mínima para que el gas encienda.", "El calor del cuerpo humano en movimiento."], respuesta_correcta:1, explicacion:"Puedes estar en aire a 22°C, pero si las paredes están a 10°C, vas a tener frío. El cuerpo intercambia calor con todo lo que le rodea, no solo con el aire." , question: "What is 'Operative Temperature'?", options: ["The temperature of the furnace motor.", "An average of the air temperature and the radiant temperature of the walls; it defines how a person actually feels.", "The minimum temperature for gas ignition.", "The heat of the human body in motion."], explanation: "You can be in air at 72 degrees Fahrenheit, but if the walls are at 50 degrees, you will feel cold. The body exchanges heat with everything around it, not just the air." },
  { id:"calef_594", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es el 'Límite de Punto de Rocío' recomendado para las superficies internas de los ductos de suministro que pasan por áreas no acondicionadas?", opciones:["Cualquier temperatura por encima de los 0°C.", "La temperatura de la superficie debe estar siempre por encima del punto de rocío del aire circundante para evitar la condensación externa y el crecimiento de moho.", "Debe ser exactamente igual a la temperatura de bulbo húmedo del retorno.", "No importa si el ducto es de aluminio flexible."], respuesta_correcta:1, explicacion:"Si el ducto está más frío que el punto de rocío del aire del ático, 'sudará'. Ese agua mojará el aislamiento, arruinará el techo y causará moho estructural." , question: "What is the recommended 'Dew Point Limit' for the internal surfaces of supply ducts passing through unconditioned areas?", options: ["Any temperature above 32 degrees Fahrenheit.", "The surface temperature must always be above the dew point of the surrounding air to prevent external condensation and mold growth.", "It must be exactly equal to the wet bulb temperature of the return air.", "It does not matter if the duct is flexible aluminum."], explanation: "If the duct is colder than the dew point of the attic air, it will sweat. That water will soak the insulation, ruin the ceiling, and cause structural mold." },
  { id:"calef_595", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué se desaconseja el uso de cinta adhesiva tipo 'Duct Tape' de tela para sellar uniones de ductos de calefacción permanentes?", opciones:["Porque el pegamento es conductor de electricidad.", "Debido a que el adhesivo se degrada rápidamente con los ciclos de calor, se despega y pierde su capacidad de sello hermético (se prefiere mastic o cinta de aluminio).", "Atrae a insectos que se alimentan del tejido de la cinta.", "Es una norma estética impuesta por los arquitectos."], respuesta_correcta:1, explicacion:"Irónicamente, la 'Duct Tape' no sirve para ductos a largo plazo. El calor del horno 'seca' el pegamento y en dos años el ducto está goteando aire caliente al ático." , question: "Why is cloth 'Duct Tape' discouraged for permanently sealing heating duct joints?", options: ["Because the adhesive is electrically conductive.", "Because the adhesive degrades rapidly through heat cycling, peels off, and loses its airtight seal (mastic or aluminum tape is preferred).", "It attracts insects that feed on the tape fabric.", "It is an aesthetic standard imposed by architects."], explanation: "Ironically, duct tape does not work well on ducts long-term. The furnace heat dries out the adhesive and within two years the duct is leaking warm air into the attic." },
  { id:"calef_596", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted instala un deshumidificador de aire de suministro en un sistema de calefacción. ¿En qué punto del sistema de ductos debe inyectarse el aire seco para máxima eficiencia?", opciones:["Directamente en el plenum de retorno antes del filtro.", "En el plenum de suministro, después del intercambiador de calor del horno.", "En el medio de la bota de registro de la habitación principal.", "Dentro de la cámara de combustión del horno."], respuesta_correcta:1, explicacion:"El aire seco debe mezclarse con el aire ya caliente para distribuirse uniformemente. Si lo metes antes del filtro, podrías condensar agua en el intercambiador de calor por error." , question: "You install a supply-air dehumidifier in a heating system. At what point in the duct system should the dry air be injected for maximum efficiency?", options: ["Directly into the return plenum before the filter.", "Into the supply plenum, after the furnace heat exchanger.", "In the middle of the register boot of the master bedroom.", "Inside the furnace combustion chamber."], explanation: "The dry air should mix with the already-heated air so it is distributed evenly. If you introduce it before the filter, you could accidentally condense water on the heat exchanger." },
  { id:"calef_597", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué el agua líquida puede estar a 105°C en una caldera de calefacción sin hervir?", opciones:["Porque se le añade un químico anticongelante especial.", "Debido a que el sistema está bajo presión (ej. 15-20 PSI); la presión eleva el punto de ebullición del agua.", "El agua en movimiento constante no puede formar burbujas de vapor.", "Es una ilusión óptica causada por los termómetros analógicos."], respuesta_correcta:1, explicacion:"Física básica: a más presión, más difícil es que el agua se vuelva gas. Esto permite transportar mucha más energía térmica sin que se formen bolsas de vapor molestas." , question: "Why can liquid water be at 221 degrees Fahrenheit inside a heating boiler without boiling?", options: ["Because a special antifreeze chemical is added.", "Because the system is under pressure (e.g., 15-20 PSI); pressure raises the boiling point of water.", "Water in constant motion cannot form vapor bubbles.", "It is an optical illusion caused by analog thermometers."], explanation: "Basic physics: the higher the pressure, the harder it is for water to become steam. This allows the system to transport much more thermal energy without forming troublesome vapor pockets." },
  { id:"calef_598", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué una 'Bomba de Calor' se siente menos 'caliente' en las rejillas que un horno de gas, incluso si ambas mantienen la casa a 22°C?", opciones:["Porque el calor de la bomba de calor no tiene electrones térmicos.", "Debido a que la temperatura de suministro de una bomba de calor es de ~35-40°C (cerca de la temperatura corporal), mientras que un horno de gas entrega aire a ~50-60°C.", "La bomba de calor solo calienta la humedad, no el aire seco.", "Es un efecto psicológico causado por el ruido de la unidad exterior."], respuesta_correcta:1, explicacion:"La bomba de calor entrega más volumen de aire pero a menor temperatura. Como sale casi a la misma temperatura que tu mano, se siente como una 'brisa tibia' y no como 'calor ardiente'." , question: "Why does a 'Heat Pump' feel less 'hot' at the registers than a gas furnace, even if both keep the house at 72 degrees Fahrenheit?", options: ["Because heat pump heat lacks thermal electrons.", "Because the supply air temperature of a heat pump is about 95-104 degrees Fahrenheit (close to body temperature), while a gas furnace delivers air at about 120-140 degrees Fahrenheit.", "The heat pump only heats the humidity, not the dry air.", "It is a psychological effect caused by the outdoor unit noise."], explanation: "The heat pump delivers more air volume but at a lower temperature. Since the air is nearly the same temperature as your hand, it feels like a warm breeze rather than a hot blast." },
  { id:"calef_599", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Estratificación Térmica' en un tanque de almacenamiento de agua caliente para calefacción?", opciones:["La separación del agua por su contenido mineral.", "La tendencia del agua más caliente y menos densa a acumularse en la parte superior, mientras el agua fría se queda en el fondo.", "Un proceso de filtración por gravedad.", "Cuando el tanque se congela por fuera."], respuesta_correcta:1, explicacion:"Es el efecto 'termo'. Si el tanque está bien diseñado, el agua sale muy caliente por arriba sin mezclarse con la fría que entra por abajo, maximizando el uso de la energía." , question: "What is 'Thermal Stratification' in a hot water storage tank for heating?", options: ["The separation of water by its mineral content.", "The tendency of the hotter, less dense water to accumulate at the top while cooler water stays at the bottom.", "A gravity filtration process.", "When the tank freezes on the outside."], explanation: "It is the thermos effect. If the tank is well designed, very hot water exits from the top without mixing with the cold water entering at the bottom, maximizing energy use." },
  { id:"calef_600", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es un 'Intercambiador de Entalpía' (ERV) y en qué se diferencia de un HRV?", opciones:["El ERV solo recupera calor sensible.", "El ERV recupera tanto calor sensible como calor latente (humedad), ayudando a mantener la humedad interior en invierno.", "El ERV usa un compresor para enfriar el aire exterior.", "No hay diferencia, son nombres regionales para el mismo aparato."], respuesta_correcta:1, explicacion:"El ERV es más avanzado. No solo calienta el aire que entra, sino que le 'pasa' la humedad del aire que sale, evitando que la casa se reseque demasiado en invierno." , question: "What is an 'Enthalpy Recovery Ventilator' (ERV) and how does it differ from an HRV?", options: ["The ERV only recovers sensible heat.", "The ERV recovers both sensible heat and latent heat (moisture), helping to maintain indoor humidity in winter.", "The ERV uses a compressor to cool the outdoor air.", "There is no difference; they are regional names for the same device."], explanation: "The ERV is more advanced. It not only warms the incoming air but also transfers humidity from the exhaust air, preventing the house from drying out too much in winter." },
  { id:"calef_601", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Reganancia Estática' (Static Regain) en el diseño de ductos de alta velocidad?", opciones:["Cuando el ducto se expande por el calor.", "La conversión de la presión dinámica (velocidad) en presión estática al aumentar gradualmente el tamaño del ducto, mejorando el flujo en las ramas lejanas.", "Un aumento del ruido debido a la fricción.", "La pérdida total de energía al final de la línea."], respuesta_correcta:1, explicacion:"Es pura ingeniería de fluidos. Si ensanchas el tubo suavemente, el aire frena pero 'empuja' con más fuerza hacia afuera, logrando que el aire llegue bien al último cuarto de la casa." , question: "What is 'Static Regain' in the design of high-velocity ductwork?", options: ["When the duct expands due to heat.", "The conversion of dynamic pressure (velocity) into static pressure by gradually increasing the duct size, improving airflow to distant branches.", "An increase in noise due to friction.", "The total energy loss at the end of the line."], explanation: "It is pure fluid engineering. If you gradually widen the duct, the air slows down but pushes outward with more force, ensuring air reaches the last room in the house." },
  { id:"calef_602", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué se desaconseja el uso de humidificadores de disco rotatorio en sistemas de calefacción modernos?", opciones:["Porque consumen demasiada agua.", "Tienden a acumular agua estancada en su bandeja, lo que facilita el crecimiento de bacterias y moho que se distribuyen por toda la casa.", "Son demasiado pesados para los ductos de lámina.", "El vapor que producen es demasiado frío."], respuesta_correcta:1, explicacion:"Cualquier cosa que tenga un charco de agua quieta dentro de un ducto de aire es un riesgo para la salud. Los sistemas modernos de panel desechable son mucho más limpios." , question: "Why is the use of rotary-disc humidifiers discouraged in modern heating systems?", options: ["Because they consume too much water.", "They tend to accumulate stagnant water in their tray, which facilitates the growth of bacteria and mold that are distributed throughout the house.", "They are too heavy for sheet metal ducts.", "The vapor they produce is too cold."], explanation: "Anything with a pool of stagnant water inside an air duct is a health risk. Modern disposable-pad systems are much cleaner." },
  { id:"calef_603", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es el 'Aire de Dilución' y por qué es crítico en hornos de tiro natural?", opciones:["Aire que se mezcla con el gas antes de quemarse.", "Aire de la habitación que entra por la campana de tiro para enfriar los gases y asegurar que suban por la chimenea sin condensar y sin apagar el piloto.", "El aire que limpia los filtros de carbón.", "Un gas inerte usado para apagar incendios en los ductos."], respuesta_correcta:1, explicacion:"Sin este aire, los gases de escape estarían demasiado calientes y pesados para la chimenea de metal simple. Es el 'motor' invisible que hace que el humo flote hacia afuera." , question: "What is 'Dilution Air' and why is it critical in natural-draft furnaces?", options: ["Air that mixes with the gas before combustion.", "Room air that enters through the draft hood to cool the flue gases and ensure they rise through the chimney without condensing and without extinguishing the pilot.", "Air that cleans the carbon filters.", "An inert gas used to extinguish fires in the ductwork."], explanation: "Without this air, the exhaust gases would be too hot and heavy for a single-wall metal chimney. It is the invisible engine that makes the flue gases float upward and out." },
  { id:"calef_604", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Presión Estática' en un ducto, explicada de forma sencilla?", opciones:["La velocidad a la que viaja el aire.", "La presión hacia afuera (como un globo inflado) que el aire ejerce contra las paredes del ducto; es la fuerza que vence la resistencia del filtro y las rejillas.", "El peso del metal del ducto.", "La temperatura del aire en reposo."], respuesta_correcta:1, explicacion:"Es la fuerza de 'inflado'. Si el ventilador no genera suficiente presión estática, no podrá empujar el aire a través del filtro sucio o los ductos largos." , question: "What is 'Static Pressure' in a duct, explained simply?", options: ["The speed at which air travels.", "The outward pressure (like an inflated balloon) that air exerts against the duct walls; it is the force that overcomes the resistance of the filter and registers.", "The weight of the duct metal.", "The temperature of the air at rest."], explanation: "It is the inflating force. If the blower cannot generate enough static pressure, it will not be able to push air through the dirty filter or long ductwork." },
  { id:"calef_605", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué los ductos de retorno deben ser generalmente más grandes que los de suministro?", opciones:["Para que el técnico pueda entrar a limpiarlos.", "Para reducir la velocidad del aire y el ruido, y asegurar que el soplador no tenga restricciones que causen una caída de presión estática excesiva en la succión.", "Aumenta la temperatura del aire por fricción molecular.", "Es una norma para evitar que los objetos pequeños sean succionados."], respuesta_correcta:1, explicacion:"El aire de retorno es más denso y difícil de mover. Si el tubo es pequeño, el ventilador silba y el horno se 'ahoga', reduciendo drásticamente su eficiencia." , question: "Why should return ducts generally be larger than supply ducts?", options: ["So the technician can fit inside to clean them.", "To reduce air velocity and noise, and to ensure the blower has no restrictions that would cause excessive static pressure drop on the suction side.", "It increases the air temperature through molecular friction.", "It is a code requirement to prevent small objects from being sucked in."], explanation: "Return air is denser and harder to move. If the duct is small, the blower whistles and the furnace is starved of air, drastically reducing its efficiency." },
  { id:"calef_606", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Temperatura del Punto de Rocío'?", opciones:["La temperatura a la que el agua se congela.", "La temperatura a la que el aire se satura de humedad y el vapor de agua comienza a condensarse en forma líquida.", "El calor generado por la fricción del aire en los ductos.", "La temperatura mínima para que el rocío de la mañana se evapore."], respuesta_correcta:1, explicacion:"Es el valor clave para evitar moho. Si tus paredes o ventanas están por debajo de esta temperatura, se mojarán. En invierno, queremos mantener este punto bajo control." , question: "What is the 'Dew Point Temperature'?", options: ["The temperature at which water freezes.", "The temperature at which the air becomes saturated with moisture and water vapor begins to condense into liquid form.", "The heat generated by air friction in the ducts.", "The minimum temperature needed for morning dew to evaporate."], explanation: "It is the key value for preventing mold. If your walls or windows are below this temperature, they will get wet. In winter, keeping this point under control is essential." },
  { id:"calef_607", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué ocurre con la eficiencia de una bomba de calor si el refrigerante entra al compresor con un sobrecalentamiento (superheat) excesivo de 25°C?", opciones:["La eficiencia aumenta porque el gas está más caliente.", "La eficiencia disminuye debido a que el gas es menos denso, reduciendo el flujo masivo y aumentando la temperatura de descarga, lo que estresa el aceite.", "El compresor consume menos amperaje porque el gas es más ligero.", "Evita que el aceite se mezcle con el refrigerante en el condensador."], respuesta_correcta:1, explicacion:"Un superheat alto significa que el gas se expandió demasiado. El compresor mueve menos 'peso' de refrigerante por cada embolada, trabajando más para calentar menos." , question: "What happens to the efficiency of a heat pump if the refrigerant enters the compressor with an excessive superheat of 45 degrees Fahrenheit?", options: ["Efficiency increases because the gas is hotter.", "Efficiency decreases because the gas is less dense, reducing the mass flow rate and raising the discharge temperature, which stresses the oil.", "The compressor draws less amperage because the gas is lighter.", "It prevents oil from mixing with the refrigerant in the condenser."], explanation: "High superheat means the gas has expanded too much. The compressor moves less refrigerant mass per stroke, working harder to deliver less heating." },
  { id:"calef_608", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted mezcla 1000 CFM de aire exterior a 0°C con 2000 CFM de aire de retorno a 21°C. ¿Cuál será la temperatura aproximada de la mezcla antes de entrar al horno?", opciones:["10.5°C (Promedio simple).", "14°C (Promedio ponderado por el flujo masivo).", "7°C debido al efecto de enfriamiento por expansión.", "21°C porque el aire caliente domina la mezcla."], respuesta_correcta:1, explicacion:"Fórmula: $T_{mix} = (CFM_1 	imes T_1 + CFM_2 	imes T_2) / CFM_{total}$. $(1000 	imes 0 + 2000 	imes 21) / 3000 = 14°C$. Es vital para evitar que el intercambiador se congele o condense." , question: "You mix 1,000 CFM of outdoor air at 32 degrees Fahrenheit with 2,000 CFM of return air at 70 degrees Fahrenheit. What will the approximate mixed-air temperature be before entering the furnace?", options: ["51 degrees Fahrenheit (simple average).", "57 degrees Fahrenheit (weighted average by airflow mass).", "45 degrees Fahrenheit due to expansion cooling effect.", "70 degrees Fahrenheit because the warm air dominates the mixture."], explanation: "Formula: T_mix = (CFM1 x T1 + CFM2 x T2) / CFM_total. (1000 x 32 + 2000 x 70) / 3000 = 57 degrees Fahrenheit. This is critical to avoid freezing or condensing on the heat exchanger." },
  { id:"calef_609", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un serpentín de enfriamiento (A-Coil) instalado ANTES de un horno de gas es una violación de seguridad y de código?", opciones:["Porque el aire frío apaga la llama.", "Porque el aire caliente del horno en invierno pasaría por el serpentín, aumentando la presión del refrigerante a niveles explosivos, y el condensado oxidaría el intercambiador.", "Aumenta la humedad de la casa de forma incontrolada.", "El soplador no tiene fuerza para empujar el aire a través del serpentín caliente."], respuesta_correcta:1, explicacion:"El orden correcto es: Retorno -> Filtro -> Soplador -> Horno -> Serpentín. Si pones el serpentín antes, el agua que gotea en verano destruirá el horno en poco tiempo." , question: "Why is installing a cooling coil (A-coil) upstream of a gas furnace a safety and code violation?", options: ["Because the cold air extinguishes the flame.", "Because in winter the hot air from the furnace would pass over the coil, raising refrigerant pressure to explosive levels, and the condensate would corrode the heat exchanger.", "It increases the house humidity uncontrollably.", "The blower lacks the force to push air through the hot coil."], explanation: "The correct order is: Return, Filter, Blower, Furnace, then Coil. If you put the coil before the furnace, the water that drips in summer will destroy the furnace in short order." },
  { id:"calef_610", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted mide una presión estática de 1.2\" w.c. en un sistema diseñado para 0.5\". ¿Qué sonido característico escuchará el cliente?", opciones:["Un zumbido eléctrico grave.", "Silbidos de alta frecuencia en las rejillas (air whistling) y un ruido sordo del soplador (booming) debido a la turbulencia masiva.", "Sonido de 'clic' constante en el termostato.", "No habrá sonido porque el aire se mueve muy lento."], respuesta_correcta:1, explicacion:"Presión alta = aire forzado por huecos pequeños. Es como soplar por una rendija. Además, el motor trabajará forzado y hará mucho más ruido mecánico." , question: "You measure a static pressure of 1.2 inches w.c. in a system designed for 0.5 inches. What characteristic sound will the customer hear?", options: ["A low-pitched electrical hum.", "High-frequency whistling at the registers (air whistling) and a deep thudding from the blower (booming) due to massive turbulence.", "A constant clicking sound at the thermostat.", "No sound because the air is moving very slowly."], explanation: "High pressure equals air forced through small openings. It is like blowing through a crack. Additionally, the motor runs under strain and produces much more mechanical noise." },
  { id:"calef_611", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Carga Radial' y cómo afecta al motor del soplador si la polea está demasiado tensa?", opciones:["La fuerza del campo magnético sobre el estator.", "La fuerza perpendicular al eje que jala el rodamiento hacia un lado; si es excesiva, desgasta el balero prematuramente y quema el motor.", "El peso del aire sobre las aspas del ventilador.", "La presión del aceite lubricante dentro del sello."], respuesta_correcta:1, explicacion:"Si aprietas demasiado la banda (correa), estás jalando el eje hacia la polea. El rodamiento no está diseñado para esa presión lateral y se destruirá por fricción." , question: "What is 'Radial Load' and how does it affect the blower motor if the belt is over-tensioned?", options: ["The force of the magnetic field on the stator.", "The perpendicular force on the shaft that pulls the bearing to one side; if excessive, it wears the bearing prematurely and burns out the motor.", "The weight of the air on the fan blades.", "The oil pressure inside the lubricant seal."], explanation: "If you over-tighten the belt, you pull the shaft toward the pulley. The bearing is not designed for that side load and will be destroyed by friction." },
  { id:"calef_612", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Entalpía de Vaporización' en el contexto de un humidificador de horno?", opciones:["La temperatura del vapor de agua.", "La cantidad de energía (BTUs) necesaria para convertir 1 lb de agua líquida en vapor a la misma temperatura.", "La velocidad a la que el agua viaja por el tubo de cobre.", "La presión del agua dentro del panel evaporativo."], respuesta_correcta:1, explicacion:"Para humidificar, robas calor al horno. Por cada libra de agua evaporada, le quitas unos 970 BTUs al aire caliente. Por eso la temperatura de suministro baja cuando prendes el humidificador." , question: "What is the 'Enthalpy of Vaporization' in the context of a furnace humidifier?", options: ["The temperature of the water vapor.", "The amount of energy (BTUs) needed to convert one pound of liquid water into vapor at the same temperature.", "The speed at which water travels through the copper tube.", "The water pressure inside the evaporative pad."], explanation: "To humidify, you steal heat from the furnace. For every pound of water evaporated, you take about 970 BTUs from the warm air. That is why the supply temperature drops when the humidifier runs." },
  { id:"calef_613", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un cliente siente 'corrientes de aire' (drafts) incluso si el horno está entregando aire a 45°C?", opciones:["Porque el aire caliente es muy seco.", "Velocidad de salida excesiva en las rejillas o mala ubicación de las mismas, lo que causa una mezcla turbulenta que roba calor corporal por convección rápida.", "El filtro de aire está cargado estáticamente.", "Es una percepción debida al color de las paredes de la habitación."], respuesta_correcta:1, explicacion:"No solo importa la temperatura, sino la velocidad. Aire a 45°C moviéndose muy rápido se siente frío sobre la piel porque evapora la humedad natural del cuerpo." , question: "Why does a customer feel 'drafts' even though the furnace is delivering air at 113 degrees Fahrenheit?", options: ["Because the warm air is very dry.", "Excessive air velocity at the registers or poor register placement, causing turbulent mixing that robs body heat through rapid convection.", "The air filter is statically charged.", "It is a perception related to the room's wall color."], explanation: "Not only temperature matters, but also velocity. Air at 113 degrees Fahrenheit moving very fast still feels cold on the skin because it evaporates the body's natural moisture." },
  { id:"calef_614", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es la función de un 'Vane' (deflector curvo) dentro de un codo de ducto rectangular?", opciones:["Reducir el peso del ducto.", "Guiar el aire suavemente a través de la curva para reducir la turbulencia, la caída de presión y el ruido generado por el choque del aire contra el metal.", "Filtrar las partículas de polvo grandes.", "Aumentar la temperatura del aire mediante compresión local."], respuesta_correcta:1, explicacion:"Sin deflectores, el aire choca contra la esquina y se vuelve un remolino loco. Los 'Turning Vanes' hacen que el aire siga la curva como si fuera un coche en una pista de carreras." , question: "What is a 'Turning Vane' (curved deflector) inside a rectangular duct elbow?", options: ["It reduces the weight of the duct.", "It guides the air smoothly through the curve to reduce turbulence, pressure drop, and noise caused by air slamming into the metal.", "It filters large dust particles.", "It increases the air temperature through localized compression."], explanation: "Without turning vanes, the air slams into the corner and creates a chaotic vortex. Turning vanes make the air follow the curve like a car on a racetrack." },
  { id:"calef_615", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted instala un humidificador. Si el cliente tiene agua muy dura (calcio/magnesio), ¿qué efecto secundario observará en la casa?", opciones:["Las plantas crecerán más rápido.", "Aparición de un 'polvo blanco' fino sobre los muebles y equipos electrónicos, derivado de los minerales del agua evaporada.", "El aire olerá a cloro constantemente.", "Las ventanas se volverán opacas permanentemente."], respuesta_correcta:1, explicacion:"Cuando el agua se evapora, los minerales se quedan. En humidificadores de spray o ultrasónicos, esos minerales flotan y aterrizan por toda la casa como polvo blanco." , question: "You install a humidifier. If the customer has very hard water (calcium/magnesium), what side effect will be observed in the house?", options: ["Plants will grow faster.", "A fine 'white dust' will appear on furniture and electronic equipment, formed by the minerals from the evaporated water.", "The air will constantly smell like chlorine.", "The windows will become permanently opaque."], explanation: "When water evaporates, the minerals stay behind. In spray or ultrasonic humidifiers, those minerals become airborne and settle throughout the house as white dust." },
  { id:"calef_616", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué ocurre con el flujo de aire (CFM) si usted quita el filtro de aire y no pone uno nuevo?", opciones:["El flujo de aire disminuye porque el aire está sucio.", "El flujo de aire aumenta (menos resistencia), lo que puede causar que el motor se sobrecargue y que el intercambiador de calor se ensucie de forma irreversible.", "La presión estática sube peligrosamente.", "El motor soplador se detiene por seguridad neumática."], respuesta_correcta:1, explicacion:"Menos obstáculos = más aire moviéndose. Pero sin filtro, el polvo se pega al intercambiador caliente, creando una capa de 'cemento' que arruina la eficiencia y huele a quemado." , question: "What happens to the airflow (CFM) if you remove the air filter and do not install a replacement?", options: ["Airflow decreases because the air is dirty.", "Airflow increases (less resistance), which can cause the motor to overload and the heat exchanger to become irreversibly fouled.", "Static pressure rises dangerously.", "The blower motor stops for pneumatic safety."], explanation: "Fewer obstacles means more air moving. But without a filter, dust sticks to the hot heat exchanger, creating a cement-like layer that ruins efficiency and smells like burning." },
  { id:"calef_617", categoria:"CALEF_TERMODINAMICA", pregunta:"En un sistema de calefacción, ¿qué es el 'Calor de Combustión Superior' (Higher Heating Value)?", opciones:["La temperatura más alta de la llama.", "La cantidad total de calor liberado incluyendo el calor latente contenido en el vapor de agua producido durante la combustión.", "El calor que se queda en el intercambiador primario.", "La presión máxima que alcanza el gas al explotar."], respuesta_correcta:1, explicacion:"Es el valor 'teórico' de energía del gas. Los hornos de condensación intentan llegar a este valor atrapando el calor del vapor de agua, algo que los hornos viejos no hacían." , question: "In a heating system, what is the 'Higher Heating Value' (HHV)?", options: ["The highest temperature of the flame.", "The total heat released including the latent heat contained in the water vapor produced during combustion.", "The heat that stays in the primary heat exchanger.", "The maximum pressure the gas reaches when it ignites."], explanation: "It is the theoretical energy value of the gas. Condensing furnaces aim to capture this value by recovering the heat from the water vapor, something older furnaces could not do." },
  { id:"calef_618", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted nota moho en las esquinas del techo de un cuarto. La humedad relativa de la casa es del 45%. ¿Cuál es el diagnóstico técnico?", opciones:["El humidificador está roto.", "Esa esquina está mal aislada (puente térmico); su superficie está por debajo del punto de rocío y el aire de la casa condensa ahí constantemente.", "El moho se alimenta del polvo de los ductos.", "La pintura del techo es de mala calidad."], respuesta_correcta:1, explicacion:"No es culpa de la humedad de la casa (45% es ideal). El problema es el aislamiento. Si la esquina está a 10°C y el punto de rocío es 12°C, siempre estará mojada y el moho crecerá." , question: "You notice mold in the ceiling corners of a room. The house relative humidity is 45 percent. What is the technical diagnosis?", options: ["The humidifier is broken.", "That corner is poorly insulated (thermal bridge); its surface temperature is below the dew point and indoor air condenses there continuously.", "The mold feeds on dust from the ductwork.", "The ceiling paint is of poor quality."], explanation: "It is not the house humidity's fault (45 percent is ideal). The problem is the insulation. If the corner is at 50 degrees Fahrenheit and the dew point is 54 degrees, it will always be wet and mold will grow." },
  { id:"calef_619", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Presión Dinámica'?", opciones:["La presión del aire cuando el horno está apagado.", "La presión causada por el movimiento del aire; se calcula restando la presión estática de la presión total.", "La fuerza que ejerce el soplador sobre el filtro.", "La temperatura del aire en movimiento."], respuesta_correcta:1, explicacion:"Es la energía de la velocidad. Si el aire va muy rápido, tiene mucha presión dinámica. Es lo que hace que el aire 'llegue lejos' al salir de la rejilla." , question: "What is 'Dynamic Pressure'?", options: ["The air pressure when the furnace is off.", "The pressure caused by the movement of air; it is calculated by subtracting static pressure from total pressure.", "The force the blower exerts on the filter.", "The temperature of air in motion."], explanation: "It is the energy of velocity. If the air is moving very fast, it has high dynamic pressure. It is what makes the air travel far when it exits the register." },
  { id:"calef_620", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un humidificador de panel evaporativo es más eficiente en Phoenix (clima seco) que en Miami (clima húmedo) para la misma temperatura de aire?", opciones:["Porque el agua de Phoenix es más ligera.", "Debido a que la depresión del bulbo húmedo es mayor en aire seco, lo que aumenta la tasa de evaporación adiabática al pasar por el panel saturado.", "El aire seco tiene más electrones para romper las moléculas de agua.", "Es una percepción subjetiva; la eficiencia es idéntica en ambos climas."], respuesta_correcta:1, explicacion:"El aire seco tiene 'más espacio' para el vapor. La diferencia entre la temperatura seca y la húmeda es el motor que hace que el agua se evapore rápido y enfríe o humidifique el aire." , question: "Why is an evaporative pad humidifier more efficient in Phoenix (dry climate) than in Miami (humid climate) at the same air temperature?", options: ["Because water in Phoenix is lighter.", "Because the wet bulb depression is greater in dry air, which increases the rate of adiabatic evaporation as air passes through the saturated pad.", "Dry air has more electrons to break water molecules.", "It is a subjective perception; the efficiency is identical in both climates."], explanation: "Dry air has more room for vapor. The difference between the dry bulb and wet bulb temperatures is the driving force that makes water evaporate quickly and humidify the air." },
  { id:"calef_621", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué sucede con la Entalpía total de un flujo de aire si se le añade vapor de agua a la misma temperatura (proceso isotérmico)?", opciones:["La entalpía se mantiene igual.", "La entalpía aumenta debido a la adición de calor latente contenido en la masa de vapor de agua.", "La entalpía disminuye porque el aire se vuelve más denso.", "Se vuelve negativa en relación con el punto de congelación."], respuesta_correcta:1, explicacion:"Energía es energía. Aunque el aire no esté 'más caliente' al tacto, tiene más energía almacenada en forma de humedad. Por eso el aire húmedo es más difícil de enfriar." , question: "What happens to the total Enthalpy of an airstream if water vapor is added at the same temperature (isothermal process)?", options: ["Enthalpy stays the same.", "Enthalpy increases due to the addition of latent heat contained in the mass of water vapor.", "Enthalpy decreases because the air becomes denser.", "It becomes negative relative to the freezing point."], explanation: "Energy is energy. Even though the air does not feel hotter to the touch, it has more energy stored as moisture. That is why humid air is harder to cool." },
  { id:"calef_622", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted encuentra que la Presión Estática en el retorno es de -0.6\" w.c. y el filtro está limpio. ¿Qué indica esta lectura?", opciones:["Que el soplador tiene mucha potencia.", "Que el ducto de retorno es demasiado pequeño o está obstruido, lo que causa que el ventilador trabaje forzado 'aspirando' un vacío.", "Presencia de una fuga masiva en el suministro.", "Es una lectura normal en sistemas de alta eficiencia."], respuesta_correcta:1, explicacion:"Un retorno con mucha succión (-0.6 es alto) significa que el aire no puede llegar al motor fácilmente. Es como tratar de respirar a través de un popote; el motor sufrirá." , question: "You find that the return Static Pressure reads minus 0.6 inches w.c. and the filter is clean. What does this reading indicate?", options: ["The blower is very powerful.", "The return ductwork is too small or obstructed, causing the fan to work hard creating a vacuum to draw air in.", "A massive leak in the supply side.", "It is a normal reading in high-efficiency systems."], explanation: "A return with high suction (minus 0.6 is elevated) means the air cannot easily reach the motor. It is like trying to breathe through a straw; the motor will suffer." },
  { id:"calef_623", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Corrosión Galvánica' en un intercambiador de calor de una caldera hidrónica?", opciones:["El óxido causado por el nitrógeno del aire.", "La degradación del metal causada por el contacto entre dos metales diferentes (ej. cobre y acero) en presencia de agua, creando una micro-batería eléctrica.", "El desgaste por la velocidad del agua.", "La acumulación de calcio en las tuberías de plástico."], respuesta_correcta:1, explicacion:"Nunca unas cobre con hierro sin un conector especial (dieléctrico). Si lo haces, el agua hará que un metal se 'coma' al otro hasta que haya una fuga." , question: "What is 'Galvanic Corrosion' in a hydronic boiler heat exchanger?", options: ["Rust caused by nitrogen in the air.", "Metal degradation caused by contact between two dissimilar metals (e.g., copper and steel) in the presence of water, creating a micro-battery.", "Wear from water velocity.", "Calcium buildup in plastic piping."], explanation: "Never join copper to iron without a dielectric fitting. If you do, the water will cause one metal to eat the other until a leak develops." },
  { id:"calef_624", categoria:"CALEF_TERMODINAMICA", pregunta:"En un sistema de calefacción por aire forzado, ¿por qué es crítico que el 'Salto Térmico' (Delta T) esté entre 40°F y 70°F?", opciones:["Para que el cliente no se queje del ruido.", "Asegura que el metal del intercambiador no se sobrecaliente (por Delta T alto) ni condense agua ácida (por Delta T bajo).", "Es el rango donde el gas natural tiene más octanaje.", "Para que el motor del soplador no gire al revés."], respuesta_correcta:1, explicacion:"Es el balance perfecto. Muy poco aire = horno se funde. Demasiado aire = el humo se enfría tanto que el horno se oxida por dentro con su propio condensado." , question: "In a forced-air heating system, why is it critical that the 'Temperature Rise' (Delta T) stays between 40 and 70 degrees Fahrenheit?", options: ["So the customer does not complain about noise.", "It ensures the heat exchanger metal does not overheat (from high Delta T) or condense corrosive moisture (from low Delta T).", "It is the range where natural gas has the highest octane.", "To prevent the blower motor from spinning in reverse."], explanation: "It is the perfect balance. Too little air means the furnace overheats. Too much air means the flue gases cool so much that the furnace corrodes internally from its own condensate." },
  { id:"calef_625", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es el 'Efecto de Enfriamiento por Viento' (Wind Chill) dentro de una casa con calefacción?", opciones:["El aire que entra por las rendijas de las ventanas.", "La sensación de frío causada por el aire en movimiento que acelera la evaporación de la humedad de la piel, incluso si el aire está a 22°C.", "El ruido que hace el soplador al arrancar.", "Cuando el termostato está cerca de una puerta exterior."], respuesta_correcta:1, explicacion:"Si el aire sale muy rápido de la rejilla y te pega directo, sentirás frío. El aire debe 'bañar' la habitación suavemente para que sea confortable." , question: "What is the 'Wind Chill Effect' inside a house with heating?", options: ["Air that enters through window cracks.", "The sensation of cold caused by moving air that accelerates the evaporation of skin moisture, even if the air is at 72 degrees Fahrenheit.", "The noise the blower makes when starting.", "When the thermostat is placed near an exterior door."], explanation: "If the air exits the register at high velocity and hits you directly, you will feel cold. The air should gently bathe the room for comfortable heating." },
  { id:"calef_626", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un ducto de suministro que termina bruscamente (Dead End) sin una reducción de tamaño causa problemas de flujo?", opciones:["Porque el aire se detiene y se enfría.", "Crea una zona de alta presión estática y turbulencia que impide que el aire salga correctamente por las últimas rejillas del sistema.", "Aumenta la humedad del aire por compresión.", "El metal del ducto comienza a vibrar a la frecuencia de 60Hz."], respuesta_correcta:1, explicacion:"El aire es como el tráfico. Si llegas a un muro, todos chocan. Los ductos deben reducirse al final para mantener la velocidad y que el aire quiera salir por las rejillas." , question: "Why does a supply duct that ends abruptly (dead end) without a size reduction cause airflow problems?", options: ["Because the air stops and cools down.", "It creates a high static pressure zone and turbulence that prevents air from properly exiting through the last registers in the system.", "It increases air humidity through compression.", "The duct metal begins to vibrate at 60 Hz."], explanation: "Air is like traffic. If you hit a wall, everything piles up. Ducts should taper at the end to maintain velocity and encourage the air to exit through the registers." },
  { id:"calef_627", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Convección' en un sistema de calefacción por aire forzado?", opciones:["El calor que viaja a través del metal del intercambiador.", "La transferencia de calor mediante el movimiento masivo de un fluido (el aire) que transporta la energía de un lugar a otro.", "La radiación que emiten las rejillas hacia las personas.", "El proceso de convertir gas natural en fuego azul."], respuesta_correcta:1, explicacion:"Es el soplador trabajando. El metal calienta el aire, y el soplador mueve ese aire caliente hacia ti. Es la forma más rápida de calentar una casa entera." , question: "What is 'Convection' in a forced-air heating system?", options: ["Heat that travels through the metal of the heat exchanger.", "Heat transfer through the bulk movement of a fluid (the air) that carries energy from one place to another.", "Radiation emitted from the registers toward the occupants.", "The process of converting natural gas into a blue flame."], explanation: "It is the blower at work. The metal heats the air, and the blower moves that warm air to you. It is the fastest way to heat an entire house." },
  { id:"calef_628", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué el aire de suministro se siente 'seco' incluso si el humidificador está funcionando al 100%?", opciones:["Porque el humidificador está roto.", "Debido a que el aire caliente tiene una capacidad de retención de humedad tan alta que el porcentaje de HR baja, aunque la cantidad absoluta de agua haya subido.", "El filtro de aire atrapa las moléculas de agua por magnetismo.", "El gas natural absorbe la humedad del aire durante la combustión."], respuesta_correcta:1, explicacion:"Es pura relatividad. Aire a 50°C con un poco de agua se siente seco. Una vez que ese aire se mezcla con la casa y se enfría a 22°C, la humedad relativa subirá y se sentirá bien." , question: "Why does the supply air feel 'dry' even if the humidifier is running at 100 percent?", options: ["Because the humidifier is broken.", "Because the hot air has such a high moisture-holding capacity that the relative humidity percentage drops, even though the absolute moisture content has increased.", "The air filter traps water molecules magnetically.", "Natural gas absorbs moisture from the air during combustion."], explanation: "It is purely relative. Air at 122 degrees Fahrenheit with a small amount of water feels dry. Once that air mixes with the house air and cools to 72 degrees, the relative humidity will rise and it will feel fine." },
  { id:"calef_629", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es un 'Salto de Aire' (Air Jump) en el diseño de retornos de aire?", opciones:["Cuando el aire sale por la ventana.", "Un conducto pequeño que conecta habitaciones cerradas con el área común para permitir que el aire de retorno fluya sin tener que instalar ductos grandes en cada cuarto.", "La velocidad a la que el aire salta de la rejilla.", "Un sensor que detecta si el filtro se cayó."], respuesta_correcta:1, explicacion:"Es una solución barata y efectiva. Permite que el aire salga del cuarto por el techo o sobre la puerta, evitando que la habitación se presurice y deje de recibir calor." , question: "What is an 'Air Jump' (transfer duct) in return air design?", options: ["When air escapes through the window.", "A small duct that connects closed rooms to the common area to allow return air to flow without having to install large ducts in each room.", "The velocity at which air jumps from the register.", "A sensor that detects if the filter has fallen out."], explanation: "It is a cheap and effective solution. It allows air to leave the room through the ceiling or above the door, preventing the room from pressurizing and losing heat delivery." },
  { id:"calef_630", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Radiación' en un sistema de calefacción?", opciones:["La energía nuclear que calienta el gas.", "La transferencia de calor mediante ondas electromagnéticas infrarrojas que calientan los objetos directamente sin calentar el aire entre ellos.", "El sonido que hacen los ductos al expandirse.", "El proceso de ionización del sensor de llama."], respuesta_correcta:1, explicacion:"Es como el sol. Un radiador de hierro fundido te calienta a ti directamente, no solo al aire. Es el calor más confortable que existe porque calienta tus huesos, no solo tu piel." , question: "What is 'Radiation' in a heating system?", options: ["Nuclear energy that heats the gas.", "Heat transfer through electromagnetic infrared waves that warm objects directly without heating the air between them.", "The sound ducts make when they expand.", "The ionization process of the flame sensor."], explanation: "It is like the sun. A cast iron radiator warms you directly, not just the air. It is the most comfortable form of heat because it warms your core, not just your skin." },
  { id:"calef_631", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un humidificador de spray (atomizador) puede enfriar el aire de suministro en 2 o 3 grados?", opciones:["Porque el agua sale directamente del refrigerador.", "Debido al enfriamiento evaporativo: el agua líquida absorbe calor sensible del aire para convertirse en vapor (calor latente), bajando la temperatura seca.", "El aire pierde velocidad al chocar con las gotas de agua.", "El gas natural reacciona con la niebla enfriando el intercambiador."], respuesta_correcta:1, explicacion:"Es física pura. Para evaporar agua necesitas calor. Ese calor se le roba al aire. Por eso, aunque humidifiques, el aire saldrá un poco más fresco de las rejillas." , question: "Why can a spray (atomizing) humidifier cool the supply air by 2 to 3 degrees?", options: ["Because the water comes straight from the refrigerator.", "Due to evaporative cooling: liquid water absorbs sensible heat from the air to convert into vapor (latent heat), lowering the dry bulb temperature.", "The air loses velocity from colliding with water droplets.", "The natural gas reacts with the mist, cooling the heat exchanger."], explanation: "It is pure physics. Evaporating water requires heat. That heat is stolen from the air. So even though you are humidifying, the air will exit the registers slightly cooler." },
  { id:"calef_632", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Presión Total' en un sistema de aire?", opciones:["La presión que marca el manómetro de gas.", "La suma de la presión estática (fuerza de inflado) y la presión dinámica (energía de la velocidad) en un punto determinado del ducto.", "El peso total de los ductos de metal.", "La presión máxima que aguanta el filtro de aire."], respuesta_correcta:1, explicacion:"Es la energía total del aire. Nos dice cuánta 'gasolina' le queda al aire para seguir moviéndose por los tubos hasta llegar a la última habitación." , question: "What is 'Total Pressure' in an air system?", options: ["The pressure shown on the gas manifold gauge.", "The sum of static pressure (inflating force) and dynamic pressure (velocity energy) at a given point in the duct.", "The total weight of the metal ductwork.", "The maximum pressure the air filter can withstand."], explanation: "It is the total energy of the air. It tells us how much momentum the air has left to keep moving through the pipes until it reaches the last room." },
  { id:"calef_633", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un cliente se queja de que el aire de calefacción 'le pica en la nariz'?", opciones:["Porque el aire tiene demasiado oxígeno.", "Baja Humedad Relativa (< 20%) causada por el calentamiento excesivo del aire frío exterior, lo que reseca las mucosas nasales y causa irritación.", "El filtro de aire está soltando perfumes químicos.", "El soplador está girando a 2000 RPM."], respuesta_correcta:1, explicacion:"El aire muy seco es agresivo. Absorbe el agua de tu nariz y garganta. La solución es un humidificador para mantener la humedad en un nivel confortable (35-45%)." , question: "Why does a customer complain that the heated air 'stings their nose'?", options: ["Because the air has too much oxygen.", "Low Relative Humidity (below 20 percent) caused by excessive heating of cold outdoor air, which dries out the nasal mucous membranes and causes irritation.", "The air filter is releasing chemical perfumes.", "The blower is spinning at 2,000 RPM."], explanation: "Extremely dry air is aggressive. It absorbs moisture from your nose and throat. The solution is a humidifier to maintain humidity at a comfortable level (35 to 45 percent)." },
  { id:"calef_634", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué ocurre técnicamente con la temperatura de 'Bulbo Húmedo' durante un proceso de calentamiento sensible puro en un horno de gas?", opciones:["Permanece constante al no haber cambio en la humedad absoluta.", "Aumenta, ya que aunque la humedad absoluta es la misma, la entalpía total del aire ha subido por el calor sensible añadido.", "Disminuye debido a la caída de la humedad relativa.", "Se iguala a la temperatura de punto de rocío del aire exterior."], respuesta_correcta:1, explicacion:"La temperatura de bulbo húmedo es una medida de energía (entalpía). Al calentar el aire, le das energía; por lo tanto, el bulbo húmedo debe subir necesariamente." , question: "What technically happens to the Wet Bulb temperature during a purely sensible heating process in a gas furnace?", options: ["It remains constant because there is no change in absolute humidity.", "It increases because, even though absolute humidity is the same, the total enthalpy of the air has risen due to the sensible heat added.", "It decreases due to the drop in relative humidity.", "It equals the dew point temperature of the outdoor air."], explanation: "Wet bulb temperature is a measure of energy (enthalpy). When you heat the air, you add energy; therefore, the wet bulb must necessarily increase." },
  { id:"calef_635", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué el uso de humidificadores ultrasónicos con agua del grifo puede ser perjudicial para la calidad del aire en invierno?", opciones:["Porque consumen demasiada energía eléctrica.", "Debido a la emisión de partículas finas de minerales (PM2.5) que pueden ser inhaladas y causar irritación pulmonar o depósitos de polvo blanco en la casa.", "El sonido ultrasónico estresa a las mascotas domésticas.", "El vapor que producen es ácido y oxida los muebles de metal."], respuesta_correcta:1, explicacion:"El ultrasonido rompe el agua en gotas minúsculas, incluyendo los minerales. Al evaporarse la gota en el aire, el mineral se queda flotando como polvo que respiramos." , question: "Why can the use of ultrasonic humidifiers with tap water be harmful to indoor air quality in winter?", options: ["Because they consume too much electricity.", "Due to the emission of fine mineral particles (PM2.5) that can be inhaled and cause lung irritation or white dust deposits throughout the house.", "The ultrasonic sound stresses household pets.", "The vapor they produce is acidic and corrodes metal furniture."], explanation: "Ultrasonic waves break water into tiny droplets, including the minerals. When the droplet evaporates in the air, the mineral remains suspended as fine dust that we breathe in." },
  { id:"calef_636", categoria:"CALEF_TERMODINAMICA", pregunta:"En un sistema de calefacción por aire forzado, ¿dónde se debe ubicar el humidostato para obtener la lectura más representativa de la casa?", opciones:["En el ducto de suministro, justo después del humidificador.", "En el ducto de retorno de aire, antes de que el aire entre al horno, o en una pared interior junto al termostato.", "Cerca de la ventana de la cocina.", "Dentro del gabinete del soplador para medir la humedad del motor."], respuesta_correcta:1, explicacion:"El retorno trae el aire 'promedio' de toda la casa. Si lo pones en el suministro, medirás el aire que acabas de mojar y el humidificador se apagará a los 2 segundos." , question: "In a forced-air heating system, where should the humidistat be located for the most representative reading of the house?", options: ["In the supply duct, right after the humidifier.", "In the return air duct before the air enters the furnace, or on an interior wall near the thermostat.", "Near the kitchen window.", "Inside the blower cabinet to measure the motor humidity."], explanation: "The return carries the average air from the entire house. If you place it in the supply duct, you will measure the air you just moistened and the humidifier will shut off within 2 seconds." },
  { id:"calef_637", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Entrada de Puesto' (Stall) en un ventilador de soplador centrífugo?", opciones:["Cuando el motor se queda sin energía eléctrica.", "Una condición de inestabilidad aerodinámica causada por una presión estática excesiva, donde el aire se separa de las aspas y el flujo se vuelve turbulento y ruidoso.", "El momento en que el ventilador alcanza sus RPM máximas.", "Un error en el capacitor de marcha del motor."], respuesta_correcta:1, explicacion:"Es como cuando un avión vuela muy lento y se cae. El ventilador intenta empujar aire contra una pared (ductos tapados) y el aire deja de fluir, solo hace ruido y vibra." , question: "What is 'Stall' in a centrifugal blower fan?", options: ["When the motor loses electrical power.", "An aerodynamic instability condition caused by excessive static pressure, where the air separates from the blades and flow becomes turbulent and noisy.", "The moment the fan reaches its maximum RPM.", "A fault in the motor's run capacitor."], explanation: "It is like when an airplane flies too slow and drops. The fan tries to push air against a wall (blocked ducts) and the air stops flowing, producing only noise and vibration." },
  { id:"calef_638", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cómo afecta la adición de un 30% de Propilenglicol a la 'Cabeza de Bombeo' (Pump Head) requerida en un sistema de calefacción?", opciones:["La disminuye porque el glicol es más resbaladizo que el agua.", "La aumenta, ya que el glicol es más viscoso y denso que el agua pura, requiriendo más energía para mover el mismo volumen de fluido.", "No tiene efecto en la mecánica de fluidos residencial.", "Permite usar tuberías de menor diámetro para el mismo flujo."], respuesta_correcta:1, explicacion:"El glicol es 'espeso'. La bomba tiene que empujar con más fuerza para que esa mezcla llegue a todos los radiadores de la casa." , question: "How does adding 30 percent propylene glycol affect the 'Pump Head' required in a heating system?", options: ["It decreases it because glycol is more slippery than water.", "It increases it because glycol is more viscous and dense than pure water, requiring more energy to move the same volume of fluid.", "It has no effect on residential fluid mechanics.", "It allows using smaller-diameter piping for the same flow."], explanation: "Glycol is thick. The pump must push harder to get that mixture to all the radiators in the house." },
  { id:"calef_639", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un sistema de calefacción que 'sobrecalienta' el aire (suministro a > 65°C) causa quejas de 'aire pesado' u olores a quemado?", opciones:["Porque el aire caliente es más denso.", "Debido a la pirólisis de las partículas de polvo doméstico que pasan por el intercambiador de calor excesivamente caliente.", "El oxígeno se quema y desaparece de la habitación.", "Se genera ozono de forma natural por el calor del gas."], respuesta_correcta:1, explicacion:"El polvo es materia orgánica. Si el metal está muy caliente, el polvo se 'tuesta' al pasar. No es peligroso, pero huele mal y reseca el aire de forma molesta." , question: "Why does a heating system that 'overheats' the air (supply above 150 degrees Fahrenheit) cause complaints of 'heavy air' or a burning smell?", options: ["Because hot air is denser.", "Due to the pyrolysis of household dust particles that pass over the excessively hot heat exchanger.", "The oxygen burns off and disappears from the room.", "Ozone is naturally generated by the heat of the gas."], explanation: "Dust is organic matter. If the metal is very hot, the dust toasts as it passes through. It is not dangerous, but it smells bad and over-dries the air." },
  { id:"calef_640", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted mide una presión estática externa total (TESP) de 1.1\" w.c. en un motor PSC. ¿Qué riesgo corre el motor a largo plazo?", opciones:["El motor consumirá menos energía y durará más.", "Sobrecalentamiento severo y falla del aislamiento de los devanados, ya que el motor intenta trabajar contra una restricción masiva sin flujo de aire para enfriarse.", "El ventilador se desprenderá del eje por la presión.", "La placa de control aumentará el voltaje a 240V automáticamente."], respuesta_correcta:1, explicacion:"Presión alta = poco aire. Poco aire = el motor no puede disipar su propio calor. Es una muerte lenta por calor para cualquier motor de soplador." , question: "You measure a total external static pressure (TESP) of 1.1 inches w.c. on a PSC motor. What long-term risk does the motor face?", options: ["The motor will use less energy and last longer.", "Severe overheating and winding insulation failure, as the motor works against a massive restriction without enough airflow to cool itself.", "The blower wheel will detach from the shaft due to the pressure.", "The control board will automatically increase voltage to 240V."], explanation: "High pressure means low airflow. Low airflow means the motor cannot dissipate its own heat. It is a slow death by overheating for any blower motor." },
  { id:"calef_641", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Temperatura de Color' de una llama y cómo se relaciona con la eficiencia en calefacción de gas?", opciones:["A mayor temperatura de color (más blanca), mayor es la eficiencia de combustión.", "No existe relación directa; la eficiencia depende de la transferencia de calor, no del espectro de luz de la llama.", "La llama azul es más fría que la llama naranja.", "Define la cantidad de radiación infrarroja que absorbe el filtro."], respuesta_correcta:1, explicacion:"Puedes tener una llama azul 'perfecta' pero si el intercambiador está sucio, la eficiencia será una basura. La luz de la llama solo nos dice si el quemador está limpio." , question: "What is the 'Color Temperature' of a flame and how does it relate to heating efficiency in a gas system?", options: ["The whiter (higher color temperature) the flame, the higher the combustion efficiency.", "There is no direct relationship; efficiency depends on heat transfer, not the light spectrum of the flame.", "A blue flame is cooler than an orange flame.", "It defines the amount of infrared radiation the filter absorbs."], explanation: "You can have a perfect blue flame, but if the heat exchanger is dirty, efficiency will be poor. The flame color only tells you whether the burner is clean." },
  { id:"calef_642", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es un 'Atenuador Acústico' en un sistema de ductos de calefacción comercial?", opciones:["Un tipo de aislante térmico de fibra de vidrio.", "Un tramo de ducto diseñado con deflectores y material absorbente para reducir el ruido del soplador sin restringir significativamente el flujo de aire.", "Un sensor que apaga el horno si el ruido supera los 80 dB.", "Una rejilla de retorno que se cierra automáticamente por la noche."], respuesta_correcta:1, explicacion:"Es el 'silenciador' del sistema. Permite que el horno trabaje a toda potencia sin que la gente en la oficina escuche el rugido del ventilador gigante." , question: "What is an 'Acoustic Attenuator' in a commercial heating duct system?", options: ["A type of fiberglass thermal insulation.", "A section of ductwork designed with baffles and sound-absorbing material to reduce blower noise without significantly restricting airflow.", "A sensor that shuts off the furnace if noise exceeds 80 dB.", "A return grille that closes automatically at night."], explanation: "It is the system's silencer. It allows the furnace to run at full capacity without the people in the office hearing the roar of the large fan." },
  { id:"calef_643", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cómo afecta la velocidad del aire de suministro al 'Calor Latente' del cuerpo humano?", opciones:["Aumenta la tasa de evaporación del sudor, aumentando la pérdida de calor latente y haciendo que la persona sienta más frío.", "No afecta el calor latente, solo el calor sensible.", "Reduce la humedad relativa de la piel mediante fricción.", "Convierte el sudor en energía eléctrica estática."], respuesta_correcta:0, explicacion:"Si el aire se mueve rápido, te 'seca' más rápido. Al secarte, te roba energía (calor). Por eso las corrientes de aire son tan molestas en invierno aunque el aire esté caliente." , question: "How does air supply velocity affect the 'Latent Heat' loss from the human body?", options: ["It increases the rate of sweat evaporation, increasing latent heat loss and making the person feel colder.", "It does not affect latent heat, only sensible heat.", "It reduces skin humidity through friction.", "It converts sweat into static electricity."], explanation: "If the air moves fast, it dries you faster. When it dries you, it robs you of energy (heat). That is why drafts are so uncomfortable in winter even if the air is warm." },
  { id:"calef_644", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué sucede con el punto de ebullición del agua en un sistema de calefacción si la presión absoluta se duplica?", opciones:["El punto de ebullición se mantiene en 100°C.", "El punto de ebullición aumenta significativamente, permitiendo transportar más calor sin que el agua se convierta en vapor.", "El agua hierve a temperatura ambiente (20°C).", "El agua se vuelve ácida instantáneamente."], respuesta_correcta:1, explicacion:"A más presión, más calor aguanta el agua antes de evaporarse. Por eso las ollas exprés cocinan más rápido y las calderas presurizadas calientan mejor." , question: "What happens to the boiling point of water in a heating system if the absolute pressure is doubled?", options: ["The boiling point stays at 212 degrees Fahrenheit.", "The boiling point increases significantly, allowing more heat to be transported without the water turning to steam.", "The water boils at room temperature (68 degrees Fahrenheit).", "The water becomes acidic instantly."], explanation: "More pressure means water can hold more heat before vaporizing. That is why pressure cookers cook faster and pressurized boilers heat more effectively." },
  { id:"calef_645", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es el 'Enfriamiento por Entalpía' en un sistema de ventilación de invierno y por qué es superior al enfriamiento por temperatura seca?", opciones:["Porque el aire húmedo es más fácil de calentar.", "Considera tanto la temperatura como la humedad del aire exterior para decidir si es más eficiente usar aire de la calle o recircular el de la casa, maximizando el ahorro energético.", "Usa la energía estática de los ductos para enfriar el aire.", "Solo funciona cuando la temperatura exterior es exactamente de 10°C."], respuesta_correcta:1, explicacion:"A veces el aire de afuera está fresco pero muy húmedo. Meter ese aire obligaría al sistema a gastar mucha energía deshumidificando. El control por entalpía evita ese error costoso." , question: "What is 'Enthalpy Cooling' in a winter ventilation system and why is it superior to dry bulb cooling?", options: ["Because humid air is easier to heat.", "It considers both the temperature and humidity of outdoor air to decide whether it is more efficient to use outside air or recirculate indoor air, maximizing energy savings.", "It uses the static energy of the ducts to cool the air.", "It only works when the outdoor temperature is exactly 50 degrees Fahrenheit."], explanation: "Sometimes the outdoor air is cool but very humid. Bringing in that air would force the system to spend a lot of energy dehumidifying. Enthalpy-based control avoids that costly mistake." },
  { id:"calef_646", categoria:"CALEF_TERMODINAMICA", pregunta:"En un sistema de calefacción, ¿qué es la 'Difusión de Aire' y cómo afecta al gradiente de temperatura vertical?", opciones:["La mezcla de gas natural con aire primario.", "La capacidad de la rejilla de suministro para mezclar el aire caliente con el aire de la habitación, evitando que el calor se quede atrapado en el techo (estratificación).", "El paso del aire a través de un filtro HEPA.", "La velocidad a la que el monóxido de carbono se dispersa en el aire."], respuesta_correcta:1, explicacion:"Una buena rejilla 'lanza' el aire para que se mezcle. Si la difusión es mala, el aire caliente flota al techo y tus pies siguen a 15°C mientras tu cabeza está a 28°C." , question: "In a heating system, what is 'Air Diffusion' and how does it affect the vertical temperature gradient?", options: ["The mixing of natural gas with primary air.", "The ability of the supply register to mix warm air with the room air, preventing heat from being trapped at the ceiling (stratification).", "Air passing through a HEPA filter.", "The rate at which carbon monoxide disperses in the air."], explanation: "A good register throws the air so it mixes thoroughly. If diffusion is poor, warm air floats to the ceiling and your feet stay at 59 degrees while your head is at 82 degrees." },
  { id:"calef_647", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué indica el término 'Juego Axialmente' (End Play) excesivo en el eje de un motor de soplador?", opciones:["Que el motor puede girar a más RPM de las nominales.", "Desgaste en las arandelas de empuje o rodamientos, permitiendo que el eje se mueva de adelante hacia atrás, causando ruidos de 'golpeteo' y vibración.", "Es un ajuste necesario para climas con alta humedad.", "Indica que el capacitor de marcha tiene mucha fuerza."], respuesta_correcta:1, explicacion:"El eje debe estar firme. Si se mueve como un pistón hacia los lados, la rueda del soplador golpeará la carcasa de metal, haciendo un ruido molesto y dañando el motor." , question: "What does excessive 'End Play' (axial play) in a blower motor shaft indicate?", options: ["The motor can spin faster than its rated RPM.", "Wear in the thrust washers or bearings, allowing the shaft to move back and forth and causing knocking sounds and vibration.", "It is a necessary adjustment for high-humidity climates.", "It indicates the run capacitor is too strong."], explanation: "The shaft must be firm. If it moves like a piston from side to side, the blower wheel will strike the metal housing, making an annoying noise and damaging the motor." },
  { id:"calef_648", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un sistema de calefacción por aire forzado causa que el polvo doméstico se acumule más rápido en las superficies?", opciones:["Porque el horno genera polvo de forma química.", "Debido al movimiento constante de grandes volúmenes de aire que mantienen las partículas en suspensión y a la baja humedad que genera cargas electrostáticas atractivas.", "El filtro de aire está diseñado para soltar polvo.", "Es una percepción visual debida a la luz cálida de la casa."], respuesta_correcta:1, explicacion:"El aire en movimiento es un transportador. Además, el aire seco hace que el polvo se 'pegue' a las cosas por estática. Un buen filtro MERV 11 o 13 ayuda a mitigar esto." , question: "Why does a forced-air heating system cause household dust to accumulate faster on surfaces?", options: ["Because the furnace generates dust chemically.", "Because the constant movement of large volumes of air keeps particles suspended, and the low humidity generates electrostatic charges that attract dust to surfaces.", "The air filter is designed to release dust.", "It is a visual perception caused by the warm house lighting."], explanation: "Moving air is a transporter. Additionally, dry air causes dust to cling to objects through static. A good MERV 11 or 13 filter helps mitigate this." },
  { id:"calef_649", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué sucede con el rendimiento de un ventilador centrífugo si las aspas están cubiertas por una capa de 1/16 de pulgada de polvo?", opciones:["No afecta, el polvo es muy ligero.", "Reducción drástica del flujo de aire (hasta un 30%) y aumento del ruido y vibración debido a la alteración del perfil aerofoil de las aspas.", "El motor consumirá menos electricidad por ser más pesado.", "Aumenta la presión estática del sistema automáticamente."], respuesta_correcta:1, explicacion:"Las aspas son como alas de avión. El polvo arruina su forma y ya no pueden 'agarrar' el aire. Limpiar la rueda del soplador es tan importante como cambiar el filtro." , question: "What happens to the performance of a centrifugal blower if the blades are coated with a 1/16-inch layer of dust?", options: ["No effect; the dust is too light.", "Drastic airflow reduction (up to 30 percent) and increased noise and vibration due to alteration of the blade airfoil profile.", "The motor will draw less electricity because the blades are heavier.", "System static pressure automatically increases."], explanation: "The blades are like airplane wings. Dust ruins their shape and they can no longer grip the air. Cleaning the blower wheel is as important as changing the filter." },
  { id:"calef_650", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es la causa técnica de las 'ventanas lloronas' (condensación masiva) en una casa durante el invierno?", opciones:["El vidrio de las ventanas es de mala calidad química.", "La temperatura del vidrio está por debajo del punto de rocío del aire interior, causado por una humedad relativa excesiva para la temperatura exterior actual.", "El horno está quemando demasiado nitrógeno.", "Es una señal de que el humidificador necesita mantenimiento."], respuesta_correcta:1, explicacion:"Si hace mucho frío afuera, el vidrio se enfría. Si tienes mucha humedad adentro, el agua se pega al vidrio frío. Hay que bajar el humidificador cuando la temperatura exterior cae." , question: "What is the technical cause of 'weeping windows' (massive condensation) in a house during winter?", options: ["The window glass is of poor chemical quality.", "The glass temperature is below the dew point of the indoor air, caused by excessive relative humidity for the current outdoor temperature.", "The furnace is burning too much nitrogen.", "It is a sign that the humidifier needs maintenance."], explanation: "If it is very cold outside, the glass chills. If there is too much humidity inside, water clings to the cold glass. You need to lower the humidifier setting when outdoor temperatures drop." },
  { id:"calef_651", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué se recomienda una velocidad de aire de 'Cara de Rejilla' (Grille Face Velocity) menor a 500 pies por minuto en calefacción residencial?", opciones:["Para que el aire no mueva las cortinas de la casa.", "Para minimizar el ruido aerodinámico y evitar la sensación de corrientes de aire frío (drafts) que causan incomodidad térmica por enfriamiento convectivo.", "Aumenta la vida útil del filtro de aire de carbón.", "El gas natural no puede calentar aire que se mueve más rápido."], respuesta_correcta:1, explicacion:"Si el aire sale muy rápido, hace un silbido molesto y se siente como un ventilador frío sobre la piel, aunque el aire esté caliente. El confort es silencio y suavidad." , question: "Why is a 'Grille Face Velocity' below 500 feet per minute recommended for residential heating?", options: ["To keep the air from blowing the curtains.", "To minimize aerodynamic noise and prevent the sensation of cold drafts that cause thermal discomfort through convective cooling.", "It extends the life of the carbon air filter.", "Natural gas cannot heat air moving faster than that."], explanation: "If the air exits too fast, it creates an annoying whistle and feels like a cold fan on the skin, even though the air is warm. Comfort means silence and gentleness." },
  { id:"calef_652", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Presión de Saturación' de un refrigerante dentro de un serpentín de bomba de calor?", opciones:["La presión máxima que aguanta el tubo antes de romperse.", "La presión a la cual el refrigerante existe tanto en estado líquido como gaseoso a una temperatura determinada.", "El peso del aceite mezclado con el gas de succión.", "La fuerza del soplador contra las aletas de aluminio."], respuesta_correcta:1, explicacion:"Es el punto de equilibrio. Si conoces la presión, conoces la temperatura. Es la base de todo el diagnóstico que hace un técnico con sus manómetros." , question: "What is the 'Saturation Pressure' of a refrigerant inside a heat pump coil?", options: ["The maximum pressure the tube can withstand before bursting.", "The pressure at which the refrigerant exists in both liquid and gaseous states at a given temperature.", "The weight of the oil mixed with the suction gas.", "The force of the blower against the aluminum fins."], explanation: "It is the equilibrium point. If you know the pressure, you know the temperature. It is the foundation of all the diagnostics a technician performs with gauges." },
  { id:"calef_653", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es el propósito técnico de un 'Plenum de Suministro' de gran tamaño en la salida del horno?", opciones:["Servir como caja de herramientas para el técnico.", "Actuar como una cámara de expansión que reduce la turbulencia del aire y estabiliza la presión estática antes de distribuirla a los ductos ramales.", "Aumentar la temperatura del aire mediante compresión estática.", "Filtrar las partículas de metal que suelta el intercambiador."], respuesta_correcta:1, explicacion:"El aire sale del ventilador muy 'loco' y turbulento. El plenum le da espacio para calmarse y que pueda entrar a los ductos de forma suave y silenciosa." , question: "What is the technical purpose of an oversized 'Supply Plenum' at the furnace outlet?", options: ["To serve as a toolbox for the technician.", "To act as an expansion chamber that reduces turbulence and stabilizes static pressure before distributing the air to the branch ducts.", "To increase air temperature through static compression.", "To filter metal particles shed by the heat exchanger."], explanation: "The air exits the blower in a very chaotic and turbulent state. The plenum gives it space to calm down so it can enter the ducts smoothly and quietly." },
  { id:"calef_654", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es el 'Volumen Específico' del aire y por qué aumenta a medida que calentamos la casa?", opciones:["Es el peso del aire en un metro cuadrado.", "Es el espacio que ocupa una libra de aire; al calentarse, las moléculas se mueven más rápido y se separan, ocupando más volumen por la misma masa.", "La cantidad de agua que puede absorber un filtro seco.", "La presión que ejerce el nitrógeno sobre el intercambiador."], respuesta_correcta:1, explicacion:"El aire caliente es 'gordo'. Ocupa más espacio. Por eso el ventilador tiene que trabajar un poco más para mover el mismo 'peso' de aire caliente que de aire frío." , question: "What is 'Specific Volume' of air and why does it increase as we heat the house?", options: ["It is the weight of air per square meter.", "It is the space one pound of air occupies; when heated, molecules move faster and spread apart, occupying more volume for the same mass.", "The amount of water a dry filter can absorb.", "The pressure nitrogen exerts on the heat exchanger."], explanation: "Hot air is bulky. It takes up more space. That is why the blower must work a bit harder to move the same weight of hot air compared to cold air." },
  { id:"calef_655", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cómo afecta un aumento de la 'Velocidad de Aire' sobre un ocupante en invierno si el aire está a 20°C?", opciones:["Aumenta su sensación de calor por fricción molecular.", "Aumenta la pérdida de calor por convección y evaporación de la piel, haciendo que la persona sienta frío (Draft Effect) aunque el aire no lo esté.", "No afecta, el cuerpo humano solo reacciona a la temperatura seca.", "Reduce la cantidad de oxígeno que los pulmones pueden absorber."], respuesta_correcta:1, explicacion:"El aire en movimiento te 'roba' calor. En invierno, queremos que el aire se mueva lento para que no se sienta como una brisa fría. El confort es aire tibio y quieto." , question: "How does increased 'Air Velocity' over an occupant in winter affect them if the air is at 68 degrees Fahrenheit?", options: ["It increases their sensation of warmth through molecular friction.", "It increases heat loss through convection and skin evaporation, making the person feel cold (draft effect) even though the air is not actually cold.", "It has no effect; the human body only reacts to dry bulb temperature.", "It reduces the amount of oxygen the lungs can absorb."], explanation: "Moving air robs you of heat. In winter, we want air to move slowly so it does not feel like a cold breeze. Comfort is warm, still air." },
  { id:"calef_656", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted mide una TESP de 0.9\" en un horno. Al quitar el filtro de aire sucio, la TESP baja a 0.5\". ¿Cuál era la caída de presión a través del filtro?", opciones:["0.9\" w.c.", "0.4\" w.c. (la diferencia entre ambas lecturas).", "1.4\" w.c. según la suma de las presiones.", "0.5\" w.c. porque el filtro no cuenta."], respuesta_correcta:1, explicacion:"El filtro se estaba 'robando' casi la mitad de la fuerza del ventilador. Esa caída de 0.4 es altísima para un solo componente. ¡Filtro nuevo urgente!" , question: "You measure a TESP of 0.9 inches w.c. on a furnace. When you remove the dirty air filter, TESP drops to 0.5 inches. What was the pressure drop across the filter?", options: ["0.9 inches w.c.", "0.4 inches w.c. (the difference between the two readings).", "1.4 inches w.c. per the sum of the pressures.", "0.5 inches w.c. because the filter does not count."], explanation: "The filter was robbing almost half the blower's force. A drop of 0.4 is extremely high for a single component. A new filter is needed urgently." },
  { id:"calef_657", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un horno de gas de 100,000 BTU instalado en una ciudad a 3,000 metros de altura debe ser 're-calibrado' (derating) obligatoriamente?", opciones:["Porque el gas natural se vuelve más denso con la altura.", "Debido a la menor densidad del aire; hay menos oxígeno por pie cúbico para la combustión, lo que causaría una llama rica en combustible y niveles letales de CO.", "El ventilador centrífugo consume el doble de amperaje por la falta de presión.", "Es una norma para evitar que el condensado se congele a 0°C."], respuesta_correcta:1, explicacion:"A 3,000 metros, el aire es 'delgado'. Si dejas el mismo flujo de gas que al nivel del mar, no habrá suficiente O2 para quemarlo todo. Hay que reducir el tamaño del orificio del gas." , question: "Why must a 100,000 BTU gas furnace installed in a city at 10,000 feet above sea level be mandatorily derated?", options: ["Because natural gas becomes denser with altitude.", "Due to the lower density of air; there is less oxygen per cubic foot for combustion, which would cause a fuel-rich flame and lethal levels of CO.", "The centrifugal fan draws double the amperage due to the lack of pressure.", "It is a code requirement to prevent condensate from freezing at 32 degrees Fahrenheit."], explanation: "At 10,000 feet, the air is thin. If you leave the same gas flow as at sea level, there will not be enough O2 to burn it all. The gas orifice size must be reduced." },
  { id:"calef_658", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un nivel de Humedad Relativa superior al 60% en invierno aumenta el riesgo de asma y alergias en la vivienda?", opciones:["Porque el aire se vuelve demasiado pesado para los pulmones.", "Promueve el crecimiento acelerado de ácaros del polvo y moho (fungi) en las alfombras y rincones fríos de las paredes.", "La humedad alta reduce el contenido de oxígeno en un 10%.", "El agua en el aire atrae estática que golpea a los ocupantes."], respuesta_correcta:1, explicacion:"Al moho le encanta el agua. Si pasas del 60%, las esquinas de tu casa se vuelven un nido de hongos que sueltan esporas al aire que respiras. El rango ideal es 35-45%." , question: "Why does a Relative Humidity above 60 percent in winter increase the risk of asthma and allergies in the home?", options: ["Because the air becomes too heavy for the lungs.", "It promotes the accelerated growth of dust mites and mold (fungi) in carpets and cold wall corners.", "High humidity reduces the oxygen content by 10 percent.", "Water in the air attracts static that shocks the occupants."], explanation: "Mold loves water. If you exceed 60 percent, the corners of your house become a breeding ground for fungi that release spores into the air you breathe. The ideal range is 35 to 45 percent." },
  { id:"calef_659", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Evaporación Latente' de la piel y cómo se ve afectada por el aire de suministro a alta velocidad?", opciones:["El sudor que se convierte en energía sensible.", "Es el enfriamiento natural del cuerpo; el aire a alta velocidad acelera este proceso, haciendo que el ocupante sienta frío aunque el aire esté a 24°C.", "La pérdida de humedad a través de los poros de la ropa.", "No ocurre si la humedad relativa es superior al 30%."], respuesta_correcta:1, explicacion:"Por eso odiamos el aire que nos pega directo. El aire 'barre' el sudor microscópico de nuestra piel, robándonos calor y dándonos escalofríos." , question: "What is 'Latent Evaporation' from the skin and how is it affected by high-velocity supply air?", options: ["Sweat that converts into sensible energy.", "It is the body's natural cooling mechanism; high-velocity air accelerates this process, making the occupant feel cold even though the air is at 75 degrees Fahrenheit.", "Moisture loss through the pores of clothing.", "It does not occur if relative humidity is above 30 percent."], explanation: "That is why we hate air blowing directly on us. The air sweeps the microscopic perspiration from our skin, robbing us of heat and giving us chills." },
  { id:"calef_660", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué ocurre con la 'Densidad del Aire' si la temperatura del suministro sube de 20°C a 50°C?", opciones:["La densidad se duplica por el calor acumulado.", "La densidad disminuye; las moléculas se separan, por lo que el ventilador mueve menos 'masa' de aire por cada pie cúbico de volumen.", "Se mantiene igual porque el aire es un gas ideal.", "La densidad aumenta debido a la expansión de los ductos de metal."], respuesta_correcta:1, explicacion:"Aire caliente = aire liviano. Por eso el soplador debe esforzarse más en invierno para mover la misma cantidad de 'calor' real que en verano." , question: "What happens to 'Air Density' if the supply temperature rises from 68 to 122 degrees Fahrenheit?", options: ["Density doubles from the accumulated heat.", "Density decreases; the molecules spread apart, so the fan moves less air mass per cubic foot of volume.", "It stays the same because air is an ideal gas.", "Density increases due to the expansion of the metal ductwork."], explanation: "Hot air equals light air. That is why the blower must work harder in winter to move the same amount of actual heat as in summer." },
  { id:"calef_661", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Humedad Absoluta' (Humidity Ratio) y por qué no cambia dentro de un horno de gas convencional?", opciones:["Es el peso del agua por libra de aire seco; no cambia porque el horno solo añade calor sensible, no añade ni quita agua física del aire.", "Es el porcentaje de agua en el aire; cambia cada vez que el termostato se apaga.", "Se mide en grados centígrados y representa el calor latente.", "Aumenta en el horno debido a la quema del hidrógeno del gas."], respuesta_correcta:0, explicacion:"Capciosa: El horno calienta el aire pero no le mete agua. La humedad relativa baja, pero la cantidad real de agua (absoluta) es la misma de principio a fin del ducto." , question: "What is 'Absolute Humidity' (Humidity Ratio) and why does it not change inside a conventional gas furnace?", options: ["It is the weight of water per pound of dry air; it does not change because the furnace only adds sensible heat and neither adds nor removes physical water from the air.", "It is the percentage of water in the air; it changes every time the thermostat shuts off.", "It is measured in degrees Celsius and represents latent heat.", "It increases in the furnace due to the combustion of hydrogen in the gas."], explanation: "This is a tricky question: the furnace heats the air but does not add water. Relative humidity drops, but the actual amount of water (absolute humidity) remains the same from start to finish of the duct." },
  { id:"calef_662", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué el aire de suministro en calefacción debe tener una velocidad menor en el 'Throw' (Alcance) que en enfriamiento?", opciones:["Para que el calor no se escape por la puerta.", "Evitar que el aire caliente se mezcle demasiado rápido con el aire frío del suelo, permitiendo que suba suavemente y bañe la habitación sin causar corrientes frías.", "El aire caliente es más difícil de mover que el aire frío.", "Para reducir el ruido del soplador en invierno."], respuesta_correcta:1, explicacion:"En invierno queremos que el aire 'caiga' como una manta tibia. Si sale disparado, se mezcla mal y da una sensación de brisa fría molesta." , question: "Why should the supply air velocity in heating have a lower 'Throw' than in cooling?", options: ["To keep the heat from escaping through the door.", "To prevent warm air from mixing too rapidly with the cold air at floor level, allowing it to rise gently and blanket the room without causing cold drafts.", "Hot air is harder to move than cold air.", "To reduce blower noise in winter."], explanation: "In winter, we want the air to descend like a warm blanket. If it is launched at high speed, it mixes poorly and creates an uncomfortable cold breeze sensation." },
  { id:"calef_663", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un cliente se queja de 'Aire con olor a quemado' los primeros 10 minutos de uso de la calefacción en otoño?", opciones:["Porque el intercambiador de calor se rompió durante el verano.", "Pirólisis del polvo doméstico acumulado sobre el intercambiador de calor durante los meses de inactividad; es un proceso normal y temporal.", "El gas natural caduca si no se usa en 3 meses.", "Falla del motor inductor por falta de lubricación interna."], respuesta_correcta:1, explicacion:"Es el 'olor a invierno'. El polvo se quema al tocar el metal caliente. Avisa al cliente que es normal para que no llame a los bomberos sin necesidad." , question: "Why does a customer complain of a 'burning smell' during the first 10 minutes of fall heating season use?", options: ["Because the heat exchanger cracked over the summer.", "Pyrolysis of household dust accumulated on the heat exchanger during the months of inactivity; it is a normal and temporary process.", "Natural gas expires if not used for 3 months.", "Inducer motor failure due to lack of internal lubrication."], explanation: "It is the smell of winter arriving. The dust burns off when it contacts the hot metal. Advise the customer that it is normal so they do not call the fire department unnecessarily." },
  { id:"calef_664", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es la 'Presión Estática' y por qué se mide antes y después del filtro de aire?", opciones:["Es la velocidad del aire en los ductos.", "Es la resistencia al flujo; la diferencia entre ambas medidas indica el grado de suciedad del filtro y la caída de presión que el soplador debe vencer.", "La fuerza del metal del ducto contra el aire.", "La temperatura del aire en reposo dentro del plenum."], respuesta_correcta:1, explicacion:"Es la 'presión arterial' del horno. Si el filtro está muy tapado, la presión sube, el aire no pasa y el horno se enferma (se sobrecalienta)." , question: "What is 'Static Pressure' and why is it measured before and after the air filter?", options: ["It is the air velocity in the ducts.", "It is the resistance to airflow; the difference between the two measurements indicates how dirty the filter is and the pressure drop the blower must overcome.", "The force of the duct metal against the air.", "The temperature of the air at rest inside the plenum."], explanation: "It is the furnace's blood pressure. If the filter is severely clogged, the pressure rises, the air cannot pass, and the furnace gets sick (overheats)." },
  { id:"calef_665", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué el aire exterior a -10°C se siente 'seco' una vez que entra a la casa y se calienta a 22°C?", opciones:["Porque el frío destruye las moléculas de agua.", "Porque la Humedad Relativa cae drásticamente al aumentar la temperatura, aunque la cantidad absoluta de agua (Humedad Absoluta) sea la misma.", "El horno absorbe el agua del aire por magnetismo térmico.", "Es una percepción psicológica debido al color del fuego."], respuesta_correcta:1, explicacion:"Aire caliente = vaso más grande. El aire frío tiene poca agua. Al calentarlo, el 'vaso' crece pero el agua es la misma, por eso se siente vacío (seco)." , question: "Why does outdoor air at 14 degrees Fahrenheit feel 'dry' once it enters the house and is heated to 72 degrees Fahrenheit?", options: ["Because the cold destroys water molecules.", "Because the Relative Humidity drops dramatically as the temperature increases, even though the Absolute Humidity (actual water content) is the same.", "The furnace absorbs the water from the air through thermal magnetism.", "It is a psychological perception related to the color of the flame."], explanation: "Warm air equals a bigger glass. Cold air holds very little water. When you heat it, the glass grows but the water stays the same, so it feels empty (dry)." },
  { id:"calef_666", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un ducto de metal 'truena' (banging noise) cuando el soplador se enciende o se apaga?", opciones:["Hay una rata dentro del ducto.", "Expansión térmica o cambios bruscos de presión que causan que la lámina de metal se doble y vuelva a su posición (Oil Canning).", "El aire caliente está golpeando los tornillos.", "El motor del soplador está mal balanceado magnéticamente."], respuesta_correcta:1, explicacion:"Se llama 'Oil Canning'. El metal es muy delgado o no tiene refuerzos. Al prender el aire, el tubo se infla y hace '¡CLAC!'. Se soluciona poniendo refuerzos o 'X' en la lámina." , question: "Why does a metal duct 'bang' (oil canning noise) when the blower turns on or off?", options: ["There is a rat inside the duct.", "Thermal expansion or sudden pressure changes cause the thin sheet metal to flex and snap back into position (oil canning).", "The warm air is hitting the screws.", "The blower motor is magnetically unbalanced."], explanation: "It is called oil canning. The metal is too thin or lacks reinforcement. When the air pressure changes, the duct pops in or out with a loud bang. It is fixed by adding cross-breaks or stiffeners to the sheet metal." },
  { id:"calef_667", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cómo afecta un aumento de altitud al punto de ebullición del agua en una caldera?", opciones:["El agua hierve a una temperatura más alta.", "El agua hierve a una temperatura más baja debido a la menor presión atmosférica, lo que requiere ajustes en los controles de temperatura.", "No afecta, el agua siempre hierve a 100°C.", "El agua se congela más rápido a gran altitud."], respuesta_correcta:1, explicacion:"En las montañas hay menos aire 'empujando' el agua. El agua escapa más fácil y se vuelve vapor a menos calor. Por eso en Denver el agua hierve a ~95°C." , question: "How does an increase in altitude affect the boiling point of water in a boiler?", options: ["Water boils at a higher temperature.", "Water boils at a lower temperature due to reduced atmospheric pressure, which requires adjustments to the temperature controls.", "It does not matter; water always boils at 212 degrees Fahrenheit.", "Water freezes faster at high altitude."], explanation: "In the mountains, there is less air pressing down on the water. The water escapes more easily and becomes steam at a lower temperature. That is why in Denver water boils at about 203 degrees Fahrenheit." },
  { id:"calef_668", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es el 'Efecto de Estratificación' en una habitación con techos altos?", opciones:["Cuando el aire se vuelve eléctrico.", "La acumulación de aire caliente cerca del techo y aire frío cerca del suelo debido a la diferencia de densidad, causando incomodidad térmica.", "Un proceso de filtración por capas de carbón.", "La pérdida de presión en los ductos verticales."], respuesta_correcta:1, explicacion:"El calor sube. En un techo alto, el calor se queda allá arriba con las lámparas y tú tienes los pies fríos abajo. Se arregla con ventiladores de techo o rejillas bajas." , question: "What is the 'Stratification Effect' in a room with high ceilings?", options: ["When the air becomes electrically charged.", "The accumulation of warm air near the ceiling and cold air near the floor due to the density difference, causing thermal discomfort.", "A multi-layer carbon filtration process.", "Pressure loss in vertical ducts."], explanation: "Heat rises. In a high-ceiling room, the heat stays up with the light fixtures and you have cold feet down below. It is fixed with ceiling fans or low-mounted registers." },
  { id:"calef_669", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué se siente más 'calor' a 22°C con 50% de humedad que a 22°C con 10% de humedad?", opciones:["Porque el aire húmedo es más caliente físicamente.", "Porque el aire húmedo reduce la tasa de evaporación del sudor de nuestra piel, impidiendo que el cuerpo se enfríe de forma natural.", "La humedad aumenta la fricción del aire sobre la piel.", "El aire seco atrae el frío del exterior por osmosis."], respuesta_correcta:1, explicacion:"El sudor nos enfría. Si el aire está muy húmedo, el sudor no se seca y nos sentimos 'pegajosos' y con más calor. Por eso la humedad hace que el invierno se sienta menos frío." , question: "Why does it feel warmer at 72 degrees Fahrenheit with 50 percent humidity than at 72 degrees Fahrenheit with 10 percent humidity?", options: ["Because humid air is physically hotter.", "Because humid air reduces the rate of sweat evaporation from our skin, preventing the body from cooling itself naturally.", "Humidity increases the friction of air on the skin.", "Dry air attracts cold from outside through osmosis."], explanation: "Sweat cools us. If the air is very humid, sweat does not dry and we feel sticky and warmer. That is why humidity makes winter feel less cold." },
  { id:"calef_670", categoria:"CALEF_TERMODINAMICA", pregunta:"En un ciclo de bomba de calor, ¿cuál es el término técnico para el calor que se añade al refrigerante en el evaporador por encima de su temperatura de saturación?", opciones:["Calor Latente de Condensación.", "Sobrecalentamiento (Superheat).", "Subenfriamiento (Subcooling).", "Entalpía de formación adiabática."], respuesta_correcta:1, explicacion:"El Superheat asegura que no entre líquido al compresor. Es el aumento de temperatura del vapor una vez que todo el líquido se ha evaporado." , question: "In a heat pump cycle, what is the technical term for the heat added to the refrigerant in the evaporator above its saturation temperature?", options: ["Latent heat of condensation.", "Superheat.", "Subcooling.", "Adiabatic enthalpy of formation."], explanation: "Superheat ensures no liquid enters the compressor. It is the temperature increase of the vapor once all the liquid has evaporated." },
  { id:"calef_671", categoria:"CALEF_TERMODINAMICA", pregunta:"Si la temperatura de Bulbo Seco es de 20°C y la de Bulbo Húmedo es de 10°C, ¿qué indica esto sobre la capacidad del aire para absorber humedad?", opciones:["El aire está saturado y no puede absorber más agua.", "El aire tiene una gran capacidad de absorción (humedad relativa baja).", "Existe un riesgo inminente de condensación en las ventanas de cristal sencillo.", "La temperatura de rocío es igual a la temperatura seca."], respuesta_correcta:1, explicacion:"Cuanto mayor es la diferencia entre el bulbo seco y el húmedo, más seco está el aire. La evaporación en el bulbo húmedo lo enfría más cuando el aire tiene 'hambre' de agua." , question: "If the dry bulb temperature is 68 degrees Fahrenheit and the wet bulb temperature is 50 degrees Fahrenheit, what does this indicate about the air's moisture absorption capacity?", options: ["The air is saturated and cannot absorb more water.", "The air has a large absorption capacity (low relative humidity).", "There is an imminent risk of condensation on single-pane windows.", "The dew point temperature equals the dry bulb temperature."], explanation: "The greater the difference between the dry bulb and wet bulb, the drier the air is. Evaporation on the wet bulb cools it more when the air is hungry for water." },
  { id:"calef_672", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué nivel de humedad relativa se considera el límite superior para evitar la formación de condensación en las paredes exteriores frías en invierno?", opciones:["10% HR.", "40-45% HR; por encima de esto, el aire toca la pared fría, llega al punto de rocío y genera agua líquida que produce moho.", "70% HR para mantener las plantas saludables.", "La humedad no afecta a las paredes, solo a las ventanas."], respuesta_correcta:1, explicacion:"En invierno, el exceso de humedad es el enemigo de la casa. Si tienes 60% de humedad y afuera hace mucho frío, tus paredes 'llorarán' por dentro y el moho aparecerá rápido." , question: "What relative humidity level is considered the upper limit to prevent condensation from forming on cold exterior walls in winter?", options: ["10 percent RH.", "40 to 45 percent RH; above this, the air contacts the cold wall, reaches the dew point, and generates liquid water that produces mold.", "70 percent RH to keep plants healthy.", "Humidity does not affect walls, only windows."], explanation: "In winter, excess humidity is the enemy of the house. If you have 60 percent humidity and it is very cold outside, your walls will weep internally and mold will appear quickly." },
  { id:"calef_673", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted mide una presión estática de 0.8\" w.c. en el plenum de suministro. El máximo del horno es 0.5\". ¿Cuál es la solución más técnica?", opciones:["Aumentar la velocidad del motor del ventilador.", "Revisar si el filtro está sucio, si el serpentín de AC está tapado o si los ductos de suministro son demasiado pequeños para el flujo (CFM).", "Hacer agujeros en el plenum para liberar la presión.", "Cambiar la válvula de gas por una de menor capacidad."], respuesta_correcta:1, explicacion:"Presión alta significa restricción. Antes de tocar el motor, hay que quitar el obstáculo. Un filtro sucio es la causa #1 de este problema." , question: "You measure a static pressure of 0.8 inches w.c. in the supply plenum. The furnace maximum is 0.5 inches. What is the most technically sound solution?", options: ["Increase the blower motor speed.", "Check whether the filter is dirty, whether the AC coil is clogged, or whether the supply ducts are too small for the airflow (CFM).", "Cut holes in the plenum to release the pressure.", "Replace the gas valve with a smaller-capacity one."], explanation: "High pressure means restriction. Before touching the motor, remove the obstruction. A dirty filter is the number one cause of this problem." },
  { id:"calef_674", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué el aire caliente se acumula en el techo (Estratificación) y cómo se soluciona en invierno?", opciones:["Porque el aire caliente es más pesado.", "Porque el aire caliente es menos denso; se soluciona moviendo el aire con ventiladores de techo en reversa o aumentando la velocidad del soplador.", "Es un efecto de la estática de las alfombras.", "El aire caliente busca el metal de los ductos del techo."], respuesta_correcta:1, explicacion:"El calor flota. Si no lo empujas hacia abajo, tus pies estarán fríos mientras el techo está a 30°C. Los ventiladores de techo en modo 'invierno' (reversa) ayudan mucho." , question: "Why does warm air accumulate at the ceiling (stratification) and how is it corrected in winter?", options: ["Because warm air is heavier.", "Because warm air is less dense; it is corrected by running ceiling fans in reverse or increasing the blower speed.", "It is an effect of carpet static.", "The warm air is attracted to the metal ducts in the ceiling."], explanation: "Heat floats. If you do not push it down, your feet will be cold while the ceiling is at 86 degrees Fahrenheit. Ceiling fans in winter (reverse) mode help a lot." },
  { id:"calef_675", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué sucede con la Humedad Relativa de una casa si no se utiliza humidificador en invierno?", opciones:["La HR sube porque afuera llueve o nieva.", "La HR baja a niveles desérticos (<15%) porque al calentar el aire frío exterior, su capacidad de absorber agua crece enormemente.", "Se mantiene constante en el 50%.", "El horno produce agua que humidifica la casa automáticamente."], respuesta_correcta:1, explicacion:"Este es el problema del invierno. Aire caliente = vaso gigante. Al calentar aire frío sin añadirle agua, el 'vaso' se queda vacío y el aire te roba humedad de la piel y ojos." , question: "What happens to the Relative Humidity of a house if no humidifier is used in winter?", options: ["RH rises because it is raining or snowing outside.", "RH drops to desert levels (below 15 percent) because heating the cold outdoor air greatly expands its moisture-holding capacity.", "It stays constant at 50 percent.", "The furnace produces water that humidifies the house automatically."], explanation: "This is the winter problem. Warm air equals a giant glass. When you heat cold air without adding water, the glass stays empty and the air steals moisture from your skin and eyes." },
  { id:"calef_676", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es un 'Plenum de Retorno'?", opciones:["La caja donde sale el aire caliente.", "La caja metálica o espacio donde se recolecta el aire frío de la casa antes de entrar al filtro y al soplador del horno.", "Un tipo de filtro de alta eficiencia.", "El tubo que saca el humo hacia la chimenea."], respuesta_correcta:1, explicacion:"Es el pulmón de entrada. Si es muy pequeño, el horno silba y el motor se esfuerza demasiado porque no puede 'respirar'." , question: "What is a 'Return Plenum'?", options: ["The box where warm air exits.", "The metal box or space where cooled house air is collected before entering the filter and the furnace blower.", "A type of high-efficiency filter.", "The pipe that carries flue gases to the chimney."], explanation: "It is the intake lung. If it is too small, the furnace whistles and the motor strains because it cannot breathe." },
  { id:"calef_677", categoria:"CALEF_TERMODINAMICA", pregunta:"En un sistema de calefacción, ¿qué es el 'Salto Térmico' (Temperature Rise)?", opciones:["La temperatura del aire afuera menos la de adentro.", "La diferencia de temperatura entre el aire que entra al horno (retorno) y el aire que sale (suministro).", "Lo que tarda el horno en calentar la casa de 15 a 22 grados.", "La temperatura máxima que aguanta el motor del soplador."], respuesta_correcta:1, explicacion:"Es vital medirlo. Si el salto es muy alto (ej. 100°F), el horno se va a quemar. Si es muy bajo, el cliente sentirá frío." , question: "In a heating system, what is 'Temperature Rise'?", options: ["The outdoor air temperature minus the indoor air temperature.", "The difference in temperature between the air entering the furnace (return) and the air leaving the furnace (supply).", "How long it takes the furnace to heat the house from 59 to 72 degrees.", "The maximum temperature the blower motor can withstand."], explanation: "It is essential to measure it. If the rise is too high (e.g., 100 degrees Fahrenheit), the furnace will burn out. If it is too low, the customer will feel cold." },
  { id:"calef_678", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué el aire seco de invierno causa 'estática' (choques eléctricos) al tocar objetos?", opciones:["Porque el horno genera electricidad por fricción.", "Porque el aire seco es un excelente aislante; las cargas eléctricas se acumulan en las personas y no pueden disiparse en el aire.", "Es un síntoma de que el cable de tierra de la casa está roto.", "El gas natural es magnético y carga el aire de la casa."], respuesta_correcta:1, explicacion:"El agua en el aire ayuda a que la electricidad se escape suavemente. Sin agua, te conviertes en una batería humana hasta que tocas algo de metal." , question: "Why does dry winter air cause 'static' (electric shocks) when touching objects?", options: ["Because the furnace generates electricity through friction.", "Because dry air is an excellent insulator; electrical charges accumulate on people and cannot dissipate into the air.", "It is a symptom of a broken house ground wire.", "Natural gas is magnetic and charges the house air."], explanation: "Water in the air helps electricity escape gently. Without moisture, you become a human battery until you touch something metal." },
  { id:"calef_679", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué sucede si el filtro de aire se instala al revés (flecha hacia afuera del horno)?", opciones:["El motor girará en sentido contrario.", "El filtro perderá eficiencia, se colapsará más fácil y podría ensuciar el motor del ventilador y el intercambiador rápido.", "El aire saldrá más frío de las rejillas.", "No pasa nada, los filtros son iguales por ambos lados."], respuesta_correcta:1, explicacion:"Los filtros tienen una estructura reforzada de un lado. Si los pones al revés, el aire puede doblar el filtro y el polvo pasará por las orillas." , question: "What happens if the air filter is installed backwards (arrow pointing away from the furnace)?", options: ["The motor will spin in reverse.", "The filter will lose efficiency, collapse more easily, and could quickly foul the blower motor and heat exchanger.", "The air will come out cooler from the registers.", "Nothing happens; filters are the same on both sides."], explanation: "Filters have a reinforced structure on one side. If installed backwards, the airflow can bend the filter and dust will bypass around the edges." },
  { id:"calef_680", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué es importante mantener el 'Drenaje de Condensado' limpio en un horno de alta eficiencia?", opciones:["Para que el agua no sepa amarga.", "Para evitar que el agua se estanque, produzca moho, bacterias u olores, y para prevenir que el horno se bloquee por el interruptor de desbordamiento.", "Aumenta la presión de la válvula de gas.", "El agua de condensación es necesaria para enfriar el motor inductor."], respuesta_correcta:1, explicacion:"El agua de estos hornos es sucia y ácida. Si se tapa, el horno se apaga y el piso se moja. Mantenerlo limpio evita muchas llamadas de emergencia." , question: "Why is it important to keep the 'Condensate Drain' clean in a high-efficiency furnace?", options: ["So the water does not taste bitter.", "To prevent water from pooling, producing mold, bacteria, or odors, and to prevent the furnace from locking out on the overflow safety switch.", "It increases gas valve pressure.", "The condensate water is needed to cool the inducer motor."], explanation: "The water from these furnaces is dirty and acidic. If the drain clogs, the furnace shuts down and the floor gets wet. Keeping it clean prevents many emergency service calls." },
  { id:"calef_681", categoria:"CALEF_TERMODINAMICA", pregunta:"Usted mide una temperatura de retorno de 70°F y una de suministro de 130°F. ¿Cuál es el Salto Térmico (Rise)?", opciones:["200°F.", "60°F ($130 - 70 = 60$).", "30°F.", "No se puede calcular sin la humedad."], respuesta_correcta:1, explicacion:"Es una resta simple. 60 grados es un rango perfecto para la mayoría de los hornos residenciales. Estás en la zona segura." , question: "You measure a return temperature of 70 degrees Fahrenheit and a supply temperature of 130 degrees Fahrenheit. What is the Temperature Rise?", options: ["200 degrees Fahrenheit.", "60 degrees Fahrenheit (130 minus 70 equals 60).", "30 degrees Fahrenheit.", "It cannot be calculated without the humidity."], explanation: "It is a simple subtraction. 60 degrees is a perfect range for most residential furnaces. You are in the safe zone." },
  { id:"calef_682", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué las rejillas de suministro suelen estar debajo de las ventanas?", opciones:["Para que el técnico las encuentre fácil.", "Para crear una 'cortina' de aire caliente que bloquee el frío que entra por el cristal de la ventana, mejorando el confort.", "Para evitar que el vidrio se empañe con el frío.", "Porque el metal de los ductos se oxida menos cerca de la luz natural."], respuesta_correcta:1, explicacion:"Es pura estrategia. La ventana es el punto más frío de la pared. Si pones el calor ahí, neutralizas el frío antes de que llegue a tus pies." , question: "Why are supply registers typically located below windows?", options: ["So the technician can find them easily.", "To create a curtain of warm air that blocks the cold entering through the window glass, improving comfort.", "To prevent the glass from fogging up in the cold.", "Because the duct metal corrodes less near natural light."], explanation: "It is pure strategy. The window is the coldest point on the wall. If you place the heat there, you neutralize the cold before it reaches your feet." },
  { id:"calef_683", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es el principal mantenimiento de un humidificador de panel (bypass)?", opciones:["Cambiar el motor cada año.", "Reemplazar el panel evaporativo (pad) y limpiar la válvula de agua de sedimentos de calcio.", "Vaciar el agua y rellenarlo con agua destilada cada semana.", "Lijar las aspas del ventilador interno."], respuesta_correcta:1, explicacion:"El panel se llena de sarro (minerales del agua). Si está tapado de blanco, el aire no pasa y el agua no se evapora. Cambiarlo es barato y mantiene la casa cómoda." , question: "What is the primary maintenance task for a bypass panel humidifier?", options: ["Replace the motor every year.", "Replace the evaporative pad and clean the water valve of calcium deposits.", "Drain the water and refill with distilled water weekly.", "Sand the blades of the internal fan."], explanation: "The pad fills up with scale (water minerals). If it is caked in white deposits, air cannot pass and water will not evaporate. Replacing it is inexpensive and keeps the house comfortable." },
  { id:"calef_684", categoria:"CALEF_TERMODINAMICA", pregunta:"Un horno de gas enciende perfectamente, pero el soplador (blower) arranca y se apaga intermitentemente cada 10 segundos mientras la llama sigue encendida. ¿Qué falla?", opciones:["El sensor de llama está sucio.", "Falla en el relé de la placa de control o un protector térmico interno del motor del soplador que se abre por sobrecalentamiento local.", "La presión del gas es intermitente.", "El termostato está enviando señales de 'Fan On' y 'Auto' simultáneamente."], respuesta_correcta:1, explicacion:"Si el motor 'cliquea' o se apaga solo, es un problema eléctrico o térmico del motor. Si la llama sigue, la placa cree que el motor está bien, pero el motor se está protegiendo o el relé no sostiene el contacto." , question: "A gas furnace ignites successfully, but the blower starts and stops intermittently every 10 seconds while the flame remains lit. What is the failure?", options: ["The flame sensor is dirty.", "A faulty relay on the control board or an internal thermal protector in the blower motor that is opening due to localized overheating.", "The gas pressure is intermittent.", "The thermostat is sending 'Fan On' and 'Auto' signals simultaneously."], explanation: "If the motor clicks or shuts itself off, it is an electrical or thermal problem with the motor. If the flame continues, the control board believes the motor is fine, but the motor is protecting itself or the relay is not holding contact." },
  { id:"calef_685", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué sucede con el 'Punto de Rocío' de la casa si instalamos un humidificador y lo ajustamos al 60% cuando afuera hay -10°C?", opciones:["El punto de rocío se mantiene igual.", "El punto de rocío sube por encima de la temperatura de la superficie de las ventanas, causando condensación severa e incluso formación de hielo en los marcos.", "La temperatura de bulbo húmedo baja para compensar.", "El aire se vuelve más pesado y el soplador consume menos amperaje."], respuesta_correcta:1, explicacion:"A mayor humedad, mayor punto de rocío. Si el punto de rocío es de 15°C y tu ventana está a 5°C por el frío exterior, el agua se va a chorrear por todo el vidrio." , question: "What happens to the 'Dew Point' of the house if we install a humidifier and set it to 60 percent when it is 14 degrees Fahrenheit outside?", options: ["The dew point stays the same.", "The dew point rises above the surface temperature of the windows, causing severe condensation and even ice formation on the window frames.", "The wet bulb temperature drops to compensate.", "The air becomes heavier and the blower draws less amperage."], explanation: "Higher humidity means a higher dew point. If the dew point is 59 degrees Fahrenheit and your window is at 41 degrees due to the cold outside, water will stream down the glass." },
  { id:"calef_686", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es la causa técnica de que el aire de calefacción se sienta 'pesado' o 'sin oxígeno' en una habitación sin ventilación?", opciones:["El horno quema el oxígeno de la habitación.", "Aumento de la concentración de $CO_2$ y contaminantes orgánicos volátiles (VOCs) debido a la falta de aire fresco (dilución).", "El filtro de aire está soltando iones negativos.", "El gas natural se está filtrando a través de los ductos."], respuesta_correcta:1, explicacion:"El horno no quema el oxígeno de tu cuarto (lo jala del ático o exterior). El aire se siente mal porque estás respirando el mismo aire una y otra vez sin meter aire fresco de la calle." , question: "What is the technical cause of heating air feeling 'heavy' or 'oxygen-depleted' in a room with no ventilation?", options: ["The furnace burns the oxygen in the room.", "Increased concentration of CO2 and volatile organic compounds (VOCs) due to the lack of fresh air (dilution).", "The air filter is releasing negative ions.", "Natural gas is leaking through the ductwork."], explanation: "The furnace does not burn the oxygen in your room (it draws combustion air from the attic or outside). The air feels stale because you are breathing the same air over and over without introducing fresh outdoor air." },
  { id:"calef_687", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es el 'Efecto de Garganta Seca' y cómo se relaciona con el Delta T del horno?", opciones:["Es una alergia al gas natural.", "Un Delta T muy alto genera aire de suministro excesivamente caliente y seco, lo que acelera la evaporación de las mucosas respiratorias de los ocupantes.", "El soplador está soltando partículas de metal microscópicas.", "Se soluciona instalando un filtro de mayor eficiencia."], respuesta_correcta:1, explicacion:"Si el aire sale 'quemando', va a secar todo a su paso. Un horno bien ajustado debe calentar la casa suavemente, no como un secador de pelo gigante." , question: "What is the 'Dry Throat Effect' and how does it relate to the furnace Delta T?", options: ["It is an allergy to natural gas.", "A very high Delta T produces excessively hot and dry supply air, which accelerates the evaporation of moisture from the occupants' respiratory membranes.", "The blower is shedding microscopic metal particles.", "It is solved by installing a higher-efficiency filter."], explanation: "If the air exits scorching hot, it will dry everything in its path. A properly adjusted furnace should heat the house gently, not like a giant hair dryer." },
  { id:"calef_688", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Cuál es el nivel de 'Ruido' (NC - Noise Criteria) ideal para una rejilla de suministro en un dormitorio?", opciones:["NC 50 (ruido de oficina ruidosa).", "NC 25 a 30 (silencio casi total, solo un ligero flujo de aire audible).", "NC 70 (ruido de una aspiradora).", "El ruido no importa en calefacción residencial."], respuesta_correcta:1, explicacion:"En el cuarto quieres dormir. Si la rejilla silba o sopla muy fuerte, el cliente no podrá descansar. Un buen diseño de ductos debe ser silencioso." , question: "What is the ideal 'Noise Criteria' (NC) level for a supply register in a bedroom?", options: ["NC 50 (noisy office level).", "NC 25 to 30 (near total silence, only a slight airflow audible).", "NC 70 (vacuum cleaner level).", "Noise does not matter in residential heating."], explanation: "In the bedroom, you want to sleep. If the register whistles or blows loudly, the customer will not be able to rest. Good duct design should be silent." },
  { id:"calef_689", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Qué es un 'Damper de Balanceo' y dónde se instala?", opciones:["En el termostato para equilibrar la temperatura.", "En cada ducto ramal (take-off) para regular la cantidad de aire que llega a cada habitación de forma proporcional.", "Dentro de la válvula de gas para equilibrar el flujo.", "En la salida de la chimenea para controlar el tiro."], respuesta_correcta:1, explicacion:"Sirve para que el cuarto que está pegado al horno no reciba todo el aire y el cuarto del fondo no se quede frío. Ajustas las llaves de los tubos para equilibrar la casa." , question: "What is a 'Balancing Damper' and where is it installed?", options: ["In the thermostat to balance the temperature.", "In each branch duct (take-off) to regulate the amount of air reaching each room proportionally.", "Inside the gas valve to balance the flow.", "At the chimney outlet to control the draft."], explanation: "It ensures the room closest to the furnace does not get all the air while the farthest room stays cold. You adjust the dampers in the branch ducts to balance the house." },
  { id:"calef_690", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué se siente más frío en una casa con 'Calefacción Eléctrica de Zócalo' (Baseboard) que con aire forzado a la misma temperatura?", opciones:["Porque la electricidad es más fría que el gas.", "Falta de circulación de aire; el calor se queda pegado a la pared y al techo, dejando el centro de la habitación y el suelo mucho más fríos (mala mezcla).", "Las resistencias eléctricas absorben la humedad de la piel.", "El aire forzado inyecta oxígeno extra a la casa."], respuesta_correcta:1, explicacion:"El Baseboard calienta por convección natural (despacio). El aire caliente sube directo al techo. Si no hay un ventilador que mueva ese aire, tú que estás sentado abajo tendrás frío." , question: "Why does a house with 'Electric Baseboard Heating' feel colder than one with forced air at the same temperature?", options: ["Because electricity is colder than gas.", "Lack of air circulation; the heat stays against the wall and ceiling, leaving the center of the room and the floor much colder (poor mixing).", "The electric elements absorb skin moisture.", "Forced air injects extra oxygen into the house."], explanation: "Baseboard heaters rely on natural convection (slow). The warm air rises straight to the ceiling. If there is no fan to move that air around, you sitting below will be cold." },
  { id:"calef_691", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué un filtro de aire MERV 16 es mejor para personas con alergias que un MERV 8?", opciones:["Porque el MERV 16 deja pasar más aire.", "Porque tiene un tejido mucho más denso capaz de atrapar partículas microscópicas como bacterias, virus y esporas de moho que el MERV 8 no puede detener.", "El MERV 16 calienta el aire por fricción molecular.", "No hay diferencia, el número solo indica el precio del filtro."], respuesta_correcta:1, explicacion:"A mayor número MERV, más pequeño es el 'agujero' del filtro. Un MERV 16 es casi un filtro de hospital; atrapa casi todo lo que te hace estornudar." , question: "Why is a MERV 16 air filter better for allergy sufferers than a MERV 8?", options: ["Because the MERV 16 allows more air to pass through.", "Because it has a much denser weave capable of trapping microscopic particles such as bacteria, viruses, and mold spores that a MERV 8 cannot stop.", "The MERV 16 heats the air through molecular friction.", "There is no difference; the number only indicates the filter price."], explanation: "The higher the MERV number, the smaller the openings in the filter. A MERV 16 is nearly hospital-grade; it captures almost everything that makes you sneeze." },
  { id:"calef_692", categoria:"CALEF_TERMODINAMICA", pregunta:"¿Por qué el aire de calefacción se siente más 'fresco' en las rejillas de una Bomba de Calor que en las de un Horno de Gas?", opciones:["Porque la bomba de calor usa electricidad fría.", "Porque el aire de una bomba de calor sale a unos 35-40°C (cerca de la temperatura corporal), mientras que el horno de gas sale a unos 55-65°C.", "La bomba de calor absorbe la humedad del aire de suministro.", "Es un efecto psicológico causado por el ruido de la unidad exterior."], respuesta_correcta:1, explicacion:"Como la bomba de calor entrega aire casi a la misma temperatura que tu cuerpo, si te pega directo se siente como 'viento tibio'. El gas sale 'quemando', por eso se siente más caliente." , question: "Why does the heating air feel 'cooler' at the registers of a Heat Pump than at those of a Gas Furnace?", options: ["Because the heat pump uses cold electricity.", "Because a heat pump delivers supply air at about 95-104 degrees Fahrenheit (close to body temperature), while a gas furnace delivers it at about 130-150 degrees Fahrenheit.", "The heat pump absorbs humidity from the supply air.", "It is a psychological effect caused by outdoor unit noise."], explanation: "Because the heat pump delivers air at nearly the same temperature as your body, if it blows directly on you it feels like a warm breeze. Gas furnace air exits much hotter, so it feels like true heat." },

]; // fin CALEF_QUESTIONS

